/**
 * Wave 1 of docs/CONTENT-ROADMAP.md: the papers behind trials that had none. Written by scripts/fetch-trial-papers.ts,
 * which asks Europe PMC for PubMed records whose title or abstract cites the trial's NCT id and keeps the most cited
 * eligible paper (plus one later report when its title says it is an update). Title, journal, year, DOI, PMID and
 * authors are read from the Europe PMC record; the summary reproduces the record's abstract with markup removed
 * and house-style dashes; the TL;DR, "what it means" and caveats say only how the record was matched. Nothing here
 * has been read by an editor: findings are left empty on purpose. Trials link to these records through
 * src/data/trial-key-papers-wave1.ts. Do not edit by hand; re-run the script.
 */
export const papersTrialsWave1: PaperInput[] = [
  p({ id: "paper-aeneas-j-clin-oncol-2022", name: "AENEAS: A Randomized Phase III Trial of Aumolertinib Versus Gefitinib as First-Line Therapy for Locally Advanced or MetastaticNon-Small-Cell Lung Cancer With EGFR Exon 19 Deletion or L858R Mutations", tldr: "Published report from the AENEAS trial registered as NCT03849768, in Journal of Clinical Oncology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Aumolertinib (formerly almonertinib; HS-10296) is a novel third-generation epidermal growth factor receptor tyrosine kinase inhibitor approved in China. This double-blind phase III trial evaluated the efficacy and safety of aumolertinib compared with gefitinib as a first-line treatment for locally advanced or metastatic EGFR -mutated non-small-cell lung cancer (NSCLC; ClinicalTrials.gov identifier: NCT03849768).\n\nMethods: Patients at 53 sites in China were randomly assigned 1:1 to receive either aumolertinib (110 mg) or gefitinib (250 mg) once daily. The primary end point was progression-free survival (PFS) per investigator assessment.\n\nResults: A total of 429 patients who were naïve to treatment for locally advanced or metastatic NSCLC were enrolled. PFS was significantly longer with aumolertinib compared with gefitinib (hazard ratio, 0.46; 95% CI, 0.36 to 0.60; P <.0001). The median PFS with aumolertinib was 19.3 months (95% CI, 17.8 to 20.8) versus 9.9 months with gefitinib (95% CI, 8.3 to 12.6). Objective response rate and disease control rate were similar in the aumolertinib and gefitinib groups (objective response rate, 73.8% and 72.1%, respectively; disease control rate, 93.0% and 96.7%, respectively). The median duration of response was 18.1 months (95% CI, 15.2 to not applicable) with aumolertinib versus 8.3 months (95% CI, 6.9 to 11.1) with gefitinib. Adverse events of grade ≥ 3 severity (any cause) were observed in 36.4% and 35.8% of patients in the aumolertinib and gefitinib groups, respectively. Rash and diarrhea (any grade) were observed in 23.4% and 16.4% of patients who received aumolertinib compared with 41.4% and 35.8% of those who received gefitinib, respectively.\n\nConclusion: Aumolertinib is a well-tolerated third-generation epidermal growth factor receptor tyrosine kinase inhibitor that could serve as a treatment option for EGFR -mutant NSCLC in the first-line setting.\n\nIndexed on Europe PMC as PubMed record 35580297 (DOI 10.1200/jco.21.02641). Its abstract cites the registry id NCT03849768, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2022, doi: "10.1200/jco.21.02641", pmid: "35580297", authors: "Lu S, Dong X, Jian H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03849768 with the most citations, so it is the natural first reading for anyone following the AENEAS trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2022","url":"https://doi.org/10.1200/jco.21.02641"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35580297/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35580297"},{"label":"ClinicalTrials.gov NCT03849768","url":"https://clinicaltrials.gov/study/NCT03849768"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["aumolertinib","gefitinib"], targets: ["egfr"], technologies: ["kinase-inhibitors"], trials: ["aeneas"], journals: ["jco"] }),
  p({ id: "paper-alex-n-engl-j-med-2017", name: "Alectinib versus Crizotinib in Untreated ALK-Positive Non-Small-Cell Lung Cancer", tldr: "Published report from the ALEX trial registered as NCT02075840, in New England Journal of Medicine (2017), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Alectinib, a highly selective inhibitor of anaplastic lymphoma kinase (ALK), has shown systemic and central nervous system (CNS) efficacy in the treatment of ALK-positive non-small-cell lung cancer (NSCLC). We investigated alectinib as compared with crizotinib in patients with previously untreated, advanced ALK-positive NSCLC, including those with asymptomatic CNS disease.\n\nMethods: In a randomized, open-label, phase 3 trial, we randomly assigned 303 patients with previously untreated, advanced ALK-positive NSCLC to receive either alectinib (600 mg twice daily) or crizotinib (250 mg twice daily). The primary end point was investigator-assessed progression-free survival. Secondary end points were independent review committee-assessed progression-free survival, time to CNS progression, objective response rate, and overall survival.\n\nResults: During a median follow-up of 17.6 months (crizotinib) and 18.6 months (alectinib), an event of disease progression or death occurred in 62 of 152 patients (41%) in the alectinib group and 102 of 151 patients (68%) in the crizotinib group. The rate of investigator-assessed progression-free survival was significantly higher with alectinib than with crizotinib (12-month event-free survival rate, 68.4% [95% confidence interval (CI), 61.0 to 75.9] with alectinib vs. 48.7% [95% CI, 40.4 to 56.9] with crizotinib; hazard ratio for disease progression or death, 0.47 [95% CI, 0.34 to 0.65]; P<0.001); the median progression-free survival with alectinib was not reached. The results for independent review committee-assessed progression-free survival were consistent with those for the primary end point. A total of 18 patients (12%) in the alectinib group had an event of CNS progression, as compared with 68 patients (45%) in the crizotinib group (cause-specific hazard ratio, 0.16; 95% CI, 0.10 to 0.28; P<0.001). A response occurred in 126 patients in the alectinib group (response rate, 82.9%; 95% CI, 76.0 to 88.5) and in 114 patients in the crizotinib group (response rate, 75.5%; 95% CI, 67.8 to 82.1) (P=0.09). Grade 3 to 5 adverse events were less frequent with alectinib (41% vs. 50% with crizotinib).\n\nConclusions: As compared with crizotinib, alectinib showed superior efficacy and lower toxicity in primary treatment of ALK-positive NSCLC. (Funded by F. Hoffmann-La Roche; ALEX ClinicalTrials.gov number, NCT02075840.).\n\nIndexed on Europe PMC as PubMed record 28586279 (DOI 10.1056/nejmoa1704795). Its abstract cites the registry id NCT02075840, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2017, doi: "10.1056/nejmoa1704795", pmid: "28586279", authors: "Peters S, Camidge DR, Shaw AT, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02075840 with the most citations, so it is the natural first reading for anyone following the ALEX trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2017","url":"https://doi.org/10.1056/nejmoa1704795"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28586279/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28586279"},{"label":"ClinicalTrials.gov NCT02075840","url":"https://clinicaltrials.gov/study/NCT02075840"}], tags: ["europepmc-ingest"], cancers: ["nsclc","alk-positive-nsclc"], drugs: ["alectinib","crizotinib"], targets: ["alk"], technologies: ["kinase-inhibitors"], trials: ["alex"], journals: ["nejm"] }),
  p({ id: "paper-alex-ann-oncol-2020-update", name: "Updated overall survival and final progression-free survival data for patients with treatment-naive advanced ALK-positive non-small-cell lung cancer in the ALEX study", tldr: "Later report from the ALEX trial registered as NCT02075840, in Annals of Oncology (2020); its title describes an updated or longer-term analysis.", summary: "Background: The ALEX study demonstrated significantly improved progression-free survival (PFS) with alectinib versus crizotinib in treatment-naive ALK-positive non-small-cell lung cancer (NSCLC) at the primary data cut-off (9 February 2017). We report mature PFS (cut-off: 30 November 2018) and overall survival (OS) data up to 5 years (cut-off: 29 November 2019).\n\nPatients and methods: Patients with stage III/IV ALK-positive NSCLC were randomized to receive twice-daily alectinib 600 mg (n = 152) or crizotinib 250 mg (n = 151) until disease progression, toxicity, withdrawal or death. Primary end point: investigator-assessed PFS. Secondary end points included objective response rate, OS and safety.\n\nResults: Mature PFS data showed significantly prolonged investigator-assessed PFS with alectinib [hazard ratio (HR) 0.43, 95% confidence interval (CI) 0.32-0.58; median PFS 34.8 versus 10.9 months crizotinib]. Median duration of OS follow-up: 48.2 months alectinib, 23.3 months crizotinib. OS data remain immature (37% of events). Median OS was not reached with alectinib versus 57.4 months with crizotinib (stratified HR 0.67, 95% CI 0.46-0.98). The 5-year OS rate was 62.5% (95% CI 54.3-70.8) with alectinib and 45.5% (95% CI 33.6-57.4) with crizotinib, with 34.9% and 8.6% of patients still on study treatment, respectively. The OS benefit of alectinib was seen in patients with central nervous system metastases at baseline [HR 0.58 (95% CI 0.34-1.00)] and those without [HR 0.76 (95% CI 0.45-1.26)]. Median treatment duration was longer with alectinib (28.1 versus 10.8 months), and no new safety signals were observed.\n\nConclusions: Mature PFS data from ALEX confirmed significant improvement in PFS for alectinib over crizotinib in ALK-positive NSCLC. OS data remain immature, with a higher 5-year OS rate with alectinib versus crizotinib. This is the first global randomized study to show clinically meaningful improvement in OS for a next-generation tyrosine kinase inhibitor versus crizotinib in treatment-naive ALK-positive NSCLC.\n\nClinical trials number: NCT02075840.\n\nIndexed on Europe PMC as PubMed record 32418886 (DOI 10.1016/j.annonc.2020.04.478). Its abstract cites the registry id NCT02075840, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2020, doi: "10.1016/j.annonc.2020.04.478", pmid: "32418886", authors: "Mok T, Camidge DR, Gadgeel SM, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the ALEX trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2020","url":"https://doi.org/10.1016/j.annonc.2020.04.478"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32418886/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32418886"},{"label":"ClinicalTrials.gov NCT02075840","url":"https://clinicaltrials.gov/study/NCT02075840"}], tags: ["europepmc-ingest"], cancers: ["nsclc","alk-positive-nsclc"], drugs: ["alectinib","crizotinib"], targets: ["alk"], technologies: ["kinase-inhibitors"], trials: ["alex"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-alina-n-engl-j-med-2024", name: "Alectinib in Resected ALK -Positive Non-Small-Cell Lung Cancer", tldr: "Published report from the ALINA trial registered as NCT03456076, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Platinum-based chemotherapy is the recommended adjuvant treatment for patients with resectable, ALK -positive non-small-cell lung cancer (NSCLC). Data on the efficacy and safety of adjuvant alectinib as compared with chemotherapy in patients with resected ALK -positive NSCLC are lacking.\n\nMethods: We conducted a global, phase 3, open-label, randomized trial in which patients with completely resected, ALK -positive NSCLC of stage IB (tumors ≥4 cm), II, or IIIA (as classified according to the seventh edition of the Cancer Staging Manual of the American Joint Committee on Cancer and Union for International Cancer Control) were randomly assigned in a 1:1 ratio to receive oral alectinib (600 mg twice daily) for 24 months or intravenous platinum-based chemotherapy in four 21-day cycles. The primary end point was disease-free survival, tested hierarchically among patients with stage II or IIIA disease and then in the intention-to-treat population. Other end points included central nervous system (CNS) disease-free survival, overall survival, and safety.\n\nResults: In total, 257 patients were randomly assigned to receive alectinib (130 patients) or chemotherapy (127 patients). The percentage of patients alive and disease-free at 2 years was 93.8% in the alectinib group and 63.0% in the chemotherapy group among patients with stage II or IIIA disease (hazard ratio for disease recurrence or death, 0.24; 95% confidence interval [CI], 0.13 to 0.45; P<0.001) and 93.6% and 63.7%, respectively, in the intention-to-treat population (hazard ratio, 0.24; 95% CI, 0.13 to 0.43; P<0.001). Alectinib was associated with a clinically meaningful benefit with respect to CNS disease-free survival as compared with chemotherapy (hazard ratio for CNS disease recurrence or death, 0.22; 95% CI, 0.08 to 0.58). Data for overall survival were immature. No unexpected safety findings were observed.\n\nConclusions: Among patients with resected ALK -positive NSCLC of stage IB, II, or IIIA, adjuvant alectinib significantly improved disease-free survival as compared with platinum-based chemotherapy. (Funded by F. Hoffmann-La Roche; ALINA ClinicalTrials.gov number, NCT03456076.).\n\nIndexed on Europe PMC as PubMed record 38598794 (DOI 10.1056/nejmoa2310532). Its abstract cites the registry id NCT03456076, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2310532", pmid: "38598794", authors: "Wu YL, Dziadziuszko R, Ahn JS, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03456076 with the most citations, so it is the natural first reading for anyone following the ALINA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2310532"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38598794/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38598794"},{"label":"ClinicalTrials.gov NCT03456076","url":"https://clinicaltrials.gov/study/NCT03456076"}], tags: ["europepmc-ingest"], cancers: ["nsclc","alk-positive-nsclc","resectable-nsclc"], drugs: ["alectinib"], targets: ["alk"], technologies: [], trials: ["alina"], journals: ["nejm"] }),
  p({ id: "paper-alta-1l-n-engl-j-med-2018", name: "Brigatinib versus Crizotinib in ALK-Positive Non-Small-Cell Lung Cancer", tldr: "Published report from the ALTA-1L trial registered as NCT02737501, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Brigatinib, a next-generation anaplastic lymphoma kinase (ALK) inhibitor, has robust efficacy in patients with ALK-positive non-small-cell lung cancer (NSCLC) that is refractory to crizotinib. The efficacy of brigatinib, as compared with crizotinib, in patients with advanced ALK-positive NSCLC who have not previously received an ALK inhibitor is unclear.\n\nMethods: In an open-label, phase 3 trial, we randomly assigned, in a 1:1 ratio, patients with advanced ALK-positive NSCLC who had not previously received ALK inhibitors to receive brigatinib at a dose of 180 mg once daily (with a 7-day lead-in period at 90 mg) or crizotinib at a dose of 250 mg twice daily. The primary end point was progression-free survival as assessed by blinded independent central review. Secondary end points included the objective response rate and intracranial response. The first interim analysis was planned when approximately 50% of 198 expected events of disease progression or death had occurred.\n\nResults: A total of 275 patients underwent randomization; 137 were assigned to brigatinib and 138 to crizotinib. At the first interim analysis (99 events), the median follow-up was 11.0 months in the brigatinib group and 9.3 months in the crizotinib group. The rate of progression-free survival was higher with brigatinib than with crizotinib (estimated 12-month progression-free survival, 67% [95% confidence interval {CI}, 56 to 75] vs. 43% [95% CI, 32 to 53]; hazard ratio for disease progression or death, 0.49 [95% CI, 0.33 to 0.74]; P<0.001 by the log-rank test). The confirmed objective response rate was 71% (95% CI, 62 to 78) with brigatinib and 60% (95% CI, 51 to 68) with crizotinib; the confirmed rate of intracranial response among patients with measurable lesions was 78% (95% CI, 52 to 94) and 29% (95% CI, 11 to 52), respectively. No new safety concerns were noted.\n\nConclusions: Among patients with ALK-positive NSCLC who had not previously received an ALK inhibitor, progression-free survival was significantly longer among patients who received brigatinib than among those who received crizotinib. (Funded by Ariad Pharmaceuticals; ALTA-1L ClinicalTrials.gov number, NCT02737501.).\n\nIndexed on Europe PMC as PubMed record 30280657 (DOI 10.1056/nejmoa1810171). Its abstract cites the registry id NCT02737501, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1810171", pmid: "30280657", authors: "Camidge DR, Kim HR, Ahn MJ, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02737501 with the most citations, so it is the natural first reading for anyone following the ALTA-1L trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1810171"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30280657/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30280657"},{"label":"ClinicalTrials.gov NCT02737501","url":"https://clinicaltrials.gov/study/NCT02737501"}], tags: ["europepmc-ingest"], cancers: ["nsclc","alk-positive-nsclc"], drugs: ["brigatinib","crizotinib"], targets: ["alk"], technologies: ["kinase-inhibitors"], trials: ["alta-1l"], journals: ["nejm"] }),
  p({ id: "paper-alter-0303-jama-oncol-2018", name: "Effect of Anlotinib as a Third-Line or Further Treatment on Overall Survival of Patients With Advanced Non-Small Cell Lung Cancer: The ALTER 0303 Phase 3 Randomized Clinical Trial", tldr: "Published report from the ALTER 0303 trial registered as NCT02388919, in JAMA Oncology (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Anlotinib is a novel multitarget tyrosine kinase inhibitor for tumor angiogenesis and proliferative signaling. A phase 2 trial showed anlotinib to improve progression-free survival with a potential benefit of overall survival, leading to the phase 3 trial to confirm the drug's efficacy in advanced non-small cell lung cancer (NSCLC).\n\nObjective: To investigate the efficacy of anlotinib on overall survival of patients with advanced NSCLC progressing after second-line or further treatment.\n\nDesign, setting, and participants: The ALTER 0303 trial was a multicenter, double-blind, phase 3 randomized clinical trial designed to evaluate the efficacy and safety of anlotinib in patients with advanced NSCLC. Patients from 31 grade-A tertiary hospitals in China were enrolled between March 1, 2015, and August 31, 2016. Those aged 18 to 75 years who had histologically or cytologically confirmed NSCLC were eligible (n = 606), and those who had centrally located squamous cell carcinoma with cavitary features or brain metastases that were uncontrolled or controlled for less than 2 months were excluded. Patients (n = 440) were randomly assigned in a 2-to-1 ratio to receive either 12 mg/d of anlotinib or a matched placebo. All cases were treated with study drugs at least once in accordance with the intention-to-treat principle.\n\nMain outcomes and measures: The primary end point was overall survival. The secondary end points were progression-free survival, objective response rate, disease control rate, quality of life, and safety.\n\nResults: In total, 439 patients were randomized, 296 to the anlotinib group (106 [36.1%] were female and 188 [64.0%] were male, with a mean [SD] age of 57.9 [9.1] years) and 143 to the placebo group (46 [32.2%] were female and 97 [67.8%] were male, with a mean [SD] age of 56.8 [9.1] years). Overall survival was significantly longer in the anlotinib group (median, 9.6 months; 95% CI, 8.2-10.6) than the placebo group (median, 6.3 months; 95% CI, 5.0-8.1), with a hazard ratio (HR) of 0.68 (95% CI, 0.54-0.87; P =.002). A substantial increase in progression-free survival was noted in the anlotinib group compared with the placebo group (median, 5.4 months [95% CI, 4.4-5.6] vs 1.4 months [95% CI, 1.1-1.5]; HR, 0.25 [95% CI, 0.19-0.31]; P <.001). Considerable improvement in objective response rate and disease control rate was observed in the anlotinib group over the placebo group. The most common grade 3 or higher adverse events in the anlotinib arm were hypertension and hyponatremia.\n\nConclusions and relevance: Among the Chinese patients in this trial, anlotinib appears to lead to prolonged overall survival and progression-free survival. This finding suggests that anlotinib is well tolerated and is a potential third-line or further therapy for patients with advanced NSCLC.\n\nTrial registration: ClinicalTrials.gov identifier: NCT02388919.\n\nIndexed on Europe PMC as PubMed record 30098152 (DOI 10.1001/jamaoncol.2018.3039). Its abstract cites the registry id NCT02388919, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2018, doi: "10.1001/jamaoncol.2018.3039", pmid: "30098152", authors: "Han B, Li K, Wang Q, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02388919 with the most citations, so it is the natural first reading for anyone following the ALTER 0303 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2018","url":"https://doi.org/10.1001/jamaoncol.2018.3039"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30098152/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30098152"},{"label":"ClinicalTrials.gov NCT02388919","url":"https://clinicaltrials.gov/study/NCT02388919"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["anlotinib"], targets: [], technologies: ["kinase-inhibitors","antiangiogenic"], trials: ["alter-0303"], journals: ["jama-oncology"] }),
  p({ id: "paper-astrum-005-jama-2022", name: "Effect of First-Line Serplulimab vs Placebo Added to Chemotherapy on Survival in Patients With Extensive-Stage Small Cell Lung Cancer: The ASTRUM-005 Randomized Clinical Trial", tldr: "Published report from the ASTRUM-005 trial registered as NCT04063163, in JAMA (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Programmed cell death ligand 1 inhibitors combined with chemotherapy has changed the approach to first-line treatment in patients with extensive-stage small cell lung cancer (SCLC). It remained unknown whether adding a programmed cell death 1 (PD-1) inhibitor to chemotherapy provided similar or better benefits in patients with extensive-stage SCLC, which would add evidence on the efficacy of checkpoint inhibitors in the treatment of extensive-stage SCLC.\n\nObjective: To evaluate the efficacy and adverse event profile of the PD-1 inhibitor serplulimab plus chemotherapy compared with placebo plus chemotherapy as first-line treatment in patients with extensive-stage SCLC.\n\nDesign, setting, and participants: This international, double-blind, phase 3 randomized clinical trial (ASTRUM-005) enrolled patients at 114 hospital sites in 6 countries between September 12, 2019, and April 27, 2021. Of 894 patients who were screened, 585 with extensive-stage SCLC who had not previously received systemic therapy were randomized. Patients were followed up through October 22, 2021.\n\nInterventions: Patients were randomized 2:1 to receive either 4.5 mg/kg of serplulimab (n = 389) or placebo (n = 196) intravenously every 3 weeks. All patients received intravenous carboplatin and etoposide every 3 weeks for up to 12 weeks.\n\nMain outcomes and measures: The primary outcome was overall survival (prespecified significance threshold at the interim analysis, 2-sided P <.012). There were 13 secondary outcomes, including progression-free survival and adverse events.\n\nResults: Among the 585 patients who were randomized (mean age, 61.1 [SD, 8.67] years; 104 [17.8%] women), 246 (42.1%) completed the trial and 465 (79.5%) discontinued study treatment. All patients received study treatment and were included in the primary analyses. at the data cutoff (October 22, 2021) for this interim analysis, the median duration of follow-up was 12.3 months (range, 0.2-24.8 months). The median overall survival was significantly longer in the serplulimab group (15.4 months [95% CI, 13.3 months-not evaluable]) than in the placebo group (10.9 months [95% CI, 10.0-14.3 months]) (hazard ratio, 0.63 [95% CI, 0.49-0.82]; P <.001). The median progression-free survival (assessed by an independent radiology review committee) also was longer in the serplulimab group (5.7 months [95% CI, 5.5-6.9 months]) than in the placebo group (4.3 months [95% CI, 4.2-4.5 months]) (hazard ratio, 0.48 [95% CI, 0.38-0.59]). Treatment-related adverse events that were grade 3 or higher occurred in 129 patients (33.2%) in the serplulimab group and in 54 patients (27.6%) in the placebo group.\n\nConclusions and relevance: Among patients with previously untreated extensive-stage SCLC, serplulimab plus chemotherapy significantly improved overall survival compared with chemotherapy alone, supporting the use of serplulimab plus chemotherapy as the first-line treatment for this patient population.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT04063163.\n\nIndexed on Europe PMC as PubMed record 36166026 (DOI 10.1001/jama.2022.16464). Its abstract cites the registry id NCT04063163, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA", year: 2022, doi: "10.1001/jama.2022.16464", pmid: "36166026", authors: "Cheng Y, Han L, Wu L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04063163 with the most citations, so it is the natural first reading for anyone following the ASTRUM-005 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA 2022","url":"https://doi.org/10.1001/jama.2022.16464"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36166026/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36166026"},{"label":"ClinicalTrials.gov NCT04063163","url":"https://clinicaltrials.gov/study/NCT04063163"}], tags: ["europepmc-ingest"], cancers: ["sclc","extensive-stage-sclc"], drugs: ["serplulimab","platinum-etoposide"], targets: [], technologies: [], trials: ["astrum-005"], journals: ["jama"] }),
  p({ id: "paper-atlantis-lancet-respir-med-2023", name: "Combination lurbinectedin and doxorubicin versus physician's choice of chemotherapy in patients with relapsed small-cell lung cancer (ATLANTIS): a multicentre, randomised, open-label, phase 3 trial", tldr: "Published report from the ATLANTIS trial registered as NCT02566993, in The Lancet. Respiratory medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Lurbinectedin is a synthetic marine-derived anticancer agent that acts as a selective inhibitor of oncogenic transcription. Lurbinectedin monotherapy (3·2 mg/m 2 every 3 weeks) received accelerated approval from the US Food and Drug Administration on the basis of efficacy in patients with small-cell lung cancer (SCLC) who relapsed after first-line platinum-based chemotherapy. The ATLANTIS trial assessed the efficacy and safety of combination lurbinectedin and the anthracycline doxorubicin as second-line treatment for SCLC.\n\nMethods: In this phase 3, open-label, randomised study, adult patients aged 18 years or older with SCLC who relapsed after platinum-based chemotherapy were recruited from 135 hospitals across North America, South America, Europe, and the Middle East. Patients were randomly assigned (1:1) centrally by dynamic allocation to intravenous lurbinectedin 2·0 mg/m 2 plus doxorubicin 40·0 mg/m 2 administered on day 1 of 21-day cycles or physician's choice of control therapy (intravenous topotecan 1·5 mg/m 2 on days 1-5 of 21-day cycles; or intravenous cyclophosphamide 1000 mg/m 2, doxorubicin 45·0 mg/m 2, and vincristine 2·0 mg on day 1 of 21-day cycles [CAV]) administered until disease progression or unacceptable toxicity. Primary granulocyte-colony stimulating factor prophylaxis was mandatory in both treatment groups. Neither patients nor clinicians were masked to treatment allocation, but the independent review committee, which assessed outcomes, was masked to patients' treatment allocation. The primary endpoint was overall survival in the intention-to-treat population. This trial is registered with ClinicalTrials.gov, NCT02566993, and with EudraCT, 2015-001641-89, and is complete.\n\nFindings: Between Aug 30, 2016, and Aug 20, 2018, 613 patients were randomly assigned to lurbinectedin plus doxorubicin (n=307) or control (topotecan, n=127; CAV, n=179) and comprised the intention-to-treat population; safety endpoints were assessed in patients who had received any partial or complete study treatment infusions (lurbinectedin plus doxorubicin, n=303; control, n=289). After a median follow-up of 24·1 months (95% CI 21·7-26·3), 303 patients in the lurbinectedin plus doxorubicin group and 289 patients in the control group had discontinued study treatment; progressive disease was the most common reason for discontinuation (213 [70%] patients in the lurbinectedin plus doxorubicin group vs 152 [53%] in the control group). Median overall survival was 8·6 months (95% CI 7·1-9·4) in the lurbinectedin plus doxorubicin group versus 7·6 months (6·6-8·2) in the control group (stratified log-rank p=0·90; hazard ratio 0·97 [95% CI 0·82-1·15], p=0·70). 12 patients died because of treatment-related adverse events: two (<1%) of 303 in the lurbinectedin plus doxorubicin group and ten (3%) of 289 in the control group. 296 (98%) of 303 patients in the lurbinectedin plus doxorubicin group had treatment-emergent adverse events compared with 284 (98%) of 289 patients in the control group; treatment-related adverse events occurred in 268 (88%) patients in the lurbinectedin plus doxorubicin group and 266 (92%) patients in the control group. Grade 3 or worse haematological adverse events were less frequent in the lurbinectedin plus doxorubicin group than the control group (anaemia, 57 [19%] of 302 patients in the lurbinectedin plus doxorubicin group vs 110 [38%] of 288 in the control group; neutropenia, 112 [37%] vs 200 [69%]; thrombocytopenia, 42 [14%] vs 90 [31%]). The frequency of treatment-related adverse events leading to treatment discontinuation was lower in the lurbinectedin plus doxorubicin group than in the control group (26 [9%] of 303 patients in the lurbinectedin plus doxorubicin group vs 47 [16%] of 289 in the control group).\n\nInterpretation: Combination therapy with lurbinectedin plus doxorubicin did not improve overall survival versus control in patients with relapsed SCLC. However, lurbinectedin plus doxorubicin showed a favourable haematological safety profile compared with control.\n\nFunding: PharmaMar.\n\nIndexed on Europe PMC as PubMed record 36252599 (DOI 10.1016/s2213-2600(22)00309-5). Its abstract cites the registry id NCT02566993, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2023, doi: "10.1016/s2213-2600(22)00309-5", pmid: "36252599", authors: "Aix SP, Ciuleanu TE, Navarro A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02566993 with the most citations, so it is the natural first reading for anyone following the ATLANTIS trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2023","url":"https://doi.org/10.1016/s2213-2600(22)00309-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36252599/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36252599"},{"label":"ClinicalTrials.gov NCT02566993","url":"https://clinicaltrials.gov/study/NCT02566993"}], tags: ["europepmc-ingest"], cancers: ["sclc"], drugs: ["lurbinectedin","topotecan"], targets: [], technologies: [], trials: ["atlantis"] }),
  p({ id: "paper-calgb-140503-n-engl-j-med-2023", name: "Lobar or Sublobar Resection for Peripheral Stage IA Non-Small-Cell Lung Cancer", tldr: "Published report from the CALGB 140503 trial registered as NCT00499330, in New England Journal of Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The increased detection of small-sized peripheral non-small-cell lung cancer (NSCLC) has renewed interest in sublobar resection in lieu of lobectomy.\n\nMethods: We conducted a multicenter, noninferiority, phase 3 trial in which patients with NSCLC clinically staged as T1aN0 (tumor size, ≤2 cm) were randomly assigned to undergo sublobar resection or lobar resection after intraoperative confirmation of node-negative disease. The primary end point was disease-free survival, defined as the time between randomization and disease recurrence or death from any cause. Secondary end points were overall survival, locoregional and systemic recurrence, and pulmonary functions.\n\nResults: From June 2007 through March 2017, a total of 697 patients were assigned to undergo sublobar resection (340 patients) or lobar resection (357 patients). After a median follow-up of 7 years, sublobar resection was noninferior to lobar resection for disease-free survival (hazard ratio for disease recurrence or death, 1.01; 90% confidence interval [CI], 0.83 to 1.24). In addition, overall survival after sublobar resection was similar to that after lobar resection (hazard ratio for death, 0.95; 95% CI, 0.72 to 1.26). The 5-year disease-free survival was 63.6% (95% CI, 57.9 to 68.8) after sublobar resection and 64.1% (95% CI, 58.5 to 69.0) after lobar resection. The 5-year overall survival was 80.3% (95% CI, 75.5 to 84.3) after sublobar resection and 78.9% (95% CI, 74.1 to 82.9) after lobar resection. No substantial difference was seen between the two groups in the incidence of locoregional or distant recurrence. At 6 months postoperatively, a between-group difference of 2 percentage points was measured in the median percentage of predicted forced expiratory volume in 1 second, favoring the sublobar-resection group.\n\nConclusions: In patients with peripheral NSCLC with a tumor size of 2 cm or less and pathologically confirmed node-negative disease in the hilar and mediastinal lymph nodes, sublobar resection was not inferior to lobectomy with respect to disease-free survival. Overall survival was similar with the two procedures. (Funded by the National Cancer Institute and others; CALGB 140503 ClinicalTrials.gov number, NCT00499330.).\n\nIndexed on Europe PMC as PubMed record 36780674 (DOI 10.1056/nejmoa2212083). Its abstract cites the registry id NCT00499330, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2212083", pmid: "36780674", authors: "Altorki N, Wang X, Kozono D, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00499330 with the most citations, so it is the natural first reading for anyone following the CALGB 140503 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2212083"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36780674/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36780674"},{"label":"ClinicalTrials.gov NCT00499330","url":"https://clinicaltrials.gov/study/NCT00499330"}], tags: ["europepmc-ingest"], cancers: ["nsclc","resectable-nsclc"], drugs: [], targets: [], technologies: ["robotic-surgery","low-dose-ct-screening"], trials: ["calgb-140503"], journals: ["nejm"] }),
  p({ id: "paper-camel-lancet-respir-med-2021", name: "Camrelizumab plus carboplatin and pemetrexed versus chemotherapy alone in chemotherapy-naive patients with advanced non-squamous non-small-cell lung cancer (CameL): a randomised, open-label, multicentre, phase 3 trial", tldr: "Published report from the CameL trial registered as NCT03134872, in The Lancet. Respiratory medicine (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Immunotherapy combined with chemotherapy has been shown to be efficacious as treatment for advanced non-squamous non-small-cell lung cancer (NSCLC) without targetable genetic aberrations; however, there is scarce evidence of the effectiveness of the combinations in the Asian population. We evaluated camrelizumab plus chemotherapy against non-squamous NSCLC in China.\n\nMethods: We did a randomised, open-label, multicentre, phase 3 trial (CameL) in 52 hospitals in China for patients with non-squamous NSCLC without EGFR and ALK alteration. Eligible patients were aged 18-70 years and had no previous systemic chemotherapy, Eastern Cooperative Oncology Group performance status of 0 or 1, and at least one measurable lesion per Response Evaluation Criteria in Solid Tumors (version 1.1). Patients were randomly assigned (1:1) to receive 4-6 cycles of carboplatin (area under curve 5 mg/mL per min) plus pemetrexed (500 mg/m 2) with or without camrelizumab (200 mg) every 3 weeks, followed by maintenance therapy with camrelizumab plus pemetrexed or pemetrexed alone. Medication was administered intravenously on day 1 of each 3-week treatment cycle. Randomisation was done using a centralised interactive web-response system with the block size randomly generated as four or six and stratified by sex and smoking history. The two primary endpoints were progression-free survival per blinded independent central review, in all patients and in patients who were PD-L1 positive. Primary analysis was done in the full analysis set that included all randomly assigned patients who received at least one dose of the study treatment. Herein, due to the primary endpoint being met at the interim analysis, we reported the findings of prespecified interim analysis, which only included confirmatory statistical testing for progression-free survival in all patients. Safety was assessed in the as-treated population. This study is registered with ClinicalTrials.gov, NCT03134872 (follow-up is ongoing).\n\nFindings: Between May 12, 2017, and June 6, 2018, of the 419 patients who were randomly assigned, seven did not receive assigned treatment and 412 received either camrelizumab plus chemotherapy (n=205) or chemotherapy alone (n=207). At interim analysis, median follow-up duration was 11·9 months (IQR 9·0-14·9). Progression-free survival in this interim analysis was significantly prolonged with camrelizumab plus chemotherapy than with chemotherapy alone (median 11·3 months [95% CI 9·6-15·4] vs 8·3 months [6·0-9·7]; hazard ratio 0·60 [0·45-0·79]; one-sided p=0·0001). Most common grade 3 or worse treatment-related adverse events were decreased neutrophil count (78 [38%] patients in the camrelizumab plus chemotherapy group vs 63 [30%] patients in the chemotherapy alone group), decreased white blood cell count (40 [20%] vs 30 [14%]), anaemia (38 [19%] vs 23 [11%]), and decreased platelet count (34 [17%] vs 24 [12%]). Serious treatment-related adverse events occurred in 74 (36%) patients in the camrelizumab plus chemotherapy group and 27 (13%) patients in the chemotherapy alone group.\n\nInterpretation: The primary endpoint was met at the interim analysis, showing a statistically significant and clinically meaningful improvement in progression-free survival with camrelizumab plus carboplatin and pemetrexed versus chemotherapy alone in all patients, supporting camrelizumab plus carboplatin and pemetrexed as a first-line treatment option for Chinese patients with advanced non-squamous NSCLC without EGFR and ALK alterations. The trial is being continued to collect long-term outcomes in all patients and carry out confirmatory statistical testing for progression-free survival in the PD-L1-positive population.\n\nFunding: Jiangsu Hengrui Medicine.\n\nIndexed on Europe PMC as PubMed record 33347829 (DOI 10.1016/s2213-2600(20)30365-9). Its abstract cites the registry id NCT03134872, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2021, doi: "10.1016/s2213-2600(20)30365-9", pmid: "33347829", authors: "Zhou C, Chen G, Huang Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03134872 with the most citations, so it is the natural first reading for anyone following the CameL trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2021","url":"https://doi.org/10.1016/s2213-2600(20)30365-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33347829/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33347829"},{"label":"ClinicalTrials.gov NCT03134872","url":"https://clinicaltrials.gov/study/NCT03134872"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["camrelizumab","carboplatin","pemetrexed"], targets: [], technologies: ["checkpoint-inhibitor"], trials: ["camel"] }),
  p({ id: "paper-camel-j-thorac-oncol-2023-update", name: "Camrelizumab Plus Carboplatin and Pemetrexed as First-Line Treatment for Advanced Nonsquamous NSCLC: Extended Follow-Up of CameL Phase 3 Trial", tldr: "Later report from the CameL trial registered as NCT03134872, in Journal of Thoracic Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Introduction: In CameL phase 3 study (ClinicalTrials.gov: NCT03134872), addition of camrelizumab to first-line chemotherapy significantly improved the progression-free survival in patients with stages IIIB to IV nonsquamous NSCLC. Here, we present outcomes after a minimum follow-up of 43.9 months since last patient randomization.\n\nMethods: Eligible patients were randomized 1:1 to 4 to 6 cycles of camrelizumab plus carboplatin and pemetrexed or chemotherapy alone every 3 weeks, followed by maintenance camrelizumab plus pemetrexed or pemetrexed only (n = 205 and 207, respectively). Total camrelizumab exposure was up to 2 years.\n\nResults: at January 31, 2022, camrelizumab plus chemotherapy exhibited substantially improved overall survival over chemotherapy alone (median, 27.1 versus 19.8 mo; hazard ratio = 0.72 [95% confidence interval: 0.57-0.92]). In the chemotherapy-alone group, 95 patients (45.9%) crossed over to camrelizumab monotherapy. After adjustment for crossover, the survival benefit with camrelizumab plus chemotherapy was more pronounced (adjusted hazard ratio = 0.55 [95% confidence interval: 0.42-0.71]). In camrelizumab plus chemotherapy group, 33 patients completed 2 years of camrelizumab. Objective response rate was 97.0%, with ongoing responses in 17 of the 32 responses (53.1%), and 93.9% (31 of 33) of the patients were alive at data cutoff. Safety profiles were consistent with the previous report, and no obvious evidence of cumulative toxicity was found with long exposure to camrelizumab.\n\nConclusions: Camrelizumab plus carboplatin and pemetrexed provides long-term survival benefit over chemotherapy, with manageable toxicity and remarkable and durable response in patients receiving 2 years of camrelizumab, further supporting camrelizumab combination as first-line treatment for advanced nonsquamous NSCLC.\n\nIndexed on Europe PMC as PubMed record 36646210 (DOI 10.1016/j.jtho.2022.12.017). Its abstract cites the registry id NCT03134872, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2023, doi: "10.1016/j.jtho.2022.12.017", pmid: "36646210", authors: "Zhou C, Chen G, Huang Y, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CameL trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Thorac Oncol 2023","url":"https://doi.org/10.1016/j.jtho.2022.12.017"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36646210/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36646210"},{"label":"ClinicalTrials.gov NCT03134872","url":"https://clinicaltrials.gov/study/NCT03134872"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["camrelizumab","carboplatin","pemetrexed"], targets: [], technologies: ["checkpoint-inhibitor"], trials: ["camel"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-capstone-1-lancet-oncol-2022", name: "Adebrelimab or placebo plus carboplatin and etoposide as first-line treatment for extensive-stage small-cell lung cancer (CAPSTONE-1): a multicentre, randomised, double-blind, placebo-controlled, phase 3 trial", tldr: "Published report from the CAPSTONE-1 trial registered as NCT03711305, in The Lancet Oncology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Extensive-stage small-cell lung cancer (ES-SCLC) is associated with poor prognosis and treatment options are scarce. Immunotherapy has shown robust clinical activity in ES-SCLC in previous phase 3 trials. We aimed to assess the efficacy and safety of adebrelimab (SHR-1316), a novel anti-PD-L1 antibody, with standard chemotherapy as a first-line treatment for ES-SCLC.\n\nMethods: The CAPSTONE-1 study was a randomised, double-blind, placebo-controlled, phase 3 trial, done in 47 tertiary hospitals in China. Key inclusion criteria were patients aged 18-75 years, with previously untreated histologically or cytologically confirmed ES-SCLC and an Eastern Cooperative Oncology Group (ECOG) performance status of 0-1. Eligible patients were randomly assigned (1:1) to receive four to six cycles of carboplatin (area under the curve of 5 mg/mL per min, day 1 of each cycle) and etoposide (100 mg/m 2 of body-surface area, on days 1-3 of each cycle) with either adebrelimab (20 mg/kg, day 1 of each cycle) or matching placebo, followed by maintenance therapy with adebrelimab or placebo. All treatments were given intravenously in 21-day cycles. Randomisation was done using a centralised interactive web response system with a block size of four, stratified by liver metastases, brain metastases, and lactate dehydrogenase concentration. The primary endpoint was overall survival in patients who received at least one dose of study medication. Safety was analysed in the as-treated population. This study is complete and registered with ClinicalTrials.gov, NCT03711305.\n\nFindings: Between Dec 26, 2018, and Sept 4, 2020, 462 eligible patients were enrolled and randomly assigned: 230 (50%) patients received adebrelimab plus chemotherapy (adebrelimab group) and 232 (50%) patients received placebo plus chemotherapy (placebo group). At data cutoff (Oct 8, 2021), median follow-up was 13·5 months (IQR 8·9-20·1). Median overall survival was significantly improved in the adebrelimab group (median 15·3 months [95% CI 13·2-17·5]) compared with the placebo group (12·8 months [11·3-13·7]; hazard ratio 0·72 [95% CI 0·58-0·90]; one-sided p=0·0017). The most common treatment-related grade 3 or 4 adverse events were decreased neutrophil count (174 [76%] patients in the adebrelimab group and 175 [75%] patients in the placebo group), decreased white blood cell count (106 [46%] and 88 [38%]), decreased platelet count (88 [38%] and 78 [34%]), and anaemia (64 [28%] and 66 [28%]). Treatment-related serious adverse events occurred in 89 (39%) patients in the adebrelimab group and 66 (28%) patients in the placebo group. Four treatment-related deaths were reported: two each in the adebrelimab group (respiratory failure and interstitial lung disease and pneumonia) and placebo group (multiple organ dysfunction and unknown cause of death).\n\nInterpretation: Adding adebrelimab to chemotherapy significantly improved overall survival with an acceptable safety profile in patients with ES-SCLC, supporting this combination as a new first-line treatment option for this population.\n\nFunding: Jiangsu Hengrui Pharmaceuticals.\n\nIndexed on Europe PMC as PubMed record 35576956 (DOI 10.1016/s1470-2045(22)00224-8). Its abstract cites the registry id NCT03711305, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2022, doi: "10.1016/s1470-2045(22)00224-8", pmid: "35576956", authors: "Wang J, Zhou C, Yao W, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03711305 with the most citations, so it is the natural first reading for anyone following the CAPSTONE-1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2022","url":"https://doi.org/10.1016/s1470-2045(22)00224-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35576956/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35576956"},{"label":"ClinicalTrials.gov NCT03711305","url":"https://clinicaltrials.gov/study/NCT03711305"}], tags: ["europepmc-ingest"], cancers: ["sclc"], drugs: ["adebrelimab","carboplatin","etoposide"], targets: [], technologies: ["checkpoint-inhibitor"], trials: ["capstone-1"], journals: ["lancet-oncology"] }),
  p({ id: "paper-caspian-lancet-2019", name: "Durvalumab plus platinum-etoposide versus platinum-etoposide in first-line treatment of extensive-stage small-cell lung cancer (CASPIAN): a randomised, controlled, open-label, phase 3 trial", tldr: "Published report from the CASPIAN trial registered as NCT03043872, in The Lancet (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Most patients with small-cell lung cancer (SCLC) have extensive-stage disease at presentation, and prognosis remains poor. Recently, immunotherapy has demonstrated clinical activity in extensive-stage SCLC (ES-SCLC). The CASPIAN trial assessed durvalumab, with or without tremelimumab, in combination with etoposide plus either cisplatin or carboplatin (platinum-etoposide) in treatment-naive patients with ES-SCLC.\n\nMethods: This randomised, open-label, phase 3 trial was done at 209 sites across 23 countries. Eligible patients were adults with untreated ES-SCLC, with WHO performance status 0 or 1 and measurable disease as per Response Evaluation Criteria in Solid Tumors, version 1.1. Patients were randomly assigned (in a 1:1:1 ratio) to durvalumab plus platinum-etoposide; durvalumab plus tremelimumab plus platinum-etoposide; or platinum-etoposide alone. All drugs were administered intravenously. Platinum-etoposide consisted of etoposide 80-100 mg/m 2 on days 1-3 of each cycle with investigator's choice of either carboplatin area under the curve 5-6 mg/mL per min or cisplatin 75-80 mg/m 2 (administered on day 1 of each cycle). Patients received up to four cycles of platinum-etoposide plus durvalumab 1500 mg with or without tremelimumab 75 mg every 3 weeks followed by maintenance durvalumab 1500 mg every 4 weeks in the immunotherapy groups and up to six cycles of platinum-etoposide every 3 weeks plus prophylactic cranial irradiation (investigator's discretion) in the platinum-etoposide group. The primary endpoint was overall survival in the intention-to-treat population. We report results for the durvalumab plus platinum-etoposide group versus the platinum-etoposide group from a planned interim analysis. Safety was assessed in all patients who received at least one dose of their assigned study treatment. This study is registered at ClinicalTrials.gov, NCT03043872, and is ongoing.\n\nFindings: Patients were enrolled between March 27, 2017, and May 29, 2018. 268 patients were allocated to the durvalumab plus platinum-etoposide group and 269 to the platinum-etoposide group. Durvalumab plus platinum-etoposide was associated with a significant improvement in overall survival, with a hazard ratio of 0·73 (95% CI 0·59-0·91; p=0·0047]); median overall survival was 13·0 months (95% CI 11·5-14·8) in the durvalumab plus platinum-etoposide group versus 10·3 months (9·3-11·2) in the platinum-etoposide group, with 34% (26·9-41·0) versus 25% (18·4-31·6) of patients alive at 18 months. Any-cause adverse events of grade 3 or 4 occurred in 163 (62%) of 265 treated patients in the durvalumab plus platinum-etoposide group and 166 (62%) of 266 in the platinum-etoposide group; adverse events leading to death occurred in 13 (5%) and 15 (6%) patients.\n\nInterpretation: First-line durvalumab plus platinum-etoposide significantly improved overall survival in patients with ES-SCLC versus a clinically relevant control group. Safety findings were consistent with the known safety profiles of all drugs received.\n\nFunding: AstraZeneca.\n\nIndexed on Europe PMC as PubMed record 31590988 (DOI 10.1016/s0140-6736(19)32222-6). Its abstract cites the registry id NCT03043872, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2019, doi: "10.1016/s0140-6736(19)32222-6", pmid: "31590988", authors: "Paz-Ares L, Dvorkin M, Chen Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03043872 with the most citations, so it is the natural first reading for anyone following the CASPIAN trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2019","url":"https://doi.org/10.1016/s0140-6736(19)32222-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31590988/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31590988"},{"label":"ClinicalTrials.gov NCT03043872","url":"https://clinicaltrials.gov/study/NCT03043872"}], tags: ["europepmc-ingest"], cancers: ["sclc","extensive-stage-sclc"], drugs: ["durvalumab","tremelimumab","platinum-etoposide"], targets: [], technologies: [], trials: ["caspian"], journals: ["lancet"] }),
  p({ id: "paper-caspian-lancet-oncol-2021-update", name: "Durvalumab, with or without tremelimumab, plus platinum-etoposide versus platinum-etoposide alone in first-line treatment of extensive-stage small-cell lung cancer (CASPIAN): updated results from a randomised, controlled, open-label, phase 3 trial", tldr: "Later report from the CASPIAN trial registered as NCT03043872, in The Lancet Oncology (2021); its title describes an updated or longer-term analysis.", summary: "Background: First-line durvalumab plus etoposide with either cisplatin or carboplatin (platinum-etoposide) showed a significant improvement in overall survival versus platinum-etoposide alone in patients with extensive-stage small-cell lung cancer (ES-SCLC) in the CASPIAN study. Here we report updated results, including the primary analysis for overall survival with durvalumab plus tremelimumab plus platinum-etoposide versus platinum-etoposide alone.\n\nMethods: CASPIAN is an ongoing, open-label, sponsor-blind, randomised, controlled phase 3 trial at 209 cancer treatment centres in 23 countries worldwide. Eligible patients were aged 18 years or older (20 years in Japan) and had treatment-naive, histologically or cytologically documented ES-SCLC, with a WHO performance status of 0 or 1. Patients were randomly assigned (1:1:1) in blocks of six, stratified by planned platinum, using an interactive voice-response or web-response system to receive intravenous durvalumab plus tremelimumab plus platinum-etoposide, durvalumab plus platinum-etoposide, or platinum-etoposide alone. In all groups, patients received etoposide 80-100 mg/m 2 on days 1-3 of each cycle with investigator's choice of either carboplatin area under the curve 5-6 mg/mL/min or cisplatin 75-80 mg/m 2 on day 1 of each cycle. Patients in the platinum-etoposide group received up to six cycles of platinum-etoposide every 3 weeks and optional prophylactic cranial irradiation (investigator's discretion). Patients in the immunotherapy groups received four cycles of platinum-etoposide plus durvalumab 1500 mg with or without tremelimumab 75 mg every 3 weeks followed by maintenance durvalumab 1500 mg every 4 weeks. The two primary endpoints were overall survival for durvalumab plus platinum-etoposide versus platinum-etoposide and for durvalumab plus tremelimumab plus platinum-etoposide versus platinum-etoposide in the intention-to-treat population. Safety was assessed in all patients who received at least one dose of study treatment. This study is registered at ClinicalTrials.gov, NCT03043872.\n\nFindings: Between March 27, 2017, and May 29, 2018, 972 patients were screened and 805 were randomly assigned (268 to durvalumab plus tremelimumab plus platinum-etoposide, 268 to durvalumab plus platinum-etoposide, and 269 to platinum-etoposide). at Jan 27, 2020, the median follow-up was 25·1 months (IQR 22·3-27·9). Durvalumab plus tremelimumab plus platinum-etoposide was not associated with a significant improvement in overall survival versus platinum-etoposide (hazard ratio [HR] 0·82 [95% CI 0·68-1·00]; p=0·045); median overall survival was 10·4 months (95% CI 9·6-12·0) versus 10·5 months (9·3-11·2). Durvalumab plus platinum-etoposide showed sustained improvement in overall survival versus platinum-etoposide (HR 0·75 [95% CI 0·62-0·91]; nominal p=0·0032); median overall survival was 12·9 months (95% CI 11·3-14·7) versus 10·5 months (9·3-11·2). The most common any-cause grade 3 or worse adverse events were neutropenia (85 [32%] of 266 patients in the durvalumab plus tremelimumab plus platinum-etoposide group, 64 [24%] of 265 patients in the durvalumab plus platinum-etoposide group, and 88 [33%] of 266 patients in the platinum-etoposide group) and anaemia (34 [13%], 24 [9%], and 48 [18%]). Any-cause serious adverse events were reported in 121 (45%) patients in the durvalumab plus tremelimumab plus platinum-etoposide group, 85 (32%) in the durvalumab plus platinum-etoposide group, and 97 (36%) in the platinum-etoposide group. Treatment-related deaths occurred in 12 (5%) patients in the durvalumab plus tremelimumab plus platinum-etoposide group (death, febrile neutropenia, and pulmonary embolism [n=2 each]; enterocolitis, general physical health deterioration and multiple organ dysfunction syndrome, pneumonia, pneumonitis and hepatitis, respiratory failure, and sudden death [n=1 each]), six (2%) patients in the durvalumab plus platinum-etoposide group (cardiac arrest, dehydration, hepatotoxicity, interstitial lung disease, pancytopenia, and sepsis [n=1 each]), and two (1%) in the platinum-etoposide group (pancytopenia and thrombocytopenia [n=1 each]).\n\nInterpretation: First-line durvalumab plus platinum-etoposide showed sustained overall survival improvement versus platinum-etoposide but the addition of tremelimumab to durvalumab plus platinum-etoposide did not significantly improve outcomes versus platinum-etoposide. These results support the use of durvalumab plus platinum-etoposide as a new standard of care for the first-line treatment of ES-SCLC.\n\nFunding: AstraZeneca.\n\nIndexed on Europe PMC as PubMed record 33285097 (DOI 10.1016/s1470-2045(20)30539-8). Its abstract cites the registry id NCT03043872, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2021, doi: "10.1016/s1470-2045(20)30539-8", pmid: "33285097", authors: "Goldman JW, Dvorkin M, Chen Y, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CASPIAN trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2021","url":"https://doi.org/10.1016/s1470-2045(20)30539-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33285097/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33285097"},{"label":"ClinicalTrials.gov NCT03043872","url":"https://clinicaltrials.gov/study/NCT03043872"}], tags: ["europepmc-ingest"], cancers: ["sclc","extensive-stage-sclc"], drugs: ["durvalumab","tremelimumab","platinum-etoposide"], targets: [], technologies: [], trials: ["caspian"], journals: ["lancet-oncology"] }),
  p({ id: "paper-checkmate-227-n-engl-j-med-2018", name: "Nivolumab plus Ipilimumab in Lung Cancer with a High Tumor Mutational Burden", tldr: "Published report from the CheckMate 227 trial registered as NCT02477826, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Nivolumab plus ipilimumab showed promising efficacy for the treatment of non-small-cell lung cancer (NSCLC) in a phase 1 trial, and tumor mutational burden has emerged as a potential biomarker of benefit. In this part of an open-label, multipart, phase 3 trial, we examined progression-free survival with nivolumab plus ipilimumab versus chemotherapy among patients with a high tumor mutational burden (≥10 mutations per megabase).\n\nMethods: We enrolled patients with stage IV or recurrent NSCLC that was not previously treated with chemotherapy. Those with a level of tumor programmed death ligand 1 (PD-L1) expression of at least 1% were randomly assigned, in a 1:1:1 ratio, to receive nivolumab plus ipilimumab, nivolumab monotherapy, or chemotherapy; those with a tumor PD-L1 expression level of less than 1% were randomly assigned, in a 1:1:1 ratio, to receive nivolumab plus ipilimumab, nivolumab plus chemotherapy, or chemotherapy. Tumor mutational burden was determined by the FoundationOne CDx assay.\n\nResults: Progression-free survival among patients with a high tumor mutational burden was significantly longer with nivolumab plus ipilimumab than with chemotherapy. The 1-year progression-free survival rate was 42.6% with nivolumab plus ipilimumab versus 13.2% with chemotherapy, and the median progression-free survival was 7.2 months (95% confidence interval [CI], 5.5 to 13.2) versus 5.5 months (95% CI, 4.4 to 5.8) (hazard ratio for disease progression or death, 0.58; 97.5% CI, 0.41 to 0.81; P<0.001). The objective response rate was 45.3% with nivolumab plus ipilimumab and 26.9% with chemotherapy. The benefit of nivolumab plus ipilimumab over chemotherapy was broadly consistent within subgroups, including patients with a PD-L1 expression level of at least 1% and those with a level of less than 1%. The rate of grade 3 or 4 treatment-related adverse events was 31.2% with nivolumab plus ipilimumab and 36.1% with chemotherapy. ical; CheckMate 227 ClinicalTrials.gov number, NCT02477826.).\n\nConclusions: Progression-free survival was significantly longer with first-line nivolumab plus ipilimumab than with chemotherapy among patients with NSCLC and a high tumor mutational burden, irrespective of PD-L1 expression level. The results validate the benefit of nivolumab plus ipilimumab in NSCLC and the role of tumor mutational burden as a biomarker for patient selection. (Funded by Bristol-Myers Squibb and Ono Pharmaceut\n\nIndexed on Europe PMC as PubMed record 29658845 (DOI 10.1056/nejmoa1801946). Its abstract cites the registry id NCT02477826, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1801946", pmid: "29658845", authors: "Hellmann MD, Ciuleanu TE, Pluzanski A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02477826 with the most citations, so it is the natural first reading for anyone following the CheckMate 227 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1801946"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/29658845/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/29658845"},{"label":"ClinicalTrials.gov NCT02477826","url":"https://clinicaltrials.gov/study/NCT02477826"}], tags: ["europepmc-ingest"], cancers: ["pdl1-high-nsclc","nsclc","lung-cancer"], drugs: ["nivolumab","ipilimumab"], targets: [], technologies: [], trials: ["checkmate-227"], journals: ["nejm"] }),
  p({ id: "paper-checkmate-227-int-j-clin-oncol-2023-update", name: "First-line nivolumab plus ipilimumab in metastatic non-small cell lung cancer: 5-year outcomes in Japanese patients from CheckMate 227 Part 1", tldr: "Later report from the CheckMate 227 trial registered as NCT02477826, in International journal of clinical oncology (2023); its title describes an updated or longer-term analysis.", summary: "Background: In CheckMate 227 Part 1 (NCT02477826), first-line nivolumab plus ipilimumab demonstrated long-term durable overall survival (OS) benefit versus chemotherapy in patients with metastatic non-small cell lung cancer (NSCLC), regardless of tumor programmed death ligand 1 (PD-L1) expression. We report results in Japanese patients with ≥ 5-year follow-up.\n\nMethods: Adults with stage IV/recurrent NSCLC without EGFR/ALK aberrations were randomized 1:1:1 to nivolumab plus ipilimumab, nivolumab alone, or chemotherapy (patients with tumor PD-L1 ≥ 1%), or nivolumab plus ipilimumab, nivolumab plus chemotherapy, or chemotherapy (patients with tumor PD-L1 < 1%). Five-year efficacy and safety were assessed in Japanese patients.\n\nResults: At 62.1 months' minimum follow-up, 143 Japanese patients with PD-L1 ≥ 1% or < 1% were randomized to nivolumab plus ipilimumab (n = 66) or chemotherapy (n = 77). Five-year OS rates were 46% with nivolumab plus ipilimumab versus 34% with chemotherapy (PD-L1 ≥ 1%) and 36% versus 19% (PD-L1 < 1%). Median duration of response was 59.1 versus 7.1 months (PD-L1 ≥ 1%) and 17.3 versus 3.0 months (PD-L1 < 1%). Among 5-year survivors treated with nivolumab plus ipilimumab (PD-L1 ≥ 1% and < 1%; n = 27), 59% (95% CI, 39%-75%) were off treatment for ≥ 3 years without receiving subsequent therapy. No new safety signals were observed.\n\nConclusions: At 5-year follow-up, nivolumab plus ipilimumab continued to show long-term durable clinical benefit versus chemotherapy, regardless of tumor PD-L1 expression. Consistent with findings for the global population, these data support the use of nivolumab plus ipilimumab as first-line treatment in Japanese patients with metastatic NSCLC.\n\nIndexed on Europe PMC as PubMed record 37548831 (DOI 10.1007/s10147-023-02390-2). Its abstract cites the registry id NCT02477826, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "International journal of clinical oncology", year: 2023, doi: "10.1007/s10147-023-02390-2", pmid: "37548831", authors: "Nishio M, Ohe Y, Ikeda S, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CheckMate 227 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Int J Clin Oncol 2023","url":"https://doi.org/10.1007/s10147-023-02390-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37548831/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37548831"},{"label":"ClinicalTrials.gov NCT02477826","url":"https://clinicaltrials.gov/study/NCT02477826"}], tags: ["europepmc-ingest"], cancers: ["pdl1-high-nsclc","nsclc","lung-cancer"], drugs: ["nivolumab","ipilimumab"], targets: [], technologies: [], trials: ["checkmate-227"], journals: ["international-journal-of-clinical-oncology"] }),
  p({ id: "paper-checkmate-816-n-engl-j-med-2025-update", name: "Overall Survival with Neoadjuvant Nivolumab plus Chemotherapy in Lung Cancer", tldr: "Later report from the CheckMate 816 trial registered as NCT02998528, in New England Journal of Medicine (2025); its title describes an updated or longer-term analysis.", summary: "Background: Neoadjuvant nivolumab plus chemotherapy significantly improved pathological complete response and event-free survival in patients with resectable non-small-cell lung cancer (NSCLC) in a phase 3 trial. Data are needed on overall survival.\n\nMethods: In this open-label, phase 3 trial, patients with stage IB to IIIA resectable NSCLC were randomly assigned to receive nivolumab plus chemotherapy or chemotherapy alone for three cycles, followed by surgery. The primary end points were event-free survival and pathological complete response. Here, we report the results of the planned analysis of overall survival.\n\nResults: A total of 358 patients were concurrently assigned to receive nivolumab plus chemotherapy (179 patients) or chemotherapy alone (179 patients). The final analysis of overall survival significantly favored neoadjuvant nivolumab plus chemotherapy over chemotherapy (hazard ratio for death, 0.72; 95% confidence interval [CI], 0.523 to 0.998; P = 0.048). At a median follow-up of 68.4 months, the 5-year overall survival was 65.4% with nivolumab plus chemotherapy and 55.0% with chemotherapy alone, with consistency across most subgroups. In exploratory analyses, the 5-year overall survival in the nivolumab-plus-chemotherapy group was 95.3% (95% CI, 82.7 to 98.8) among the patients with a pathological complete response and 55.7% (95% CI, 46.9 to 63.7) among those without such a response; survival was 75.0% among the patients with presurgery clearance of circulating tumor DNA (ctDNA) and 52.6% among those without such clearance. No new safety signals were observed.\n\nConclusions: Three cycles of neoadjuvant nivolumab plus chemotherapy significantly improved overall survival among patients with resectable NSCLC as compared with chemotherapy alone. (Funded by Bristol Myers Squibb; CheckMate 816 ClinicalTrials.gov number, NCT02998528.).\n\nIndexed on Europe PMC as PubMed record 40454642 (DOI 10.1056/nejmoa2502931). Its abstract cites the registry id NCT02998528, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2025, doi: "10.1056/nejmoa2502931", pmid: "40454642", authors: "Forde PM, Spicer JD, Provencio M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CheckMate 816 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"N Engl J Med 2025","url":"https://doi.org/10.1056/nejmoa2502931"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40454642/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40454642"},{"label":"ClinicalTrials.gov NCT02998528","url":"https://clinicaltrials.gov/study/NCT02998528"}], tags: ["europepmc-ingest"], cancers: ["nsclc","resectable-nsclc"], drugs: ["nivolumab"], targets: [], technologies: [], trials: ["checkmate-816"], journals: ["nejm"] }),
  p({ id: "paper-chisel-lancet-oncol-2019", name: "Stereotactic ablative radiotherapy versus standard radiotherapy in stage 1 non-small-cell lung cancer (TROG 09.02 CHISEL): a phase 3, open-label, randomised controlled trial", tldr: "Published report from the CHISEL trial registered as NCT01014130, in The Lancet Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Stereotactic ablative body radiotherapy (SABR) is widely used to treat inoperable stage 1 non-small-cell lung cancer (NSCLC), despite the absence of prospective evidence that this type of treatment improves local control or prolongs overall survival compared with standard radiotherapy. We aimed to compare the two treatment techniques.\n\nMethods: We did this multicentre, phase 3, randomised, controlled trial in 11 hospitals in Australia and three hospitals in New Zealand. Patients were eligible if they were aged 18 years or older, had biopsy-confirmed stage 1 (T1-T2aN0M0) NSCLC diagnosed on the basis of 18 F-fluorodeoxyglucose PET, and were medically inoperable or had refused surgery. Patients had to have an Eastern Cooperative Oncology Group performance status of 0 or 1, and the tumour had to be peripherally located. Patients were randomly assigned after stratification for T stage and operability in a 2:1 ratio to SABR (54 Gy in three 18 Gy fractions, or 48 Gy in four 12 Gy fractions if the tumour was <2 cm from the chest wall) or standard radiotherapy (66 Gy in 33 daily 2 Gy fractions or 50 Gy in 20 daily 2·5 Gy fractions, depending on institutional preference) using minimisation, so no sequence was pre-generated. Clinicians, patients, and data managers had no previous knowledge of the treatment group to which patients would be assigned; however, the treatment assignment was subsequently open label (because of the nature of the interventions). The primary endpoint was time to local treatment failure (assessed according to Response Evaluation Criteria in Solid Tumors version 1.0), with the hypothesis that SABR would result in superior local control compared with standard radiotherapy. All efficacy analyses were based on the intention-to-treat analysis. Safety analyses were done on a per-protocol basis, according to treatment that the patients actually received. The trial is registered with ClinicalTrials.gov (NCT01014130) and the Australia and New Zealand Clinical Trials Registry (ACTRN12610000479000). The trial is closed to new participants.\n\nFindings: Between Dec 31, 2009, and June 22, 2015, 101 eligible patients were enrolled and randomly assigned to receive SABR (n=66) or standard radiotherapy (n=35). Five (7·6%) patients in the SABR group and two (6·5%) in the standard radiotherapy group did not receive treatment, and a further four in each group withdrew before study end. at data cutoff (July 31, 2017), median follow-up for local treatment failure was 2·1 years (IQR 1·2-3·6) for patients randomly assigned to standard radiotherapy and 2·6 years (IQR 1·6-3·6) for patients assigned to SABR. 20 (20%) of 101 patients had progressed locally: nine (14%) of 66 patients in the SABR group and 11 (31%) of 35 patients in the standard radiotherapy group, and freedom from local treatment failure was improved in the SABR group compared with the standard radiotherapy group (hazard ratio 0·32, 95% CI 0·13-0·77, p=0·0077). Median time to local treatment failure was not reached in either group. In patients treated with SABR, there was one grade 4 adverse event (dyspnoea) and seven grade 3 adverse events (two cough, one hypoxia, one lung infection, one weight loss, one dyspnoea, and one fatigue) related to treatment compared with two grade 3 events (chest pain) in the standard treatment group.\n\nInterpretation: In patients with inoperable peripherally located stage 1 NSCLC, compared with standard radiotherapy, SABR resulted in superior local control of the primary disease without an increase in major toxicity. The findings of this trial suggest that SABR should be the treatment of choice for this patient group.\n\nFunding: The Radiation and Optometry Section of the Australian Government Department of Health with the assistance of Cancer Australia, and the Cancer Society of New Zealand and the Cancer Research Trust New Zealand (formerly Genesis Oncology Trust).\n\nIndexed on Europe PMC as PubMed record 30770291 (DOI 10.1016/s1470-2045(18)30896-9). Its abstract cites the registry id NCT01014130, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2019, doi: "10.1016/s1470-2045(18)30896-9", pmid: "30770291", authors: "Ball D, Mai GT, Vinod S, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01014130 with the most citations, so it is the natural first reading for anyone following the CHISEL trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2019","url":"https://doi.org/10.1016/s1470-2045(18)30896-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30770291/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30770291"},{"label":"ClinicalTrials.gov NCT01014130","url":"https://clinicaltrials.gov/study/NCT01014130"}], tags: ["europepmc-ingest"], cancers: ["nsclc","resectable-nsclc"], drugs: [], targets: [], technologies: ["sbrt","respiratory-motion-management"], trials: ["chisel"], journals: ["lancet-oncology"] }),
  p({ id: "paper-convert-lancet-oncol-2017", name: "Concurrent once-daily versus twice-daily chemoradiotherapy in patients with limited-stage small-cell lung cancer (CONVERT): an open-label, phase 3, randomised, superiority trial", tldr: "Published report from the CONVERT trial registered as NCT00433563, in The Lancet Oncology (2017), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Concurrent chemoradiotherapy is the standard of care in limited-stage small-cell lung cancer, but the optimal radiotherapy schedule and dose remains controversial. The aim of this study was to establish a standard chemoradiotherapy treatment regimen in limited-stage small-cell lung cancer.\n\nMethods: The CONVERT trial was an open-label, phase 3, randomised superiority trial. We enrolled adult patients (aged ≥18 years) who had cytologically or histologically confirmed limited-stage small-cell lung cancer, Eastern Cooperative Oncology Group performance status of 0-2, and adequate pulmonary function. Patients were recruited from 73 centres in eight countries. Patients were randomly assigned to receive either 45 Gy radiotherapy in 30 twice-daily fractions of 1·5 Gy over 19 days, or 66 Gy in 33 once-daily fractions of 2 Gy over 45 days, starting on day 22 after commencing cisplatin-etoposide chemotherapy (given as four to six cycles every 3 weeks in both groups). The allocation method used was minimisation with a random element, stratified by institution, planned number of chemotherapy cycles, and performance status. Treatment group assignments were not masked. The primary endpoint was overall survival, defined as time from randomisation until death from any cause, analysed by modified intention-to-treat. A 12% higher overall survival at 2 years in the once-daily group versus the twice-daily group was considered to be clinically significant to show superiority of the once-daily regimen. The study is registered with ClinicalTrials.gov (NCT00433563) and is currently in follow-up.\n\nFindings: Between April 7, 2008, and Nov 29, 2013, 547 patients were enrolled and randomly assigned to receive twice-daily concurrent chemoradiotherapy (274 patients) or once-daily concurrent chemoradiotherapy (273 patients). Four patients (one in the twice-daily group and three in the once-daily group) did not return their case report forms and were lost to follow-up; these patients were not included in our analyses. At a median follow-up of 45 months (IQR 35-58), median overall survival was 30 months (95% CI 24-34) in the twice-daily group versus 25 months (21-31) in the once-daily group (hazard ratio for death in the once daily group 1·18 [95% CI 0·95-1·45]; p=0·14). 2-year overall survival was 56% (95% CI 50-62) in the twice-daily group and 51% (45-57) in the once-daily group (absolute difference between the treatment groups 5·3% [95% CI -3·2% to 13·7%]). The most common grade 3-4 adverse event in patients evaluated for chemotherapy toxicity was neutropenia (197 [74%] of 266 patients in the twice-daily group vs 170 [65%] of 263 in the once-daily group). Most toxicities were similar between the groups, except there was significantly more grade 4 neutropenia with twice-daily radiotherapy (129 [49%] vs 101 [38%]; p=0·05). In patients assessed for radiotherapy toxicity, was no difference in grade 3-4 oesophagitis between the groups (47 [19%] of 254 patients in the twice-daily group vs 47 [19%] of 246 in the once-daily group; p=0·85) and grade 3-4 radiation pneumonitis (4 [3%] of 254 vs 4 [2%] of 246; p=0·70). 11 patients died from treatment-related causes (three in the twice-daily group and eight in the once-daily group).\n\nInterpretation: Survival outcomes did not differ between twice-daily and once-daily concurrent chemoradiotherapy in patients with limited-stage small-cell lung cancer, and toxicity was similar and lower than expected with both regimens. Since the trial was designed to show superiority of once-daily radiotherapy and was not powered to show equivalence, the implication is that twice-daily radiotherapy should continue to be considered the standard of care in this setting.\n\nFunding: Cancer Research UK (Clinical Trials Awards and Advisory Committee), French Ministry of Health, Canadian Cancer Society Research Institute, European Organisation for Research and Treatment of Cancer (Cancer Research Fund, Lung Cancer, and Radiation Oncology Groups).\n\nIndexed on Europe PMC as PubMed record 28642008 (DOI 10.1016/s1470-2045(17)30318-2). Its abstract cites the registry id NCT00433563, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2017, doi: "10.1016/s1470-2045(17)30318-2", pmid: "28642008", authors: "Faivre-Finn C, Snee M, Ashcroft L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00433563 with the most citations, so it is the natural first reading for anyone following the CONVERT trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2017","url":"https://doi.org/10.1016/s1470-2045(17)30318-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28642008/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28642008"},{"label":"ClinicalTrials.gov NCT00433563","url":"https://clinicaltrials.gov/study/NCT00433563"}], tags: ["europepmc-ingest"], cancers: ["sclc","limited-stage-sclc"], drugs: [], targets: [], technologies: ["imrt-igrt"], trials: ["convert"], journals: ["lancet-oncology"] }),
  p({ id: "paper-convert-int-j-radiat-oncol-biol-phys-2024-update", name: "Long-Term Outcomes After Concurrent Once- or Twice-Daily Chemoradiation in Limited-Stage Small Cell Lung Cancer: A Brief Report From the CONVERT Trial", tldr: "Later report from the CONVERT trial registered as NCT00433563, in International Journal of Radiation Oncology, Biology, Physics (2024); its title describes an updated or longer-term analysis.", summary: "Purpose: CONVERT was a phase 3 international randomized clinical trial comparing once-daily (OD) and twice-daily (BD) radiation therapy (RT). This updated analysis describes the 6.5-year outcomes of these regimens delivered with conformal techniques.\n\nMethods and materials: CONVERT (NCT00433563) randomized patients 1:1 between OD RT (66 Gy/33 fractions/6.5 weeks) and BD RT (45 Gy/30 fractions/3 weeks), both delivered with concurrent cisplatin/etoposide. Three-dimensional conformal RT was mandatory, intensity-modulated RT was permitted, and elective nodal irradiation was not allowed. Prophylactic cranial irradiation was delivered at the discretion of treating clinicians. RT treatment planning was subject to central quality assurance.\n\nResults: Five hundred forty-seven patients were recruited at 73 centers. The median follow-up for the surviving cohort (n = 164) was 81.2 months. The median survival for the OD and BD arms were 25.4 months (95% CI, 21.1-30.9) and 30.0 months (95% CI, 25.3-36.5; hazard ratio, 1.13; 95% CI, 0.92-1.38; P =.247). Performance status and tumor volume were associated with survival on multivariate analysis. No treatment-related deaths occurred subsequent to the initial analysis performed in 2017. Regarding late toxicity, 7 patients in the OD arm developed grade 3 esophagitis, 4 of which went on to develop stricture or fistulation, compared with no patients in the BD arm. Grade 3 pulmonary fibrosis occurred in 2 and 3 patients in the OD and BD arms, respectively.\n\nConclusions: As the CONVERT trial did not demonstrate the superiority of OD RT and this regimen had a slightly worse toxicity profile after 80 months of follow-up, 45 Gy BD should remain the standard of care in limited stage small cell lung cancer.\n\nIndexed on Europe PMC as PubMed record 38521132 (DOI 10.1016/j.ijrobp.2024.02.063). Its abstract cites the registry id NCT00433563, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "International Journal of Radiation Oncology, Biology, Physics", year: 2024, doi: "10.1016/j.ijrobp.2024.02.063", pmid: "38521132", authors: "Walls GM, Mistry H, Barlesi F, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CONVERT trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Int J Radiat Oncol Biol Phys 2024","url":"https://doi.org/10.1016/j.ijrobp.2024.02.063"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38521132/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38521132"},{"label":"ClinicalTrials.gov NCT00433563","url":"https://clinicaltrials.gov/study/NCT00433563"}], tags: ["europepmc-ingest"], cancers: ["sclc","limited-stage-sclc"], drugs: [], targets: [], technologies: ["imrt-igrt"], trials: ["convert"], journals: ["ijrobp"] }),
  p({ id: "paper-crown-lancet-respir-med-2023-update", name: "Efficacy and safety of first-line lorlatinib versus crizotinib in patients with advanced, ALK-positive non-small-cell lung cancer: updated analysis of data from the phase 3, randomised, open-label CROWN study", tldr: "Later report from the CROWN trial registered as NCT03052608, in The Lancet. Respiratory medicine (2023); its title describes an updated or longer-term analysis.", summary: "Background: After a median follow-up of 18·3 months, the third-generation anaplastic lymphoma kinase (ALK) tyrosine-kinase inhibitor, lorlatinib, improved progression-free survival in patients with treatment-naive, ALK-positive non-small-cell lung cancer in the phase 3 CROWN study. Here we report updated efficacy data, including intracranial activity, from an unplanned analysis after 3 years of follow-up.\n\nMethods: CROWN is an ongoing, international, randomised, open-label phase 3 trial done in 104 centres in 23 countries worldwide. Eligible participants were aged 18 years and older or aged 20 years and older (depending on local regulations) with advanced, ALK-positive non-small-cell lung cancer, had received no previous systemic treatment for metastatic disease, had at least one extracranial measurable target lesion (according to the Response Evaluation Criteria in Solid Tumours [RECIST], version 1.1), and had an Eastern Cooperative Oncology Group performance status score of 0-2. Patients were randomly assigned (1:1) to oral lorlatinib 100 mg daily or oral crizotinib 250 mg twice daily in 28-day cycles. Randomisation was stratified by the presence or absence of brain metastasis, and by ethnicity. Since the primary endpoint of the study had been met at the planned interim analysis, no further formal analysis of progression-free survival was planned, per protocol. The current unplanned analysis was done to further characterise tumour-related endpoints with a longer follow-up and is presented descriptively. For the planned study, the primary endpoint was progression-free survival assessed by blinded independent central review. Secondary endpoints included progression-free survival (investigator), objective response rate, intracranial objective response rate, time to intracranial progression, duration of response, intracranial duration of response, and safety. Efficacy endpoints were also assessed by the presence or absence of baseline brain metastases. This study is registered with ClinicalTrials.gov, NCT03052608.\n\nFindings: Between May 11, 2017, and Feb 28, 2019, 425 patients were screened for eligibility, of whom 296 were enrolled and randomly assigned to the lorlatinib (n=149) or crizotinib (n=147) group. At data cutoff for this unplanned analysis (Sept 20, 2021), median duration of follow-up for progression-free survival was 36·7 months (IQR 31·3-41·9) for lorlatinib and 29·3 months (10·8-35·0) for crizotinib. Median progression-free survival by blinded independent central review was not reached (95% CI not reached-not reached) for lorlatinib and was 9·3 months (7·6-11·1) for crizotinib (hazard ratio [HR] 0·27 [95% CI 0·18-0·39]). 3-year progression-free survival was 64% (95% CI 55-71) in the lorlatinib group and 19% (12-27) in the crizotinib group. Progression-free survival (investigator), objective response rate, intracranial objective response rate, time to intracranial progression, and duration of response were improved with lorlatinib versus crizotinib. In patients with baseline brain metastases (n=37 lorlatinib; n=39 crizotinib), the HR for time to intracranial progression for lorlatinib versus crizotinib was 0·10 (95% CI 0·04-0·27); in patients without baseline brain metastases (n=112 lorlatinib; n=108 crizotinib), the HR was 0·02 (95% CI 0·002-0·14). In patients without brain metastases, one (1%) in the lorlatinib group and 25 (23%) in the crizotinib group had intracranial progression. Grade 3-4 adverse events occurred in 113 (76%) of 149 patients (most commonly due to altered lipid levels) with lorlatinib and in 81 (57%) of 142 patients with crizotinib. Adverse events led to treatment discontinuation in 11 (7%) patients in the lorlatinib group and 14 (10%) patients in the crizotinib group. There were no new safety signals.\n\nInterpretation: These updated, long-term data from CROWN show the durable benefit of lorlatinib over crizotinib in patients with treatment-naive, ALK-positive non-small-cell lung cancer and support the use of first-line lorlatinib in patients with and without baseline brain metastases.\n\nFunding: Pfizer.\n\nIndexed on Europe PMC as PubMed record 36535300 (DOI 10.1016/s2213-2600(22)00437-4). Its abstract cites the registry id NCT03052608, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2023, doi: "10.1016/s2213-2600(22)00437-4", pmid: "36535300", authors: "Solomon BJ, Bauer TM, Mok TSK, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the CROWN trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Respir Med 2023","url":"https://doi.org/10.1016/s2213-2600(22)00437-4"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36535300/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36535300"},{"label":"ClinicalTrials.gov NCT03052608","url":"https://clinicaltrials.gov/study/NCT03052608"}], tags: ["europepmc-ingest"], cancers: ["nsclc","secondary-brain-tumours","alk-positive-nsclc"], drugs: ["lorlatinib"], targets: ["alk"], technologies: [], trials: ["crown"] }),
  p({ id: "paper-destiny-lung02-j-thorac-oncol-2025", name: "Final Analysis Results and Patient-Reported Outcomes From DESTINY-Lung02-A Dose-Blinded, Randomized, Phase 2 Study of Trastuzumab Deruxtecan in Patients With HER2-Mutant Metastatic NSCLC", tldr: "Published report from the DESTINY-Lung02 trial registered as NCT04644237, in Journal of Thoracic Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Trastuzumab deruxtecan (T-DXd) demonstrated strong and durable responses in patients with previously treated HER2 (ERBB2) mutant (HER2m) metastatic NSCLC (mNSCLC) in the DESTINY-Lung02 primary analysis (December 23, 2022, data cutoff). This final analysis evaluated T-DXd efficacy and safety after 8 additional months of follow-up, including clinically relevant subgroups and patient-reported outcomes.\n\nMethods: DESTINY-Lung02 was a randomized, dose-blinded, multicenter, phase 2 trial. Patients with previously treated HER2m mNSCLC were randomized 2:1 to receive T-DXd 5.4 or 6.4 mg/kg once every 3 weeks. Primary end point was confirmed objective response rate by blinded independent central review.\n\nResults: at August 25, 2023, 102 and 50 patients had received T-DXd 5.4 or 6.4 mg/kg, respectively. Median follow-up (Q1-Q3) was 15.8 (8.2-20.7) months and 16.5 (9.4-20.8) months, respectively. Confirmed objective response rate (95% confidence interval) was 50.0% (51/102; 39.9%-60.1%) and 56.0% (28/50; 41.3%-70.0%), respectively. Safety profile was acceptable and generally manageable. Accordingly, median treatment duration (Q1-Q3) was 7.7 (3.7-14.4) months and 8.3 (2.8-13.1) months; drug-related grade 3 or higher treatment-emergent adverse events occurred in 39.6% (40/101) and 60.0% (30/50), with nausea most common (67.3% [68/101], 82.0% [41/50]). Adjudicated drug-related interstitial lung disease occurred in 14.9% (15/101) and 32.0% (16/50), mostly grade 1 or 2 with one grade 5 in each arm. Health-related quality of life was preserved for the duration of T-DXd treatment while sample size was sufficient for analysis, with no adverse effects on health-related quality of life observed at either dose.\n\nConclusions: T-DXd demonstrated strong and durable responses at both doses, with no clinically significant changes in toxicity. The approved 5.4-mg/kg dose demonstrated a more favorable benefit-risk profile, including lower adjudicated drug-related interstitial lung disease incidence.\n\nGov identifier: NCT04644237.\n\nIndexed on Europe PMC as PubMed record 40749900 (DOI 10.1016/j.jtho.2025.07.129). Its abstract cites the registry id NCT04644237, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2025.07.129", pmid: "40749900", authors: "Jänne PA, Goto Y, Kubo T, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04644237 with the most citations, so it is the natural first reading for anyone following the DESTINY-Lung02 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2025.07.129"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40749900/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40749900"},{"label":"ClinicalTrials.gov NCT04644237","url":"https://clinicaltrials.gov/study/NCT04644237"}], tags: ["europepmc-ingest"], cancers: ["nsclc","her2-mutant-nsclc"], drugs: ["trastuzumab-deruxtecan"], targets: ["her2"], technologies: ["adc"], trials: ["destiny-lung02"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-empower-lung-1-lancet-2021", name: "Cemiplimab monotherapy for first-line treatment of advanced non-small-cell lung cancer with PD-L1 of at least 50%: a multicentre, open-label, global, phase 3, randomised, controlled trial", tldr: "Published report from the EMPOWER-Lung 1 trial registered as NCT03088540, in The Lancet (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: We aimed to examine cemiplimab, a programmed cell death 1 inhibitor, in the first-line treatment of advanced non-small-cell lung cancer with programmed cell death ligand 1 (PD-L1) of at least 50%.\n\nMethods: In EMPOWER-Lung 1, a multicentre, open-label, global, phase 3 study, eligible patients recruited in 138 clinics from 24 countries (aged ≥18 years with histologically or cytologically confirmed advanced non-small-cell lung cancer, an Eastern Cooperative Oncology Group performance status of 0-1; never-smokers were ineligible) were randomly assigned (1:1) to cemiplimab 350 mg every 3 weeks or platinum-doublet chemotherapy. Crossover from chemotherapy to cemiplimab was allowed following disease progression. Primary endpoints were overall survival and progression-free survival per masked independent review committee. Primary endpoints were assessed in the intention-to-treat population and in a prespecified PD-L1 of at least 50% population (per US Food and Drug Administration request to the sponsor), which consisted of patients with PD-L1 of at least 50% per 22C3 assay done according to instructions for use. Adverse events were assessed in all patients who received at least one dose of the assigned treatment. This study is registered with ClinicalTrials.gov, NCT03088540 and is ongoing.\n\nFindings: Between June 27, 2017 and Feb 27, 2020, 710 patients were randomly assigned (intention-to-treat population). In the PD-L1 of at least 50% population, which consisted of 563 patients, median overall survival was not reached (95% CI 17·9-not evaluable) with cemiplimab (n=283) versus 14·2 months (11·2-17·5) with chemotherapy (n=280; hazard ratio [HR] 0·57 [0·42-0·77]; p=0·0002). Median progression-free survival was 8·2 months (6·1-8·8) with cemiplimab versus 5·7 months (4·5-6·2) with chemotherapy (HR 0·54 [0·43-0·68]; p<0·0001). Significant improvements in overall survival and progression-free survival were also observed with cemiplimab in the intention-to-treat population despite a high crossover rate (74%). Grade 3-4 treatment-emergent adverse events occurred in 98 (28%) of 355 patients treated with cemiplimab and 135 (39%) of 342 patients treated with chemotherapy.\n\nInterpretation: Cemiplimab monotherapy significantly improved overall survival and progression-free survival compared with chemotherapy in patients with advanced non-small-cell lung cancer with PD-L1 of at least 50%, providing a potential new treatment option for this patient population.\n\nFunding: Regeneron Pharmaceuticals and Sanofi.\n\nIndexed on Europe PMC as PubMed record 33581821 (DOI 10.1016/s0140-6736(21)00228-2). Its abstract cites the registry id NCT03088540, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2021, doi: "10.1016/s0140-6736(21)00228-2", pmid: "33581821", authors: "Sezer A, Kilickap S, Gümüş M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03088540 with the most citations, so it is the natural first reading for anyone following the EMPOWER-Lung 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2021","url":"https://doi.org/10.1016/s0140-6736(21)00228-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33581821/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33581821"},{"label":"ClinicalTrials.gov NCT03088540","url":"https://clinicaltrials.gov/study/NCT03088540"}], tags: ["europepmc-ingest"], cancers: ["nsclc","pdl1-high-nsclc"], drugs: ["cemiplimab","carboplatin","cisplatin","paclitaxel","pemetrexed"], targets: ["pd1","pdl1"], technologies: ["checkpoint-inhibitor"], trials: ["empower-lung-1"], journals: ["lancet"] }),
  p({ id: "paper-empower-lung-1-lancet-oncol-2023-update", name: "First-line cemiplimab monotherapy and continued cemiplimab beyond progression plus chemotherapy for advanced non-small-cell lung cancer with PD-L1 50% or more (EMPOWER-Lung 1): 35-month follow-up from a mutlicentre, open-label, randomised, phase 3 trial", tldr: "Later report from the EMPOWER-Lung 1 trial registered as NCT03088540, in The Lancet Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Background: Cemiplimab provided significant survival benefit to patients with advanced non-small-cell lung cancer with PD-L1 tumour expression of at least 50% and no actionable biomarkers at 1-year follow-up. In this exploratory analysis, we provide outcomes after 35 months' follow-up and the effect of adding chemotherapy to cemiplimab at the time of disease progression.\n\nMethods: EMPOWER-Lung 1 was a multicentre, open-label, randomised, phase 3 trial. We enrolled patients (aged ≥18 years) with histologically confirmed squamous or non-squamous advanced non-small-cell lung cancer with PD-L1 tumour expression of 50% or more. We randomly assigned (1:1) patients to intravenous cemiplimab 350 mg every 3 weeks for up to 108 weeks, or until disease progression, or investigator's choice of chemotherapy. Central randomisation scheme generated by an interactive web response system governed the randomisation process that was stratified by histology and geographical region. Primary endpoints were overall survival and progression free survival, as assessed by a blinded independent central review (BICR) per Response Evaluation Criteria in Solid Tumours version 1.1. Patients with disease progression on cemiplimab could continue cemiplimab with the addition of up to four cycles of chemotherapy. We assessed response in these patients by BICR against a new baseline, defined as the last scan before chemotherapy initiation. The primary endpoints were assessed in all randomly assigned participants (ie, intention-to-treat population) and in those with a PD-L1 expression of at least 50%. We assessed adverse events in all patients who received at least one dose of their assigned treatment. This trial is registered with ClinicalTrials.gov, NCT03088540.\n\nFindings: Between May 29, 2017, and March 4, 2020, we recruited 712 patients (607 [85%] were male and 105 [15%] were female). We randomly assigned 357 (50%) to cemiplimab and 355 (50%) to chemotherapy. 284 (50%) patients assigned to cemiplimab and 281 (50%) assigned to chemotherapy had verified PD-L1 expression of at least 50%. At 35 months' follow-up, among those with a verified PD-L1 expression of at least 50% median overall survival in the cemiplimab group was 26·1 months (95% CI 22·1-31·8; 149 [52%] of 284 died) versus 13·3 months (10·5-16·2; 188 [67%] of 281 died) in the chemotherapy group (hazard ratio [HR] 0·57, 95% CI 0·46-0·71; p<0·0001), median progression-free survival was 8·1 months (95% CI 6·2-8·8; 214 events occurred) in the cemiplimab group versus 5·3 months (4·3-6·1; 236 events occurred) in the chemotherapy group (HR 0·51, 95% CI 0·42-0·62; p<0·0001). Continued cemiplimab plus chemotherapy as second-line therapy (n=64) resulted in a median progression-free survival of 6·6 months (6·1-9·3) and overall survival of 15·1 months (11·3-18·7). The most common grade 3-4 treatment-emergent adverse events were anaemia (15 [4%] of 356 patients in the cemiplimab group vs 60 [17%] of 343 in the control group), neutropenia (three [1%] vs 35 [10%]), and pneumonia (18 [5%] vs 13 [4%]). Treatment-related deaths occurred in ten (3%) of 356 patients treated with cemiplimab (due to autoimmune myocarditis, cardiac failure, cardio-respiratory arrest, cardiopulmonary failure, septic shock, tumour hyperprogression, nephritis, respiratory failure, [n=1 each] and general disorders or unknown [n=2]) and in seven (2%) of 343 patients treated with chemotherapy (due to pneumonia and pulmonary embolism [n=2 each], and cardiac arrest, lung abscess, and myocardial infarction [n=1 each]). The safety profile of cemiplimab at 35 months, and of continued cemiplimab plus chemotherapy, was generally consistent with that previously observed for these treatments, with no new safety signals INTERPRETATION: At 35 months' follow-up, the survival benefit of cemiplimab for patients with advanced non-small-cell lung cancer was at least as pronounced as at 1 year, affirming its use as first-line monotherapy for this population. Adding chemotherapy to cemiplimab at progression might provide a new second-line treatment for patients with advanced non-small-cell lung cancer.\n\nFunding: Regeneron Pharmaceuticals and Sanofi.\n\nIndexed on Europe PMC as PubMed record 37591293 (DOI 10.1016/s1470-2045(23)00329-7). Its abstract cites the registry id NCT03088540, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2023, doi: "10.1016/s1470-2045(23)00329-7", pmid: "37591293", authors: "Özgüroğlu M, Kilickap S, Sezer A, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the EMPOWER-Lung 1 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2023","url":"https://doi.org/10.1016/s1470-2045(23)00329-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37591293/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37591293"},{"label":"ClinicalTrials.gov NCT03088540","url":"https://clinicaltrials.gov/study/NCT03088540"}], tags: ["europepmc-ingest"], cancers: ["nsclc","pdl1-high-nsclc"], drugs: ["cemiplimab","carboplatin","cisplatin","paclitaxel","pemetrexed"], targets: ["pd1","pdl1"], technologies: ["checkpoint-inhibitor"], trials: ["empower-lung-1"], journals: ["lancet-oncology"] }),
  p({ id: "paper-furlong-lancet-respir-med-2022", name: "Furmonertinib (AST2818) versus gefitinib as first-line therapy for Chinese patients with locally advanced or metastatic EGFR mutation-positive non-small-cell lung cancer (FURLONG): a multicentre, double-blind, randomised phase 3 study", tldr: "Published report from the FURLONG trial registered as NCT03787992, in The Lancet. Respiratory medicine (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Furmonertinib (AST2818) is an irreversible, selective, third-generation EGFR tyrosine-kinase inhibitor. We aimed to investigate the efficacy and safety of furmonertinib versus the first-generation EGFR tyrosine-kinase inhibitor gefitinib as first-line treatment in patients with EGFR mutation-positive locally advanced or metastatic non-small-cell lung cancer (NSCLC).\n\nMethods: The FURLONG study is a multicentre, double-blind, randomised, phase 3 study done in 55 hospitals across mainland China. We enrolled patients who were aged 18 years or older and had histologically confirmed, locally advanced or metastatic, stage IIIB, IIIC, or IV unresectable NSCLC with EGFR exon 19 deletions or exon 21 Leu858Arg mutation on tissue biopsy confirmed by a central laboratory. Eligible patients were stratified according to EGFR mutation (exon 19 deletions or exon 21 Leu858Arg) and CNS metastases (with or without) and randomly assigned (1:1) to receive either oral furmonertinib (80 mg/day) or oral gefitinib (250 mg/day) in 21-day cycles until disease progression, the occurrence of intolerable toxicities, withdrawal of consent, or other discontinuation reasons judged by the investigators. Investigators, clinicians, participants, independent review centre (IRC) members, the sponsor, and those analysing the data were all masked to treatment allocation. The primary endpoint was IRC-assessed progression-free survival and, along with safety, was analysed in the full analysis set, which comprised all randomly assigned patients who had received at least one dose of study drug. This study is registered with ClinicalTrials.gov, NCT03787992, and is ongoing for survival follow-up.\n\nFindings: Between May 30, 2019, and Dec 5, 2019, 750 patients were screened, of whom 358 were randomly assigned to receive either furmonertinib and gefitinib-matching placebo (n=178) or gefitinib and furmonertinib-matching placebo (n=180). 178 patients randomly assigned to furmonertinib and 179 patients randomly assigned to gefitinib were treated and were included in the full analysis set. Median follow-up was 21·0 months (IQR 18·0-23·5) in the furmonertinib group and 21·0 months (18·0-23·5) in the gefitinib group. Median IRC-assessed progression-free survival was 20·8 months (95% CI 17·8-23·5) in the furmonertinib group and 11·1 months (9·7-12·5) in the gefitinib group (hazard ratio 0·44, 95% CI 0·34-0·58; p<0·0001). Treatment-related adverse events of a grade 3 or more occurred in 20 (11%) of 178 patients in the furmonertinib group and in 32 (18%) of 179 patients in the gefitinib group. Treatment-related serious adverse events were reported in ten (6%) patients in the furmonertinib group and in 11 (6%) patients in the gefitinib group. Ten (6%) patients in the furmonertinib group and three (2%) patients in the gefitinib group died due to adverse events, which were all judged to be possibly unrelated to study treatment by the investigators.\n\nInterpretation: Furmonertinib showed superior efficacy compared with gefitinib as first-line therapy in Chinese patients with EGFR mutation-positive NSCLC, along with an acceptable safety profile without new signals. Furmonertinib is a new potential treatment option for this population.\n\nFunding: Shanghai Allist Pharmaceuticals and the China National Major Project for New Drug Innovation.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 35662408 (DOI 10.1016/s2213-2600(22)00168-0). Its abstract cites the registry id NCT03787992, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2022, doi: "10.1016/s2213-2600(22)00168-0", pmid: "35662408", authors: "Shi Y, Chen G, Wang X, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03787992 with the most citations, so it is the natural first reading for anyone following the FURLONG trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2022","url":"https://doi.org/10.1016/s2213-2600(22)00168-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35662408/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35662408"},{"label":"ClinicalTrials.gov NCT03787992","url":"https://clinicaltrials.gov/study/NCT03787992"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["furmonertinib","gefitinib"], targets: ["egfr"], technologies: ["kinase-inhibitors"], trials: ["furlong"] }),
  p({ id: "paper-gemstone-302-lancet-oncol-2022", name: "Sugemalimab versus placebo, in combination with platinum-based chemotherapy, as first-line treatment of metastatic non-small-cell lung cancer (GEMSTONE-302): interim and final analyses of a double-blind, randomised, phase 3 clinical trial", tldr: "Published report from the GEMSTONE-302 trial registered as NCT03789604, in The Lancet Oncology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: PD-1 inhibitor plus chemotherapy had been shown to be an effective first-line treatment for patients with metastatic non-small-cell lung cancer (NSCLC). However, there was no robust evidence showing a PD-L1 inhibitor combined with chemotherapy benefited patients with squamous and non-squamous NSCLC. GEMSTONE-302 aimed to evaluate the efficacy and safety of a PD-L1 inhibitor, sugemalimab, plus chemotherapy for patients with metastatic squamous or non-squamous NSCLC.\n\nMethods: This randomised, double-blind, phase 3 trial was done in 35 hospitals and academic research centres in China. Eligible patients were aged 18-75 years, had histologically or cytologically confirmed stage IV squamous or non-squamous NSCLC without known EGFR sensitising mutations, ALK, ROS1, or RET fusions, no previous systemic treatment for metastatic disease, and an Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1. Patients were randomly assigned (2:1) to receive sugemalimab (1200 mg, intravenously, every 3 weeks) plus platinum-based chemotherapy (carboplatin [area under the curve (AUC) 5 mg/mL per min, intravenously] and paclitaxel [175 mg/m 2, intravenously] for squamous NSCLC, or carboplatin [AUC 5 mg/mL per min, intravenously] and pemetrexed [500 mg/m 2, intravenously] for non-squamous NSCLC; sugemalimab group) or placebo plus the same platinum-based chemotherapy regimens for squamous or non-squamous NSCLC as in the sugemalimab group; placebo group) for up to four cycles, followed by maintenance therapy with sugemalimab or placebo for squamous NSCLC, and intravenous sugemalimab 500 mg/m 2 or matching placebo plus pemetrexed for non-squamous NSCLC. Randomisation was done by an interactive voice-web-response system via permuted blocks (block size was a mixture of three and six with a random order within each stratum) and stratified by ECOG performance status, PD-L1 expression, and tumour pathology. The investigators, patients, and the sponsor were masked to treatment assignment. The primary endpoint was investigator-assessed progression-free survival in the intention-to-treat population. Safety was analysed in all patients who received at least one treatment dose. Results reported are from a prespecified interim analysis (ie, when the study met the primary endpoint) and an updated analysis (prespecified final analysis for progression-free survival) with a longer follow-up. This study is registered with ClinicalTrials.gov (NCT03789604), is closed to new participants, and follow-up is ongoing.\n\nFindings: Between Dec 13, 2018, and May 15, 2020, 846 patients were assessed for eligibility; 367 were ineligible, and the remaining 479 patients were randomly assigned to the sugemalimab group (n=320) or placebo group (n=159). At the preplanned interim analysis (data cutoff June 8, 2020; median follow-up 8·6 months [IQR 6·1-11·4]), GEMSTONE-302 met its primary endpoint, with significantly longer progression-free survival in the sugemalimab group compared with the placebo group (median 7·8 months [95% CI 6·9-9·0] vs 4·9 months [4·7-5·0]; stratified hazard ratio [HR] 0·50 [95% CI 0·39-0·64], p<0·0001]). At the final analysis (March 15, 2021) with a median follow-up of 17·8 months (IQR 15·1-20·9), the improvement in progression-free survival was maintained (median 9·0 months [95% CI 7·4-10·8] vs 4·9 months [4·8-5·1]; stratified HR 0·48 [95% CI 0·39-0·60], p<0·0001). The most common grade 3 or 4 any treatment-related adverse events were neutrophil count decreased (104 [33%] of 320 with sugemalimab vs 52 [33%] of 159 with placebo), white blood cell count decreased (45 [14%] vs 27 [17%]), anaemia (43 [13%] vs 18 [11%]), platelet count decreased (33 [10%] vs 15 [9%]), and neutropenia (12 [4%] vs seven [4%]). Any treatment-related serious adverse events occurred in 73 (23%) patients in the sugemalimab group and 31 (20%) patients in the placebo group. Any treatment-related deaths were reported in ten (3%) patients in the sugemalimab group (pneumonia with respiratory failure in one patient; myelosuppression with septic shock in one patient; pneumonia in two patients; respiratory failure, abdominal pain, cardiac failure, and immune-mediated pneumonitis in one patient each; the other two deaths had an unspecified cause) and in two (1%) patients in the placebo group (pneumonia and multiple organ dysfunction syndrome).\n\nInterpretation: Sugemalimab plus chemotherapy showed a statistically significant and clinically meaningful progression-free survival improvement compared with placebo plus chemotherapy, in patients with previously untreated squamous and non-squamous metastatic NSCLC, regardless of PD-L1 expression, and could be a newfirst-line treatment option for both squamous and non-squamous metastatic NSCLC.\n\nFunding: CStone Pharmaceuticals.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 35038432 (DOI 10.1016/s1470-2045(21)00650-1). Its abstract cites the registry id NCT03789604, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2022, doi: "10.1016/s1470-2045(21)00650-1", pmid: "35038432", authors: "Zhou C, Wang Z, Sun Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03789604 with the most citations, so it is the natural first reading for anyone following the GEMSTONE-302 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2022","url":"https://doi.org/10.1016/s1470-2045(21)00650-1"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35038432/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35038432"},{"label":"ClinicalTrials.gov NCT03789604","url":"https://clinicaltrials.gov/study/NCT03789604"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["sugemalimab"], targets: [], technologies: ["checkpoint-inhibitor"], trials: ["gemstone-302"], journals: ["lancet-oncology"] }),
  p({ id: "paper-gemstone-302-nat-cancer-2023-update", name: "Interim survival analysis of the randomized phase III GEMSTONE-302 trial: sugemalimab or placebo plus chemotherapy as first-line treatment for metastatic NSCLC", tldr: "Later report from the GEMSTONE-302 trial registered as NCT03789604, in Nature Cancer (2023); its title describes an updated or longer-term analysis.", summary: "The randomized, double-blinded, multi-center, phase III GEMSTONE-302 ( NCT03789604) study evaluated the efficacy and safety of sugemalimab versus placebo in combination with chemotherapy as first-line treatment for metastatic non-small-cell lung cancer (NSCLC). In this study, 479 treatment-naive patients with stage IV squamous or non-squamous NSCLC without known EGFR sensitizing mutations, ALK, ROS1 or RET fusions were randomized (2:1) to receive 1,200 mg of sugemalimab (n = 320) or placebo (n = 159) every 3 weeks in combination with platinum-based chemotherapy for up to four cycles, followed by maintenance therapy with sugemalimab or placebo for squamous NSCLC and sugemalimab or placebo plus pemetrexed for non-squamous NSCLC. Placebo-treated patients could cross over to receive sugemalimab monotherapy on disease progression. The primary endpoint was investigator-assessed progression-free survival (PFS) and the secondary endpoints included overall survival (OS) and objective response rate. Sugemalimab plus chemotherapy has demonstrated significant PFS prolongation in the primary analysis as reported previously. at 22 November 2021, the prespecified interim OS analysis showed significant improvement with the addition of sugemalimab to chemotherapy (median OS = 25.4 versus 16.9 months; hazard ratio = 0.65; 95% confidence interval = 0.50-0.84; P = 0.0008). Sugemalimab plus chemotherapy provided superior PFS and OS compared to placebo plus chemotherapy, supporting the use of sugemalimab as a first-line treatment option for metastatic NSCLC.\n\nIndexed on Europe PMC as PubMed record 37322367 (DOI 10.1038/s43018-023-00578-z). Its abstract cites the registry id NCT03789604, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Cancer", year: 2023, doi: "10.1038/s43018-023-00578-z", pmid: "37322367", authors: "Zhou C, Wang Z, Sun M, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the GEMSTONE-302 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Nat Cancer 2023","url":"https://doi.org/10.1038/s43018-023-00578-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37322367/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37322367"},{"label":"ClinicalTrials.gov NCT03789604","url":"https://clinicaltrials.gov/study/NCT03789604"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["sugemalimab"], targets: [], technologies: ["checkpoint-inhibitor"], trials: ["gemstone-302"], journals: ["nature-cancer"] }),
  p({ id: "paper-geometry-mono-1-lancet-oncol-2024-update", name: "Capmatinib in MET exon 14-mutated non-small-cell lung cancer: final results from the open-label, phase 2 GEOMETRY mono-1 trial", tldr: "Later report from the GEOMETRY mono-1 trial registered as NCT02414139, in The Lancet Oncology (2024); its title describes an updated or longer-term analysis.", summary: "Background: Capmatinib has previously shown activity in treatment-naive and previously treated patients with non-small-cell lung cancer (NSCLC) and a MET exon 14-skipping mutation (METex14). Here, we report the final outcomes from the phase 2 GEOMETRY mono-1 study with an aim to provide further evidence for the activity of capmatinib.\n\nMethods: In this non-randomised, multi-cohort, open-label, phase 2 trial conducted in 152 centres and hospitals in 25 countries, with patients treated in 95 centres in 20 countries, eligible patients (aged ≥18 years) with MET-dysregulated, EGFR wild-type, and ALK rearrangement-negative advanced NSCLC (stage IIIB/IV) and an Eastern Cooperative Oncology Group performance status of 0 or 1 were assigned to cohorts (1a, 1b, 2, 3, 4, 5a, 5b, 6 and 7) based on their MET status (METex14 or MET amplification) and previous therapy lines. Patients received capmatinib (400 mg orally twice daily) in 21-day treatment cycles. The primary endpoint was overall response rate by blinded independent central review per Response Evaluation Criteria in Solid Tumours version 1.1 and was performed on the full analysis set (all patients who received at least one dose of capmatinib). Previous reports of this study had published interim or primary data for cohorts 1-7. Here, we report the final clinical outcomes from all METex14 cohorts (4, 5b, 6, and 7) and safety from all study cohorts (1-7). The trial is registered with ClinicalTrials.gov, NCT02414139, and has been completed.\n\nFindings: Of 373 treated patients enrolled from June 11, 2015, to March 12, 2020, 160 (97 [61%] female) patients had METex14 NSCLC and were enrolled in four cohorts: 60 treatment-naive (cohorts 5b and 7) and 100 previously treated (cohorts 4 and 6). The overall median study follow-up was 46·4 months (IQR 41·8-65·4) for the treatment-naïve patients and 66·9 months (56·7-73·9) for previously treated patients, respectively. Overall responses were recorded in 41 (68%; 95% CI 55·0-79·7) of 60 treatment-naive patients and 44 (44%; 95% CI 34·1-54·3) of 100 previously treated patients. In all 373 treated patients, the most common treatment-related adverse events were peripheral oedema (n=174; 47%), nausea (n=130; 35%), increased blood creatinine (n=78; 21%), and vomiting (n=74; 20%). Grade 3-4 serious adverse events occurred in 164 (44%) patients, dyspnoea being the most common (18 patients [5%]). Treatment-related deaths occurred in four (1%) patients (one each of cardiac arrest, hepatitis, organising pneumonia, and pneumonitis). No new safety signals were reported.\n\nInterpretation: These long-term results support METex14 as a targetable oncogenic driver in NSCLC and add to the evidence supporting capmatinib as a targeted treatment option for treatment-naive and previously treated patients with METex14 NSCLC.\n\nFunding: Novartis Pharmaceuticals.\n\nIndexed on Europe PMC as PubMed record 39362249 (DOI 10.1016/s1470-2045(24)00441-8). Its abstract cites the registry id NCT02414139, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2024, doi: "10.1016/s1470-2045(24)00441-8", pmid: "39362249", authors: "Wolf J, Hochmair M, Han JY, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the GEOMETRY mono-1 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet Oncol 2024","url":"https://doi.org/10.1016/s1470-2045(24)00441-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39362249/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39362249"},{"label":"ClinicalTrials.gov NCT02414139","url":"https://clinicaltrials.gov/study/NCT02414139"}], tags: ["europepmc-ingest"], cancers: ["nsclc","met-altered-nsclc"], drugs: ["capmatinib","crizotinib"], targets: ["met"], technologies: ["kinase-inhibitors"], trials: ["geometry-mono-1"], journals: ["lancet-oncology"] }),
  p({ id: "paper-harmoni-a-jama-2024", name: "Ivonescimab Plus Chemotherapy in Non-Small Cell Lung Cancer With EGFR Variant: A Randomized Clinical Trial", tldr: "Published report from the HARMONi-A trial registered as NCT05184712, in JAMA (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: For patients with non-small cell lung cancer whose disease progressed while receiving EGFR tyrosine kinase inhibitor (EGFR-TKI) therapy, particularly third-generation TKIs, optimal treatment options remain limited.\n\nObjective: To compare the efficacy of ivonescimab plus chemotherapy with chemotherapy alone for patients with relapsed advanced or metastatic non-small cell lung cancer with the epidermal growth factor receptor (EGFR) variant.\n\nDesign, setting, and participants: Double-blind, placebo-controlled, randomized, phase 3 trial at 55 sites in China enrolled participants from January 2022 to November 2022; a total of 322 eligible patients were enrolled.\n\nInterventions: Participants received ivonescimab (n = 161) or placebo (n = 161) plus pemetrexed and carboplatin once every 3 weeks for 4 cycles, followed by maintenance therapy of ivonescimab plus pemetrexed or placebo plus pemetrexed.\n\nMain outcomes and measures: The primary end point was progression-free survival in the intention-to-treat population assessed by an independent radiographic review committee (IRRC) per Response Evaluation Criteria in Solid Tumors version 1.1. The results of the first planned interim analysis are reported.\n\nResults: Among 322 enrolled patients in the ivonescimab and placebo groups, the median age was 59.6 vs 59.4 years and 52.2% vs 50.9% of patients were female. at March 10, 2023, median follow-up time was 7.89 months. Median progression-free survival was 7.1 (95% CI, 5.9-8.7) months in the ivonescimab group vs 4.8 (95% CI, 4.2-5.6) months for placebo (difference, 2.3 months; hazard ratio [HR], 0.46 [95% CI, 0.34-0.62]; P <.001). The prespecified subgroup analysis showed progression-free survival benefit favoring patients receiving ivonescimab over placebo across almost all subgroups, including patients whose disease progressed while receiving third-generation EGFR-TKI therapy (HR, 0.48 [95% CI 0.35-0.66]) and those with brain metastases (HR, 0.40 [95% CI, 0.22-0.73]). The objective response rate was 50.6% (95% CI, 42.6%-58.6%) with ivonescimab and 35.4% (95% CI, 28.0%-43.3%) with placebo (difference, 15.6% [95% CI, 5.3%-26.0%]; P =.006). The median overall survival data were not mature; at data cutoff, 69 patients (21.4%) had died. Grade 3 or higher treatment-emergent adverse events occurred in 99 patients (61.5%) in the ivonescimab group vs 79 patients (49.1%) in the placebo group, the most common of which were chemotherapy-related. Grade 3 or higher immune-related adverse events occurred in 10 patients (6.2%) in the ivonescimab group vs 4 (2.5%) in the placebo group. Grade 3 or higher vascular endothelial growth factor-related adverse events occurred in 5 patients (3.1%) in the ivonescimab group vs 4 (2.5%) in the placebo group.\n\nConclusions: Ivonescimab plus chemotherapy significantly improved progression-free survival with tolerable safety profile in TKI-treated non-small cell lung cancer.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT05184712.\n\nIndexed on Europe PMC as PubMed record 38820549 (DOI 10.1001/jama.2024.10613). Its abstract cites the registry id NCT05184712, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA", year: 2024, doi: "10.1001/jama.2024.10613", pmid: "38820549", authors: "HARMONi-A Study Investigators, Fang W, Zhao Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05184712 with the most citations, so it is the natural first reading for anyone following the HARMONi-A trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA 2024","url":"https://doi.org/10.1001/jama.2024.10613"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38820549/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38820549"},{"label":"ClinicalTrials.gov NCT05184712","url":"https://clinicaltrials.gov/study/NCT05184712"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["ivonescimab","pemetrexed","carboplatin"], targets: ["pd1","vegf","egfr"], technologies: ["bispecific-antibody"], trials: ["harmoni-a"], journals: ["jama"] }),
  p({ id: "paper-imforte-lancet-2025", name: "Efficacy and safety of first-line maintenance therapy with lurbinectedin plus atezolizumab in extensive-stage small-cell lung cancer (IMforte): a randomised, multicentre, open-label, phase 3 trial", tldr: "Published report from the IMforte trial registered as NCT05091567, in The Lancet (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Despite improved efficacy with first-line immune checkpoint inhibitors plus platinum-based chemotherapy for extensive-stage small-cell lung cancer (ES-SCLC), survival remains poor. In this study, we aimed to compare lurbinectedin plus atezolizumab and atezolizumab alone as maintenance therapies in patients with ES-SCLC without progression after induction therapy with atezolizumab, carboplatin, and etoposide.\n\nMethods: IMforte was a randomised, open-label, phase 3 trial done at 96 hospitals and medical centres in 13 countries (Belgium, Germany, Greece, Hungary, Italy, Mexico, Poland, South Korea, Spain, Taiwan, Türkiye, the UK, and the USA). Eligible patients were aged 18 years or older with treatment-naive ES-SCLC. Patients received four 21-day cycles of induction treatment (atezolizumab, carboplatin, and etoposide). After completing induction treatment, eligible patients without disease progression were randomly assigned (1:1) using permuted blocks (Interactive Voice/Web Response System) to receive maintenance treatment intravenously every 3 weeks with lurbinectedin (3·2 mg/m 2; with granulocyte colony-stimulating factor prophylaxis) plus atezolizumab (1200 mg) or atezolizumab (1200 mg). The two primary endpoints were independent review facility-assessed (IRF) progression-free survival and overall survival, measured from randomisation into the maintenance phase. Efficacy endpoints were assessed in the full analysis set, which included all patients who were randomly assigned to maintenance phase treatment, regardless of whether they received their assigned study treatment. Safety was assessed in all patients who received at least one dose of lurbinectedin or atezolizumab, and was analysed according to the treatment received. This study is registered with ClinicalTrials.gov, NCT05091567, and is closed for recruitment.\n\nFindings: Between Nov 17, 2021, and Jan 11, 2024, 895 patients were screened for enrolment, of whom 660 (74%) were enrolled into the induction phase. Between May 24, 2022, and April 30, 2024, 483 (73%) of 660 patients entered the maintenance phase and were randomly assigned to lurbinectedin plus atezolizumab (n=242) or atezolizumab (n=241). At the data cutoff (July 29, 2024), IRF progression-free survival was longer in the lurbinectedin plus atezolizumab group than the atezolizumab group (stratified hazard ratio [HR] 0·54 [95% CI 0·43-0·67]; p<0·0001), as was overall survival (stratified HR 0·73 [0·57-0·95]; p=0·017). 92 (38%) of 242 patients in the lurbinectedin plus atezolizumab group and 53 (22%) of 240 patients in the atezolizumab group had grade 3-4 adverse events. The most common grade 3-4 events in the lurbinectedin plus atezolizumab group were anaemia (20 [8%] of 242 patients), decreased neutrophil count (18 [7%] patients), and decreased platelet count (18 [7%] patients) and the most common events in the atezolizumab group were hyponatremia (five [2%] of 240 patients), dyspnoea (four [2%] patients), and pneumonia (four [2%] patients). Grade 5 adverse events occurred in 12 (5%) of 242 patients in the lurbinectedin plus atezolizumab group and six (3%) of 240 patients in the atezolizumab group. The incidence of myelosuppressive toxicities (eg, neutropenia and leukopenia) was higher in the lurbinectedin plus atezolizumab group than the atezolizumab group.\n\nInterpretation: IRF progression-free survival and overall survival were longer in the lurbinectedin plus atezolizumab group than the atezolizumab group for patients with ES-SCLC, albeit with a higher incidence of adverse events. Lurbinectedin plus atezolizumab represents a novel therapeutic option for first-line maintenance treatment in this setting.\n\nFunding: F Hoffmann-La Roche and Jazz Pharmaceuticals.\n\nIndexed on Europe PMC as PubMed record 40473449 (DOI 10.1016/s0140-6736(25)01011-6). Its abstract cites the registry id NCT05091567, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2025, doi: "10.1016/s0140-6736(25)01011-6", pmid: "40473449", authors: "Paz-Ares L, Borghaei H, Liu SV, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05091567 with the most citations, so it is the natural first reading for anyone following the IMforte trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2025","url":"https://doi.org/10.1016/s0140-6736(25)01011-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40473449/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40473449"},{"label":"ClinicalTrials.gov NCT05091567","url":"https://clinicaltrials.gov/study/NCT05091567"}], tags: ["europepmc-ingest"], cancers: ["sclc","extensive-stage-sclc"], drugs: ["lurbinectedin","atezolizumab"], targets: [], technologies: [], trials: ["imforte"], journals: ["lancet"] }),
  p({ id: "paper-impower133-n-engl-j-med-2018", name: "First-Line Atezolizumab plus Chemotherapy in Extensive-Stage Small-Cell Lung Cancer", tldr: "Published report from the IMpower133 trial registered as NCT02763579, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Enhancing tumor-specific T-cell immunity by inhibiting programmed death ligand 1 (PD-L1)-programmed death 1 (PD-1) signaling has shown promise in the treatment of extensive-stage small-cell lung cancer. Combining checkpoint inhibition with cytotoxic chemotherapy may have a synergistic effect and improve efficacy.\n\nMethods: We conducted this double-blind, placebo-controlled, phase 3 trial to evaluate atezolizumab plus carboplatin and etoposide in patients with extensive-stage small-cell lung cancer who had not previously received treatment. Patients were randomly assigned in a 1:1 ratio to receive carboplatin and etoposide with either atezolizumab or placebo for four 21-day cycles (induction phase), followed by a maintenance phase during which they received either atezolizumab or placebo (according to the previous random assignment) until they had unacceptable toxic effects, disease progression according to Response Evaluation Criteria in Solid Tumors, version 1.1, or no additional clinical benefit. The two primary end points were investigator-assessed progression-free survival and overall survival in the intention-to-treat population.\n\nResults: A total of 201 patients were randomly assigned to the atezolizumab group, and 202 patients to the placebo group. At a median follow-up of 13.9 months, the median overall survival was 12.3 months in the atezolizumab group and 10.3 months in the placebo group (hazard ratio for death, 0.70; 95% confidence interval [CI], 0.54 to 0.91; P=0.007). The median progression-free survival was 5.2 months and 4.3 months, respectively (hazard ratio for disease progression or death, 0.77; 95% CI, 0.62 to 0.96; P=0.02). The safety profile of atezolizumab plus carboplatin and etoposide was consistent with the previously reported safety profile of the individual agents, with no new findings observed.\n\nConclusions: The addition of atezolizumab to chemotherapy in the first-line treatment of extensive-stage small-cell lung cancer resulted in significantly longer overall survival and progression-free survival than chemotherapy alone. (Funded by F. Hoffmann-La Roche/Genentech; IMpower133 ClinicalTrials.gov number, NCT02763579.).\n\nIndexed on Europe PMC as PubMed record 30280641 (DOI 10.1056/nejmoa1809064). Its abstract cites the registry id NCT02763579, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1809064", pmid: "30280641", authors: "Horn L, Mansfield AS, Szczęsna A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02763579 with the most citations, so it is the natural first reading for anyone following the IMpower133 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1809064"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30280641/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30280641"},{"label":"ClinicalTrials.gov NCT02763579","url":"https://clinicaltrials.gov/study/NCT02763579"}], tags: ["europepmc-ingest"], cancers: ["sclc","extensive-stage-sclc"], drugs: ["atezolizumab","platinum-etoposide"], targets: [], technologies: ["checkpoint-inhibitor"], trials: ["impower133"], journals: ["nejm"] }),
  p({ id: "paper-keynote-024-189-j-clin-oncol-2021-update", name: "Five-Year Outcomes With Pembrolizumab Versus Chemotherapy for Metastatic Non-Small-Cell Lung Cancer With PD-L1 Tumor Proportion Score ≥ 50", tldr: "Later report from the KEYNOTE-024 trial registered as NCT02142738, in Journal of Clinical Oncology (2021); its title describes an updated or longer-term analysis.", summary: "Purpose: We report the first 5-year follow-up of any first-line phase III immunotherapy trial for non-small-cell lung cancer (NSCLC). KEYNOTE-024 (ClinicalTrials.gov identifier: NCT02142738) is an open-label, randomized controlled trial of pembrolizumab compared with platinum-based chemotherapy in patients with previously untreated NSCLC with a programmed death ligand-1 (PD-L1) tumor proportion score of at least 50% and no sensitizing EGFR or ALK alterations. Previous analyses showed pembrolizumab significantly improved progression-free survival and overall survival (OS).\n\nMethods: Eligible patients were randomly assigned (1:1) to pembrolizumab (200 mg once every 3 weeks for up to 35 cycles) or platinum-based chemotherapy. Patients in the chemotherapy group with progressive disease could cross over to pembrolizumab. The primary end point was progression-free survival; OS was a secondary end point.\n\nResults: Three hundred five patients were randomly assigned: 154 to pembrolizumab and 151 to chemotherapy. Median (range) time from randomization to data cutoff (June 1, 2020) was 59.9 (55.1-68.4) months. Among patients initially assigned to chemotherapy, 99 received subsequent anti-PD-1 or PD-L1 therapy, representing a 66.0% effective crossover rate. Median OS was 26.3 months (95% CI, 18.3 to 40.4) for pembrolizumab and 13.4 months (9.4-18.3) for chemotherapy (hazard ratio, 0.62; 95% CI, 0.48 to 0.81). Kaplan-Meier estimates of the 5-year OS rate were 31.9% for the pembrolizumab group and 16.3% for the chemotherapy group. Thirty-nine patients received 35 cycles (ie, approximately 2 years) of pembrolizumab, 82.1% of whom were still alive at data cutoff (approximately 5 years). Toxicity did not increase with longer treatment exposure.\n\nConclusion: Pembrolizumab provides a durable, clinically meaningful long-term OS benefit versus chemotherapy as first-line therapy for metastatic NSCLC with PD-L1 tumor proportion score of at least 50%.\n\nIndexed on Europe PMC as PubMed record 33872070 (DOI 10.1200/jco.21.00174). Its abstract cites the registry id NCT02142738, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2021, doi: "10.1200/jco.21.00174", pmid: "33872070", authors: "Reck M, Rodríguez-Abreu D, Robinson AG, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-024 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2021","url":"https://doi.org/10.1200/jco.21.00174"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33872070/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33872070"},{"label":"ClinicalTrials.gov NCT02142738","url":"https://clinicaltrials.gov/study/NCT02142738"}], tags: ["europepmc-ingest"], cancers: ["nsclc","pdl1-high-nsclc"], drugs: ["pembrolizumab"], targets: ["pd1","pdl1"], technologies: [], trials: ["keynote-024-189"], journals: ["jco"] }),
  p({ id: "paper-keynote-042-lancet-2019", name: "Pembrolizumab versus chemotherapy for previously untreated, PD-L1-expressing, locally advanced or metastatic non-small-cell lung cancer (KEYNOTE-042): a randomised, open-label, controlled, phase 3 trial", tldr: "Published report from the KEYNOTE-042 trial registered as NCT02220894, in The Lancet (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: First-line pembrolizumab monotherapy improves overall and progression-free survival in patients with untreated metastatic non-small-cell lung cancer with a programmed death ligand 1 (PD-L1) tumour proportion score (TPS) of 50% or greater. We investigated overall survival after treatment with pembrolizumab monotherapy in patients with a PD-L1 TPS of 1% or greater.\n\nMethods: This randomised, open-label, phase 3 study was done in 213 medical centres in 32 countries. Eligible patients were adults (≥18 years) with previously untreated locally advanced or metastatic non-small-cell lung cancer without a sensitising EGFR mutation or ALK translocation and with an Eastern Cooperative Oncology Group (ECOG) performance status score of 0 or 1, life expectancy 3 months or longer, and a PD-L1 TPS of 1% or greater. Randomisation was computer generated, accessed via an interactive voice-response and integrated web-response system, and stratified by region of enrolment (east Asia vs rest of world), ECOG performance status score (0 vs 1), histology (squamous vs non-squamous), and PD-L1 TPS (≥50% vs 1-49%). Enrolled patients were randomly assigned 1:1 in blocks of four per stratum to receive pembrolizumab 200 mg every 3 weeks for up to 35 cycles or the investigator's choice of platinum-based chemotherapy for four to six cycles. Primary endpoints were overall survival in patients with a TPS of 50% or greater, 20% or greater, and 1% or greater (one-sided significance thresholds, p=0·0122, p=0·0120, and p=0·0124, respectively) in the intention-to-treat population, assessed sequentially if the previous findings were significant. This study is registered at ClinicalTrials.gov, number NCT02220894.\n\nFindings: From Dec 19, 2014, to March 6, 2017, 1274 patients (902 men, 372 women, median age 63 years [IQR 57-69]) with a PD-L1 TPS of 1% or greater were allocated to pembrolizumab (n=637) or chemotherapy (n=637) and included in the intention-to-treat population. 599 (47%) had a TPS of 50% or greater and 818 patients (64%) had a TPS of 20% or greater. at Feb 26, 2018, median follow-up was 12·8 months. Overall survival was significantly longer in the pembrolizumab group than in the chemotherapy group in all three TPS populations (≥50% hazard ratio 0·69, 95% CI 0·56-0·85, p=0·0003; ≥20% 0·77, 0·64-0·92, p=0·0020, and ≥1% 0·81, 0·71-0·93, p=0·0018). The median surival values by TPS population were 20·0 months (95% CI 15·4-24·9) for pembrolizumab versus 12·2 months (10·4-14·2) for chemotherapy, 17·7 months (15·3-22·1) versus 13·0 months (11·6-15·3), and 16·7 months (13·9-19·7) versus 12·1 months (11·3-13·3), respectively. Treatment-related adverse events of grade 3 or worse occurred in 113 (18%) of 636 treated patients in the pembrolizumab group and in 252 (41%) of 615 in the chemotherapy group and led to death in 13 (2%) and 14 (2%) patients, respectively.\n\nInterpretation: The benefit-to-risk profile suggests that pembrolizumab monotherapy can be extended as first-line therapy to patients with locally advanced or metastatic non-small-cell lung cancer without sensitising EGFR or ALK alterations and with low PD-L1 TPS.\n\nFunding: Merck Sharp & Dohme.\n\nIndexed on Europe PMC as PubMed record 30955977 (DOI 10.1016/s0140-6736(18)32409-7). Its abstract cites the registry id NCT02220894, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2019, doi: "10.1016/s0140-6736(18)32409-7", pmid: "30955977", authors: "Mok TSK, Wu YL, Kudaba I, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02220894 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-042 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2019","url":"https://doi.org/10.1016/s0140-6736(18)32409-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30955977/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30955977"},{"label":"ClinicalTrials.gov NCT02220894","url":"https://clinicaltrials.gov/study/NCT02220894"}], tags: ["europepmc-ingest"], cancers: ["nsclc","pdl1-high-nsclc"], drugs: ["pembrolizumab","carboplatin","paclitaxel","pemetrexed"], targets: ["pd1","pdl1"], technologies: ["checkpoint-inhibitor"], trials: ["keynote-042"], journals: ["lancet"] }),
  p({ id: "paper-keynote-042-j-clin-oncol-2023-update", name: "Five-Year Outcomes With Pembrolizumab Versus Chemotherapy as First-Line Therapy in Patients With Non-Small-Cell Lung Cancer and Programmed Death Ligand-1 Tumor Proportion Score ≥ 1% in the KEYNOTE-042 Study", tldr: "Later report from the KEYNOTE-042 trial registered as NCT02220894, in Journal of Clinical Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Clinical trials frequently include multiple end points that mature at different times. The initial report, typically based on the primary end point, may be published when key planned co-primary or secondary analyses are not yet available. Clinical Trial Updates provide an opportunity to disseminate additional results from studies, published in JCO or elsewhere, for which the primary end point has already been reported. We report 5-year results from the phase III KEYNOTE-042 study (ClinicalTrials.gov identifier: NCT02220894). Eligible patients with locally advanced/metastatic non-small-cell lung cancer (NSCLC) without EGFR/ALK alterations and with programmed death ligand-1 (PD-L1) tumor proportion score (TPS) ≥ 1% received pembrolizumab 200 mg once every 3 weeks for 35 cycles or chemotherapy (carboplatin + paclitaxel or pemetrexed) for 4-6 cycles with optional maintenance pemetrexed. Primary end points were overall survival (OS) in PD-L1 TPS ≥ 50%, ≥ 20%, and ≥ 1% groups. Patients who completed 35 cycles of pembrolizumab with ≥ stable disease could begin second-course pembrolizumab upon progression. One thousand two hundred seventy-four patients were randomly assigned (pembrolizumab, n = 637; chemotherapy, n = 637). Median follow-up time was 61.1 (range, 50.0-76.3) months. OS outcomes favored pembrolizumab ( v chemotherapy) regardless of PD-L1 TPS (hazard ratio [95% CI] for TPS ≥ 50%, 0.68 [0.57 to 0.81]; TPS ≥ 20%, 0.75 [0.64 to 0.87]; TPS ≥ 1%, 0.79 [0.70 to 0.89]), with estimated 5-year OS rates with pembrolizumab of 21.9%, 19.4%, and 16.6%, respectively. No new toxicities were identified. Objective response rate was 84.3% among 102 patients who completed 35 cycles of pembrolizumab and 15.2% among 33 patients who received second-course pembrolizumab. First-line pembrolizumab monotherapy continued to show durable clinical benefit versus chemotherapy after 5 years of follow-up in PD-L1-positive, locally advanced/metastatic NSCLC without EGFR/ALK alterations and remains a standard of care.\n\nIndexed on Europe PMC as PubMed record 36306479 (DOI 10.1200/jco.21.02885). Its abstract cites the registry id NCT02220894, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2023, doi: "10.1200/jco.21.02885", pmid: "36306479", authors: "de Castro G, Kudaba I, Wu YL, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-042 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2023","url":"https://doi.org/10.1200/jco.21.02885"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36306479/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36306479"},{"label":"ClinicalTrials.gov NCT02220894","url":"https://clinicaltrials.gov/study/NCT02220894"}], tags: ["europepmc-ingest"], cancers: ["nsclc","pdl1-high-nsclc"], drugs: ["pembrolizumab","carboplatin","paclitaxel","pemetrexed"], targets: ["pd1","pdl1"], technologies: ["checkpoint-inhibitor"], trials: ["keynote-042"], journals: ["jco"] }),
  p({ id: "paper-keynote-407-n-engl-j-med-2018", name: "Pembrolizumab plus Chemotherapy for Squamous Non-Small-Cell Lung Cancer", tldr: "Published report from the KEYNOTE-407 trial registered as NCT02775435, in New England Journal of Medicine (2018), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Standard first-line therapy for metastatic, squamous non-small-cell lung cancer (NSCLC) is platinum-based chemotherapy or pembrolizumab (for patients with programmed death ligand 1 [PD-L1] expression on ≥50% of tumor cells). More recently, pembrolizumab plus chemotherapy was shown to significantly prolong overall survival among patients with nonsquamous NSCLC.\n\nMethods: In this double-blind, phase 3 trial, we randomly assigned, in a 1:1 ratio, 559 patients with untreated metastatic, squamous NSCLC to receive 200 mg of pembrolizumab or saline placebo for up to 35 cycles; all the patients also received carboplatin and either paclitaxel or nanoparticle albumin-bound [nab]-paclitaxel for the first 4 cycles. Primary end points were overall survival and progression-free survival.\n\nResults: After a median follow-up of 7.8 months, the median overall survival was 15.9 months (95% confidence interval [CI], 13.2 to not reached) in the pembrolizumab-combination group and 11.3 months (95% CI, 9.5 to 14.8) in the placebo-combination group (hazard ratio for death, 0.64; 95% CI, 0.49 to 0.85; P<0.001). The overall survival benefit was consistent regardless of the level of PD-L1 expression. The median progression-free survival was 6.4 months (95% CI, 6.2 to 8.3) in the pembrolizumab-combination group and 4.8 months (95% CI, 4.3 to 5.7) in the placebo-combination group (hazard ratio for disease progression or death, 0.56; 95% CI, 0.45 to 0.70; P<0.001). Adverse events of grade 3 or higher occurred in 69.8% of the patients in the pembrolizumab-combination group and in 68.2% of the patients in the placebo-combination group. Discontinuation of treatment because of adverse events was more frequent in the pembrolizumab-combination group than in the placebo-combination group (13.3% vs. 6.4%).\n\nConclusions: In patients with previously untreated metastatic, squamous NSCLC, the addition of pembrolizumab to chemotherapy with carboplatin plus paclitaxel or nab-paclitaxel resulted in significantly longer overall survival and progression-free survival than chemotherapy alone. (Funded by Merck Sharp & Dohme; KEYNOTE-407 ClinicalTrials.gov number, NCT02775435.).\n\nIndexed on Europe PMC as PubMed record 30280635 (DOI 10.1056/nejmoa1810865). Its abstract cites the registry id NCT02775435, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1810865", pmid: "30280635", authors: "Paz-Ares L, Luft A, Vicente D, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02775435 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-407 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1810865"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30280635/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30280635"},{"label":"ClinicalTrials.gov NCT02775435","url":"https://clinicaltrials.gov/study/NCT02775435"}], tags: ["europepmc-ingest"], cancers: ["pdl1-high-nsclc","nsclc","lung-cancer"], drugs: ["pembrolizumab","carboplatin","paclitaxel"], targets: [], technologies: [], trials: ["keynote-407"], journals: ["nejm"] }),
  p({ id: "paper-keynote-407-j-clin-oncol-2023-update", name: "Pembrolizumab Plus Chemotherapy in Squamous Non-Small-Cell Lung Cancer: 5-Year Update of the Phase III KEYNOTE-407 Study", tldr: "Later report from the KEYNOTE-407 trial registered as NCT02775435, in Journal of Clinical Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Clinical trials frequently include multiple end points that mature at different times. The initial report, typically based on the primary end point, may be published when key planned co-primary or secondary analyses are not yet available. Clinical Trial Updates provide an opportunity to disseminate additional results from studies, published in JCO or elsewhere, for which the primary end point has already been reported. We report 5-year efficacy and safety outcomes from the phase III KEYNOTE-407 study (ClinicalTrials.gov identifier: NCT02775435). Eligible patients with previously untreated, metastatic squamous non-small-cell lung cancer (NSCLC) were randomly assigned 1:1 to pembrolizumab 200 mg or placebo plus carboplatin and paclitaxel/nab-paclitaxel once every 3 weeks for four cycles, followed by pembrolizumab or placebo for up to 35 cycles. Primary end points were overall survival (OS) and progression-free survival (PFS) per RECIST version 1.1 by blinded independent central review (BICR). Five hundred fifty-nine patients were randomly assigned in the intention-to-treat population (pembrolizumab plus chemotherapy, n = 278; placebo plus chemotherapy, n = 281). The median time from random assignment to data cutoff was 56.9 (range, 49.9-66.2) months. OS and PFS were improved with pembrolizumab plus chemotherapy versus placebo plus chemotherapy (hazard ratio [95% CI], 0.71 [0.59 to 0.85] and 0.62 [0.52 to 0.74]), with 5-year OS rates of 18.4% versus 9.7%, respectively. Toxicity was manageable. Among 55 patients who completed 35 cycles of pembrolizumab, the objective response rate was 90.9% and the 3-year OS rate after completion of 35 cycles (approximately 5 years after random assignment) was 69.5%. Pembrolizumab plus chemotherapy maintained an OS and PFS benefit versus placebo plus chemotherapy in previously untreated, metastatic squamous NSCLC and is a standard-of-care first-line treatment option for metastatic squamous NSCLC regardless of programmed death ligand 1 expression.\n\nIndexed on Europe PMC as PubMed record 36735893 (DOI 10.1200/jco.22.01990). Its abstract cites the registry id NCT02775435, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2023, doi: "10.1200/jco.22.01990", pmid: "36735893", authors: "Novello S, Kowalski DM, Luft A, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-407 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2023","url":"https://doi.org/10.1200/jco.22.01990"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36735893/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36735893"},{"label":"ClinicalTrials.gov NCT02775435","url":"https://clinicaltrials.gov/study/NCT02775435"}], tags: ["europepmc-ingest"], cancers: ["pdl1-high-nsclc","nsclc","lung-cancer"], drugs: ["pembrolizumab","carboplatin","paclitaxel"], targets: [], technologies: [], trials: ["keynote-407"], journals: ["jco"] }),
  p({ id: "paper-keynote-671-n-engl-j-med-2023", name: "Perioperative Pembrolizumab for Early-Stage Non-Small-Cell Lung Cancer", tldr: "Published report from the KEYNOTE-671 trial registered as NCT03425643, in New England Journal of Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Among patients with resectable early-stage non-small-cell lung cancer (NSCLC), a perioperative approach that includes both neoadjuvant and adjuvant immune checkpoint inhibition may provide benefit beyond either approach alone.\n\nMethods: We conducted a randomized, double-blind, phase 3 trial to evaluate perioperative pembrolizumab in patients with early-stage NSCLC. Participants with resectable stage II, IIIA, or IIIB (N2 stage) NSCLC were assigned in a 1:1 ratio to receive neoadjuvant pembrolizumab (200 mg) or placebo once every 3 weeks, each of which was given with cisplatin-based chemotherapy for 4 cycles, followed by surgery and adjuvant pembrolizumab (200 mg) or placebo once every 3 weeks for up to 13 cycles. The dual primary end points were event-free survival (the time from randomization to the first occurrence of local progression that precluded the planned surgery, unresectable tumor, progression or recurrence, or death) and overall survival. Secondary end points included major pathological response, pathological complete response, and safety.\n\nResults: A total of 397 participants were assigned to the pembrolizumab group, and 400 to the placebo group. At the prespecified first interim analysis, the median follow-up was 25.2 months. Event-free survival at 24 months was 62.4% in the pembrolizumab group and 40.6% in the placebo group (hazard ratio for progression, recurrence, or death, 0.58; 95% confidence interval [CI], 0.46 to 0.72; P<0.001). The estimated 24-month overall survival was 80.9% in the pembrolizumab group and 77.6% in the placebo group (P = 0.02, which did not meet the significance criterion). A major pathological response occurred in 30.2% of the participants in the pembrolizumab group and in 11.0% of those in the placebo group (difference, 19.2 percentage points; 95% CI, 13.9 to 24.7; P<0.0001; threshold, P = 0.0001), and a pathological complete response occurred in 18.1% and 4.0%, respectively (difference, 14.2 percentage points; 95% CI, 10.1 to 18.7; P<0.0001; threshold, P = 0.0001). Across all treatment phases, 44.9% of the participants in the pembrolizumab group and 37.3% of those in the placebo group had treatment-related adverse events of grade 3 or higher, including 1.0% and 0.8%, respectively, who had grade 5 events.\n\nConclusions: Among patients with resectable, early-stage NSCLC, neoadjuvant pembrolizumab plus chemotherapy followed by resection and adjuvant pembrolizumab significantly improved event-free survival, major pathological response, and pathological complete response as compared with neoadjuvant chemotherapy alone followed by surgery. Overall survival did not differ significantly between the groups in this analysis. (Funded by Merck Sharp and Dohme; KEYNOTE-671 ClinicalTrials.gov number, NCT03425643.).\n\nIndexed on Europe PMC as PubMed record 37272513 (DOI 10.1056/nejmoa2302983). Its abstract cites the registry id NCT03425643, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2302983", pmid: "37272513", authors: "Wakelee H, Liberman M, Kato T, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03425643 with the most citations, so it is the natural first reading for anyone following the KEYNOTE-671 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2302983"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37272513/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37272513"},{"label":"ClinicalTrials.gov NCT03425643","url":"https://clinicaltrials.gov/study/NCT03425643"}], tags: ["europepmc-ingest"], cancers: ["nsclc","resectable-nsclc"], drugs: ["pembrolizumab"], targets: [], technologies: [], trials: ["keynote-671"], journals: ["nejm"] }),
  p({ id: "paper-keynote-671-ann-oncol-2026-update", name: "Five-Year Outcomes of Perioperative Pembrolizumab for Early-Stage Non-Small-Cell Lung Cancer From the Randomized KEYNOTE-671 Study", tldr: "Later report from the KEYNOTE-671 trial registered as NCT03425643, in Annals of Oncology (2026); its title describes an updated or longer-term analysis.", summary: "Background: Adding perioperative pembrolizumab to neoadjuvant chemotherapy significantly improved survival outcomes compared with neoadjuvant chemotherapy and surgery alone in participants with early-stage non-small-cell lung cancer (NSCLC) in the phase 3, randomized KEYNOTE-671 study. We report results from KEYNOTE-671 after 5 years of follow-up.\n\nPatients and methods: Eligible participants with previously untreated, resectable stage II, IIIA, or IIIB (N2) NSCLC were randomized 1:1 to 4 cycles of pembrolizumab 200 mg or placebo every 3 weeks, plus platinum-doublet chemotherapy, followed by surgery then adjuvant pembrolizumab or placebo every 3 weeks for up to 13 cycles. Dual primary endpoints were event-free survival (EFS) per RECIST v1.1 by investigator assessment and overall survival (OS).\n\nResults: 797 participants were randomized to pembrolizumab (n=397) or placebo (n=400). Median time from randomization to data cutoff (July 3, 2025) was 60.4 (range, 42.6‒85.8) months. Five-year EFS was 49.9% (95% CI, 44.6‒55.0) in the pembrolizumab arm and 26.5% (95% CI, 21.7‒31.5) in the placebo arm (HR, 0.58; 95% CI, 0.48‒0.69); 5-year OS was 64.6% (95% CI, 59.5‒69.2) and 53.6% (95% CI, 48.3‒58.6), respectively (HR, 0.74; 95% CI, 0.59‒0.92). No detriment to health-related quality of life was identified in the pembrolizumab versus placebo arm with longer follow-up. Safety was consistent with the known profiles of each treatment.\n\nConclusions: After 5 years of follow-up, EFS was nearly double with perioperative pembrolizumab plus neoadjuvant chemotherapy, along with continued improvement in OS compared with neoadjuvant chemotherapy and surgery alone. The durable and clinically meaningful benefits observed support use of this treatment as a standard of care for patients with resectable early-stage NSCLC (ClinicalTrials.gov, NCT03425643).\n\nIndexed on Europe PMC as PubMed record 42628840 (DOI 10.1016/j.annonc.2026.08.005). Its abstract cites the registry id NCT03425643, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2026, doi: "10.1016/j.annonc.2026.08.005", pmid: "42628840", authors: "Wakelee H, Spicer JD, Gao S, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the KEYNOTE-671 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2026","url":"https://doi.org/10.1016/j.annonc.2026.08.005"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42628840/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42628840"},{"label":"ClinicalTrials.gov NCT03425643","url":"https://clinicaltrials.gov/study/NCT03425643"}], tags: ["europepmc-ingest"], cancers: ["nsclc","resectable-nsclc"], drugs: ["pembrolizumab"], targets: [], technologies: [], trials: ["keynote-671"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-laura-n-engl-j-med-2024", name: "Osimertinib after Chemoradiotherapy in Stage III EGFR -Mutated NSCLC", tldr: "Published report from the LAURA trial registered as NCT03521154, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Osimertinib is a recommended treatment for advanced non-small-cell lung cancer (NSCLC) with an epidermal growth factor receptor ( EGFR) mutation and as adjuvant treatment for resected EGFR -mutated NSCLC. EGFR tyrosine kinase inhibitors have shown preliminary efficacy in unresectable stage III EGFR -mutated NSCLC.\n\nMethods: In this phase 3, double-blind, placebo-controlled trial, we randomly assigned patients with unresectable EGFR -mutated stage III NSCLC without progression during or after chemoradiotherapy to receive osimertinib or placebo until disease progression occurred (as assessed by blinded independent central review) or the regimen was discontinued. The primary end point was progression-free survival as assessed by blinded independent central review.\n\nResults: A total of 216 patients who had undergone chemoradiotherapy were randomly assigned to receive osimertinib (143 patients) or placebo (73 patients). Osimertinib resulted in a significant progression-free survival benefit as compared with placebo: the median progression-free survival was 39.1 months with osimertinib versus 5.6 months with placebo, with a hazard ratio for disease progression or death of 0.16 (95% confidence interval [CI], 0.10 to 0.24; P<0.001). The percentage of patients who were alive and progression free at 12 months was 74% (95% CI, 65 to 80) with osimertinib and 22% (95% CI, 13 to 32) with placebo. Interim overall survival data (maturity, 20%) showed 36-month overall survival among 84% of patients with osimertinib (95% CI, 75 to 89) and 74% with placebo (95% CI, 57 to 85), with a hazard ratio for death of 0.81 (95% CI, 0.42 to 1.56; P = 0.53). The incidence of adverse events of grade 3 or higher was 35% in the osimertinib group and 12% in the placebo group; radiation pneumonitis (majority grade, 1 to 2) was reported in 48% and 38%, respectively. No new safety concerns emerged.\n\nConclusions: Treatment with osimertinib resulted in significantly longer progression-free survival than placebo in patients with unresectable stage III EGFR -mutated NSCLC. (Funded by AstraZeneca; LAURA ClinicalTrials.gov number, NCT03521154.).\n\nIndexed on Europe PMC as PubMed record 38828946 (DOI 10.1056/nejmoa2402614). Its abstract cites the registry id NCT03521154, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2402614", pmid: "38828946", authors: "Lu S, Kato T, Dong X, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03521154 with the most citations, so it is the natural first reading for anyone following the LAURA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2402614"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38828946/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38828946"},{"label":"ClinicalTrials.gov NCT03521154","url":"https://clinicaltrials.gov/study/NCT03521154"}], tags: ["europepmc-ingest"], cancers: ["nsclc","egfr-mutant-nsclc","stage-iii-unresectable-nsclc"], drugs: ["osimertinib"], targets: ["egfr"], technologies: [], trials: ["laura"], journals: ["nejm"] }),
  p({ id: "paper-luminosity-j-clin-oncol-2024", name: "Telisotuzumab Vedotin Monotherapy in Patients With Previously Treated c-Met Protein-Overexpressing Advanced Nonsquamous EGFR -Wildtype Non-Small Cell Lung Cancer in the Phase II LUMINOSITY Trial", tldr: "Published report from the LUMINOSITY trial registered as NCT03539536, in Journal of Clinical Oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Telisotuzumab vedotin (Teliso-V) is a c-Met-directed antibody-drug conjugate with a monomethyl auristatin E cytotoxic payload. The phase II LUMINOSITY trial (ClinicalTrials.gov identifier: NCT03539536) aimed to identify the optimal c-Met protein-overexpressing non-small cell lung cancer (NSCLC) population for treatment with Teliso-V (stage I) and expand the selected group for efficacy evaluation (stage II). Stage II enrolled patients with nonsquamous epidermal growth factor receptor ( EGFR)-wildtype NSCLC.\n\nMethods: Eligible patients had locally advanced/metastatic c-Met protein-overexpressing NSCLC and ≤2 previous lines of therapy (including ≤1 line of systemic chemotherapy). c-Met protein overexpression in nonsquamous EGFR -wildtype NSCLC was defined as ≥25% tumor cells with 3+ staining (high [≥50% 3+]; intermediate [≥25%-<50%]). Teliso-V was administered at 1.9 mg/kg once every 2 weeks. The primary end point was overall response rate (ORR) by independent central review.\n\nResults: In total, 172 patients with nonsquamous EGFR -wildtype NSCLC received Teliso-V in stages I and II. ORR was 28.6% (95% CI, 21.7 to 36.2; c-Met high, 34.6% [95% CI, 24.2 to 46.2]; c-Met intermediate, 22.9% [95% CI, 14.4 to 33.4]). The median duration of response was 8.3 months (95% CI, 5.6 to 11.3; c-Met high, 9.0 [95% CI, 4.2 to 13.0]; c-Met intermediate: 7.2 [95% CI, 5.3 to 11.5]). The median overall survival was 14.5 months (95% CI, 9.9 to 16.6; c-Met high, 14.6 [95% CI, 9.2 to 25.6]; c-Met intermediate, 14.2 [95% CI, 9.6 to 16.6]). The median progression-free survival was 5.7 months (95% CI, 4.6 to 6.9; c-Met high, 5.5 [95% CI, 4.1 to 8.3]; c-Met intermediate: 6.0 [95% CI, 4.5 to 8.1]). Most common any-grade treatment-related adverse events (AEs) were peripheral sensory neuropathy (30%), peripheral edema (16%), and fatigue (14%); the most common grade ≥3 AE was peripheral sensory neuropathy (7%).\n\nConclusion: Teliso-V was associated with durable responses in c-Met protein-overexpressing nonsquamous EGFR -wildtype NSCLC, especially in those with high c-Met. AEs were generally manageable.\n\nIndexed on Europe PMC as PubMed record 38843488 (DOI 10.1200/jco.24.00720). Its abstract cites the registry id NCT03539536, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2024, doi: "10.1200/jco.24.00720", pmid: "38843488", authors: "Camidge DR, Bar J, Horinouchi H, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03539536 with the most citations, so it is the natural first reading for anyone following the LUMINOSITY trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2024","url":"https://doi.org/10.1200/jco.24.00720"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38843488/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38843488"},{"label":"ClinicalTrials.gov NCT03539536","url":"https://clinicaltrials.gov/study/NCT03539536"}], tags: ["europepmc-ingest"], cancers: ["nsclc","met-altered-nsclc"], drugs: ["telisotuzumab-vedotin"], targets: ["met"], technologies: ["adc"], trials: ["luminosity"], journals: ["jco"] }),
  p({ id: "paper-luminosity-jto-clin-res-rep-2026-update", name: "Telisotuzumab Vedotin Monotherapy in Patients With Previously Treated c-Met Protein Overexpressing, Nonsquamous, EGFR Wild-type Advanced NSCLC: Updated Analysis of the LUMINOSITY Trial", tldr: "Later report from the LUMINOSITY trial registered as NCT03539536, in JTO clinical and research reports (2026); its title describes an updated or longer-term analysis.", summary: "Introduction: Telisotuzumab vedotin (Teliso-V) is a c-Met-directed antibody-drug conjugate comprising the monoclonal antibody telisotuzumab and the monomethyl auristatin E payload. Primary analysis of the phase 2 LUMINOSITY trial (NCT03539536) revealed Teliso-V monotherapy 1.9 mg/kg elicited durable responses and had generally manageable safety in patients with locally advanced or metastatic c-Met protein overexpressing, EGFR wild-type, nonsquamous NSCLC. We present updated outcomes with approximately 6 months longer follow-up and explore the impact of previous therapies.\n\nMethods: Patients (≥18 y; had previous therapy including ≤1 chemotherapy) received 1.9 mg/kg Teliso-V every 2 weeks. c-Met protein overexpression (clinical trial assay for MET [SP44] [Roche]) was defined as greater than or equal to 25% tumor cells with 3+ staining intensity (c-Met high: ≥50% 3+; c-Met intermediate: 25 to <50% 3+). Primary end point was the overall response rate by independent central review per the Response Evaluation Criteria in Solid Tumors version 1.1.\n\nResults: at February 21, 2024, 172 patients received at least one dose of Teliso-V; 168 patients (c-Met high, n = 84; c-Met intermediate, n = 84) were evaluable for efficacy. The overall response rate was 29.2% (95% confidence interval [CI]: 22.4-36.7; c-Met high, 34.5% [24.5-45.7]; c-Met intermediate, 23.8% [15.2-34.3]). Median duration of response was 7.2 months (95% CI: 5.5-11.0; c-Met high, 7.2 [95% CI: 4.2-12.0]; c-Met intermediate, 7.2 [95% CI: 4.7-11.5]). Previous therapy (platinum, immune checkpoint inhibitors, or both) did not impact efficacy outcomes. The most common treatment-related adverse event was peripheral sensory neuropathy (any-grade: 31%; grade ≥3: 7%).\n\nConclusions: Teliso-V monotherapy 1.9 mg/kg elicited durable responses, irrespective of the type of previous therapy received, and maintained a manageable safety profile in patients with c-Met protein overexpressing EGFR wild-type, nonsquamous NSCLC.\n\nClinicaltrialsgov id number: NCT03539536.\n\nIndexed on Europe PMC as PubMed record 42368479 (DOI 10.1016/j.jtocrr.2026.100988). Its abstract cites the registry id NCT03539536, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JTO clinical and research reports", year: 2026, doi: "10.1016/j.jtocrr.2026.100988", pmid: "42368479", authors: "Girard N, Goldman J, Lu S, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the LUMINOSITY trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"JTO Clin Res Rep 2026","url":"https://doi.org/10.1016/j.jtocrr.2026.100988"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42368479/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42368479"},{"label":"ClinicalTrials.gov NCT03539536","url":"https://clinicaltrials.gov/study/NCT03539536"}], tags: ["europepmc-ingest"], cancers: ["nsclc","met-altered-nsclc"], drugs: ["telisotuzumab-vedotin"], targets: ["met"], technologies: ["adc"], trials: ["luminosity"] }),
  p({ id: "paper-lung-map-s1400i-jama-oncol-2021", name: "Nivolumab Plus Ipilimumab vs Nivolumab for Previously Treated Patients With Stage IV Squamous Cell Lung Cancer: The Lung-MAP S1400I Phase 3 Randomized Clinical Trial", tldr: "Published report from the S1400I trial registered as NCT02785952, in JAMA Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Nivolumab plus ipilimumab is superior to platinum-based chemotherapy in treatment-naive advanced non-small cell lung cancer (NSCLC). Nivolumab is superior to docetaxel in advanced pretreated NSCLC.\n\nObjective: To determine whether the addition of ipilimumab to nivolumab improves survival in patients with advanced, pretreated, immunotherapy-naive squamous (Sq) NSCLC.\n\nDesign, setting, and participants: The Lung Cancer Master Protocol (Lung-MAP) S1400I phase 3, open-label randomized clinical trial was conducted from December 18, 2015, to April 23, 2018, randomizing patients in a 1:1 ratio to nivolumab alone or combined with ipilimumab. The median follow-up in surviving patients was 29.5 months. The trial was conducted through the National Clinical Trials Network and included patients with advanced immunotherapy-naive SqNSCLC and a Zubrod score of 0 (asymptomatic) to 1 (symptomatic but completely ambulatory) with disease progression after standard platinum-based chemotherapy. Randomization was stratified by sex and number of prior therapies (1 vs 2 or more). Data were analyzed from May 3, 2018, to February 1, 2021.\n\nInterventions: Nivolumab, 3 mg/kg intravenously every 2 weeks, with or without ipilimumab, 1 mg/kg intravenously every 6 weeks, until disease progression or intolerable toxic effects.\n\nMain outcomes and measures: The primary end point was overall survival (OS). Secondary end points included investigator-assessed progression-free survival (IA-PFS) and response per Response Evaluation Criteria in Solid Tumors (RECIST) guidelines, version 1.1.\n\nResults: Of 275 enrolled patients, 252 (mean age, 67.5 years [range 41.8-90.3 years]; 169 men [67%]; 206 White patients [82%]) were deemed eligible (125 randomized to nivolumab/ipilimumab and 127 to nivolumab). The study was closed for futility at a planned interim analysis. Overall survival was not significantly different between the groups (hazard ratio [HR], 0.87; 95% CI, 0.66-1.16; P =.34). Median survival was 10 months (95% CI, 8.0-14.4 months) in the nivolumab/ipilimumab group and 11 months (95% CI, 8.6-13.7 months) in the nivolumab group. The IA-PFS HR was 0.80 (95% CI, 0.61-1.03; P =.09); median IA-PFS was 3.8 months (95% CI, 2.7-4.4 months) in the nivolumab/ipilimumab group and 2.9 months (95% CI, 1.8-4.0 months) in the nivolumab alone group. Response rates were 18% (95% CI, 12%-25%) with nivolumab/ipilimumab and 17% (95% CI, 10%-23%) with nivolumab. Median response duration was 28.4 months (95% CI, 4.9 months to not reached) with nivolumab/ipilimumab and 9.7 months with nivolumab (95% CI, 4.2-23.1 months). Grade 3 or higher treatment-related adverse events occurred in 49 of 124 patients (39.5%) who received nivolumab/ipilimumab and in 41 of 123 (33.3%) who received nivolumab alone. Toxic effects led to discontinuation in 31 of 124 patients (25%) on nivolumab/ipilimumab and in 19 of 123 (15%) on nivolumab.\n\nConclusions and relevance: In this phase 3 randomized clinical trial, ipilimumab added to nivolumab did not improve outcomes in patients with advanced, pretreated, immune checkpoint inhibitor-naive SqNSCLC.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02785952.\n\nIndexed on Europe PMC as PubMed record 34264316 (DOI 10.1001/jamaoncol.2021.2209). Its abstract cites the registry id NCT02785952, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2021, doi: "10.1001/jamaoncol.2021.2209", pmid: "34264316", authors: "Gettinger SN, Redman MW, Bazhenova L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02785952 with the most citations, so it is the natural first reading for anyone following the S1400I trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2021","url":"https://doi.org/10.1001/jamaoncol.2021.2209"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34264316/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34264316"},{"label":"ClinicalTrials.gov NCT02785952","url":"https://clinicaltrials.gov/study/NCT02785952"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["nivolumab","ipilimumab"], targets: [], technologies: ["checkpoint-inhibitor"], trials: ["lung-map-s1400i"], journals: ["jama-oncology"] }),
  p({ id: "paper-navigate-j-clin-invest-2021", name: "NTRK and RET fusion-directed therapy in pediatric thyroid cancer yields a tumor response and radioiodine uptake", tldr: "Published report from the NAVIGATE trial registered as NCT02576431, in Journal of Clinical Investigation (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "BACKGROUNDMolecular characterization in pediatric papillary thyroid cancer (PTC), distinct from adult PTC, is important for developing molecularly targeted therapies for progressive radioiodine-refractory (131I-refractory) PTC.METHODSPTC samples from 106 pediatric patients (age range: 4.3-19.8 years; n = 84 girls, n = 22 boys) who were admitted to SNUH (January 1983-March 2020) were available for genomic profiling. Previous transcriptomic data from 125 adult PTC samples were used for comparison.RESULTSWe identified genetic drivers in 80 tumors: 31 with fusion oncogenes (RET in 21 patients, ALK in 6 patients, and NTRK1/3 in 4 patients); 47 with point mutations (BRAFV600E in 41 patients, TERTC228T in 2 patients [1 of whom had a coexisting BRAFV600E], and DICER1 variants in 5 patients); and 2 with amplifications. Fusion oncogene PTCs, which are predominantly detected in younger patients, were at a more advanced stage and showed more recurrent or persistent disease compared with BRAFV600E PTCs, which are detected mostly in adolescents. Pediatric fusion PTCs (in patients <10 years of age) had lower expression of thyroid differentiation genes, including SLC5A5, than did adult fusion PTCs. Two girls with progressive 131I-refractory lung metastases harboring a TPR-NTRK1 or CCDC6-RET fusion oncogene received fusion-targeted therapy; larotrectinib and selpercatinib decreased the size of the tumor and restored 125I radioiodine uptake. The girl with the CCDC6-RET fusion oncogene received 131I therapy combined with selpercatinib, resulting in a tumor response. In vitro 125I uptake and 131I clonogenic assays showed that larotrectinib inhibited tumor growth and restored radioiodine avidity.CONCLUSIONSIn pediatric patients with fusion oncogene PTC who have 131I-refractory advanced disease, selective fusion-directed therapy may restore radioiodine avidity and lead to a dramatic tumor response, underscoring the importance of molecular testing in pediatric patients with PTC.FUNDINGThe Ministry of Science, ICT and Future Planning (NRF-2016R1A2B4012417 and 2019R1A2C2084332); the Korean Ministry of Health and Welfare (H14C1277); the Ministry of Education (2020R1A6A1A03047972); and the SNUH Research Fund (04-2015-0830).TRIAL REGISTRATIONTwo patients received fusion-targeted therapy with larotrectinib (NCT02576431; NAVIGATE) or selpercatinib (LOXO-RET-18018).\n\nIndexed on Europe PMC as PubMed record 34237031 (DOI 10.1172/jci144847). Its abstract cites the registry id NCT02576431, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Investigation", year: 2021, doi: "10.1172/jci144847", pmid: "34237031", authors: "Lee YA, Lee H, Im SW, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02576431 with the most citations, so it is the natural first reading for anyone following the NAVIGATE trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Invest 2021","url":"https://doi.org/10.1172/jci144847"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34237031/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34237031"},{"label":"ClinicalTrials.gov NCT02576431","url":"https://clinicaltrials.gov/study/NCT02576431"}], tags: ["europepmc-ingest"], cancers: ["metastatic-cancer","ntrk-fusion-nsclc"], drugs: ["larotrectinib"], targets: ["ntrk"], technologies: [], trials: ["navigate"], journals: ["jci"] }),
  p({ id: "paper-orient-11-j-thorac-oncol-2020", name: "Efficacy and Safety of Sintilimab Plus Pemetrexed and Platinum as First-Line Treatment for Locally Advanced or Metastatic Nonsquamous NSCLC: a Randomized, Double-Blind, Phase 3 Study (Oncology pRogram by InnovENT anti-PD-1-11)", tldr: "Published report from the ORIENT-11 trial registered as NCT03607539, in Journal of Thoracic Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Sintilimab, an anti-programmed death 1 antibody, plus pemetrexed and platinum had revealed promising efficacy for nonsquamous NSCLC in a phase 1b study. We conducted a randomized, double-blind, phase 3 study to compare the efficacy and safety of sintilimab with placebo, both in combination with such chemotherapy (ClinicalTrials.gov: NCT03607539).\n\nMethods: A total of 397 patients with previously untreated, locally advanced or metastatic nonsquamous NSCLC without sensitizing EGFR or anaplastic lymphoma kinase genomic aberration were randomized (2:1 ratio) to receive either sintilimab 200 mg or placebo plus pemetrexed and platinum once every 3 weeks for four cycles, followed by sintilimab or placebo plus pemetrexed therapy. Crossover or treatment beyond disease progression was allowed. The primary end point was progression-free survival (PFS) as judged by an independent radiographic review committee.\n\nResults: at November 15, 2019, the median follow-up was 8.9 months. The median PFS was significantly longer in the sintilimab-combination group than that in the placebo-combination group (8.9 versus 5.0 mo; hazard ratio, 0.482, 95% confidence interval [CI]: 0.362-0.643; p < 0.00001). The confirmed objective response rate was 51.9% (95% CI: 45.7%-58.0%) in the sintilimab-combination group and 29.8% (95% CI: 22.1%-38.4%) in placebo-combination group. The incidence of grade 3 or higher adverse events was 61.7% in sintilimab-combination group and 58.8% in placebo-combination group.\n\nConclusions: In Chinese patients with previously untreated, locally advanced or metastatic nonsquamous NSCLC, the addition of sintilimab to chemotherapy with pemetrexed and platinum resulted in considerably longer PFS than with chemotherapy alone with manageable safety profiles.\n\nIndexed on Europe PMC as PubMed record 32781263 (DOI 10.1016/j.jtho.2020.07.014). Its abstract cites the registry id NCT03607539, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2020, doi: "10.1016/j.jtho.2020.07.014", pmid: "32781263", authors: "Yang Y, Wang Z, Fang J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03607539 with the most citations, so it is the natural first reading for anyone following the ORIENT-11 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2020","url":"https://doi.org/10.1016/j.jtho.2020.07.014"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32781263/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32781263"},{"label":"ClinicalTrials.gov NCT03607539","url":"https://clinicaltrials.gov/study/NCT03607539"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["sintilimab","pemetrexed"], targets: [], technologies: ["checkpoint-inhibitor"], trials: ["orient-11"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-orient-11-lung-cancer-2022-update", name: "Final overall survival data of sintilimab plus pemetrexed and platinum as First-Line treatment for locally advanced or metastatic nonsquamous NSCLC in the Phase 3 ORIENT-11 study", tldr: "Later report from the ORIENT-11 trial registered as NCT03607539, in Lung cancer (2022); its title describes an updated or longer-term analysis.", summary: "Objectives: In ORIENT-11, first-line sintilimab + pemetrexed-platinum significantly improved PFS compared with placebo + pemetrexed-platinum in patients with advanced metastatic nonsquamous non-small-cell lung cancer (AMnsqNSCLC). The study met the primary endpoint of PFS at 15November2019. Here we report final survival analysis from ORIENT-11 (NCT03607539) using a 15September2021 data cutoff.\n\nMethods: Patients with treatment-naïve locally AMnsqNSCLC without sensitizing EGFR or ALK genomic tumor aberrations were randomly assigned to sintilimab + pemetrexed-platinum (n = 266) or placebo + pemetrexed-platinum (n = 131). Patients were stratified by PD-L1 expression, platinum-chemotherapy, and gender. Treatment continued until PD, unacceptable toxicity, or a maximum of 24 months. Patients in the placebo + pemetrexed-platinum arm could be sequenced to second-line sintilimab monotherapy, contingent upon PD. Response was assessed (RECISTv.1.1) by blinded independent radiographic review committee. Primary endpoint was PFS. OS was a secondary endpoint and defined from date of randomization to date of death due to any cause. Final OS analysis was defined as approximately 2 years after last patient randomized or when approximately 65 % of patients died, whichever first.\n\nResults: At data cutoff of final OS analysis, median study follow-up was 30.8 months. Of 397 patients, 243 OS events were observed (sintilimab + pemetrexed-platinum:151[57 %];placebo + pemetrexed-platinum:92 [70 %]). Of the patients in placebo + pemetrexed-platinum arm, 47 % crossed over to sintilimab monotherapy per protocol. Median OS was 24.2 months in sintilimab + pemetrexed-platinum arm and 16.8 months in placebo + pemetrexed-platinum arm (HR:0.65[95 % CI:0.50,0.85]). Estimated 2-year OS rates were 50 %(sintilimab + pemetrexed-platinum) and 32 %(placebo + pemetrexed-platinum). After adjusting for the crossover effect, OS treatment effect was more pronounced with HR 0.52 (95 % CI:0.38,0.69). OS benefit across all prespecified subgroups was largely consistent with that observed in the ITT population.\n\nConclusions: In the ORIENT-11 final OS analysis, sintilimab + pemetrexed-platinum demonstrated improved OS compared to placebo + pemetrexed-platinum when administered as first-line therapy in AMnsqNSCLC without EGFR or ALK genomic tumor aberrations.\n\nIndexed on Europe PMC as PubMed record 35917647 (DOI 10.1016/j.lungcan.2022.07.013). Its abstract cites the registry id NCT03607539, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Lung cancer", year: 2022, doi: "10.1016/j.lungcan.2022.07.013", pmid: "35917647", authors: "Zhang L, Wang Z, Fang J, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the ORIENT-11 trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lung Cancer 2022","url":"https://doi.org/10.1016/j.lungcan.2022.07.013"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35917647/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35917647"},{"label":"ClinicalTrials.gov NCT03607539","url":"https://clinicaltrials.gov/study/NCT03607539"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["sintilimab","pemetrexed"], targets: [], technologies: ["checkpoint-inhibitor"], trials: ["orient-11"], journals: ["lung-cancer-journal"] }),
  p({ id: "paper-pacific-n-engl-j-med-2018-update", name: "Overall Survival with Durvalumab after Chemoradiotherapy in Stage III NSCLC", tldr: "Later report from the PACIFIC trial registered as NCT02125461, in New England Journal of Medicine (2018); its title describes an updated or longer-term analysis.", summary: "Background: An earlier analysis in this phase 3 trial showed that durvalumab significantly prolonged progression-free survival, as compared with placebo, among patients with stage III, unresectable non-small-cell lung cancer (NSCLC) who did not have disease progression after concurrent chemoradiotherapy. Here we report the results for the second primary end point of overall survival.\n\nMethods: We randomly assigned patients, in a 2:1 ratio, to receive durvalumab intravenously, at a dose of 10 mg per kilogram of body weight, or matching placebo every 2 weeks for up to 12 months. Randomization occurred 1 to 42 days after the patients had received chemoradiotherapy and was stratified according to age, sex, and smoking history. The primary end points were progression-free survival (as assessed by blinded independent central review) and overall survival. Secondary end points included the time to death or distant metastasis, the time to second progression, and safety.\n\nResults: Of the 713 patients who underwent randomization, 709 received the assigned intervention (473 patients received durvalumab and 236 received placebo). at March 22, 2018, the median follow-up was 25.2 months. The 24-month overall survival rate was 66.3% (95% confidence interval [CI], 61.7 to 70.4) in the durvalumab group, as compared with 55.6% (95% CI, 48.9 to 61.8) in the placebo group (two-sided P=0.005). Durvalumab significantly prolonged overall survival, as compared with placebo (stratified hazard ratio for death, 0.68; 99.73% CI, 0.47 to 0.997; P=0.0025). Updated analyses regarding progression-free survival were similar to those previously reported, with a median duration of 17.2 months in the durvalumab group and 5.6 months in the placebo group (stratified hazard ratio for disease progression or death, 0.51; 95% CI, 0.41 to 0.63). The median time to death or distant metastasis was 28.3 months in the durvalumab group and 16.2 months in the placebo group (stratified hazard ratio, 0.53; 95% CI, 0.41 to 0.68). A total of 30.5% of the patients in the durvalumab group and 26.1% of those in the placebo group had grade 3 or 4 adverse events of any cause; 15.4% and 9.8% of the patients, respectively, discontinued the trial regimen because of adverse events.\n\nConclusions: Durvalumab therapy resulted in significantly longer overall survival than placebo. No new safety signals were identified. (Funded by AstraZeneca; PACIFIC ClinicalTrials.gov number, NCT02125461.).\n\nIndexed on Europe PMC as PubMed record 30280658 (DOI 10.1056/nejmoa1809697). Its abstract cites the registry id NCT02125461, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2018, doi: "10.1056/nejmoa1809697", pmid: "30280658", authors: "Antonia SJ, Villegas A, Daniel D, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the PACIFIC trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"N Engl J Med 2018","url":"https://doi.org/10.1056/nejmoa1809697"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30280658/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30280658"},{"label":"ClinicalTrials.gov NCT02125461","url":"https://clinicaltrials.gov/study/NCT02125461"}], tags: ["europepmc-ingest"], cancers: ["nsclc","stage-iii-unresectable-nsclc"], drugs: ["durvalumab"], targets: [], technologies: ["imrt-igrt","checkpoint-inhibitor"], trials: ["pacific"], journals: ["nejm"] }),
  p({ id: "paper-pharos-j-thorac-oncol-2025", name: "Updated Efficacy and Safety From the Phase 2 PHAROS Study of Encorafenib Plus Binimetinib in Patients With BRAF V600E-Mutant Metastatic NSCLC-A Brief Report", tldr: "Published report from the PHAROS trial registered as NCT03915951, in Journal of Thoracic Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: The PHAROS primary analysis revealed robust antitumor activity and acceptable safety with encorafenib plus binimetinib in patients with BRAF V600E-mutant metastatic NSCLC (mNSCLC). We report results after 18 months of additional follow-up.\n\nMethods: In this ongoing open-label, single-arm, phase 2 study, patients with BRAF V600E-mutant mNSCLC (59 treatment-naive and 39 previously treated) received encorafenib 450 mg once daily and binimetinib 45 mg twice daily. Primary end point was objective response rate (ORR). Secondary end points included duration of response (DOR), progression-free survival (PFS), overall survival (OS), and safety.\n\nResults: At this data cutoff, median treatment duration with encorafenib plus binimetinib was 16.3 months in treatment-naive and 5.5 months in previously treated patients; minimum follow-up was approximately 32 and 22 months, respectively. In treatment-naive patients, the ORR was 75%, median DOR was 40.0 months, median PFS was 30.2 months, median OS was not estimable (95% confidence interval: 31.3-not estimable), and the 3-year OS probability was 53%. In previously treated patients, the ORR was 46%, median DOR was 16.7 months, median PFS was 9.3 months, median OS was 22.7 months, and the 3-year OS probability was 29%. Overall, the most frequent treatment-related adverse events were nausea (52%), diarrhea (44%), fatigue (33%), and vomiting (30%). Treatment-related adverse events led to dose reductions and permanent treatment discontinuations in 25 (26%) and 16 (16%) patients, respectively.\n\nConclusions: With longer follow-up, encorafenib plus binimetinib showed durable and clinically meaningful antitumor activity, especially in treatment-naive patients, with a manageable safety profile in patients with BRAF V600E-mutant mNSCLC.\n\nClinical trial information: ClinicalTrials.gov Identifier: NCT03915951.\n\nIndexed on Europe PMC as PubMed record 40480428 (DOI 10.1016/j.jtho.2025.05.023). Its abstract cites the registry id NCT03915951, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2025.05.023", pmid: "40480428", authors: "Riely GJ, Ahn MJ, Clarke JM, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03915951 with the most citations, so it is the natural first reading for anyone following the PHAROS trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2025.05.023"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40480428/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40480428"},{"label":"ClinicalTrials.gov NCT03915951","url":"https://clinicaltrials.gov/study/NCT03915951"}], tags: ["europepmc-ingest"], cancers: ["nsclc","braf-v600e-nsclc"], drugs: ["encorafenib","binimetinib","dabrafenib-trametinib"], targets: ["braf"], technologies: ["kinase-inhibitors"], trials: ["pharos"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-ponsegromab-phase-2-n-engl-j-med-2024", name: "Ponsegromab for the Treatment of Cancer Cachexia", tldr: "Published report from the trial registered as NCT05546476, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Cachexia is a common complication of cancer and is associated with an increased risk of death. The level of growth differentiation factor 15 (GDF-15), a circulating cytokine, is elevated in cancer cachexia. In a small, open-label, phase 1b study involving patients with cancer cachexia, ponsegromab, a humanized monoclonal antibody inhibiting GDF-15, was associated with improved weight, appetite, and physical activity, along with suppressed serum GDF-15 levels.\n\nMethods: In this phase 2, randomized, double-blind, 12-week trial, we assigned patients with cancer cachexia and an elevated serum GDF-15 level (≥1500 pg per milliliter) in a 1:1:1:1 ratio to receive ponsegromab at a dose of 100 mg, 200 mg, or 400 mg or to receive placebo, administered subcutaneously every 4 weeks for three doses. The primary end point was the change from baseline in body weight at 12 weeks. Key secondary end points were appetite and cachexia symptoms, digital measures of physical activity, and safety.\n\nResults: A total of 187 patients underwent randomization. Of these patients, 40% had non-small-cell lung cancer, 32% had pancreatic cancer, and 29% had colorectal cancer. At 12 weeks, patients in the ponsegromab groups had significantly greater weight gain than those in the placebo group, with a median between-group difference of 1.22 kg (95% credible interval, 0.37 to 2.25) in the 100-mg group, 1.92 (95% credible interval, 0.92 to 2.97) in the 200-mg group, and 2.81 (95% credible interval, 1.55 to 4.08) in the 400-mg group. Improvements were observed across measures of appetite and cachexia symptoms, along with physical activity, in the 400-mg ponsegromab group relative to placebo. Adverse events of any cause were reported in 70% of the patients in the ponsegromab group and in 80% of those in the placebo group.\n\nConclusions: Among patients with cancer cachexia and elevated GDF-15 levels, the inhibition of GDF-15 with ponsegromab resulted in increased weight gain and overall activity level and reduced cachexia symptoms, findings that confirmed the role of GDF-15 as a driver of cachexia. (Funded by Pfizer; ClinicalTrials.gov number, NCT05546476.).\n\nIndexed on Europe PMC as PubMed record 39282907 (DOI 10.1056/nejmoa2409515). Its abstract cites the registry id NCT05546476, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2409515", pmid: "39282907", authors: "Groarke JD, Crawford J, Collins SM, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05546476 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2409515"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39282907/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39282907"},{"label":"ClinicalTrials.gov NCT05546476","url":"https://clinicaltrials.gov/study/NCT05546476"}], tags: ["europepmc-ingest"], cancers: ["nsclc","pancreatic","colorectal"], drugs: [], targets: [], technologies: ["cachexia-therapy","cachexia-appetite-pharmacotherapy"], trials: ["ponsegromab-phase-2"], journals: ["nejm"] }),
  p({ id: "paper-romana-1-2-lancet-oncol-2016", name: "Anamorelin in patients with non-small-cell lung cancer and cachexia (ROMANA 1 and ROMANA 2): results from two randomised, double-blind, phase 3 trials", tldr: "Published report from the ROMANA 1 trial registered as NCT01387269, in The Lancet Oncology (2016), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Patients with advanced cancer frequently experience anorexia and cachexia, which are associated with reduced food intake, altered body composition, and decreased functionality. We assessed anamorelin, a novel ghrelin-receptor agonist, on cachexia in patients with advanced non-small-cell lung cancer and cachexia.\n\nMethods: ROMANA 1 and ROMANA 2 were randomised, double-blind, placebo-controlled phase 3 trials done at 93 sites in 19 countries. Patients with inoperable stage III or IV non-small-cell lung cancer and cachexia (defined as ≥5% weight loss within 6 months or body-mass index <20 kg/m(2)) were randomly assigned 2:1 to anamorelin 100 mg orally once daily or placebo, with a computer-generated randomisation algorithm stratified by geographical region, cancer treatment status, and weight loss over the previous 6 months. Co-primary efficacy endpoints were the median change in lean body mass and handgrip strength over 12 weeks and were measured in all study participants (intention-to-treat population). Both trials are now completed and are registered with ClinicalTrials.gov, numbers NCT01387269 and NCT01387282.\n\nFindings: From July 8, 2011, to Jan 28, 2014, 484 patients were enrolled in ROMANA 1 (323 to anamorelin, 161 to placebo), and from July 14, 2011, to Oct 31, 2013, 495 patients were enrolled in ROMANA 2 (330 to anamorelin, 165 to placebo). Over 12 weeks, lean body mass increased in patients assigned to anamorelin compared with those assigned to placebo in ROMANA 1 (median increase 0·99 kg [95% CI 0·61 to 1·36] vs -0·47 kg [-1·00 to 0·21], p<0·0001) and ROMANA 2 (0·65 kg [0·38 to 0·91] vs -0·98 kg [-1·49 to -0·41], p<0·0001). We noted no difference in handgrip strength in ROMANA 1 (-1·10 kg [-1·69 to -0·40] vs -1·58 kg [-2·99 to -1·14], p=0·15) or ROMANA 2 (-1·49 kg [-2·06 to -0·58] vs -0·95 kg [-1·56 to 0·04], p=0·65). There were no differences in grade 3-4 treatment-related adverse events between study groups; the most common grade 3-4 adverse event was hyperglycaemia, occurring in one (<1%) of 320 patients given anamorelin in ROMANA 1 and in four (1%) of 330 patients given anamorelin in ROMANA 2.\n\nInterpretation: Anamorelin significantly increased lean body mass, but not handgrip, strength in patients with advanced non-small-cell lung cancer. Considering the unmet medical need for safe and effective treatments for cachexia, anamorelin might be a treatment option for patients with cancer anorexia and cachexia.\n\nFunding: Helsinn Therapeutics.\n\nIndexed on Europe PMC as PubMed record 26906526 (DOI 10.1016/s1470-2045(15)00558-6). Its abstract cites the registry id NCT01387269, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2016, doi: "10.1016/s1470-2045(15)00558-6", pmid: "26906526", authors: "Temel JS, Abernethy AP, Currow DC, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01387269 with the most citations, so it is the natural first reading for anyone following the ROMANA 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","The abstract cites more than one registry id (NCT01387269, NCT01387282); it was kept because the trial's acronym appears in the title."], links: [{"label":"Lancet Oncol 2016","url":"https://doi.org/10.1016/s1470-2045(15)00558-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/26906526/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/26906526"},{"label":"ClinicalTrials.gov NCT01387269","url":"https://clinicaltrials.gov/study/NCT01387269"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: [], targets: [], technologies: ["cachexia-appetite-pharmacotherapy","cachexia-therapy"], trials: ["romana-1-2"], journals: ["lancet-oncology"] }),
  p({ id: "paper-rtog-0617-lancet-oncol-2015", name: "Standard-dose versus high-dose conformal radiotherapy with concurrent and consolidation carboplatin plus paclitaxel with or without cetuximab for patients with stage IIIA or IIIB non-small-cell lung cancer (RTOG 0617): a randomised, two-by-two factorial phase 3 study", tldr: "Published report from the RTOG 0617 trial registered as NCT00533949, in The Lancet Oncology (2015), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: We aimed to compare overall survival after standard-dose versus high-dose conformal radiotherapy with concurrent chemotherapy and the addition of cetuximab to concurrent chemoradiation for patients with inoperable stage III non-small-cell lung cancer.\n\nMethods: In this open-label randomised, two-by-two factorial phase 3 study in 185 institutions in the USA and Canada, we enrolled patients (aged ≥ 18 years) with unresectable stage III non-small-cell lung cancer, a Zubrod performance status of 0-1, adequate pulmonary function, and no evidence of supraclavicular or contralateral hilar adenopathy. We randomly assigned (1:1:1:1) patients to receive either 60 Gy (standard dose), 74 Gy (high dose), 60 Gy plus cetuximab, or 74 Gy plus cetuximab. All patients also received concurrent chemotherapy with 45 mg/m(2) paclitaxel and carboplatin once a week (AUC 2); 2 weeks after chemoradiation, two cycles of consolidation chemotherapy separated by 3 weeks were given consisting of paclitaxel (200 mg/m(2)) and carboplatin (AUC 6). Randomisation was done with permuted block randomisation methods, stratified by radiotherapy technique, Zubrod performance status, use of PET during staging, and histology; treatment group assignments were not masked. Radiation dose was prescribed to the planning target volume and was given in 2 Gy daily fractions with either intensity-modulated radiation therapy or three-dimensional conformal radiation therapy. The use of four-dimensional CT and image-guided radiation therapy were encouraged but not necessary. For patients assigned to receive cetuximab, 400 mg/m(2) cetuximab was given on day 1 followed by weekly doses of 250 mg/m(2), and was continued through consolidation therapy. The primary endpoint was overall survival. All analyses were done by modified intention-to-treat. The study is registered with ClinicalTrials.gov, number NCT00533949.\n\nFindings: Between Nov 27, 2007, and Nov 22, 2011, 166 patients were randomly assigned to receive standard-dose chemoradiotherapy, 121 to high-dose chemoradiotherapy, 147 to standard-dose chemoradiotherapy and cetuximab, and 110 to high-dose chemoradiotherapy and cetuximab. Median follow-up for the radiotherapy comparison was 22.9 months (IQR 27.5-33.3). Median overall survival was 28.7 months (95% CI 24.1-36.9) for patients who received standard-dose radiotherapy and 20.3 months (17.7-25.0) for those who received high-dose radiotherapy (hazard ratio [HR] 1.38, 95% CI 1.09-1.76; p=0.004). Median follow-up for the cetuximab comparison was 21.3 months (IQR 23.5-29.8). Median overall survival in patients who received cetuximab was 25.0 months (95% CI 20.2-30.5) compared with 24.0 months (19.8-28.6) in those who did not (HR 1.07, 95% CI 0.84-1.35; p=0.29). Both the radiation-dose and cetuximab results crossed protocol-specified futility boundaries. We recorded no statistical differences in grade 3 or worse toxic effects between radiotherapy groups. By contrast, the use of cetuximab was associated with a higher rate of grade 3 or worse toxic effects (205 [86%] of 237 vs 160 [70%] of 228 patients; p<0.0001). There were more treatment-related deaths in the high-dose chemoradiotherapy and cetuximab groups (radiotherapy comparison: eight vs three patients; cetuximab comparison: ten vs five patients). There were no differences in severe pulmonary events between treatment groups. Severe oesophagitis was more common in patients who received high-dose chemoradiotherapy than in those who received standard-dose treatment (43 [21%] of 207 patients vs 16 [7%] of 217 patients; p<0.0001).\n\nInterpretation: 74 Gy radiation given in 2 Gy fractions with concurrent chemotherapy was not better than 60 Gy plus concurrent chemotherapy for patients with stage III non-small-cell lung cancer, and might be potentially harmful. Addition of cetuximab to concurrent chemoradiation and consolidation treatment provided no benefit in overall survival for these patients.\n\nFunding: National Cancer Institute and Bristol-Myers Squibb.\n\nIndexed on Europe PMC as PubMed record 25601342 (DOI 10.1016/s1470-2045(14)71207-0). Its abstract cites the registry id NCT00533949, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2015, doi: "10.1016/s1470-2045(14)71207-0", pmid: "25601342", authors: "Bradley JD, Paulus R, Komaki R, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT00533949 with the most citations, so it is the natural first reading for anyone following the RTOG 0617 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2015","url":"https://doi.org/10.1016/s1470-2045(14)71207-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/25601342/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/25601342"},{"label":"ClinicalTrials.gov NCT00533949","url":"https://clinicaltrials.gov/study/NCT00533949"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["cetuximab","carboplatin","paclitaxel"], targets: [], technologies: ["imrt-igrt","radiosensitisers"], trials: ["rtog-0617"], journals: ["lancet-oncology"] }),
  p({ id: "paper-sabr-comet-lancet-2019", name: "Stereotactic ablative radiotherapy versus standard of care palliative treatment in patients with oligometastatic cancers (SABR-COMET): a randomised, phase 2, open-label trial", tldr: "Published report from the trial registered as NCT01446744, in The Lancet (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The oligometastatic paradigm suggests that some patients with a limited number of metastases might be cured if all lesions are eradicated. Evidence from randomised controlled trials to support this paradigm is scarce. We aimed to assess the effect of stereotactic ablative radiotherapy (SABR) on survival, oncological outcomes, toxicity, and quality of life in patients with a controlled primary tumour and one to five oligometastatic lesions.\n\nMethods: This randomised, open-label phase 2 study was done at 10 hospitals in Canada, the Netherlands, Scotland, and Australia. Patients aged 18 or older with a controlled primary tumour and one to five metastatic lesions, Eastern Cooperative Oncology Group score of 0-1, and a life expectancy of at least 6 months were eligible. After stratifying by the number of metastases (1-3 vs 4-5), we randomly assigned patients (1:2) to receive either palliative standard of care treatments alone (control group), or standard of care plus SABR to all metastatic lesions (SABR group), using a computer-generated randomisation list with permuted blocks of nine. Neither patients nor physicians were masked to treatment allocation. The primary endpoint was overall survival. We used a randomised phase 2 screening design with a two-sided α of 0·20 (wherein p<0·20 designates a positive trial). All analyses were intention to treat. This study is registered with ClinicalTrials.gov, number NCT01446744.\n\nFindings: 99 patients were randomised between Feb 10, 2012, and Aug 30, 2016. Of 99 patients, 33 (33%) were assigned to the control group and 66 (67%) to the SABR group. Two (3%) patients in the SABR group did not receive allocated treatment and withdrew from the trial; two (6%) patients in the control group also withdrew from the trial. Median follow-up was 25 months (IQR 19-54) in the control group versus 26 months (23-37) in the SABR group. Median overall survival was 28 months (95% CI 19-33) in the control group versus 41 months (26-not reached) in the SABR group (hazard ratio 0·57, 95% CI 0·30-1·10; p=0·090). Adverse events of grade 2 or worse occurred in three (9%) of 33 controls and 19 (29%) of 66 patients in the SABR group (p=0·026), an absolute increase of 20% (95% CI 5-34). Treatment-related deaths occurred in three (4·5%) of 66 patients after SABR, compared with none in the control group.\n\nInterpretation: SABR was associated with an improvement in overall survival, meeting the primary endpoint of this trial, but three (4·5%) of 66 patients in the SABR group had treatment-related death. Phase 3 trials are needed to conclusively show an overall survival benefit, and to determine the maximum number of metastatic lesions wherein SABR provides a benefit.\n\nFunding: Ontario Institute for Cancer Research and London Regional Cancer Program Catalyst Grant.\n\nIndexed on Europe PMC as PubMed record 30982687 (DOI 10.1016/s0140-6736(18)32487-5). Its abstract cites the registry id NCT01446744, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2019, doi: "10.1016/s0140-6736(18)32487-5", pmid: "30982687", authors: "Palma DA, Olson R, Harrow S, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01446744 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2019","url":"https://doi.org/10.1016/s0140-6736(18)32487-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30982687/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/30982687"},{"label":"ClinicalTrials.gov NCT01446744","url":"https://clinicaltrials.gov/study/NCT01446744"}], tags: ["europepmc-ingest"], cancers: ["metastatic-cancer","breast-hr-positive","nsclc","colorectal","prostate"], drugs: [], targets: [], technologies: ["sbrt"], trials: ["sabr-comet"], journals: ["lancet"] }),
  p({ id: "paper-soho-01-n-engl-j-med-2025", name: "Sevabertinib in Advanced HER2 -Mutant Non-Small-Cell Lung Cancer", tldr: "Published report from the SOHO-01 trial registered as NCT05099172, in New England Journal of Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: HER2 gene mutations occur in 2 to 4% of patients with non-small-cell lung cancer (NSCLC). Sevabertinib is an oral, reversible tyrosine kinase inhibitor that has shown anti-HER2 activity in preclinical models.\n\nMethods: We conducted an open-label, multicenter, multicohort, phase 1-2 study to evaluate sevabertinib at a twice-daily dose of 20 mg in patients with locally advanced or metastatic HER2 -mutant NSCLC. Three cohorts were defined according to previous therapy: cohort D comprised previously treated patients who had not received HER2-targeted therapy; cohort E, patients who had previously received HER2-directed antibody-drug conjugates; and cohort F, patients who had not previously received treatment. The primary end point was an objective response, as assessed by blinded independent central review. Secondary end points were duration of response and progression-free survival.\n\nResults: A total of 209 patients received sevabertinib (at June 27, 2025, the data-cutoff date); the median duration of follow-up was 13.8 months in cohort D, 11.7 months in cohort E, and 9.9 months in cohort F. Among 81 patients in cohort D, an objective response was observed in 64% (95% confidence interval [CI], 53 to 75); the median duration of response was 9.2 months (95% CI, 6.3 to 13.5), and the median progression-free survival was 8.3 months (95% CI, 6.9 to 12.3). Among 55 patients in cohort E, an objective response was observed in 38% (95% CI, 25 to 52); the median duration of response was 8.5 months, and the median progression-free survival was 5.5 months. Among 73 patients in cohort F, an objective response was observed in 71% (95% CI, 59 to 81), and the median duration of response was 11.0 months; data on progression-free survival were immature. Grade 3 or higher drug-related adverse events occurred in 31% of the patients. The most common adverse event was diarrhea (in 84 to 91%), with diarrhea of grade 3 or higher occurring in 5 to 23%. Treatment was discontinued by 3% of the patients owing to drug-related adverse events.\n\nConclusions: Sevabertinib showed antitumor activity in patients with locally advanced or metastatic HER2 -mutant NSCLC. Diarrhea was the most common adverse event. (Funded by Bayer; SOHO-01 ClinicalTrials.gov number, NCT05099172.).\n\nIndexed on Europe PMC as PubMed record 41104928 (DOI 10.1056/nejmoa2511065). Its abstract cites the registry id NCT05099172, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2025, doi: "10.1056/nejmoa2511065", pmid: "41104928", authors: "Le X, Kim TM, Loong HH, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05099172 with the most citations, so it is the natural first reading for anyone following the SOHO-01 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2025","url":"https://doi.org/10.1056/nejmoa2511065"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41104928/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41104928"},{"label":"ClinicalTrials.gov NCT05099172","url":"https://clinicaltrials.gov/study/NCT05099172"}], tags: ["europepmc-ingest"], cancers: ["nsclc","her2-mutant-nsclc"], drugs: ["sevabertinib"], targets: ["her2"], technologies: [], trials: ["soho-01"], journals: ["nejm"] }),
  p({ id: "paper-tropion-lung05-j-clin-oncol-2025", name: "Datopotamab Deruxtecan in Advanced or Metastatic Non-Small Cell Lung Cancer With Actionable Genomic Alterations: Results From the Phase II TROPION-Lung05 Study", tldr: "Published report from the TROPION-Lung05 trial registered as NCT04484142, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Datopotamab deruxtecan (Dato-DXd) is a trophoblast cell-surface antigen-2-directed antibody-drug conjugate with a highly potent topoisomerase I inhibitor payload. The TROPION-Lung05 phase II trial (ClinicalTrials.gov identifier: NCT04484142) evaluated the safety and clinical activity of Dato-DXd in patients with advanced/metastatic non-small cell lung cancer (NSCLC) with actionable genomic alterations progressing on or after targeted therapy and platinum-based chemotherapy.\n\nPatients and methods: Patients received Dato-DXd 6 mg/kg once every 3 weeks. The primary end point was objective response rate (ORR) by blinded independent central review. Secondary end points included duration of response (DOR), safety, tolerability, and survival.\n\nResults: Among 137 patients who received at least 1 dose of Dato-DXd, 71.5% received at least three lines of prior therapies for advanced/metastatic disease. Overall, 56.9% had EGFR mutations and 24.8% had ALK rearrangements. Median treatment duration was 4.4 months (range, 0.7-20.6). The confirmed ORR was 35.8% (95% CI, 27.8 to 44.4) overall, and 43.6% (95% CI, 32.4 to 55.3) and 23.5% (95% CI, 10.7 to 41.2) in those with EGFR mutations and ALK rearrangements, respectively. The median DOR was 7.0 months (95% CI, 4.2 to 9.8), and the overall disease control rate was 78.8% (95% CI, 71.0 to 85.3). Grade ≥3 treatment-related adverse events (TRAEs) occurred in 28.5% of patients. The most common TRAE was stomatitis (preferred term; any grade: 56.2%; grade ≥3: 9.5%). Five (3.6%) patients experienced adjudicated treatment-related interstitial lung disease/pneumonitis, with 1 (0.7%) grade 5 event.\n\nConclusion: Encouraging and durable antitumor activity was observed with Dato-DXd in this heavily pretreated advanced/metastatic NSCLC population with actionable genomic alterations. The rate of treatment-related grade ≥3 toxicities was comparable with previous observations, and no new safety signals were observed.\n\nIndexed on Europe PMC as PubMed record 39761483 (DOI 10.1200/jco-24-01349). Its abstract cites the registry id NCT04484142, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-24-01349", pmid: "39761483", authors: "Sands J, Ahn MJ, Lisberg A, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04484142 with the most citations, so it is the natural first reading for anyone following the TROPION-Lung05 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-24-01349"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39761483/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39761483"},{"label":"ClinicalTrials.gov NCT04484142","url":"https://clinicaltrials.gov/study/NCT04484142"}], tags: ["europepmc-ingest"], cancers: ["nsclc","egfr-mutant-nsclc"], drugs: ["datopotamab-deruxtecan"], targets: ["trop2","egfr"], technologies: [], trials: ["tropion-lung05"], journals: ["jco"] }),
  p({ id: "paper-alchemist-jama-oncol-2022", name: "Rates of Guideline-Concordant Surgery and Adjuvant Chemotherapy Among Patients With Early-Stage Lung Cancer in the US ALCHEMIST Study (Alliance A151216)", tldr: "Published report from the ALCHEMIST trial registered as NCT02194738, in JAMA Oncology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Standard treatment for resectable non-small cell lung cancer (NSCLC) includes anatomic resection with adequate lymph node dissection and adjuvant chemotherapy for appropriate patients. Historically, many patients with early-stage NSCLC have not received such treatment, which may affect the interpretation of the results of adjuvant therapy trials.\n\nObjective: To ascertain patterns of guideline-concordant treatment among patients enrolled in a US-wide screening protocol for adjuvant treatment trials for resected NSCLC.\n\nDesign, setting, and participants: This retrospective cohort study included 2833 patients with stage IB to IIIA NSCLC (per American Joint Committee on Cancer 7th edition criteria) who enrolled in the Adjuvant Lung Cancer Enrichment Marker Identification and Sequencing Trial (ALCHEMIST) screening study (Alliance for Clinical Trials in Oncology A151216) from August 18, 2014, to April 1, 2019, and who did not enroll in a therapeutic adjuvant clinical trial; patients had tumors of at least 4 cm and/or with positive lymph nodes. Statistical analysis was conducted from June 1, 2020, through October 1, 2021.\n\nExposures: Care patterns were ascertained overall and by sociodemographic and clinical factors, including age, sex, race and ethnicity, educational level, marital status, geography, histologic characteristics, stage, genomic variant status, smoking history, and comorbidities.\n\nMain outcomes and measures: Five outcomes are reported: whether patients (1) had anatomic surgical resection, (2) had adequate lymph node dissection (≥1 N1 nodal station plus ≥3 N2 nodal stations), (3) received any adjuvant chemotherapy, (4) received any cisplatin-based adjuvant chemotherapy, and (5) received at least 4 cycles of adjuvant chemotherapy.\n\nResults: Of the 2833 patients (1505 women [53%]; mean [SD] age, 66.5 [9.2] years) included in this analysis, 2697 (95%) had anatomic surgical resection, 1513 (53%) had adequate lymph node dissection, 1617 (57%) received any adjuvant chemotherapy, 1237 (44%) received at least 4 cycles of adjuvant platinum-based chemotherapy, and 965 (34%) received any cisplatin-based adjuvant chemotherapy. Rates were similar across race and ethnicity.\n\nConclusions and relevance: This cohort study found that among participants in a screening protocol for adjuvant clinical trials for resected early-stage NSCLC, just 53% underwent adequate lymph node dissection, and 57% received adjuvant chemotherapy, despite indications for such treatment. These results may affect the interpretation of adjuvant trials. Efforts are needed to optimize the use of proven therapies for early-stage NSCLC.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02194738.\n\nIndexed on Europe PMC as PubMed record 35297944 (DOI 10.1001/jamaoncol.2022.0039). Its abstract cites the registry id NCT02194738, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2022, doi: "10.1001/jamaoncol.2022.0039", pmid: "35297944", authors: "Kehl KL, Zahrieh D, Yang P, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02194738 with the most citations, so it is the natural first reading for anyone following the ALCHEMIST trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2022","url":"https://doi.org/10.1001/jamaoncol.2022.0039"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35297944/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35297944"},{"label":"ClinicalTrials.gov NCT02194738","url":"https://clinicaltrials.gov/study/NCT02194738"}], tags: ["europepmc-ingest"], cancers: ["nsclc","resectable-nsclc"], drugs: ["erlotinib","crizotinib","nivolumab","osimertinib","alectinib"], targets: [], technologies: ["cgp","histopathology-ihc","checkpoint-inhibitor","kinase-inhibitors"], trials: ["alchemist"], journals: ["jama-oncology"] }),
  p({ id: "paper-chrysalis-nat-med-2023", name: "Amivantamab plus lazertinib in osimertinib-relapsed EGFR-mutant advanced non-small cell lung cancer: a phase 1 trial", tldr: "Published report from the CHRYSALIS trial registered as NCT02609776, in Nature Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Patients with epidermal growth factor receptor (EGFR)-mutated non-small cell lung cancer (NSCLC) often develop resistance to current standard third-generation EGFR tyrosine kinase inhibitors (TKIs); no targeted treatments are approved in the osimertinib-relapsed setting. In this open-label, dose-escalation and dose-expansion phase 1 trial, the potential for improved anti-tumor activity by combining amivantamab, an EGFR-MET bispecific antibody, with lazertinib, a third-generation EGFR TKI, was evaluated in patients with EGFR-mutant NSCLC whose disease progressed on third-generation TKI monotherapy but were chemotherapy naive (CHRYSALIS cohort E). In the dose-escalation phase, the recommended phase 2 combination dose was established; in the dose-expansion phase, the primary endpoints were safety and overall response rate, and key secondary endpoints included progression-free survival and overall survival. The safety profile of amivantamab and lazertinib was generally consistent with previous experience of each agent alone, with 4% experiencing grade ≥3 events; no new safety signals were identified. In an exploratory cohort of 45 patients who were enrolled without biomarker selection, the primary endpoint of investigator-assessed overall response rate was 36% (95% confidence interval, 22-51). The median duration of response was 9.6 months, and the median progression-free survival was 4.9 months. Next-generation sequencing and immunohistochemistry analyses identified high EGFR and/or MET expression as potential predictive biomarkers of response, which will need to be validated with prospective assessment. ClinicalTrials.gov identifier: NCT02609776.\n\nIndexed on Europe PMC as PubMed record 37710001 (DOI 10.1038/s41591-023-02554-7). Its abstract cites the registry id NCT02609776, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2023, doi: "10.1038/s41591-023-02554-7", pmid: "37710001", authors: "Cho BC, Kim DW, Spira AI, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02609776 with the most citations, so it is the natural first reading for anyone following the CHRYSALIS trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2023","url":"https://doi.org/10.1038/s41591-023-02554-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37710001/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37710001"},{"label":"ClinicalTrials.gov NCT02609776","url":"https://clinicaltrials.gov/study/NCT02609776"}], tags: ["europepmc-ingest"], cancers: ["egfr-mutant-nsclc","nsclc","lung-cancer"], drugs: ["amivantamab","lazertinib"], targets: [], technologies: [], trials: ["chrysalis"], journals: ["nature-medicine"] }),
  p({ id: "paper-lung-map-j-thorac-oncol-2019", name: "SWOG S1400C (NCT02154490)-A Phase II Study of Palbociclib for Previously Treated Cell Cycle Gene Alteration-Positive Patients with Stage IV Squamous Cell Lung Cancer (Lung-MAP Substudy)", tldr: "Published report from the Lung-MAP trial registered as NCT02154490, in Journal of Thoracic Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Objective: Lung-MAP (SWOG S1400) is a master platform trial assessing targeted therapies in squamous NSCLC. The objective of study C (S1400C) was to evaluate the response rate to palbociclib, a cyclin-dependent kinase 4 and cyclin-dependent kinase 6 inhibitor, in patients with cell cycle gene abnormalities.\n\nMethods: Patients with squamous NSCLC, a performance status of 0 to 2, and normal organ function who had progressed after at least one prior platinum-based chemotherapy with cyclin-dependent kinase 4 gene (CDK4) or cyclin D1 gene (CCND1), cyclin D2 gene (CCND2), or cyclin D3 gene (CCND3) amplifications on tumor specimens were eligible. The study was originally designed as a phase II/III trial comparing palbociclib with docetaxel, but it was modified to a single-arm phase II trial with the primary end point of response when immunotherapy was approved. If two or fewer responses were seen in the first 20 patients, then the study would cease enrollment.\n\nResults: A total of 88 patients (9% of patients screened) were assigned to S1400C, and 53 patients enrolled (including 17 to receive docetaxel). One patient who had been registered to receive docetaxel was re-registered to receive palbociclib after progression while taking docetaxel. The frequencies of cell cycle gene alterations in the eligible patients taking palbociclib (n = 32) were as follows: CCND1, 81% (n = 26); CCND2, 9% (n = 3); CCND3, 6% (n = 2); and CDK4, 3% (n = 1). In all, 32 eligible patients received palbociclib. There were two partial responses (response rate 6% [95% confidence interval (CI): 0%-15%]), both with CCND1 amplification. Twelve patients had stable disease (38% [95% CI: 21%-54%]). The median progression-free survival was 1.7 months (95% CI: 1.6-2.9 months) and the median overall survival was 7.1 months (95% CI: 4.2-12.5).\n\nConclusion: Palbociclib as monotherapy failed to demonstrate the prespecified criteria for advancement to phase III testing.\n\nIndexed on Europe PMC as PubMed record 31302234 (DOI 10.1016/j.jtho.2019.06.027). Its title cites the registry id NCT02154490, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2019, doi: "10.1016/j.jtho.2019.06.027", pmid: "31302234", authors: "Edelman MJ, Redman MW, Albain KS, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02154490 with the most citations, so it is the natural first reading for anyone following the Lung-MAP trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2019","url":"https://doi.org/10.1016/j.jtho.2019.06.027"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31302234/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31302234"},{"label":"ClinicalTrials.gov NCT02154490","url":"https://clinicaltrials.gov/study/NCT02154490"}], tags: ["europepmc-ingest"], cancers: ["nsclc","lung-cancer"], drugs: ["durvalumab","tremelimumab","palbociclib","talazoparib","nivolumab","ipilimumab","telisotuzumab-vedotin","ramucirumab","pembrolizumab","erlotinib","docetaxel"], targets: [], technologies: ["cgp","checkpoint-inhibitor","cdk46-inhibitor","parp-inhibitor","adc"], trials: ["lung-map"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct01933932-jama-2017", name: "Selumetinib Plus Docetaxel Compared With Docetaxel Alone and Progression-Free Survival in Patients With KRAS-Mutant Advanced Non-Small Cell Lung Cancer: The SELECT-1 Randomized Clinical Trial", tldr: "Published report from the SELECT 1 trial registered as NCT01933932, in JAMA (2017), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: There are no specifically approved targeted therapies for the most common genomically defined subset of non-small cell lung cancer (NSCLC), KRAS-mutant lung cancer.\n\nObjective: To compare efficacy of the mitogen-activated protein kinase kinase (MEK) inhibitor selumetinib + docetaxel with docetaxel alone as a second-line therapy for advanced KRAS-mutant NSCLC.\n\nDesign, setting, and participants: Multinational, randomized clinical trial conducted at 202 sites across 25 countries from October 2013 through January 2016. Of 3323 patients with advanced NSCLC and disease progression following first-line anticancer therapy tested for a KRAS mutation, 866 were enrolled and 510 randomized. Primary reason for exclusion was ineligibility. The data cutoff date for analysis was June 7, 2016.\n\nInterventions: Patients were randomized 1:1; 254 to receive selumetinib + docetaxel and 256 to receive placebo + docetaxel.\n\nMain outcomes and measures: Primary end point was investigator assessed progression-free survival. Secondary end points included overall survival, objective response rate, duration of response, effects on disease-related symptoms, safety, and tolerability.\n\nResults: Of 510 randomized patients (mean age, 61.4 years [SD, 8.3]; women, 207 [41%]), 505 patients (99%) received treatment and completed the study (251 received selumetinib + docetaxel; 254 received placebo + docetaxel). At the time of data cutoff, 447 patients (88%) had experienced a progression event and 346 deaths (68%) had occurred. Median progression-free survival was 3.9 months (interquartile range [IQR], 1.5-5.9) with selumetinib + docetaxel and 2.8 months (IQR, 1.4-5.5) with placebo + docetaxel (difference, 1.1 months; hazard ratio [HR], 0.93 [95% CI, 0.77-1.12]; P =.44). Median overall survival was 8.7 months (IQR, 3.6-16.8) with selumetinib + docetaxel and 7.9 months (IQR, 3.8-20.1) with placebo + docetaxel (difference, 0.9 months; HR, 1.05 [95% CI, 0.85-1.30]; P =.64). Objective response rate was 20.1% with selumetinib + docetaxel and 13.7% with placebo + docetaxel (difference, 6.4%; odds ratio, 1.61 [95% CI, 1.00-2.62]; P =.05). Median duration of response was 2.9 months (IQR, 1.7-4.8; 95% CI, 2.7-4.1) with selumetinib + docetaxel and 4.5 months (IQR, 2.3-7.3; 95% CI, 2.8-5.6) with placebo + docetaxel. Adverse events of grade 3 or higher were more frequent with selumetinib + docetaxel (169 adverse events [67%] for selumetinib + docetaxel vs 115 adverse events [45%] for placebo + docetaxel; difference, 22%).\n\nConclusions and relevance: Among patients with previously treated advanced KRAS-mutant non-small cell lung cancer, addition of selumetinib to docetaxel did not improve progression-free survival compared with docetaxel alone.\n\nTrial registration: clinicaltrials.gov: NCT01933932.\n\nIndexed on Europe PMC as PubMed record 28492898 (DOI 10.1001/jama.2017.3438). Its abstract cites the registry id NCT01933932, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA", year: 2017, doi: "10.1001/jama.2017.3438", pmid: "28492898", authors: "Jänne PA, van den Heuvel MM, Barlesi F, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT01933932 with the most citations, so it is the natural first reading for anyone following the SELECT 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA 2017","url":"https://doi.org/10.1001/jama.2017.3438"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28492898/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/28492898"},{"label":"ClinicalTrials.gov NCT01933932","url":"https://clinicaltrials.gov/study/NCT01933932"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["selumetinib","docetaxel"], targets: [], technologies: [], trials: ["nct01933932"], journals: ["jama"] }),
  p({ id: "paper-nct02152631-front-oncol-2020", name: "A Randomized Phase III Study of Abemaciclib Versus Erlotinib in Patients with Stage IV Non-small Cell Lung Cancer With a Detectable KRAS Mutation Who Failed Prior Platinum-Based Therapy: JUNIPER", tldr: "Published report from the JUNIPER trial registered as NCT02152631, in Frontiers in oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: JUNIPER compared the efficacy and safety of abemaciclib, a selective cyclin-dependent kinase 4 and 6 inhibitor, with erlotinib in patients with non-small cell lung cancer (NSCLC) harboring a Kirsten rat sarcoma ( KRAS) mutation.\n\nMethods: JUNIPER was a Phase III, multicenter, randomized, open-label trial of abemaciclib versus erlotinib in patients with stage IV NSCLC and a detectable mutation in codons 12 or 13 of the KRAS oncogene, who progressed after platinum-based chemotherapy and 1 additional therapy (could include immune checkpoint inhibitor therapy). Randomized patients (3:2) received either 200 mg abemaciclib twice daily or 150 mg erlotinib once daily with best supportive care until disease progression or unacceptable toxicity. The primary endpoint was overall survival (OS); secondary endpoints included overall response rate (ORR), progression-free survival (PFS), and safety.\n\nResults: Between December 2014 and April 2017, 453 patients were randomly assigned to receive abemaciclib (N = 270) or erlotinib (N = 183). Median OS was 7.4 months (95% confidence interval [CI]: 6.5, 8.8) with abemaciclib and 7.8 months (95% CI: 6.4, 9.5) with erlotinib (hazard ratio [HR] = 0.968 [95% CI: 0.768, 1.219]; p =.77). Median PFS was 3.6 months (95% CI: 2.8, 3.8) with abemaciclib and 1.9 months (95% CI: 1.9, 2.0) with erlotinib (HR = 0.583 [95% CI: 0.470, 0.723]; p <.000001). ORR was 8.9% and 2.7% (p =.010), and the disease control rate was 54.4% and 31.7% (p <.001) with abemaciclib and erlotinib, respectively. Safety results reflected the known safety profiles of abemaciclib and erlotinib.\n\nConclusions: In this study, the primary endpoint of OS was not met; PFS and ORR were improved with manageable toxicity in the abemaciclib arm. The increases in response rates and PFS support further investigation of abemaciclib in other NSCLC subpopulations or in combination with other agents.\n\nClinical trial registration: www.ClinicalTrials.gov, identifier: NCT02152631.\n\nIndexed on Europe PMC as PubMed record 33194700 (DOI 10.3389/fonc.2020.578756). Its abstract cites the registry id NCT02152631, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Frontiers in oncology", year: 2020, doi: "10.3389/fonc.2020.578756", pmid: "33194700", authors: "Goldman JW, Mazieres J, Barlesi F, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02152631 with the most citations, so it is the natural first reading for anyone following the JUNIPER trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Front Oncol 2020","url":"https://doi.org/10.3389/fonc.2020.578756"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/33194700/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/33194700"},{"label":"ClinicalTrials.gov NCT02152631","url":"https://clinicaltrials.gov/study/NCT02152631"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["abemaciclib","erlotinib"], targets: [], technologies: [], trials: ["nct02152631"] }),
  p({ id: "paper-nct02411448-lancet-oncol-2019", name: "Ramucirumab plus erlotinib in patients with untreated, EGFR-mutated, advanced non-small-cell lung cancer (RELAY): a randomised, double-blind, placebo-controlled, phase 3 trial", tldr: "Published report from the RELAY trial registered as NCT02411448, in The Lancet Oncology (2019), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Dual blockade of the EGFR and VEGF pathways in EGFR-mutated metastatic non-small-cell lung cancer (NSCLC) is supported by preclinical and clinical data, yet the approach is not widely implemented. RELAY assessed erlotinib, an EGFR tyrosine kinase inhibitor (TKI) standard of care, plus ramucirumab, a human IgG1 VEGFR2 antagonist, or placebo in patients with untreated EGFR-mutated metastatic NSCLC.\n\nMethods: This is a worldwide, double-blind, phase 3 trial done in 100 hospitals, clinics, and medical centres in 13 countries. Eligible patients were aged 18 years or older (20 years or older in Japan and Taiwan) at the time of study entry, had stage IV NSCLC, with an EGFR exon 19 deletion (ex19del) or exon 21 substitution (Leu858Arg) mutation, an Eastern Cooperative Oncology Group performance status of 0 or 1, and no CNS metastases. We randomly assigned eligible patients in a 1:1 ratio to receive oral erlotinib (150 mg/day) plus either intravenous ramucirumab (10 mg/kg) or matching placebo once every 2 weeks. Randomisation was done by an interactive web response system with a computer-generated sequence and stratified by sex, geographical region, EGFR mutation type, and EGFR testing method. The primary endpoint was investigator-assessed progression-free survival in the intention-to-treat population. Safety was assessed in all patients who received at least one dose of study treatment. This trial is registered at ClinicalTrials.gov, NCT02411448, and is ongoing for long-term survival follow-up.\n\nFindings: Between Jan 28, 2016, and Feb 1, 2018, 449 eligible patients were enrolled and randomly assigned to treatment with ramucirumab plus erlotinib (n=224) or placebo plus erlotinib (n=225). Median duration of follow-up was 20·7 months (IQR 15·8-27·2). At the time of primary analysis, progression-free survival was significantly longer in the ramucirumab plus erlotinib group (19·4 months [95% CI 15·4-21·6]) than in the placebo plus erlotinib group (12·4 months [11·0-13·5]), with a stratified hazard ratio of 0·59 (95% CI 0·46-0·76; p<0·0001). Grade 3-4 treatment-emergent adverse events were reported in 159 (72%) of 221 patients in the ramucirumab plus erlotinib group versus 121 (54%) of 225 in the placebo plus erlotinib group. The most common grade 3-4 treatment-emergent adverse events in the ramucirumab plus erlotinib group were hypertension (52 [24%]; grade 3 only) and dermatitis acneiform (33 [15%]), and in the placebo plus erlotinib group were dermatitis acneiform (20 [9%]) and increased alanine aminotransferase (17 [8%]). Treatment-emergent serious adverse events were reported in 65 (29%) of 221 patients in the ramucirumab plus erlotinib group and 47 (21%) of 225 in the placebo plus erlotinib group. The most common serious adverse events of any grade in the ramucirumab plus erlotinib group were pneumonia (seven [3%]) and cellulitis and pneumothorax (four [2%], each); the most common in the placebo plus erlotinib group were pyrexia (four [2%]) and pneumothorax (three [1%]). One on-study treatment-related death due to an adverse event occurred (haemothorax after a thoracic drainage procedure for a pleural empyema) in the ramucirumab plus erlotinib group.\n\nInterpretation: Ramucirumab plus erlotinib demonstrated superior progression-free survival compared with placebo plus erlotinib in patients with untreated EGFR-mutated metastatic NSCLC. Safety was consistent with the safety profiles of the individual compounds in advanced lung cancer. The RELAY regimen is a viable new treatment option for the initial treatment of EGFR-mutated metastatic NSCLC.\n\nFunding: Eli Lilly.\n\nIndexed on Europe PMC as PubMed record 31591063 (DOI 10.1016/s1470-2045(19)30634-5). Its abstract cites the registry id NCT02411448, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2019, doi: "10.1016/s1470-2045(19)30634-5", pmid: "31591063", authors: "Nakagawa K, Garon EB, Seto T, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02411448 with the most citations, so it is the natural first reading for anyone following the RELAY trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2019","url":"https://doi.org/10.1016/s1470-2045(19)30634-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/31591063/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/31591063"},{"label":"ClinicalTrials.gov NCT02411448","url":"https://clinicaltrials.gov/study/NCT02411448"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc"], drugs: ["ramucirumab","erlotinib","gefitinib","osimertinib"], targets: [], technologies: [], trials: ["nct02411448"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct02411448-j-thorac-oncol-2025-update", name: "RELAY: Final Overall Survival for Erlotinib Plus Ramucirumab or Placebo in Untreated, EGFR-Mutated Metastatic NSCLC", tldr: "Later report from the RELAY trial registered as NCT02411448, in Journal of Thoracic Oncology (2025); its title describes an updated or longer-term analysis.", summary: "Introduction: RELAY, a global double-blind, placebo-controlled phase 3 study (NCT02411448) found statistically significant improvement in progression-free survival (primary end point) for ramucirumab (RAM) plus erlotinib (ERL) (RAM + ERL) in patients with untreated EGFR-mutated metastatic NSCLC (hazard ratio [HR] = 0.59, 95% confidence interval [CI]: 0.46-0.76, p < 0.0001; median progression-free survival: 19.4 versus 12.4 mo). Here, we report the final overall survival (OS; secondary end point) outcomes for the intention-to-treat population.\n\nMethods: Between January 2016 and February 2018, 449 eligible patients with an EGFR exon 19del or L858R mutation and no central nervous system metastases were randomized (1:1) to ERL (150 mg/day) with RAM (10 mg/kg every two weeks, N = 224) or placebo (N = 225).\n\nResults: At data cutoff, 297 deaths were reported (overall event rate = 66%), with a median follow-up of 45.1 months (interquartile range: 26.7-71.2), an OS HR of 0.98 (95% CI: 0.78-1.24, p = 0.864), and median OS of 51.1 months (RAM + ERL) and 46.0 months (placebo + ERL). Outcomes in subsets of patients with poor prognosis (L858R or TP53 co-mutation) suggest a directional improvement in OS (L858R: HR = 0.87, 95% CI: 0.62-1.22; exon 19del: HR = 1.13, 95% CI: 0.83-1.55; TP53 co-mutation: HR = 0.83, 95% CI: 0.58-1.19; TP53-wild-type: HR = 1.22, 95% CI: 0.87-1.72). Treatment-emergent T790M rates were similar between arms. Over 80% of patients received post-study discontinuation therapy (>50% received osimertinib in comparable numbers between arms). The safety profile for RAM + ERL was consistent with previous reports with no increased toxicity over time or new safety signals observed.\n\nConclusion: In RELAY, OS was not significantly improved with similar long OS durations in both treatment arms.\n\nClinical trial information: ClinicalTrials.gov Identifier: NCT02411448.\n\nIndexed on Europe PMC as PubMed record 39622410 (DOI 10.1016/j.jtho.2024.11.032). Its abstract cites the registry id NCT02411448, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2024.11.032", pmid: "39622410", authors: "Nakagawa K, Garon EB, Seto T, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the RELAY trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2024.11.032"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39622410/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39622410"},{"label":"ClinicalTrials.gov NCT02411448","url":"https://clinicaltrials.gov/study/NCT02411448"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc"], drugs: ["ramucirumab","erlotinib","gefitinib","osimertinib"], targets: [], technologies: [], trials: ["nct02411448"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct02453282-jama-oncol-2020", name: "Durvalumab With or Without Tremelimumab vs Standard Chemotherapy in First-line Treatment of Metastatic Non-Small Cell Lung Cancer: The MYSTIC Phase 3 Randomized Clinical Trial", tldr: "Published report from the MYSTIC trial registered as NCT02453282, in JAMA Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Checkpoint inhibitors targeting programmed cell death 1 or its ligand (PD-L1) as monotherapies or in combination with anti-cytotoxic T-lymphocyte-associated antigen 4 have shown clinical activity in patients with metastatic non-small cell lung cancer.\n\nObjective: To compare durvalumab, with or without tremelimumab, with chemotherapy as a first-line treatment for patients with metastatic non-small cell lung cancer.\n\nDesign, setting, and participants: This open-label, phase 3 randomized clinical trial (MYSTIC) was conducted at 203 cancer treatment centers in 17 countries. Patients with treatment-naive, metastatic non-small cell lung cancer who had no sensitizing EGFR or ALK genetic alterations were randomized to receive treatment with durvalumab, durvalumab plus tremelimumab, or chemotherapy. Data were collected from July 21, 2015, to October 30, 2018.\n\nInterventions: Patients were randomized (1:1:1) to receive treatment with durvalumab (20 mg/kg every 4 weeks), durvalumab (20 mg/kg every 4 weeks) plus tremelimumab (1 mg/kg every 4 weeks, up to 4 doses), or platinum-based doublet chemotherapy.\n\nMain outcomes and measures: The primary end points, assessed in patients with ≥25% of tumor cells expressing PD-L1, were overall survival (OS) for durvalumab vs chemotherapy, and OS and progression-free survival (PFS) for durvalumab plus tremelimumab vs chemotherapy. Analysis of blood tumor mutational burden (bTMB) was exploratory.\n\nResults: Between July 21, 2015, and June 8, 2016, 1118 patients were randomized. Baseline demographic and disease characteristics were balanced between treatment groups. Among 488 patients with ≥25% of tumor cells expressing PD-L1, median OS was 16.3 months (95% CI, 12.2-20.8) with durvalumab vs 12.9 months (95% CI, 10.5-15.0) with chemotherapy (hazard ratio [HR], 0.76; 97.54% CI, 0.56-1.02; P =.04 [nonsignificant]). Median OS was 11.9 months (95% CI, 9.0-17.7) with durvalumab plus tremelimumab (HR vs chemotherapy, 0.85; 98.77% CI, 0.61-1.17; P =.20). Median PFS was 3.9 months (95% CI, 2.8-5.0) with durvalumab plus tremelimumab vs 5.4 months (95% CI, 4.6-5.8) with chemotherapy (HR, 1.05; 99.5% CI, 0.72-1.53; P =.71). Among 809 patients with evaluable bTMB, those with a bTMB ≥20 mutations per megabase showed improved OS for durvalumab plus tremelimumab vs chemotherapy (median OS, 21.9 months [95% CI, 11.4-32.8] vs 10.0 months [95% CI, 8.1-11.7]; HR, 0.49; 95% CI, 0.32-0.74). Treatment-related adverse events of grade 3 or higher occurred in 55 (14.9%) of 369 patients who received treatment with durvalumab, 85 (22.9%) of 371 patients who received treatment with durvalumab plus tremelimumab, and 119 (33.8%) of 352 patients who received treatment with chemotherapy. These adverse events led to death in 2 (0.5%), 6 (1.6%), and 3 (0.9%) patients, respectively.\n\nConclusions and relevance: The phase 3 MYSTIC study did not meet its primary end points of improved OS with durvalumab vs chemotherapy or improved OS or PFS with durvalumab plus tremelimumab vs chemotherapy in patients with ≥25% of tumor cells expressing PD-L1. Exploratory analyses identified a bTMB threshold of ≥20 mutations per megabase for optimal OS benefit with durvalumab plus tremelimumab.\n\nTrial registration: ClinicalT rials.gov Identifier: NCT02453282.\n\nIndexed on Europe PMC as PubMed record 32271377 (DOI 10.1001/jamaoncol.2020.0237). Its abstract cites the registry id NCT02453282, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2020, doi: "10.1001/jamaoncol.2020.0237", pmid: "32271377", authors: "Rizvi NA, Cho BC, Reinmuth N, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02453282 with the most citations, so it is the natural first reading for anyone following the MYSTIC trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2020","url":"https://doi.org/10.1001/jamaoncol.2020.0237"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32271377/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32271377"},{"label":"ClinicalTrials.gov NCT02453282","url":"https://clinicaltrials.gov/study/NCT02453282"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["durvalumab","tremelimumab","carboplatin","gemcitabine-cisplatin","gemcitabine","cisplatin"], targets: [], technologies: [], trials: ["nct02453282"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct02486718-lancet-2021", name: "Adjuvant atezolizumab after adjuvant chemotherapy in resected stage IB-IIIA non-small-cell lung cancer (IMpower010): a randomised, multicentre, open-label, phase 3 trial", tldr: "Published report from the trial registered as NCT02486718, in The Lancet (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Novel adjuvant strategies are needed to optimise outcomes after complete surgical resection in patients with early-stage non-small-cell lung cancer (NSCLC). We aimed to evaluate adjuvant atezolizumab versus best supportive care after adjuvant platinum-based chemotherapy in these patients.\n\nMethods: IMpower010 was a randomised, multicentre, open-label, phase 3 study done at 227 sites in 22 countries and regions. Eligible patients were 18 years or older with completely resected stage IB (tumours ≥4 cm) to IIIA NSCLC per the Union Internationale Contre le Cancer and American Joint Committee on Cancer staging system (7th edition). Patients were randomly assigned (1:1) by a permuted-block method (block size of four) to receive adjuvant atezolizumab (1200 mg every 21 days; for 16 cycles or 1 year) or best supportive care (observation and regular scans for disease recurrence) after adjuvant platinum-based chemotherapy (one to four cycles). The primary endpoint, investigator-assessed disease-free survival, was tested hierarchically first in the stage II-IIIA population subgroup whose tumours expressed PD-L1 on 1% or more of tumour cells (SP263), then all patients in the stage II-IIIA population, and finally the intention-to-treat (ITT) population (stage IB-IIIA). Safety was evaluated in all patients who were randomly assigned and received atezolizumab or best supportive care. IMpower010 is registered with ClinicalTrials.gov, NCT02486718 (active, not recruiting).\n\nFindings: Between Oct 7, 2015, and Sept 19, 2018, 1280 patients were enrolled after complete resection. 1269 received adjuvant chemotherapy, of whom 1005 patients were eligible for randomisation to atezolizumab (n=507) or best supportive care (n=498); 495 in each group received treatment. After a median follow-up of 32·2 months (IQR 27·4-38·3) in the stage II-IIIA population, atezolizumab treatment improved disease-free survival compared with best supportive care in patients in the stage II-IIIA population whose tumours expressed PD-L1 on 1% or more of tumour cells (HR 0·66; 95% CI 0·50-0·88; p=0·0039) and in all patients in the stage II-IIIA population (0·79; 0·64-0·96; p=0·020). In the ITT population, HR for disease-free survival was 0·81 (0·67-0·99; p=0·040). Atezolizumab-related grade 3 and 4 adverse events occurred in 53 (11%) of 495 patients and grade 5 events in four patients (1%).\n\nInterpretation: IMpower010 showed a disease-free survival benefit with atezolizumab versus best supportive care after adjuvant chemotherapy in patients with resected stage II-IIIA NSCLC, with pronounced benefit in the subgroup whose tumours expressed PD-L1 on 1% or more of tumour cells, and no new safety signals. Atezolizumab after adjuvant chemotherapy offers a promising treatment option for patients with resected early-stage NSCLC.\n\nFunding: F Hoffmann-La Roche and Genentech.\n\nIndexed on Europe PMC as PubMed record 34555333 (DOI 10.1016/s0140-6736(21)02098-5). Its abstract cites the registry id NCT02486718, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2021, doi: "10.1016/s0140-6736(21)02098-5", pmid: "34555333", authors: "Felip E, Altorki N, Zhou C, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02486718 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2021","url":"https://doi.org/10.1016/s0140-6736(21)02098-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34555333/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34555333"},{"label":"ClinicalTrials.gov NCT02486718","url":"https://clinicaltrials.gov/study/NCT02486718"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","resectable-nsclc"], drugs: ["atezolizumab","cisplatin","vinorelbine","docetaxel","gemcitabine","pemetrexed"], targets: [], technologies: [], trials: ["nct02486718"], journals: ["lancet"] }),
  p({ id: "paper-nct02486718-ann-oncol-2023-update", name: "Overall survival with adjuvant atezolizumab after chemotherapy in resected stage II-IIIA non-small-cell lung cancer (IMpower010): a randomised, multicentre, open-label, phase III trial", tldr: "Later report from the trial registered as NCT02486718, in Annals of Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Background: IMpower010 (NCT02486718) demonstrated significantly improved disease-free survival (DFS) with adjuvant atezolizumab versus best supportive care (BSC) following platinum-based chemotherapy in the programmed death-ligand 1 (PD-L1)-positive and all stage II-IIIA non-small-cell lung cancer (NSCLC) populations, at the DFS interim analysis. Results of the first interim analysis of overall survival (OS) are reported here.\n\nPatient and methods: The design, participants, and primary-endpoint DFS outcomes have been reported for this phase III, open-label, 1: 1 randomised study of atezolizumab (1200 mg q3w; 16 cycles) versus BSC after adjuvant platinum-based chemotherapy (1-4 cycles) in adults with completely resected stage IB (≥4 cm)-IIIA NSCLC (per the Union Internationale Contre le Cancer and American Joint Committee on Cancer staging system, 7th edition). Key secondary endpoints included OS in the stage IB-IIIA intent-to-treat (ITT) population and safety in randomised treated patients. The first pre-specified interim analysis of OS was conducted after 251 deaths in the ITT population. Exploratory analyses included OS by baseline PD-L1 expression level (SP263 assay).\n\nResults: At a median of 45.3 months' follow-up on 18 April 2022, 127 of 507 patients (25%) in the atezolizumab arm and 124 of 498 (24.9%) in the BSC arm had died. The median OS in the ITT population was not estimable; the stratified hazard ratio (HR) was 0.995 [95% confidence interval (CI) 0.78-1.28]. The stratified OS HRs (95% CI) were 0.95 (0.74-1.24) in the stage II-IIIA (n = 882), 0.71 (0.49-1.03) in the stage II-IIIA PD-L1 tumour cell (TC) ≥1% (n = 476), and 0.43 (95% CI 0.24-0.78) in the stage II-IIIA PD-L1 TC ≥50% (n = 229) populations. Atezolizumab-related adverse event incidences remained unchanged since the previous analysis [grade 3/4 in 53 (10.7%) and grade 5 in 4 (0.8%) of 495 patients, respectively].\n\nConclusions: Although OS remains immature for the ITT population, these data indicate a positive trend favouring atezolizumab in PD-L1 subgroup analyses, primarily driven by the PD-L1 TC ≥50% stage II-IIIA subgroup. No new safety signals were observed after 13 months' additional follow-up. Together, these findings support the positive benefit-risk profile of adjuvant atezolizumab in this setting.\n\nIndexed on Europe PMC as PubMed record 37467930 (DOI 10.1016/j.annonc.2023.07.001). Its abstract cites the registry id NCT02486718, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2023, doi: "10.1016/j.annonc.2023.07.001", pmid: "37467930", authors: "Felip E, Altorki N, Zhou C, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2023","url":"https://doi.org/10.1016/j.annonc.2023.07.001"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37467930/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37467930"},{"label":"ClinicalTrials.gov NCT02486718","url":"https://clinicaltrials.gov/study/NCT02486718"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","resectable-nsclc"], drugs: ["atezolizumab","cisplatin","vinorelbine","docetaxel","gemcitabine","pemetrexed"], targets: [], technologies: [], trials: ["nct02486718"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct02716116-jama-oncol-2021", name: "Treatment Outcomes and Safety of Mobocertinib in Platinum-Pretreated Patients With EGFR Exon 20 Insertion-Positive Metastatic Non-Small Cell Lung Cancer: A Phase 1/2 Open-label Nonrandomized Clinical Trial", tldr: "Published report from the trial registered as NCT02716116, in JAMA Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Metastatic non-small cell lung cancer (mNSCLC) with EGFR exon 20 insertion (EGFRex20ins) mutations is associated with a poor prognosis. Mobocertinib is an oral tyrosine kinase inhibitor designed to selectively target EGFRex20ins mutations.\n\nObjective: To evaluate treatment outcomes and safety of mobocertinib in patients with previously treated EGFRex20ins-positive mNSCLC.\n\nDesign, setting, and participants: This 3-part, open-label, phase 1/2 nonrandomized clinical trial with dose-escalation/dose-expansion cohorts (28 sites in the US) and a single-arm extension cohort (EXCLAIM; 40 sites in Asia, Europe, and North America) was conducted between June 2016 and November 2020 (data cutoff date). The primary analysis populations were the platinum-pretreated patients (PPP) cohort and the EXCLAIM cohort. The PPP cohort included 114 patients with platinum-pretreated EGFRex20ins-positive mNSCLC who received mobocertinib 160 mg once daily from the dose-escalation (n = 6), dose-expansion (n = 22), and EXCLAIM (n = 86) cohorts. The EXCLAIM cohort included 96 patients with previously treated EGFRex20ins-positive mNSCLC (10 were not platinum pretreated and thus were excluded from the PPP cohort).\n\nInterventions: Mobocertinib 160 mg once daily.\n\nMain outcomes and measures: The primary end point of the PPP and EXCLAIM cohorts was confirmed objective response rate (ORR) assessed by independent review committee (IRC). Secondary end points included confirmed ORR by investigator, duration of response, progression-free survival, overall survival, and safety.\n\nResults: Among the PPP (n = 114) and EXCLAIM (n = 96) cohorts, the median (range) age was 60 (27-84) and 59 (27-80) years, respectively; most patients were women (75 [66%] and 62 [65%], respectively) and of Asian race (68 [60%] and 66 [69%], respectively). At data cutoff, median follow-up was 14.2 months in the PPP cohort (median 2 prior anticancer regimens; 40 [35%] had baseline brain metastases), with confirmed ORR of 28% (95% CI, 20%-37%) by IRC assessment and 35% (95% CI, 26%-45%) by investigator assessment; median duration of response by IRC assessment was 17.5 months (95% CI, 7.4-20.3). Median progression-free survival by IRC assessment was 7.3 months (95% CI, 5.5-9.2). Median overall survival was 24.0 months (95% CI, 14.6-28.8). In the EXCLAIM cohort, median follow-up was 13.0 months, with confirmed ORR by IRC assessment of 25% (95% CI, 17%-35%) and by investigator assessment of 32% (95% CI, 23%-43%). The most common treatment-related adverse events were diarrhea and rash.\n\nConclusions and relevance: In this open-label, phase 1/2 nonrandomized clinical trial, mobocertinib was associated with clinically meaningful benefit in patients with previously treated EGFRex20ins-positive mNSCLC, with a manageable safety profile.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02716116.\n\nIndexed on Europe PMC as PubMed record 34647988 (DOI 10.1001/jamaoncol.2021.4761). Its abstract cites the registry id NCT02716116, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2021, doi: "10.1001/jamaoncol.2021.4761", pmid: "34647988", authors: "Zhou C, Ramalingam SS, Kim TM, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02716116 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2021","url":"https://doi.org/10.1001/jamaoncol.2021.4761"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34647988/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34647988"},{"label":"ClinicalTrials.gov NCT02716116","url":"https://clinicaltrials.gov/study/NCT02716116"}], tags: ["europepmc-ingest"], cancers: ["nsclc","egfr-mutant-nsclc","her2-mutant-nsclc"], drugs: [], targets: [], technologies: [], trials: ["nct02716116"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct02734004-lancet-oncol-2020", name: "Olaparib and durvalumab in patients with germline BRCA-mutated metastatic breast cancer (MEDIOLA): an open-label, multicentre, phase 1/2, basket study", tldr: "Published report from the MEDIOLA trial registered as NCT02734004, in The Lancet Oncology (2020), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Poly (ADP-ribose) polymerase inhibitors combined with immunotherapy have shown antitumour activity in preclinical studies. We aimed to assess the safety and activity of olaparib in combination with the PD-L1-inhibitor, durvalumab, in patients with germline BRCA1-mutated or BRCA2-mutated metastatic breast cancer.\n\nMethods: The MEDIOLA trial is a multicentre, open-label, phase 1/2, basket trial of durvalumab and olaparib in solid tumours. Patients were enrolled into four initial cohorts: germline BRCA-mutated, metastatic breast cancer; germline BRCA-mutated, metastatic ovarian cancer; metastatic gastric cancer; and relapsed small-cell lung cancer. Here, we report on the cohort of patients with breast cancer. Patients who were aged 18 years or older (or aged 19 years or older in South Korea) with germline BRCA1-mutated or BRCA2-mutated or both and histologically confirmed, progressive, HER2-negative, metastatic breast cancer were enrolled from 14 health centres in the UK, the USA, Israel, France, Switzerland, and South Korea. Patients should not have received more than two previous lines of chemotherapy for metastatic breast cancer. Patients received 300 mg olaparib in tablet form orally twice daily for 4 weeks and thereafter a combination of olaparib 300 mg twice daily and durvalumab 1·5 g via intravenous infusion every 4 weeks until disease progression. Primary endpoints were safety and tolerability, and 12-week disease control rate. Safety was analysed in patients who received at least one dose of study treatment, and activity analyses were done in the full-analysis set (patients who received at least one dose of study treatment and were not excluded from the study). Recruitment has completed and the study is ongoing. This trial is registered with ClinicalTrials.gov, NCT02734004.\n\nFindings: Between June 14, 2016, and May 2, 2017, 34 patients were enrolled and received both study drugs and were included in the safety analysis. 11 (32%) patients experienced grade 3 or worse adverse events, of which the most common were anaemia (four [12%]), neutropenia (three [9%]), and pancreatitis (two [6%]). Three (9%) patients discontinued due to adverse events and four (12%) patients experienced a total of six serious adverse events. There were no treatment-related deaths. 24 (80%; 90% CI 64·3-90·9) of 30 patients eligible for activity analysis had disease control at 12 weeks.\n\nInterpretation: Combination of olaparib and durvalumab showed promising antitumour activity and safety similar to that previously observed in olaparib and durvalumab monotherapy studies. Further research in a randomised setting is needed to determine predictors of therapeutic benefit and whether addition of durvalumab improves long-term clinical outcomes compared with olaparib monotherapy.\n\nFunding: AstraZeneca.\n\nIndexed on Europe PMC as PubMed record 32771088 (DOI 10.1016/s1470-2045(20)30324-7). Its abstract cites the registry id NCT02734004, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2020, doi: "10.1016/s1470-2045(20)30324-7", pmid: "32771088", authors: "Domchek SM, Postel-Vinay S, Im SA, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02734004 with the most citations, so it is the natural first reading for anyone following the MEDIOLA trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2020","url":"https://doi.org/10.1016/s1470-2045(20)30324-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/32771088/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/32771088"},{"label":"ClinicalTrials.gov NCT02734004","url":"https://clinicaltrials.gov/study/NCT02734004"}], tags: ["europepmc-ingest"], cancers: ["ovarian","sclc","gastric"], drugs: ["olaparib","bevacizumab"], targets: [], technologies: [], trials: ["nct02734004"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct02767804-jama-oncol-2021", name: "Ensartinib vs Crizotinib for Patients With Anaplastic Lymphoma Kinase-Positive Non-Small Cell Lung Cancer: A Randomized Clinical Trial", tldr: "Published report from the trial registered as NCT02767804, in JAMA Oncology (2021), chosen as the most cited paper whose own text cites the registry id.", summary: "Importance: Ensartinib, an oral tyrosine kinase inhibitor of anaplastic lymphoma kinase (ALK), has shown systemic and central nervous system efficacy for patients with ALK-positive non-small cell lung cancer (NSCLC).\n\nObjective: To compare ensartinib with crizotinib among patients with advanced ALK-positive NSCLC who had not received prior treatment with an ALK inhibitor.\n\nDesign, setting, and participants: This open-label, multicenter, randomized, phase 3 trial conducted in 120 centers in 21 countries enrolled 290 patients between July 25, 2016, and November 12, 2018. Eligible patients were 18 years of age or older and had advanced, recurrent, or metastatic ALK-positive NSCLC.\n\nInterventions: Patients were randomized (1:1) to ensartinib, 225 mg once daily, or crizotinib, 250 mg twice daily.\n\nMain outcomes and measures: The primary end point was blinded independent review committee-assessed progression-free survival (PFS). Secondary end points included systemic and intracranial response, time to central nervous system progression, and overall survival. Efficacy was evaluated in the intent-to-treat (ITT) population as well as a prespecified modified ITT (mITT) population consisting of patients with central laboratory-confirmed ALK-positive NSCLC.\n\nResults: A total of 290 patients (149 men [51.4%]; median age, 54 years [range, 25-90 years]) were randomized. In the ITT population, the median PFS was significantly longer with ensartinib than with crizotinib (25.8 [range, 0.03-44.0 months] vs 12.7 months [range, 0.03-38.6 months]; hazard ratio, 0.51 [95% CI, 0.35-0.72]; log-rank P <.001), with a median follow-up of 23.8 months (range, 0-44 months) for the ensartinib group and 20.2 months (range, 0-38 months) for the crizotinib group. In the mITT population, the median PFS in the ensartinib group was not reached, and the median PFS in the crizotinib group was 12.7 months (95% CI, 8.9-16.6 months; hazard ratio, 0.45; 95% CI, 0.30-0.66; log-rank P <.001). The intracranial response rate confirmed by a blinded independent review committee was 63.6% (7 of 11) with ensartinib vs 21.1% (4 of 19) with crizotinib for patients with target brain metastases at baseline. Progression-free survival for patients without brain metastases was not reached with ensartinib vs 16.6 months with crizotinib as a result of a lower central nervous system progression rate (at 12 months: 4.2% with ensartinib vs 23.9% with crizotinib; cause-specific hazard ratio, 0.32; 95% CI, 0.16-0.63; P =.001). Frequencies of treatment-related serious adverse events (ensartinib: 11 [7.7%] vs crizotinib: 9 [6.1%]), dose reductions (ensartinib: 34 of 143 [23.8%] vs crizotinib: 29 of 146 [19.9%]), or drug discontinuations (ensartinib: 13 of 143 [9.1%] vs crizotinib: 10 of 146 [6.8%]) were similar, without any new safety signals.\n\nConclusions and relevance: In this randomized clinical trial, ensartinib showed superior efficacy to crizotinib in both systemic and intracranial disease. Ensartinib represents a new first-line option for patients with ALK-positive NSCLC.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02767804.\n\nIndexed on Europe PMC as PubMed record 34473194 (DOI 10.1001/jamaoncol.2021.3523). Its abstract cites the registry id NCT02767804, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2021, doi: "10.1001/jamaoncol.2021.3523", pmid: "34473194", authors: "Horn L, Wang Z, Wu G, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT02767804 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JAMA Oncol 2021","url":"https://doi.org/10.1001/jamaoncol.2021.3523"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/34473194/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/34473194"},{"label":"ClinicalTrials.gov NCT02767804","url":"https://clinicaltrials.gov/study/NCT02767804"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","alk-positive-nsclc"], drugs: ["ensartinib","crizotinib"], targets: [], technologies: [], trials: ["nct02767804"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct02864992-jama-oncol-2023-update", name: "Tepotinib Treatment in Patients With MET Exon 14-Skipping Non-Small Cell Lung Cancer: Long-term Follow-up of the VISION Phase 2 Nonrandomized Clinical Trial", tldr: "Later report from the trial registered as NCT02864992, in JAMA Oncology (2023); its title describes an updated or longer-term analysis.", summary: "Importance: MET inhibitors have recently demonstrated clinical activity in patients with MET exon 14 (METex14)-skipping non-small cell lung cancer (NSCLC); however, data with longer follow-up and in larger populations are needed to further optimize therapeutic approaches.\n\nObjective: To assess the long-term efficacy and safety of tepotinib, a potent and highly selective MET inhibitor, in patients with METex14-skipping NSCLC in the VISION study.\n\nDesign, setting, and participants: The VISION phase 2 nonrandomized clinical trial was a multicohort, open-label, multicenter study that enrolled patients with METex14-skipping advanced/metastatic NSCLC (cohorts A and C) from September 2016 to May 2021. Cohort C (>18 months' follow-up) was an independent cohort, designed to confirm findings from cohort A (>35 months' follow-up). Data cutoff was November 20, 2022.\n\nIntervention: Patients received tepotinib, 500 mg (450 mg active moiety), once daily.\n\nMain outcomes and measures: The primary end point was objective response by independent review committee (RECIST v1.1). Secondary end points included duration of response (DOR), progression-free survival (PFS), overall survival (OS), and safety.\n\nResults: Cohorts A and C included 313 patients (50.8% female, 33.9% Asian; median [range] age, 72 [41-94] years). The objective response rate (ORR) was 51.4% (95% CI, 45.8%-57.1%) with a median (m)DOR of 18.0 (95% CI, 12.4-46.4) months. In cohort C (n = 161), an ORR of 55.9% (95% CI, 47.9%-63.7%) with an mDOR of 20.8 (95% CI, 12.6-not estimable [NE]) months was reported across treatment lines, comparable to cohort A (n = 152). In treatment-naive patients (cohorts A and C; n = 164), ORR was 57.3% (95% CI, 49.4%-65.0%) and mDOR was 46.4 (95% CI, 13.8-NE) months. In previously treated patients (n = 149), ORR was 45.0% (95% CI, 36.8%-53.3%) and mDOR was 12.6 (95% CI, 9.5-18.5) months. Peripheral edema, the most common treatment-related adverse event, occurred in 210 patients (67.1%) (35 [11.2%] experienced grade ≥3 events).\n\nConclusions and relevance: The findings from cohort C in this nonrandomized clinical trial supported the results from original cohort A. Overall, the long-term outcomes of VISION demonstrated robust and durable clinical activity following treatment with tepotinib, particularly in the treatment-naive setting, in the largest known clinical trial of patients with METex14-skipping NSCLC, supporting the global approvals of tepotinib and enabling clinicians to implement this therapeutic approach for such patients.\n\nTrial registration: ClinicalTrials.gov Identifier: NCT02864992.\n\nIndexed on Europe PMC as PubMed record 37270698 (DOI 10.1001/jamaoncol.2023.1962). Its abstract cites the registry id NCT02864992, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JAMA Oncology", year: 2023, doi: "10.1001/jamaoncol.2023.1962", pmid: "37270698", authors: "Mazieres J, Paik PK, Garassino MC, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"JAMA Oncol 2023","url":"https://doi.org/10.1001/jamaoncol.2023.1962"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37270698/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37270698"},{"label":"ClinicalTrials.gov NCT02864992","url":"https://clinicaltrials.gov/study/NCT02864992"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","met-altered-nsclc"], drugs: ["tepotinib"], targets: [], technologies: [], trials: ["nct02864992"], journals: ["jama-oncology"] }),
  p({ id: "paper-nct03003962-j-thorac-oncol-2025", name: "Durvalumab Versus Chemotherapy as First-line Treatment for Metastatic NSCLC With Tumor PD-L1 Expression of 25% or Higher: Results From the Randomized Phase 3 PEARL Study", tldr: "Published report from the PEARL trial registered as NCT03003962, in Journal of Thoracic Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: PEARL (NCT03003962) is an open-label, phase 3 study comparing first-line durvalumab monotherapy with chemotherapy in patients with metastatic NSCLC (mNSCLC [EGFR/ALK wild type]) with programmed cell death ligand 1 (PD-L1) tumor cell (TC) membrane expression status of 25% or higher. We report the final analysis of PEARL.\n\nMethods: Adults (N = 669) with previously untreated stage IV mNSCLC were randomized (1:1) to durvalumab 20 mg/kg every four weeks or chemotherapy every three weeks for four to six cycles. The dual primary endpoints were overall survival (OS) in the population with PD-L1 TC of 25% or higher and OS in the population at low risk of early mortality (LREM) with PD-L1 TC of 25% or higher.\n\nResults: Durvalumab was associated with a numerical reduction in the risk of death versus chemotherapy in the 25% and higher PD-L1 TC population (OS hazard ratio [HR] = 0.84, 95% confidence interval [CI]: 0.71-0.99, p = 0.037; median OS 14.6 months, 95% CI: 12.2-16.9 versus 12.8 months, 95% CI: 10.1-14.7, respectively). In the 25% and higher PD-L1 TC low risk of early mortality population the OS hazard ratio for durvalumab versus chemotherapy was 0.96 (95% CI: 0.79-1.15, p = 0.628); median OS 14.6 months (95% CI: 12.6-17.2) versus 15.0 months (95% CI: 13.1-16.8), respectively. In the safety population, the incidence of grade 3 or 4 treatment-related adverse events was 15.5% (durvalumab) and 45.9% (chemotherapy).\n\nConclusions: Durvalumab did not statistically significantly improve OS versus chemotherapy as first-line treatment in patients with mNSCLC and 25% and higher PD-L1 TC. The numerical improvement in OS was consistent with previous studies of first-line immune checkpoint inhibitor monotherapy in patients with mNSCLC.\n\nIndexed on Europe PMC as PubMed record 39521433 (DOI 10.1016/j.jtho.2024.10.024). Its abstract cites the registry id NCT03003962, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2024.10.024", pmid: "39521433", authors: "Lu S, Wu L, Wang Q, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03003962 with the most citations, so it is the natural first reading for anyone following the PEARL trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2024.10.024"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39521433/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39521433"},{"label":"ClinicalTrials.gov NCT03003962","url":"https://clinicaltrials.gov/study/NCT03003962"}], tags: ["europepmc-ingest"], cancers: ["nsclc","pdl1-high-nsclc"], drugs: ["durvalumab","carboplatin","gemcitabine-cisplatin","gemcitabine","cisplatin","pemetrexed"], targets: [], technologies: [], trials: ["nct03003962"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct03157128-j-clin-oncol-2024-update", name: "Durability of Response With Selpercatinib in Patients With RET -Activated Thyroid Cancer: Long-Term Safety and Efficacy From LIBRETTO-001", tldr: "Later report from the RET Fusion-Positive Solid Tumors trial registered as NCT03157128, in Journal of Clinical Oncology (2024); its title describes an updated or longer-term analysis.", summary: "Clinical trials frequently include multiple end points that mature at different times. The initial report, typically based on the primary end point, may be published when key planned co-primary or secondary analyses are not yet available. Clinical Trial Updates provide an opportunity to disseminate additional results from studies, published in JCO or elsewhere, for which the primary end point has already been reported. LIBRETTO-001 is a registrational phase I/II, single-arm, open-label study of selpercatinib in patients with RET (REarranged during Transfection)-activated cancers (ClinicalTrials.gov identifier: NCT03157128). We present long-term safety and efficacy from LIBRETTO-001 in patients with RET -mutant medullary thyroid cancer (MTC; n = 324) and RET fusion-positive thyroid cancer encompassing different histological subtypes (TC; n = 66). At the data cutoff of January 2023, the objective response rate was 82.5% among patients with cabozantinib/vandetanib-naïve MTC and 95.8% among patients with treatment-naïve TC. At a median follow-up time of 42.4 and 44.0 months in patients with cabozantinib/vandetanib-naïve and pretreated MTC, the median progression-free survival (PFS) was not reached and 41.4 months, respectively. At a median follow-up time of 24.9 and 30.4 months in patients with treatment-naïve and pretreated TC, the median PFS was not reached and 27.4 months, respectively. Three-year PFS rates were 75.2% and 87.3% among patients with cabozantinib/vandetanib-naïve MTC and treatment-naïve TC, respectively. Median PFS was similar to median duration of response for each patient group. The safety profile of selpercatinib was consistent with previous reports. With an additional follow-up of 37 months and 228 more patients from the last disclosure, selpercatinib continued to provide durable and robust responses in treatment-naïve and previously treated patients with RET -mutant MTC and RET fusion-positive TC.\n\nIndexed on Europe PMC as PubMed record 39094065 (DOI 10.1200/jco.23.02503). Its abstract cites the registry id NCT03157128, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2024, doi: "10.1200/jco.23.02503", pmid: "39094065", authors: "Wirth LJ, Brose MS, Subbiah V, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the RET Fusion-Positive Solid Tumors trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2024","url":"https://doi.org/10.1200/jco.23.02503"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39094065/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39094065"},{"label":"ClinicalTrials.gov NCT03157128","url":"https://clinicaltrials.gov/study/NCT03157128"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","thyroid","ret-fusion-nsclc","medullary-thyroid-cancer"], drugs: ["selpercatinib"], targets: [], technologies: [], trials: ["nct03157128"], journals: ["jco"] }),
  p({ id: "paper-nct03178552-nat-med-2022", name: "Atezolizumab versus chemotherapy in advanced or metastatic NSCLC with high blood-based tumor mutational burden: primary analysis of BFAST cohort C randomized phase 3 trial", tldr: "Published report from the B-FAST trial registered as NCT03178552, in Nature Medicine (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Tumor mutational burden (TMB) is being explored as a predictive biomarker for cancer immunotherapy outcomes in non-small cell lung cancer. BFAST (NCT03178552)-an open-label, global, multicohort trial-evaluated the safety and efficacy of first-line targeted therapies or immunotherapy in patients with unresectable Stage IIIB or IV advanced or metastatic non-small cell lung cancer who were selected for biomarker status using blood-based targeted next-generation sequencing. In the Phase 3 cohort C evaluating blood-based (b)TMB as a biomarker of atezolizumab efficacy, patients with bTMB of ≥10 (N = 471) were randomized 1:1 to receive atezolizumab or platinum-based chemotherapy per local standard of care. Cohort C did not meet its primary endpoint of investigator-assessed progression-free survival in the population with bTMB of ≥16 (hazard ratio, 0.77; 95% confidence interval: 0.59, 1.00; P = 0.053). Adverse events leading to treatment withdrawal occurred in 10% of patients in the atezolizumab arm and 20% in the chemotherapy arm. Adverse events of special interest occurred in 42% of patients in the atezolizumab arm and 26% in the chemotherapy arm. A prespecified exploratory analysis compared the bTMB clinical trial assay with the FoundationOne Liquid Companion Diagnostic assay and showed high concordance between assays. Additional exploration of bTMB to identify optimal cutoffs, confounding factors, assay improvements or cooperative biomarkers is warranted.\n\nIndexed on Europe PMC as PubMed record 35995953 (DOI 10.1038/s41591-022-01933-w). Its abstract cites the registry id NCT03178552, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2022, doi: "10.1038/s41591-022-01933-w", pmid: "35995953", authors: "Peters S, Dziadziuszko R, Morabito A, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03178552 with the most citations, so it is the natural first reading for anyone following the B-FAST trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2022","url":"https://doi.org/10.1038/s41591-022-01933-w"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35995953/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35995953"},{"label":"ClinicalTrials.gov NCT03178552","url":"https://clinicaltrials.gov/study/NCT03178552"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["alectinib","atezolizumab","pemetrexed","cisplatin","carboplatin","gemcitabine"], targets: [], technologies: [], trials: ["nct03178552"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct03334617-nat-med-2024", name: "Biomarker-directed targeted therapy plus durvalumab in advanced non-small-cell lung cancer: a phase 2 umbrella trial", tldr: "Published report from the PD-L1 Containing Therapy trial registered as NCT03334617, in Nature Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "For patients with non-small-cell lung cancer (NSCLC) tumors without currently targetable molecular alterations, standard-of-care treatment is immunotherapy with anti-PD-(L)1 checkpoint inhibitors, alone or with platinum-doublet therapy. However, not all patients derive durable benefit and resistance to immune checkpoint blockade is common. Understanding mechanisms of resistance-which can include defects in DNA damage response and repair pathways, alterations or functional mutations in STK11/LKB1, alterations in antigen-presentation pathways, and immunosuppressive cellular subsets within the tumor microenvironment-and developing effective therapies to overcome them, remains an unmet need. Here the phase 2 umbrella HUDSON study evaluated rational combination regimens for advanced NSCLC following failure of anti-PD-(L)1-containing immunotherapy and platinum-doublet therapy. A total of 268 patients received durvalumab (anti-PD-L1 monoclonal antibody)-ceralasertib (ATR kinase inhibitor), durvalumab-olaparib (PARP inhibitor), durvalumab-danvatirsen (STAT3 antisense oligonucleotide) or durvalumab-oleclumab (anti-CD73 monoclonal antibody). Greatest clinical benefit was observed with durvalumab-ceralasertib; objective response rate (primary outcome) was 13.9% (11/79) versus 2.6% (5/189) with other regimens, pooled, median progression-free survival (secondary outcome) was 5.8 (80% confidence interval 4.6-7.4) versus 2.7 (1.8-2.8) months, and median overall survival (secondary outcome) was 17.4 (14.1-20.3) versus 9.4 (7.5-10.6) months. Benefit with durvalumab-ceralasertib was consistent across known immunotherapy-refractory subgroups. In ATM-altered patients hypothesized to harbor vulnerability to ATR inhibition, objective response rate was 26.1% (6/23) and median progression-free survival/median overall survival were 8.4/22.8 months. Durvalumab-ceralasertib safety/tolerability profile was manageable. Biomarker analyses suggested that anti-PD-L1/ATR inhibition induced immune changes that reinvigorated antitumor immunity. Durvalumab-ceralasertib is under further investigation in immunotherapy-refractory NSCLC.ClinicalTrials.gov identifier: NCT03334617.\n\nIndexed on Europe PMC as PubMed record 38351187 (DOI 10.1038/s41591-024-02808-y). Its abstract cites the registry id NCT03334617, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2024, doi: "10.1038/s41591-024-02808-y", pmid: "38351187", authors: "Besse B, Pons-Tostivint E, Park K, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03334617 with the most citations, so it is the natural first reading for anyone following the PD-L1 Containing Therapy trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2024","url":"https://doi.org/10.1038/s41591-024-02808-y"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38351187/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38351187"},{"label":"ClinicalTrials.gov NCT03334617","url":"https://clinicaltrials.gov/study/NCT03334617"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["durvalumab","ceralasertib","olaparib","oleclumab","trastuzumab-deruxtecan"], targets: [], technologies: [], trials: ["nct03334617"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct03381274-j-thorac-oncol-2023", name: "CD73 Inhibitor Oleclumab Plus Osimertinib in Previously Treated Patients With Advanced T790M-Negative EGFR-Mutated NSCLC: A Brief Report", tldr: "Published report from the trial registered as NCT03381274, in Journal of Thoracic Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: CD73 is overexpressed in EGFR-mutated NSCLC and may promote immune evasion, suggesting potential for combining CD73 blockers with EGFR tyrosine kinase inhibitors (TKIs). This phase 1b-2 study (NCT03381274) evaluated the anti-CD73 antibody oleclumab plus the third-generation EGFR TKI osimertinib in advanced EGFR-mutated NSCLC.\n\nMethods: Patients had tissue T790M-negative NSCLC with TKI-sensitive EGFR mutations after progression on a first- or second-generation EGFR TKI and were osimertinib naive. They received osimertinib 80 mg orally once daily plus oleclumab 1500 mg (dose level 1 [DL1]) or 3000 mg (DL2) intravenously every 2 weeks. Primary end points included safety and objective response rate by Response Evaluation Criteria in Solid Tumors version 1.1.\n\nResults: By July 9, 2021, five patients received DL1 and 21 received DL2. Of these patients, 60.0% and 85.7% had any-grade treatment-related adverse events (TRAEs) and 20.0% and 14.3% had grade 3 TRAEs, respectively. No dose-limiting toxicities, serious TRAEs, or deaths occurred. Four patients were T790M positive on retrospective circulating tumor DNA (ctDNA) testing; three had objective partial responses. In patients who were T790M negative in tumor and ctDNA, objective response rate was 25.0% at DL1 and 11.8% at DL2 (all partial responses); response durations at DL2 were 14.8 and 16.6 months. In patients receiving DL2, excluding those who were T790M positive by ctDNA, median progression-free survival was 7.4 months, and median overall survival was 24.8 months. DL2 was the recommended phase 2 dose.\n\nConclusions: Oleclumab plus osimertinib was found to have moderate activity with acceptable tolerability in previously treated patients with advanced EGFR-mutated NSCLC.\n\nIndexed on Europe PMC as PubMed record 36641093 (DOI 10.1016/j.jtho.2022.12.021). Its abstract cites the registry id NCT03381274, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2023, doi: "10.1016/j.jtho.2022.12.021", pmid: "36641093", authors: "Kim DW, Kim SW, Camidge DR, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03381274 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2023","url":"https://doi.org/10.1016/j.jtho.2022.12.021"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36641093/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36641093"},{"label":"ClinicalTrials.gov NCT03381274","url":"https://clinicaltrials.gov/study/NCT03381274"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["oleclumab","osimertinib"], targets: [], technologies: [], trials: ["nct03381274"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct03476681-j-exp-clin-cancer-res-2023", name: "First-in-human phase 1 clinical trial of anti-core 1 O-glycans targeting monoclonal antibody NEO-201 in treatment-refractory solid tumors", tldr: "Published report from the trial registered as NCT03476681, in Journal of experimental & clinical cancer research (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: NEO201 is a humanized IgG1 monoclonal antibody (mAb) generated against tumor-associated antigens from patients with colorectal cancer. NEO-201 binds to core 1 or extended core 1 O-glycans expressed by its target cells. Here, we present outcomes from a phase I trial of NEO-201 in patients with advanced solid tumors that have not responded to standard treatments.\n\nMethods: This was a single site, open label 3 + 3 dose escalation clinical trial. NEO-201 was administered intravenously every two weeks in a 28-day cycle at dose level (DL) 1 (1 mg/kg), DL 1.5 (1.5 mg/kg) and DL 2 (2 mg/kg) until dose limiting toxicity (DLT), disease progression, or patient withdrawal. Disease evaluations were conducted after every 2 cycles. The primary objective was to assess the maximum tolerated dose (MTD) and recommended phase 2 dose (RP2D) of NEO-201. The secondary objective was to assess the antitumor activity by RECIST v1.1. The exploratory objectives assessed pharmacokinetics and the effect of NEO-201 administration on immunologic parameters and their impact on clinical response.\n\nResults: Seventeen patients (11 colorectal, 4 pancreatic and 2 breast cancers) were enrolled; 2 patients withdrew after the first dose and were not evaluable for DLT. Twelve of the 15 patients evaluable for safety discontinued due to disease progression and 3 patients discontinued due to DLT (grade 4 febrile neutropenia [1 patient] and prolonged neutropenia [1 patient] at DL 2, and grade 3 prolonged (> 72 h) febrile neutropenia [1 patient] at DL 1.5). A total of 69 doses of NEO-201 were administered (range 1-15, median 4). Common (> 10%) grade 3/4 toxicities occurred as follows: neutropenia (26/69 doses, 17/17 patients), white blood cell decrease (16/69 doses, 12/17 patients), lymphocyte decrease (8/69 doses, 6/17 patients). Thirteen patients were evaluable for disease response; the best response was stable disease (SD) in 4 patients with colorectal cancer. Analysis of soluble factors in serum revealed that a high level of soluble MICA at baseline was correlated with a downregulation of NK cell activation markers and progressive disease. Unexpectedly, flow cytometry showed that NEO-201 also binds to circulating regulatory T cells and reduction of the quantities of these cells was observed especially in patients with SD.\n\nConclusions: NEO-201 was safe and well tolerated at the MTD of 1.5 mg/kg, with neutropenia being the most common adverse event. Furthermore, a reduction in the percentage of regulatory T cells following NEO-201 treatment supports our ongoing phase II clinical trial evaluating the efficiency of the combination of NEO-201 with the immune checkpoint inhibitor pembrolizumab in adults with treatment-resistant solid tumors.\n\nTrial registration: NCT03476681. Registered 03/26/2018.\n\nIndexed on Europe PMC as PubMed record 36991390 (DOI 10.1186/s13046-023-02649-6). Its abstract cites the registry id NCT03476681, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of experimental & clinical cancer research", year: 2023, doi: "10.1186/s13046-023-02649-6", pmid: "36991390", authors: "Cole CB, Morelli MP, Fantini M, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03476681 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Exp Clin Cancer Res 2023","url":"https://doi.org/10.1186/s13046-023-02649-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/36991390/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/36991390"},{"label":"ClinicalTrials.gov NCT03476681","url":"https://clinicaltrials.gov/study/NCT03476681"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","head-and-neck","cervical"], drugs: ["pembrolizumab"], targets: [], technologies: [], trials: ["nct03476681"], journals: ["journal-of-experimental-and-clinical-cancer-research"] }),
  p({ id: "paper-nct03706690-j-hematol-oncol-2025", name: "PACIFIC-5: a phase III clinical trial of consolidation durvalumab in patients with unresectable stage III NSCLC and no progression after concurrent or sequential chemoradiotherapy", tldr: "Published report from the PACIFIC-5 trial registered as NCT03706690, in Journal of hematology & oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Consolidation durvalumab following no progression on concurrent chemoradiotherapy (cCRT) is standard of care for unresectable stage III non-small-cell lung cancer (NSCLC). However, in clinical practice many patients receive sequential CRT (sCRT). The PACIFIC-5 trial aimed to evaluate the efficacy and safety of consolidation durvalumab for unresectable stage III NSCLC following no progression on cCRT or sCRT.\n\nMethods: This randomised, double-blind, placebo-controlled, phase III trial enrolled patients aged ≥ 18 years with unresectable stage III NSCLC, regardless of PD-L1 expression or sensitising EGFR or ALK aberrations, without disease progression after cCRT or sCRT. Patients were randomised (2:1) to durvalumab 1500 mg or placebo intravenously every 4 weeks (stratified by tumour PD-L1 expression and prior treatment) until disease progression, unacceptable toxicity, or consent withdrawal. The primary endpoint was progression-free survival (PFS) by blinded independent central review in the modified intention-to-treat population (mITT). Secondary endpoints included overall survival (OS) in the mITT and safety. The safety analysis set include patients who received at least one dose of study treatment.\n\nResults: Of 407 patients randomised to receive durvalumab (n = 272) or placebo (n = 135), 405 received at least one dose of durvalumab (n = 271) or placebo (n = 134). The mITT comprised 381 patients randomised to durvalumab (n = 252) or placebo (n = 129). Durvalumab showed statistically significant improvement in PFS versus placebo in the mITT (median [95% confidence interval {CI}], 14.0 [10.9-18.0] vs. 6.5 [5.4-13.8] months; hazard ratio [95% CI], 0.75 [0.58-0.99]; p = 0.038). There was a trend toward improved OS with durvalumab versus placebo in the mITT (median [95% CI], 38.3 [28.9-42.8] vs. 32.5 [20.6-40.4] months; hazard ratio [95% CI], 0.87 [0.66-1.17]; p = 0.346 [interim analysis]). Among the safety analysis set, maximum grade 3 or 4 adverse events of any cause occurred in 26.9% (73/271) and 23.9% (32/134) and 1.5% (4/271) and 0% (0/134) had treatment-related adverse events leading to death for durvalumab and placebo, respectively.\n\nConclusions: PACIFIC-5 met its primary endpoint of improved PFS after either cCRT or sCRT. Follow-up for overall survival is ongoing.\n\nTrial registration: NCT03706690.\n\nIndexed on Europe PMC as PubMed record 41354932 (DOI 10.1186/s13045-025-01768-1). Its abstract cites the registry id NCT03706690, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of hematology & oncology", year: 2025, doi: "10.1186/s13045-025-01768-1", pmid: "41354932", authors: "Wu YL, Wu L, Bi N, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03706690 with the most citations, so it is the natural first reading for anyone following the PACIFIC-5 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Hematol Oncol 2025","url":"https://doi.org/10.1186/s13045-025-01768-1"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41354932/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41354932"},{"label":"ClinicalTrials.gov NCT03706690","url":"https://clinicaltrials.gov/study/NCT03706690"}], tags: ["europepmc-ingest"], cancers: ["nsclc","stage-iii-unresectable-nsclc"], drugs: ["durvalumab"], targets: [], technologies: [], trials: ["nct03706690"], journals: ["journal-of-hematology-and-oncology"] }),
  p({ id: "paper-nct03775486-j-thorac-oncol-2023", name: "Durvalumab in Combination With Olaparib Versus Durvalumab Alone as Maintenance Therapy in Metastatic NSCLC: The Phase 2 ORION Study", tldr: "Published report from the ORION trial registered as NCT03775486, in Journal of Thoracic Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Increased DNA damage triggered through poly (ADP-ribose) polymerase inhibition may modify tumor immunogenicity, sensitizing tumors to immunotherapy. ORION (NCT03775486) evaluated the combination of olaparib with durvalumab as maintenance therapy in patients with metastatic NSCLC.\n\nMethods: ORION is a phase 2, randomized, multicenter, double-blind, international study. Patients with metastatic NSCLC (without activating EGFR or ALK aberrations) and Eastern Cooperative Oncology Group performance status of 0 or 1 were enrolled to receive initial therapy with durvalumab (1500 mg intravenously; every 3 wk) plus platinum-based chemotherapy for four cycles. Patients without disease progression were then randomized (1:1) to maintenance durvalumab (1500 mg; every 4 wk) plus either olaparib (300 mg orally) or placebo (both twice daily); randomization was stratified by objective response during initial therapy and tumor histologic type. The primary end point was investigator-assessed progression-free survival (PFS) (Response Evaluation Criteria in Solid Tumors version 1.1).\n\nResults: Between January 2019 and February 2020, 269 of 401 patients who received initial therapy were randomized. at January 11, 2021 (median follow-up: 9.6 mo), median PFS was 7.2 months (95% confidence interval: 5.3-7.9) with durvalumab plus olaparib versus 5.3 months (3.7-5.8) with durvalumab plus placebo (hazard ratio = 0.76, 95% confidence interval: 0.57-1.02, p = 0.074). Safety findings were consistent with the known profiles of durvalumab and olaparib. Anemia was the most common adverse event (AE) with durvalumab plus olaparib (26.1% versus 8.2% with durvalumab plus placebo). The incidence of grade 3 or 4 AEs (34.3% versus 17.9%) and AEs leading to treatment discontinuation (10.4% versus 4.5%) was numerically higher with durvalumab plus olaparib versus durvalumab plus placebo.\n\nConclusions: Maintenance therapy with durvalumab in combination with olaparib was not associated with a statistically significant improvement in PFS versus durvalumab alone, although numerical improvement was observed.\n\nIndexed on Europe PMC as PubMed record 37390980 (DOI 10.1016/j.jtho.2023.06.013). Its abstract cites the registry id NCT03775486, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2023, doi: "10.1016/j.jtho.2023.06.013", pmid: "37390980", authors: "Ahn MJ, Bondarenko I, Kalinka E, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03775486 with the most citations, so it is the natural first reading for anyone following the ORION trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2023","url":"https://doi.org/10.1016/j.jtho.2023.06.013"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37390980/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37390980"},{"label":"ClinicalTrials.gov NCT03775486","url":"https://clinicaltrials.gov/study/NCT03775486"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["durvalumab","olaparib","paclitaxel","carboplatin","gemcitabine","pemetrexed"], targets: [], technologies: [], trials: ["nct03775486"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct03778229-ann-oncol-2025", name: "Savolitinib plus osimertinib in epidermal growth factor receptor (EGFR)-mutated advanced non-small cell lung cancer with MET overexpression and/or amplification following disease progression on osimertinib: primary results from the phase II SAVANNAH study", tldr: "Published report from the SAVANNAH trial registered as NCT03778229, in Annals of Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: MET-based resistance following osimertinib treatment for epidermal growth factor receptor (EGFR)-mutated advanced non-small cell lung cancer (NSCLC) is common. We report the primary analysis of the phase II SAVANNAH study (NCT03778229) evaluating savolitinib plus osimertinib in this setting.\n\nPatients and methods: Patients had EGFR-mutated, advanced NSCLC with MET overexpression and/or amplification. MET cut-offs were initially MET immunohistochemistry (IHC)3+/≥50% (3+ intensity in ≥50% of tumor cells) and/or FISH5+ (≥5 MET gene copies or MET/chromosome 7 centromere ratio ≥2), and increased to MET IHC3+/≥90% and/or FISH10+ after a preliminary analysis. Patients received oral savolitinib [300 mg twice daily (b.i.d.) or once daily (o.d.), or 600 mg o.d.] plus osimertinib 80 mg o.d., or savolitinib 300 mg b.i.d. plus placebo. A primary endpoint was investigator-assessed objective response rate (ORR) in patients with progression on first-line osimertinib and MET IHC3+/≥90% and/or FISH10+ status receiving savolitinib 300 mg b.i.d. plus osimertinib (primary efficacy population). Safety was analyzed in all patients receiving savolitinib plus osimertinib.\n\nResults: Of the 365 patients treated, 341 received savolitinib plus osimertinib, with 80 of these included in the primary efficacy population. Investigator-assessed confirmed ORR in the primary efficacy population was 56.3% [95% confidence interval (CI) 44.7% to 67.3%]; the median duration of response (mDoR) was 7.1 months (95% CI 5.6-9.6 months); the median progression-free survival (PFS) was 7.4 months (95% CI 5.5-7.6 months). Blinded independent central review was consistent: confirmed ORR 55.0% (95% CI 43.5% to 66.2%); mDoR 9.9 months (95% CI 6.0-13.7 months); median PFS 7.5 months (95% CI 6.4-11.3 months). The most common any grade adverse events in patients receiving savolitinib plus osimertinib were peripheral edema (46.0%), nausea (40.5%), and diarrhea (23.2%).\n\nConclusions: Savolitinib 300 mg b.i.d. plus osimertinib demonstrated high, clinically meaningful and durable responses in patients with EGFR-mutated, advanced NSCLC with MET IHC3+/≥90% and/or FISH10+ status following progression on first-line osimertinib. The combination was well tolerated and may provide a new oral targeted treatment approach in this setting.\n\nIndexed on Europe PMC as PubMed record 40461383 (DOI 10.1016/j.annonc.2025.04.003). Its abstract cites the registry id NCT03778229, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2025, doi: "10.1016/j.annonc.2025.04.003", pmid: "40461383", authors: "de Marinis F, Kim TM, Bonanno L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03778229 with the most citations, so it is the natural first reading for anyone following the SAVANNAH trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Ann Oncol 2025","url":"https://doi.org/10.1016/j.annonc.2025.04.003"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40461383/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40461383"},{"label":"ClinicalTrials.gov NCT03778229","url":"https://clinicaltrials.gov/study/NCT03778229"}], tags: ["europepmc-ingest"], cancers: ["metastatic-cancer","egfr-mutant-nsclc","met-altered-nsclc"], drugs: ["osimertinib","savolitinib"], targets: [], technologies: [], trials: ["nct03778229"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct03800134-n-engl-j-med-2023", name: "Perioperative Durvalumab for Resectable Non-Small-Cell Lung Cancer", tldr: "Published report from the AEGEAN trial registered as NCT03800134, in New England Journal of Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Neoadjuvant or adjuvant immunotherapy can improve outcomes in patients with resectable non-small-cell lung cancer (NSCLC). Perioperative regimens may combine benefits of both to improve long-term outcomes.\n\nMethods: We randomly assigned patients with resectable NSCLC (stage II to IIIB [N2 node stage] according to the eighth edition of the AJCC Cancer Staging Manual) to receive platinum-based chemotherapy plus durvalumab or placebo administered intravenously every 3 weeks for 4 cycles before surgery, followed by adjuvant durvalumab or placebo intravenously every 4 weeks for 12 cycles. Randomization was stratified according to disease stage (II or III) and programmed death ligand 1 (PD-L1) expression (≥1% or <1%). Primary end points were event-free survival (defined as the time to the earliest occurrence of progressive disease that precluded surgery or prevented completion of surgery, disease recurrence [assessed in a blinded fashion by independent central review], or death from any cause) and pathological complete response (evaluated centrally).\n\nResults: A total of 802 patients were randomly assigned to receive durvalumab (400 patients) or placebo (402 patients). The duration of event-free survival was significantly longer with durvalumab than with placebo; the stratified hazard ratio for disease progression, recurrence, or death was 0.68 (95% confidence interval [CI], 0.53 to 0.88; P = 0.004) at the first interim analysis. At the 12-month landmark analysis, event-free survival was observed in 73.4% of the patients who received durvalumab (95% CI, 67.9 to 78.1), as compared with 64.5% of the patients who received placebo (95% CI, 58.8 to 69.6). The incidence of pathological complete response was significantly greater with durvalumab than with placebo (17.2% vs. 4.3% at the final analysis; difference, 13.0 percentage points; 95% CI, 8.7 to 17.6; P<0.001 at interim analysis of data from 402 patients). Event-free survival and pathological complete response benefit were observed regardless of stage and PD-L1 expression. Adverse events of maximum grade 3 or 4 occurred in 42.4% of patients with durvalumab and in 43.2% with placebo. Data from 62 patients with documented EGFR or ALK alterations were excluded from the efficacy analyses in the modified intention-to-treat population.\n\nConclusions: In patients with resectable NSCLC, perioperative durvalumab plus neoadjuvant chemotherapy was associated with significantly greater event-free survival and pathological complete response than neoadjuvant chemotherapy alone, with a safety profile that was consistent with the individual agents. (Funded by AstraZeneca; AEGEAN ClinicalTrials.gov number, NCT03800134.).\n\nIndexed on Europe PMC as PubMed record 37870974 (DOI 10.1056/nejmoa2304875). Its abstract cites the registry id NCT03800134, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2304875", pmid: "37870974", authors: "Heymach JV, Harpole D, Mitsudomi T, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03800134 with the most citations, so it is the natural first reading for anyone following the AEGEAN trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2304875"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37870974/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37870974"},{"label":"ClinicalTrials.gov NCT03800134","url":"https://clinicaltrials.gov/study/NCT03800134"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","resectable-nsclc"], drugs: ["durvalumab","carboplatin","cisplatin","pemetrexed","paclitaxel","gemcitabine"], targets: [], technologies: [], trials: ["nct03800134"], journals: ["nejm"] }),
  p({ id: "paper-nct03907852-nat-med-2023", name: "Mesothelin-targeting T cell receptor fusion construct cell therapy in refractory solid tumors: phase 1/2 trial interim results", tldr: "Published report from the Phase 1 trial registered as NCT03907852, in Nature Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "The T cell receptor fusion construct (TRuC) gavocabtagene autoleucel (gavo-cel) consists of single-domain anti-mesothelin antibody that integrates into the endogenous T cell receptor (TCR) and engages the signaling capacity of the entire TCR upon mesothelin binding. Here we describe phase 1 results from an ongoing phase1/2 trial of gavo-cel in patients with treatment-refractory mesothelin-expressing solid tumors. The primary objectives were to evaluate safety and determine the recommended phase 2 dose (RP2D). Secondary objectives included efficacy. Thirty-two patients received gavo-cel at increasing doses either as a single agent (n = 3) or after lymphodepletion (LD, n = 29). Dose-limiting toxicities of grade 3 pneumonitis and grade 5 bronchioalveolar hemorrhage were noted. The RP2D was determined as 1 × 10 8 cells per m 2 after LD. Grade 3 or higher pneumonitis was seen in 16% of all patients and in none at the RP2D; grade 3 or higher cytokine release syndrome occurred in 25% of all patients and in 15% at the RP2D. In 30 evaluable patients, the overall response rate and disease control rate were 20% (13% confirmed) and 77%, respectively, and the 6-month overall survival rate was 70%. Gavo-cel warrants further study in patients with mesothelin-expressing cancers given its encouraging anti-tumor activity, but it may have a narrow therapeutic window. ClinicalTrials.gov identifier: NCT03907852.\n\nIndexed on Europe PMC as PubMed record 37501016 (DOI 10.1038/s41591-023-02452-y). Its abstract cites the registry id NCT03907852, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2023, doi: "10.1038/s41591-023-02452-y", pmid: "37501016", authors: "Hassan R, Butler M, O'Cearbhaill RE, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03907852 with the most citations, so it is the natural first reading for anyone following the Phase 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2023","url":"https://doi.org/10.1038/s41591-023-02452-y"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37501016/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37501016"},{"label":"ClinicalTrials.gov NCT03907852","url":"https://clinicaltrials.gov/study/NCT03907852"}], tags: ["europepmc-ingest"], cancers: ["mesothelioma","ovarian","nsclc","sclc"], drugs: ["fludarabine","cyclophosphamide","nivolumab","ipilimumab"], targets: [], technologies: [], trials: ["nct03907852"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct03916627-lancet-gastroenterol-hepatol-2022", name: "Neoadjuvant cemiplimab for resectable hepatocellular carcinoma: a single-arm, open-label, phase 2 trial", tldr: "Published report from the trial registered as NCT03916627, in The lancet. Gastroenterology & hepatology (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Surgical resection of early stage hepatocellular carcinoma is standard clinical practice; however, most tumours recur despite surgery, and no perioperative intervention has shown a survival benefit. Neoadjuvant immunotherapy has induced pathological responses in multiple tumour types and might decrease the risk of postoperative recurrence in hepatocellular carcinoma. We aimed to evaluate the clinical activity of neoadjuvant cemiplimab (an anti-PD-1) in patients with resectable hepatocellular carcinoma.\n\nMethods: For this single-arm, open-label, phase 2 trial, patients with resectable hepatocellular carcinoma (stage Ib, II, and IIIb) were enrolled and received two cycles of neoadjuvant cemiplimab 350 mg intravenously every 3 weeks followed by surgical resection. Eligible patients were aged 18 years or older, had confirmed resectable hepatocellular carcinoma, an Eastern Cooperative Oncology Group performance status of 0 or 1, and adequate liver function. Patients were excluded if they had metastatic disease, if the surgery was not expected to be curative, if they had a known additional malignancy requiring active treatment, or if they required systemic steroid treatment or any other immunosuppressive therapy. After resection, patients received an additional eight cycles of cemiplimab 350 mg intravenously every 3 weeks in the adjuvant setting. The primary endpoint was significant tumour necrosis on pathological examination (defined as >70% necrosis of the resected tumour). Secondary endpoints included delay of surgery, the proportion of patients with an overall response, change in CD8 + T-cell density, and adverse events. Tumour necrosis and response were analysed in all patients who received at least one dose of cemiplimab and completed surgical resection; safety and other endpoints were analysed in the intention-to-treat population. Patients underwent pre-treatment biopsies and blood collection throughout treatment. This trial is registered with ClinicalTrials.gov (NCT03916627, Cohort B) and is ongoing.\n\nFindings: Between Aug 5, 2019, and Nov 25, 2020, 21 patients were enrolled. All patients received neoadjuvant cemiplimab, and 20 patients underwent successful resection. Of the 20 patients with resected tumours, four (20%) had significant tumour necrosis. Three (15%) of 20 patients had a partial response, and all other patients maintained stable disease. 20 (95%) patients had a treatment-emergent adverse event of any grade during the neoadjuvant treatment period. The most common adverse events of any grade were increased aspartate aminotransferase (in four patients), increased blood creatine phosphokinase (in three), constipation (in three), and fatigue (in three). Seven patients had grade 3 adverse events, including increased blood creatine phosphokinase (in two patients) and hypoalbuminaemia (in one). No grade 4 or 5 events were observed. One patient developed pneumonitis, which led to a delay in surgery by 2 weeks.\n\nInterpretation: This report is, to our knowledge, the largest clinical trial of a neoadjuvant anti-PD-1 monotherapy reported to date in hepatocellular carcinoma. The observed pathological responses to cemiplimab in this cohort support the design of larger trials to identify the optimal treatment duration and definitively establish the clinical benefit of preoperative PD-1 blockade in patients with hepatocellular carcinoma.\n\nFunding: Regeneron Pharmaceuticals.\n\nIndexed on Europe PMC as PubMed record 35065058 (DOI 10.1016/s2468-1253(21)00385-x). Its abstract cites the registry id NCT03916627, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The lancet. Gastroenterology & hepatology", year: 2022, doi: "10.1016/s2468-1253(21)00385-x", pmid: "35065058", authors: "Marron TU, Fiel MI, Hamon P, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03916627 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Gastroenterol Hepatol 2022","url":"https://doi.org/10.1016/s2468-1253(21)00385-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35065058/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35065058"},{"label":"ClinicalTrials.gov NCT03916627","url":"https://clinicaltrials.gov/study/NCT03916627"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","hcc","head-and-neck","hcc-early","resectable-nsclc"], drugs: ["cemiplimab","fianlimab"], targets: [], technologies: [], trials: ["nct03916627"] }),
  p({ id: "paper-nct03944772-jco-precis-oncol-2025", name: "ORCHARD: Osimertinib Plus Necitumumab in Patients With Epidermal Growth Factor Receptor-Mutated Advanced Non-Small Cell Lung Cancer With a Secondary Epidermal Growth Factor Receptor Alteration Whose Disease Had Progressed on First-Line Osimertinib", tldr: "Published report from the ORCHARD trial registered as NCT03944772, in JCO Precision Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: ORCHARD (ClinicalTrials.gov identifier: NCT03944772) is a phase II, biomarker-directed platform study designed to characterize resistance mechanisms and evaluate novel drug combinations in patients with epidermal growth factor receptor ( EGFR)-mutated advanced non-small cell lung cancer who have progressed on first-line osimertinib. We report final results of the module assessing the efficacy and safety of osimertinib plus necitumumab (a monoclonal antibody that blocks EGFR) in patients with ≥one of the following: EGFR amplification or select secondary EGFR alterations (L718 or G724 mutation, or exon 20 insertion).\n\nMaterials and methods: Patients received osimertinib (80 mg orally once daily) plus necitumumab (800 mg intravenously, days 1 and 8 of a 3-week cycle) until disease progression or unacceptable toxicity. The primary end point was objective response rate (ORR) per RECIST 1.1 by investigator assessment.\n\nResults: Overall, 19 patients received osimertinib plus necitumumab; at data cutoff (April 18, 2023), all patients had discontinued treatment. The ORR was 11% (80% CI, 3 to 26); two patients had a confirmed partial response, with duration of response of 10.4 and 6.0 months; both patients had EGFR amplification. The median progression-free survival was 4.0 months (95% CI, 1.3 to 5.4) and the overall survival was 11.4 months (95% CI, 6.6 to 15.5). Ten patients (53%) had grade ≥3 adverse events, most commonly embolism (not otherwise specified, pulmonary embolism or deep vein thrombosis, reported in four patients; 21%). The safety profile of the combination was consistent with the known profiles of the two individual drugs, and no new signals were identified.\n\nConclusion: Osimertinib plus necitumumab demonstrated modest clinical benefit, and the overall risk-benefit analysis indicates that further evaluation of the regimen is not warranted in these molecularly defined subsets of osimertinib resistance.\n\nIndexed on Europe PMC as PubMed record 40466026 (DOI 10.1200/po-24-00818). Its abstract cites the registry id NCT03944772, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JCO Precision Oncology", year: 2025, doi: "10.1200/po-24-00818", pmid: "40466026", authors: "Riess JW, de Langen AJ, Ponce S, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03944772 with the most citations, so it is the natural first reading for anyone following the ORCHARD trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JCO Precis Oncol 2025","url":"https://doi.org/10.1200/po-24-00818"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40466026/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40466026"},{"label":"ClinicalTrials.gov NCT03944772","url":"https://clinicaltrials.gov/study/NCT03944772"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["osimertinib","savolitinib","gefitinib","necitumumab","durvalumab","carboplatin"], targets: [], technologies: [], trials: ["nct03944772"], journals: ["jco-precision-oncology"] }),
  p({ id: "paper-nct03974022-j-clin-oncol-2025", name: "Phase II Dose-Randomized Study of Sunvozertinib in Platinum-Pretreated Non-Small Cell Lung Cancer With Epidermal Growth Factor Receptor Exon 20 Insertion Mutations (WU-KONG1B)", tldr: "Published report from the WU-KONG1 trial registered as NCT03974022, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: WU-KONG1B (ClinicalTrials.gov identifier: NCT03974022) is a multinational phase II, dose-randomized study to assess the antitumor efficacy of sunvozertinib in pretreated patients with advanced non-small cell lung cancer (NSCLC) with epidermal growth factor receptor ( EGFR) exon 20 insertion mutations (exon20ins).\n\nMethods: Eligible patients with advanced-stage EGFR exon20ins NSCLC were randomly assigned by 1:1 ratio to receive sunvozertinib 200 mg or 300 mg once daily (200 and 300 mg-rand cohorts). After predefined interim analysis, additional patients were enrolled and treated with the 300 mg dose once daily. The primary end point was blinded independent review committee (IRC)-assessed confirmed objective response rate (cORR), and the key secondary end point was duration of response (DoR).\n\nResults: Among 85, 89, and 107 efficacy-evaluable patients in 200 mg-rand, 300 mg-rand, and 300 mg-all (including randomly assigned and nonrandomized patients) cohorts, the cORRs were 45.9% (97.5% CI, 33.6% to 58.5%), 47.2% (97.5% CI, 35.1% to 59.5%), and 45.8% (97.5% CI, 34.8% to 57.0%), respectively, per IRC assessment. The predefined null hypothesis was rejected with statistical significance ( P <.0001). Comparing 300 and 200 mg-rand cohorts, higher cORRs were observed in patients with baseline brain metastasis (52.4% v 28.6%) and previous amivantamab treatment (41.7% v 25%), as well as longer DoR (13.8 v 11.1 months). At 200 and 300 mg once daily, the most common treatment-related adverse events with grade ≥3 included diarrhea (2.2% v 18%), blood creatine phosphokinase increased (6.6% v 12.6%), and anemia (4.4% v 6.3%).\n\nConclusion: Sunvozertinib is efficacious at both 200 and 300 mg once daily in treating platinum-pretreated patients with advanced EGFR exon20ins NSCLC. The treatment-related adverse events of sunvozertinib were consistent with an EGFR tyrosine kinase inhibitor, with a more favorable safety profile at 200 mg than 300 mg once daily.\n\nIndexed on Europe PMC as PubMed record 40923280 (DOI 10.1200/jco-25-00788). Its abstract cites the registry id NCT03974022, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-25-00788", pmid: "40923280", authors: "Yang JC, Wang M, Doucet L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT03974022 with the most citations, so it is the natural first reading for anyone following the WU-KONG1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-25-00788"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40923280/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40923280"},{"label":"ClinicalTrials.gov NCT03974022","url":"https://clinicaltrials.gov/study/NCT03974022"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc","her2-mutant-nsclc"], drugs: ["sunvozertinib"], targets: [], technologies: [], trials: ["nct03974022"], journals: ["jco"] }),
  p({ id: "paper-nct04025879-n-engl-j-med-2024", name: "Perioperative Nivolumab in Resectable Lung Cancer", tldr: "Published report from the CheckMate 77T trial registered as NCT04025879, in New England Journal of Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Standard treatment with neoadjuvant nivolumab plus chemotherapy significantly improves outcomes in patients with resectable non-small-cell lung cancer (NSCLC). Perioperative treatment (i.e., neoadjuvant therapy followed by surgery and adjuvant therapy) with nivolumab may further improve clinical outcomes.\n\nMethods: In this phase 3, randomized, double-blind trial, we assigned adults with resectable stage IIA to IIIB NSCLC to receive neoadjuvant nivolumab plus chemotherapy or neoadjuvant chemotherapy plus placebo every 3 weeks for 4 cycles, followed by surgery and adjuvant nivolumab or placebo every 4 weeks for 1 year. The primary outcome was event-free survival according to blinded independent review. Secondary outcomes were pathological complete response and major pathological response according to blinded independent review, overall survival, and safety.\n\nResults: At this prespecified interim analysis (median follow-up, 25.4 months), the percentage of patients with 18-month event-free survival was 70.2% in the nivolumab group and 50.0% in the chemotherapy group (hazard ratio for disease progression or recurrence, abandoned surgery, or death, 0.58; 97.36% confidence interval [CI], 0.42 to 0.81; P<0.001). A pathological complete response occurred in 25.3% of the patients in the nivolumab group and in 4.7% of those in the chemotherapy group (odds ratio, 6.64; 95% CI, 3.40 to 12.97); a major pathological response occurred in 35.4% and 12.1%, respectively (odds ratio, 4.01; 95% CI, 2.48 to 6.49). Grade 3 or 4 treatment-related adverse events occurred in 32.5% of the patients in the nivolumab group and in 25.2% of those in the chemotherapy group.\n\nConclusions: Perioperative treatment with nivolumab resulted in significantly longer event-free survival than chemotherapy in patients with resectable NSCLC. No new safety signals were observed. (Funded by Bristol Myers Squibb; CheckMate 77T ClinicalTrials.gov number, NCT04025879.).\n\nIndexed on Europe PMC as PubMed record 38749033 (DOI 10.1056/nejmoa2311926). Its abstract cites the registry id NCT04025879, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2024, doi: "10.1056/nejmoa2311926", pmid: "38749033", authors: "Cascone T, Awad MM, Spicer JD, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04025879 with the most citations, so it is the natural first reading for anyone following the CheckMate 77T trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2024","url":"https://doi.org/10.1056/nejmoa2311926"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38749033/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38749033"},{"label":"ClinicalTrials.gov NCT04025879","url":"https://clinicaltrials.gov/study/NCT04025879"}], tags: ["europepmc-ingest"], cancers: ["nsclc","resectable-nsclc"], drugs: ["nivolumab","carboplatin","cisplatin","pemetrexed","docetaxel"], targets: [], technologies: [], trials: ["nct04025879"], journals: ["nejm"] }),
  p({ id: "paper-nct04036682-j-clin-oncol-2025", name: "Zipalertinib in Patients With Epidermal Growth Factor Receptor Exon 20 Insertion-Positive Non-Small Cell Lung Cancer Previously Treated With Platinum-Based Chemotherapy With or Without Amivantamab", tldr: "Published report from the REZILIENT1 trial registered as NCT04036682, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: To evaluate the safety and efficacy of zipalertinib, an irreversible epidermal growth factor receptor (EGFR) inhibitor, in pretreated patients with non-small cell lung cancer (NSCLC) harboring EGFR exon 20 insertion (ex20ins) mutations.\n\nMethods: REZILIENT1 (ClinicalTrials.gov identifier: NCT04036682) is a phase I/II open-label trial enrolling patients with locally advanced or metastatic EGFR ex20ins-mutant NSCLC previously treated with platinum-based chemotherapy with/without ex20ins-targeted therapies. Asymptomatic, treated and untreated stable CNS metastases are permitted. We report data from patients treated with zipalertinib 100 mg twice daily. The primary end points are objective response rate (ORR) and duration of response (DOR) by independent central review.\n\nResults: At data cutoff (December 10, 2024), 244 patients had received treatment with zipalertinib 100 mg twice daily. The primary efficacy population (8 months' follow-up) comprised patients who had received prior platinum-based chemotherapy without ex20ins-targeted therapy (125 patients), with amivantamab only (30 patients), or with amivantamab and other ex20ins-targeted therapy (21 patients). The confirmed ORR was 35.2% (95% CI, 28.2 to 42.8); median DOR was 8.8 months (95% CI, 8.3 to 12.7). Among patients who received prior platinum-based chemotherapy without ex20ins-targeted therapy, amivantamab only, or amivantamab and other ex20ins-targeted therapy, the confirmed ORR was 40%, 30%, and 14.3%, and median DOR was 8.8, 14.7, and 4.2 months, respectively. Among 68 patients with CNS metastases, the ORR was 30.9%. The most common grade ≥3 treatment-related adverse events were anemia (7%), pneumonitis and rash (2.5% each), and diarrhea, ALT increased, and platelet count decreased (2% each).\n\nConclusion: Zipalertinib demonstrated clinically meaningful efficacy with a manageable safety profile in patients with EGFR ex20ins-mutant NSCLC who received prior platinum-based chemotherapy with or without amivantamab.\n\nIndexed on Europe PMC as PubMed record 40450572 (DOI 10.1200/jco-25-00763). Its abstract cites the registry id NCT04036682, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-25-00763", pmid: "40450572", authors: "Piotrowska Z, Passaro A, Nguyen D, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04036682 with the most citations, so it is the natural first reading for anyone following the REZILIENT1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-25-00763"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40450572/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40450572"},{"label":"ClinicalTrials.gov NCT04036682","url":"https://clinicaltrials.gov/study/NCT04036682"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc"], drugs: ["zipalertinib"], targets: [], technologies: [], trials: ["nct04036682"], journals: ["jco"] }),
  p({ id: "paper-nct04129502-j-clin-oncol-2025", name: "First-Line Mobocertinib Versus Platinum-Based Chemotherapy in Patients With EGFR Exon 20 Insertion-Positive Metastatic Non-Small Cell Lung Cancer in the Phase III EXCLAIM-2 Trial", tldr: "Published report from the trial registered as NCT04129502, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Mobocertinib is an oral epidermal growth factor receptor (EGFR) tyrosine kinase inhibitor that targets EGFR exon 20 insertion (ex20ins) mutations in non-small cell lung cancer (NSCLC). This open-label, phase III trial (EXCLAIM-2, ClinicalTrials.gov identifier: NCT04129502) compared mobocertinib versus platinum-based chemotherapy as first-line treatment of EGFR ex20ins+ advanced/metastatic NSCLC.\n\nMethods: Patients with treatment-naive EGFR ex20ins+ locally advanced/metastatic NSCLC were randomly assigned 1:1 to mobocertinib 160 mg once daily or pemetrexed plus cisplatin or carboplatin every 3 weeks for four cycles followed by maintenance pemetrexed. The primary end point was progression-free survival (PFS) by blinded independent central review (BICR), with planned interim analysis (IA) after approximately 70% of 227 expected PFS events.\n\nResults: A total of 354 patients were randomly assigned (mobocertinib: n = 179; chemotherapy: n = 175). Baseline characteristics were balanced between arms. At IA (cutoff: April 4, 2023), the median PFS per BICR was 9.6 months in each treatment arm (hazard ratio [HR], 1.04 [95% CI, 0.77 to 1.39]; P =.803). The primary end point crossed the prespecified futility boundary (HR > 1). The confirmed objective response rate (95% CI) per BICR was 32% (26 to 40) with mobocertinib versus 30% (24 to 38) with chemotherapy; the median duration of response was 12.0 versus 8.4 months. Quality-of-life assessments indicated clinically meaningful delays in time to deterioration of lung cancer symptoms, cognitive function, and constipation with mobocertinib versus chemotherapy. Grade ≥3 adverse events in >5% of patients (mobocertinib, chemotherapy) were diarrhea (20%, 1%), anemia (6%, 10%), increased lipase (6%, 0%), and decreased neutrophil count (1%, 7%).\n\nConclusion: The EXCLAIM-2 trial did not meet its primary end point. The efficacy of mobocertinib was not superior to platinum-based chemotherapy for first-line treatment of patients with EGFR ex20ins+ advanced/metastatic NSCLC.\n\nIndexed on Europe PMC as PubMed record 39879577 (DOI 10.1200/jco-24-01269). Its abstract cites the registry id NCT04129502, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-24-01269", pmid: "39879577", authors: "Jänne PA, Wang BC, Cho BC, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04129502 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-24-01269"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39879577/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39879577"},{"label":"ClinicalTrials.gov NCT04129502","url":"https://clinicaltrials.gov/study/NCT04129502"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc"], drugs: ["mobocertinib","pemetrexed","cisplatin","carboplatin"], targets: [], technologies: [], trials: ["nct04129502"], journals: ["jco"] }),
  p({ id: "paper-nct04143607-lancet-respir-med-2025", name: "Efficacy and safety of limertinib versus gefitinib as first-line treatment for locally advanced or metastatic non-small-cell lung cancer with EGFR-sensitising mutation: a randomised, double-blind, double-dummy, phase 3 trial", tldr: "Published report from the trial registered as NCT04143607, in The Lancet. Respiratory medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Limertinib is a new third-generation epidermal growth factor receptor (EGFR) tyrosine kinase inhibitor. This study aimed to prospectively assess the efficacy and safety of limertinib versus gefitinib as a first-line treatment for locally advanced or metastatic non-small-cell lung cancer (NSCLC) with EGFR-sensitising mutation.\n\nMethods: This multicentre, randomised, double-blind, double-dummy, phase 3 trial was done at 56 hospitals in China. Eligible patients were aged ≥18 years with locally advanced or metastatic NSCLC with EGFR-sensitising mutation (exon 19 deletion or exon 21 L858R mutation) detected in tumour tissue samples using the Cobas EGFR Mutation Test at a central laboratory. Patients were randomly assigned (1:1) to receive oral limertinib 80 mg twice a day and gefitinib-matching placebo 250 mg once a day or oral gefitinib 250 mg once a day plus limertinib-matching placebo 80 mg twice a day in 21-day cycles, until disease progression or other discontinuation criteria was met. Random assignment was stratified according to EGFR mutation type (exon 19 deletion or exon 21 L858R mutation) and CNS metastasis (yes or no) using permuted blocks (block size four) through an interactive web-based response system. The primary endpoint was independent central review (ICR)-assessed progression-free survival. All enrolled patients who received at least one dose of study treatment were included in the full analysis set for efficacy analysis. All enrolled patients who received at least one dose of study treatment and one safety assessment were included in the safety set. This study is registered with ClinicalTrials.gov, NCT04143607, and follow-up is ongoing.\n\nFindings: Between June 30, 2021, and Sept 22, 2022, 337 patients were enrolled and 168 were randomly assigned to the limertinib group and 169 to the gefitinib group. Patients' median age was 63 years (34-82). 214 (64%) of 337 patients were female and 123 (36%) were male. The median masked ICR-assessed progression-free survival was 20·7 months (95% CI 15·2-22·1) in the limertinib group and 9·7 months (95% CI 8·3-11·1) in the gefitinib group (hazard ratio [HR] 0·44 [95% CI 0·34-0·58]; p<0·0001). Treatment-related adverse events of grade 3 or worse occurred in 42 (25%) of 168 patients in the limertinib group and 42 (25%) of 169 patients in the gefitinib group. Treatment-related serious adverse events occurred in nine (5%) patients and 17 (10%) patients in each group, respectively. Six (4%) patients in the limertinib group died due to adverse events, all of which were considered possibly unrelated to the study drug by investigators. In the gefitinib group, seven (4%) patients died due to adverse events, with three (2%) of those deaths judged as possibly related to the study drug by investigators. Three treatment-related deaths in the gefitinib group were recorded (one case related to pneumonia and two with cause of death unknown).\n\nInterpretation: Limertinib showed superior efficacy compared with gefitinib and a manageable safety profile for locally advanced or metastatic NSCLC patients with EGFR-sensitising mutation and should be considered as another first-line treatment option for this patient population.\n\nFunding: Jiangsu Aosaikang Pharmaceutical.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 40550238 (DOI 10.1016/s2213-2600(25)00121-3). Its abstract cites the registry id NCT04143607, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2025, doi: "10.1016/s2213-2600(25)00121-3", pmid: "40550238", authors: "Shi Y, Wu L, Ji Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04143607 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2025","url":"https://doi.org/10.1016/s2213-2600(25)00121-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40550238/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40550238"},{"label":"ClinicalTrials.gov NCT04143607","url":"https://clinicaltrials.gov/study/NCT04143607"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["limertinib"], targets: [], technologies: [], trials: ["nct04143607"] }),
  p({ id: "paper-nct04152499-j-hematol-oncol-2025", name: "Results of a phase 1/2 study of sacituzumab tirumotecan in patients with unresectable locally advanced or metastatic solid tumors refractory to standard therapies", tldr: "Published report from the TROP2 ADC trial registered as NCT04152499, in Journal of hematology & oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sacituzumab tirumotecan (sac-TMT) is an antibody-drug conjugate composed of an anti-TROP2 monoclonal antibody coupled to a cytotoxic belotecan-derived topoisomerase I inhibitor (KL610023) via a novel linker. We report results from the phase 1 dose-escalation cohorts in advanced solid tumors and phase 2 expansion cohorts for metastatic triple-negative breast cancer (TNBC) from the first-in-human MK-2870-001 (KL264-01) study (NCT04152499).\n\nMethods: Patients had unresectable locally advanced/metastatic solid tumors refractory to standard therapies. In the phase 1 dose-escalation cohorts, patients had unresectable locally advanced/metastatic solid tumors refractory to standard therapies. Sac-TMT was administered by intravenous administration every 2 weeks at 2 to 12 mg/kg. In phase 2, patients with TNBC and HR+/HER2- breast cancer received sac-TMT per recommended doses for expansion (RDEs) identified in phase 1. Primary objectives were determining maximum tolerated dose (MTD) of sac-TMT and establishing RDEs (phase 1) and determining ORR per RECIST v1.1 by investigator assessment (phase 2). Adverse events were assessed per NCI-CTCAE version 5.0.\n\nResults: Thirty patients were enrolled in phase 1 and received sac-TMT 2 mg/kg (n = 4), 4 mg/kg (n = 7), 5 mg/kg (n = 7), 5.5 mg/kg (n = 5), and 6 mg/kg (n = 7). Five patients had dose-limiting toxicities: grade 3 stomatitis at 4, 5.5, and 6 mg/kg; grade 3 rash at 5 mg/kg; and grade 3 urticaria at 6 mg/kg. MTD was 5.5 mg/kg and RDEs were 4 and 5 mg/kg. In the phase 2 dose expansion, ORR (95% CI) was 34.8% (16.4%, 57.3%) in the 4-mg/kg group (n = 23) and 38.9% (23.1%, 56.5%) in the 5-mg/kg group (n = 36) for TNBC. ORR (95% CI) was 31.7% (18.1%, 48.1%) for HR+/HER2- breast cancer (n = 41).\n\nConclusions: Sac-TMT demonstrated manageable safety profile in patients with unresectable locally advanced/metastatic solid tumors and promising antitumor activity in metastatic TNBC and HR+/HER2 - breast cancer. Sac-TMT is being investigated in phase 3 studies.\n\nTrial registration: ClinicalTrials.gov, NCT04152499.\n\nIndexed on Europe PMC as PubMed record 40481574 (DOI 10.1186/s13045-025-01705-2). Its abstract cites the registry id NCT04152499, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of hematology & oncology", year: 2025, doi: "10.1186/s13045-025-01705-2", pmid: "40481574", authors: "Ouyang Q, Rodon J, Liang Y, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04152499 with the most citations, so it is the natural first reading for anyone following the TROP2 ADC trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Hematol Oncol 2025","url":"https://doi.org/10.1186/s13045-025-01705-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40481574/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40481574"},{"label":"ClinicalTrials.gov NCT04152499","url":"https://clinicaltrials.gov/study/NCT04152499"}], tags: ["europepmc-ingest"], cancers: ["ovarian","nsclc","sclc","head-and-neck","cervical"], drugs: ["sacituzumab-tirumotecan"], targets: [], technologies: [], trials: ["nct04152499"], journals: ["journal-of-hematology-and-oncology"] }),
  p({ id: "paper-nct04379635-lancet-respir-med-2025", name: "Perioperative tislelizumab plus neoadjuvant chemotherapy for patients with resectable non-small-cell lung cancer (RATIONALE-315): an interim analysis of a randomised clinical trial", tldr: "Published report from the trial registered as NCT04379635, in The Lancet. Respiratory medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Treatment guidelines recommend neoadjuvant or adjuvant chemotherapy, with or without immune checkpoint inhibitors, for resectable non-small-cell lung cancer (NSCLC). We report the interim results for the phase 3 RATIONALE-315 study, which aimed to investigate perioperative tislelizumab for the treatment of resectable NSCLC.\n\nMethods: RATIONALE-315 is a randomised, double-blind, placebo-controlled phase 3 trial conducted at 50 sites (hospitals or academic research centres) in China. Patients (aged ≥18 years) with untreated stage II-IIIA squamous or non-squamous NSCLC were randomly assigned (1:1) to neoadjuvant tislelizumab 200 mg or placebo intravenously every 3 weeks, plus platinum-based doublet chemotherapy followed by surgery and adjuvant tislelizumab 400 mg or placebo every 6 weeks. Dual primary endpoints were major pathological response rate and event-free survival, analysed by intention to treat. Safety was also assessed in all patients who received at least one dose of study treatment. RATIONALE-315 is registered with ClinicalTrials.gov, NCT04379635, and is active but not recruiting.\n\nFindings: Between June 8, 2020, and Aug 31, 2022, 453 patients were assigned to tislelizumab (n=226) or placebo (n=227). The median age of patients was 62·0 years (IQR 56·0-67·0). 410 (91%) of 453 patients were male and 43 (9%) were female. at Aug 21, 2023 (data cutoff for the interim analysis of event-free survival), median duration of follow-up was 22·0 months (IQR 15·5-28·0). Tislelizumab significantly improved event-free survival versus placebo (stratified hazard ratio 0·56 [95% CI 0·40-0·79]; one-sided p=0·0003). The major pathological response rate was significantly higher in the tislelizumab group (56% [95% CI 50-63]) than in the placebo group (15% [11-20]; difference 41% [33-49]; one-sided p<0·0001). Grade 3 or worse adverse events and serious treatment-related adverse events occurred in 163 (72%) of 226 patients and 35 (15%) of 226 patients, respectively, in the tislelizumab group, and in 150 (66%) and 18 (8%) patients, respectively, in the placebo group. The most common grade 3 or worse treatment-related adverse event was decreased neutrophil count (138 [61%] of 226 in the tislelizumab group vs 134 [59%] of 226 in the placebo group). 31 (14%) of 226 patients in the tislelizumab group and 45 (20%) of 227 patients in the placebo group died during the study.\n\nInterpretation: Perioperative tislelizumab plus neoadjuvant chemotherapy showed a clinically meaningful and statistically significant improvement in efficacy and a manageable safety profile compared with neoadjuvant chemotherapy in patients with resectable stage II-IIIA NSCLC.\n\nFunding: BeiGene.\n\nIndexed on Europe PMC as PubMed record 39581197 (DOI 10.1016/s2213-2600(24)00269-8). Its abstract cites the registry id NCT04379635, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2025, doi: "10.1016/s2213-2600(24)00269-8", pmid: "39581197", authors: "Yue D, Wang W, Liu H, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04379635 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2025","url":"https://doi.org/10.1016/s2213-2600(24)00269-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39581197/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39581197"},{"label":"ClinicalTrials.gov NCT04379635","url":"https://clinicaltrials.gov/study/NCT04379635"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","resectable-nsclc"], drugs: ["tislelizumab","cisplatin","paclitaxel","pemetrexed","carboplatin"], targets: [], technologies: [], trials: ["nct04379635"] }),
  p({ id: "paper-nct04379635-ann-oncol-2026-update", name: "Perioperative tislelizumab plus neoadjuvant chemotherapy for patients with resectable non-small-cell lung cancer: final analysis of the randomized RATIONALE-315 trial", tldr: "Later report from the trial registered as NCT04379635, in Annals of Oncology (2026); its title describes an updated or longer-term analysis.", summary: "Background: Perioperative immunotherapy, particularly anti-programmed cell death protein 1 therapy, combined with neoadjuvant chemotherapy has emerged as one of the standard-of-care options for resectable non-small-cell lung cancer (NSCLC). We report the final analysis of RATIONALE-315, a randomized, double-blind, phase III trial evaluating the efficacy and safety of perioperative tislelizumab plus neoadjuvant chemotherapy versus neoadjuvant chemotherapy alone in patients with resectable, stage II-IIIA NSCLC.\n\nPatients and methods: Adult patients in China were randomized (1: 1) to receive either perioperative tislelizumab or placebo in combination with neoadjuvant chemotherapy. The dual primary endpoints were event-free survival (EFS) and major pathological response, assessed by blinded independent central review. The secondary endpoints included pathological complete response, overall survival (OS), disease-free survival, and safety.\n\nResults: In total, 453 patients were randomized (226 to tislelizumab and 227 to placebo). At the final analysis (median study follow-up of 38.5 months), patients in the tislelizumab group experienced statistically significantly improved OS versus those in the placebo group {hazard ratio (HR) 0.65 [95% confidence interval (CI) 0.45-0.93]; P = 0.009}. The median OS was not reached in either group. The 36-month OS rate was 79.3% in the tislelizumab group versus 69.3% in the placebo group. The median EFS was not reached in the tislelizumab group versus 30.6 months in the placebo group [HR 0.58 (95% CI 0.43-0.79)]. Survival benefits were generally consistent across subgroups. The safety profile of tislelizumab plus chemotherapy was tolerable and consistent with known profiles of the individual therapies.\n\nConclusions: Neoadjuvant tislelizumab plus chemotherapy and adjuvant tislelizumab demonstrated a statistically significant, clinically meaningful OS benefit and sustained, clinically meaningful EFS improvement compared with neoadjuvant chemotherapy, with a tolerable safety profile in patients with resectable stage II-IIIA NSCLC. These results support the use of this regimen in this patient population.\n\nClinical trial number: NCT04379635.\n\nIndexed on Europe PMC as PubMed record 41344593 (DOI 10.1016/j.annonc.2025.11.017). Its abstract cites the registry id NCT04379635, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2026, doi: "10.1016/j.annonc.2025.11.017", pmid: "41344593", authors: "Wang C, Wang W, Liu H, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Ann Oncol 2026","url":"https://doi.org/10.1016/j.annonc.2025.11.017"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41344593/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41344593"},{"label":"ClinicalTrials.gov NCT04379635","url":"https://clinicaltrials.gov/study/NCT04379635"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","resectable-nsclc"], drugs: ["tislelizumab","cisplatin","paclitaxel","pemetrexed","carboplatin"], targets: [], technologies: [], trials: ["nct04379635"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct04395677-j-clin-oncol-2024", name: "Efficacy and Safety of Taletrectinib in Chinese Patients With ROS1+ Non-Small Cell Lung Cancer: The Phase II TRUST-I Study", tldr: "Published report from the trial registered as NCT04395677, in Journal of Clinical Oncology (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Taletrectinib, a highly potent, CNS-active, ROS1 tyrosine kinase inhibitor (TKI), has demonstrated high and durable response rates, high intracranial objective response rate (ORR), prolonged progression-free survival (PFS), and activity against G2032R with a favorable safety profile. We report outcomes from the pivotal TRUST-I study (ClinicalTrials.gov identifier: NCT04395677) of taletrectinib for ROS1+ non-small cell lung cancer in China.\n\nMethods: TRUST-I evaluated TKI-naїve and crizotinib-pretreated patients. The primary end point was confirmed ORR (cORR) by independent review committee; key secondary end points included duration of response (DOR), PFS, and safety.\n\nResults: at November 2023, 173 patients were enrolled (median age, 55 years; 58% female; 73% never smoked; TKI naїve: n = 106; crizotinib pretreated: n = 67). In TKI-naїve patients, cORR and intracranial cORR were 91% and 88%, respectively, and 52% and 73% in crizotinib-pretreated patients. In TKI-naїve patients, median DOR and median PFS were not reached (NR) with 22.1-month and 23.5-month follow-up, respectively. In crizotinib-pretreated patients, the median DOR was 10.6 months (95% CI, 6.3 months to NR; 8.4-month follow-up), and the median PFS was 7.6 months (95% CI, 5.5 to 12.0 months; 9.7-month follow-up). Eight of 12 patients (67%) with G2032R mutations responded. The most frequent treatment-emergent adverse events (TEAEs) were increased AST (76%), diarrhea (70%), and increased ALT (68%), most of which were grade 1-2. Incidences of neurologic TEAEs were low (dizziness: 23%; dysgeusia: 10%) and mostly grade 1. Discontinuations (5%) and dose reductions (19%) due to TEAEs were low.\n\nConclusion: Taletrectinib continues to show high and durable overall responses, prolonged PFS, robust activity against intracranial lesions and acquired resistance mutations including G2032R, and a favorable safety profile with a low incidence of neurologic TEAEs.\n\nIndexed on Europe PMC as PubMed record 38822758 (DOI 10.1200/jco.24.00731). Its abstract cites the registry id NCT04395677, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2024, doi: "10.1200/jco.24.00731", pmid: "38822758", authors: "Li W, Xiong A, Yang N, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04395677 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2024","url":"https://doi.org/10.1200/jco.24.00731"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38822758/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38822758"},{"label":"ClinicalTrials.gov NCT04395677","url":"https://clinicaltrials.gov/study/NCT04395677"}], tags: ["europepmc-ingest"], cancers: ["nsclc","ros1-positive-nsclc"], drugs: [], targets: [], technologies: [], trials: ["nct04395677"], journals: ["jco"] }),
  p({ id: "paper-nct04395677-j-clin-oncol-2026-update", name: "Long-Term Efficacy and Safety of Taletrectinib in Patients With ROS1 + Non-Small Cell Lung Cancer: Results From the Phase II TRUST-I Study", tldr: "Later report from the trial registered as NCT04395677, in Journal of Clinical Oncology (2026); its title describes an updated or longer-term analysis.", summary: "Taletrectinib is a next-generation, CNS-active, selective ROS1 tyrosine kinase inhibitor (TKI) with activity against the ROS1 G2032R resistance mutation. Initial data from the TRUST-I study (ClinicalTrials.gov identifier: NCT04395677) demonstrated high response rates and intracranial (IC) activity, with promising durability, in Chinese patients with advanced ROS1 + non-small cell lung cancer (NSCLC). With longer follow-up, taletrectinib continued to demonstrate high and durable response rates in both TKI-naïve and crizotinib-pretreated patients, including IC activity and promising overall survival (OS). Among 103 TKI-naïve patients who started taletrectinib at 600 mg once daily (median follow-up, 51.0 months), the objective response rate (ORR) was 90.3% (95% CI, 82.9 to 95.3), the median duration of response (DOR) and median progression-free survival (PFS) exceeded 4 years (49.7 months and 49.6 months, respectively), and median OS was not reached. Among 66 crizotinib-pretreated patients (median follow-up, 45.2 months), the ORR was 51.5%, the median DOR was 13.2 months, the median PFS was 7.6 months, and the median OS was 25.6 months. The safety profile remained consistent with prior reports, and no new safety signals were identified. Overall, taletrectinib demonstrated durable long-term efficacy and a manageable safety profile in patients with advanced ROS1 + NSCLC.\n\nIndexed on Europe PMC as PubMed record 42013573 (DOI 10.1200/jco-26-00434). Its abstract cites the registry id NCT04395677, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2026, doi: "10.1200/jco-26-00434", pmid: "42013573", authors: "Li W, Zhang Y, Fan H, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"J Clin Oncol 2026","url":"https://doi.org/10.1200/jco-26-00434"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42013573/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42013573"},{"label":"ClinicalTrials.gov NCT04395677","url":"https://clinicaltrials.gov/study/NCT04395677"}], tags: ["europepmc-ingest"], cancers: ["nsclc","ros1-positive-nsclc"], drugs: [], targets: [], technologies: [], trials: ["nct04395677"], journals: ["jco"] }),
  p({ id: "paper-nct04538664-n-engl-j-med-2023", name: "Amivantamab plus Chemotherapy in NSCLC with EGFR Exon 20 Insertions", tldr: "Published report from the PAPILLON trial registered as NCT04538664, in New England Journal of Medicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Amivantamab has been approved for the treatment of patients with advanced non-small-cell lung cancer (NSCLC) with epidermal growth factor receptor ( EGFR) exon 20 insertions who have had disease progression during or after platinum-based chemotherapy. Phase 1 data showed the safety and antitumor activity of amivantamab plus carboplatin-pemetrexed (chemotherapy). Additional data on this combination therapy are needed.\n\nMethods: In this phase 3, international, randomized trial, we assigned in a 1:1 ratio patients with advanced NSCLC with EGFR exon 20 insertions who had not received previous systemic therapy to receive intravenous amivantamab plus chemotherapy (amivantamab-chemotherapy) or chemotherapy alone. The primary outcome was progression-free survival according to blinded independent central review. Patients in the chemotherapy group who had disease progression were allowed to cross over to receive amivantamab monotherapy.\n\nResults: A total of 308 patients underwent randomization (153 to receive amivantamab-chemotherapy and 155 to receive chemotherapy alone). Progression-free survival was significantly longer in the amivantamab-chemotherapy group than in the chemotherapy group (median, 11.4 months and 6.7 months, respectively; hazard ratio for disease progression or death, 0.40; 95% confidence interval [CI], 0.30 to 0.53; P<0.001). At 18 months, progression-free survival was reported in 31% of the patients in the amivantamab-chemotherapy group and in 3% in the chemotherapy group; a complete or partial response at data cutoff was reported in 73% and 47%, respectively (rate ratio, 1.50; 95% CI, 1.32 to 1.68; P<0.001). In the interim overall survival analysis (33% maturity), the hazard ratio for death for amivantamab-chemotherapy as compared with chemotherapy was 0.67 (95% CI, 0.42 to 1.09; P = 0.11). The predominant adverse events associated with amivantamab-chemotherapy were reversible hematologic and EGFR-related toxic effects; 7% of patients discontinued amivantamab owing to adverse reactions.\n\nConclusions: The use of amivantamab-chemotherapy resulted in superior efficacy as compared with chemotherapy alone as first-line treatment of patients with advanced NSCLC with EGFR exon 20 insertions. (Funded by Janssen Research and Development; PAPILLON ClinicalTrials.gov number, NCT04538664.).\n\nIndexed on Europe PMC as PubMed record 37870976 (DOI 10.1056/nejmoa2306441). Its abstract cites the registry id NCT04538664, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2023, doi: "10.1056/nejmoa2306441", pmid: "37870976", authors: "Zhou C, Tang KJ, Cho BC, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04538664 with the most citations, so it is the natural first reading for anyone following the PAPILLON trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2023","url":"https://doi.org/10.1056/nejmoa2306441"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37870976/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37870976"},{"label":"ClinicalTrials.gov NCT04538664","url":"https://clinicaltrials.gov/study/NCT04538664"}], tags: ["europepmc-ingest"], cancers: ["nsclc","egfr-mutant-nsclc"], drugs: ["amivantamab","pemetrexed","carboplatin"], targets: [], technologies: [], trials: ["nct04538664"], journals: ["nejm"] }),
  p({ id: "paper-nct04561362-j-clin-oncol-2025", name: "First-in-Human, Phase I/II Dose Escalation and Expansion Study of Zelenectide Pevedotin in Patients With Advanced Solid Tumors: Results From Monotherapy Dose Escalation", tldr: "Published report from the trial registered as NCT04561362, in Journal of Clinical Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Zelenectide pevedotin (BT8009) is a Bicycle Drug Conjugate comprising a highly selective Nectin-4-targeting Bicycle peptide, linked to monomethyl auristatin E. We report monotherapy dose-escalation results from Duravelo-1 (Phase I/II; ClinicalTrials.gov identifier: NCT04561362).\n\nMethods: Adults with advanced/metastatic solid tumors associated with Nectin-4 expression received zelenectide pevedotin intravenously at 2.5, 5.0, or 7.5 mg/m 2 once weekly on a 28-day cycle; or 7.5 mg/m 2 on days 1 and 8 of a 21-day cycle; or 7.5 or 10.0 mg/m 2 once every 2 weeks on a 28-day cycle. Primary objectives were to evaluate safety and tolerability; antitumor activity and pharmacokinetic characterization were secondary objectives.\n\nResults: Forty-nine patients, most with urothelial carcinoma (UC; 25 of 49), received three previous lines of therapy (median). Common treatment-related adverse events (TRAEs) included nausea (49% [grade 3/4 2%]), likely because of a lack of prophylactic antiemetics during the dose-limiting toxicity period, and fatigue (39% [grade 3/4 6%]). The most common TRAEs of clinical interest were peripheral neuropathy (33% [grade 3/4 2%]), neutropenia (22% [grade 3/4 16%]), and skin reactions (22% [grade 3/4 2%]). The maximum tolerated dose was 7.5 mg/m 2 once every 2 weeks; the recommended phase 2 doses were 5.0 mg/m 2 once weekly and 7.5 mg/m 2 on days 1 and 8 of a 21-day cycle. Across doses (efficacy-evaluable; all tumor types), the objective response rate (ORR) was 24% and the clinical benefit rate (CBR) was 48% (n = 10 of 42; 95% CI, 12.1 to 39.5); the ORR was 38% and the CBR was 57% for patients with UC (n = 8 of 21; 95% CI, 18.1 to 61.6). The median duration of response and the median follow-up for all patients were 11.1 and 7.4 months, respectively.\n\nConclusion: Zelenectide pevedotin monotherapy demonstrated a generally well-tolerated safety profile and preliminary efficacy, particularly in UC, supporting investigation of UC and non-UC populations in the expansion phase.\n\nIndexed on Europe PMC as PubMed record 41197088 (DOI 10.1200/jco-25-00559). Its abstract cites the registry id NCT04561362, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2025, doi: "10.1200/jco-25-00559", pmid: "41197088", authors: "Baldini C, Verlingue L, Goldschmidt V, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04561362 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2025","url":"https://doi.org/10.1200/jco-25-00559"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41197088/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41197088"},{"label":"ClinicalTrials.gov NCT04561362","url":"https://clinicaltrials.gov/study/NCT04561362"}], tags: ["europepmc-ingest"], cancers: ["urothelial","tnbc","breast-hr-positive","breast-her2-positive","nsclc","ovarian"], drugs: ["zelenectide-pevedotin","pembrolizumab"], targets: [], technologies: [], trials: ["nct04561362"], journals: ["jco"] }),
  p({ id: "paper-nct04579380-j-clin-oncol-2023", name: "Tucatinib and Trastuzumab for Previously Treated Human Epidermal Growth Factor Receptor 2-Positive Metastatic Biliary Tract Cancer (SGNTUC-019): A Phase II Basket Study", tldr: "Published report from the trial registered as NCT04579380, in Journal of Clinical Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: To evaluate the efficacy and safety of tucatinib and trastuzumab in patients with previously treated human epidermal growth factor receptor 2-positive (HER2+) metastatic biliary tract cancer (mBTC).\n\nMethods: SGNTUC-019 (ClinicalTrials.gov identifier: NCT04579380) is an open-label phase II basket study evaluating the efficacy and safety of tucatinib and trastuzumab in patients with HER2-altered solid tumors. In the biliary tract cancer cohort, patients had previously treated HER2 overexpressing or amplified (HER2+) tumors (identified with local testing) with no prior HER2-directed therapy. The primary end point was confirmed objective response rate (cORR) per investigator assessment. Patients were treated on a 21-day cycle with tucatinib (300 mg orally twice daily) and trastuzumab (8 mg/kg intravenously followed by 6 mg/kg every 3 weeks).\n\nResults: Thirty patients were enrolled. at data cutoff (January 30, 2023), the median duration of follow-up was 10.8 months. The cORR was 46.7% (90% CI, 30.8 to 63.0), with a disease control rate of 76.7% (90% CI, 60.6 to 88.5). The median duration of response and progression-free survival were 6.0 months (90% CI, 5.5 to 6.9) and 5.5 months (90% CI, 3.9 to 8.1), respectively. At data cutoff, 15 patients (50.0%) had died, and the estimated 12-month overall survival rate was 53.6% (90% CI, 36.8 to 67.8). The two most common treatment-emergent adverse events (TEAEs) were pyrexia (43.3%) and diarrhea (40.0%). Grade ≥3 TEAEs were reported in 18 patients (60.0%), with the most common being cholangitis, decreased appetite, and nausea (all 10.0%), which were generally not treatment related. TEAEs led to treatment regimen discontinuation in one patient, and there were no deaths due to TEAEs.\n\nConclusion: Tucatinib combined with trastuzumab had clinically significant antitumor activity and was well tolerated in patients with previously treated HER2+ mBTC.\n\nIndexed on Europe PMC as PubMed record 37751561 (DOI 10.1200/jco.23.00606). Its abstract cites the registry id NCT04579380, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2023, doi: "10.1200/jco.23.00606", pmid: "37751561", authors: "Nakamura Y, Mizuno N, Sunakawa Y, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04579380 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Clin Oncol 2023","url":"https://doi.org/10.1200/jco.23.00606"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37751561/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37751561"},{"label":"ClinicalTrials.gov NCT04579380","url":"https://clinicaltrials.gov/study/NCT04579380"}], tags: ["europepmc-ingest"], cancers: ["endometrial","cervical","cholangiocarcinoma","nsclc","her2-mutant-nsclc"], drugs: ["tucatinib","trastuzumab","fulvestrant"], targets: [], technologies: [], trials: ["nct04579380"], journals: ["jco"] }),
  p({ id: "paper-nct04585035-signal-transduct-target-ther-2025", name: "Garsorasib, a KRAS G12C inhibitor, with or without cetuximab, an EGFR antibody, in colorectal cancer cohorts of a phase II trial in advanced solid tumors with KRAS G12C mutation", tldr: "Published report from the trial registered as NCT04585035, in Signal transduction and targeted therapy (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Mutations in the KRAS gene have long been implicated in the pathogenesis of colorectal cancer (CRC). KRAS G12C inhibitors overcome the \"undruggable\" challenge, enabling precision therapy. Garsorasib (D-1553), a highly potent and selective KRAS G12C inhibitor, has demonstrated promising anti-tumor activity and favorable safety profile in early clinical trials. We conducted an open-label, nonrandomized phase II trial (ClinicalTrials.gov, NCT04585035) to assess the safety and efficacy of garsorasib with or without cetuximab in KRAS G12C-mutated CRC. In the monotherapy cohort (n = 26), objective response rate (ORR) was 19.2% (95% CI, 6.6-39.4), disease control rate (DCR) was 92.3% (95% CI, 74.9-99.1), median progression-free survival (PFS) was 5.5 months (95% CI, 2.9-11.6) and median overall survival (OS) was 13.1 months (95% CI, 9.5-NE). In the combination cohort (n = 42), ORR was 45.2% (95% CI, 29.8-61.3), DCR was 92.9% (95% CI, 80.5-98.5), median PFS was 7.5 months (95% CI, 5.5-8.1), and median OS was not reached. Grade ≥3 treatment-related adverse events occurred in 5 (19.2%) and 6 (14.3%) patients in monotherapy and combination cohort, respectively. Garsorasib with or without cetuximab showed a promising efficacy and manageable safety profiles in heavily pretreated patients with KRAS G12C-mutated CRC, providing a potential new treatment approach for such population.\n\nIndexed on Europe PMC as PubMed record 40523897 (DOI 10.1038/s41392-025-02274-z). Its abstract cites the registry id NCT04585035, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Signal transduction and targeted therapy", year: 2025, doi: "10.1038/s41392-025-02274-z", pmid: "40523897", authors: "Ruan DY, Wu HX, Xu Y, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04585035 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Signal Transduct Target Ther 2025","url":"https://doi.org/10.1038/s41392-025-02274-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40523897/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40523897"},{"label":"ClinicalTrials.gov NCT04585035","url":"https://clinicaltrials.gov/study/NCT04585035"}], tags: ["europepmc-ingest"], cancers: ["nsclc","kras-g12c-nsclc"], drugs: ["garsorasib","cetuximab","pembrolizumab"], targets: [], technologies: [], trials: ["nct04585035"] }),
  p({ id: "paper-nct04619004-j-clin-oncol-2023", name: "HERTHENA-Lung01, a Phase II Trial of Patritumab Deruxtecan (HER3-DXd) in Epidermal Growth Factor Receptor-Mutated Non-Small-Cell Lung Cancer After Epidermal Growth Factor Receptor Tyrosine Kinase Inhibitor Therapy and Platinum-Based Chemotherapy", tldr: "Published report from the HERTHENA-Lung01 trial registered as NCT04619004, in Journal of Clinical Oncology (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Patritumab deruxtecan, or HER3-DXd, is an antibody-drug conjugate consisting of a fully human monoclonal antibody to human epidermal growth factor receptor 3 (HER3) attached to a topoisomerase I inhibitor payload via a stable tetrapeptide-based cleavable linker. We assessed the efficacy and safety of HER3-DXd in patients with epidermal growth factor receptor ( EGFR)-mutated non-small-cell lung cancer (NSCLC).\n\nMethods: This phase II study (ClinicalTrials.gov identifier: NCT04619004) was designed to evaluate HER3-DXd in patients with advanced EGFR- mutated NSCLC previously treated with EGFR tyrosine kinase inhibitor (TKI) therapy and platinum-based chemotherapy (PBC). Patients received HER3-DXd 5.6 mg/kg intravenously once every 3 weeks or an uptitration regimen (3.2 → 4.8 → 6.4 mg/kg). The primary end point was confirmed objective response rate (ORR; RECIST 1.1) by blinded independent central review (BICR), with a null hypothesis of 26.4% on the basis of historical data.\n\nResults: Enrollment into the uptitration arm closed early on the basis of a prespecified benefit-risk assessment of data from the phase I U31402-A-U102 trial. In total, 225 patients received HER3-DXd 5.6 mg/kg once every 3 weeks. at May 18, 2023, median study duration was 18.9 (range, 14.9-27.5) months. Confirmed ORR by BICR was 29.8% (95% CI, 23.9 to 36.2); median duration of response, 6.4 months; median progression-free survival, 5.5 months; and median overall survival, 11.9 months. The subgroup of patients with previous osimertinib and PBC had similar outcomes. Efficacy was observed across a broad range of pretreatment tumor HER3 membrane expression levels and across diverse mechanisms of EGFR TKI resistance. In patients with nonirradiated brain metastases at baseline (n = 30), the confirmed CNS ORR by BICR per CNS RECIST was 33.3% (95% CI, 17.3 to 52.8). The safety profile (National Cancer Institute Common Terminology Criteria for Adverse Events v5.0) was manageable and tolerable, consistent with previous observations.\n\nConclusion: After tumor progression with EGFR TKI therapy and PBC in patients with EGFR -mutated NSCLC, HER3-DXd once every 3 weeks demonstrated clinically meaningful efficacy with durable responses, including in CNS metastases. A phase III trial in EGFR- mutated NSCLC after progression on an EGFR TKI is ongoing (HERTHENA-Lung02; ClinicalTrials.gov identifier: NCT05338970).\n\nIndexed on Europe PMC as PubMed record 37689979 (DOI 10.1200/jco.23.01476). Its abstract cites the registry id NCT04619004, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Clinical Oncology", year: 2023, doi: "10.1200/jco.23.01476", pmid: "37689979", authors: "Yu HA, Goto Y, Hayashi H, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04619004 with the most citations, so it is the natural first reading for anyone following the HERTHENA-Lung01 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","The abstract cites more than one registry id (NCT04619004, NCT05338970); it was kept because the trial's acronym appears in the title."], links: [{"label":"J Clin Oncol 2023","url":"https://doi.org/10.1200/jco.23.01476"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37689979/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37689979"},{"label":"ClinicalTrials.gov NCT04619004","url":"https://clinicaltrials.gov/study/NCT04619004"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc"], drugs: ["patritumab-deruxtecan"], targets: [], technologies: [], trials: ["nct04619004"], journals: ["jco"] }),
  p({ id: "paper-nct04665856-j-thorac-oncol-2026", name: "SKYSCRAPER-02C: A Phase 3, Randomized, Double-Blind, Placebo-Controlled Study of Atezolizumab Plus Carboplatin and Etoposide With or Without Tiragolumab in Patients With Untreated Extensive-Stage SCLC in China", tldr: "Published report from the SKYSCRAPER-02C trial registered as NCT04665856, in Journal of Thoracic Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Tiragolumab may synergize with other immunotherapies to enhance antitumor immune responses. We report efficacy, safety, and biomarker findings from SKYSCRAPER-02C (NCT04665856), comparing tiragolumab plus atezolizumab plus carboplatin and etoposide (CE; experimental arm) with atezolizumab plus CE (control arm) in patients with untreated extensive-stage SCLC (ES-SCLC) in China.\n\nMethods: Patients were randomized (1:1) to tiragolumab 600 mg or placebo, plus atezolizumab 1200 mg and CE (four cycles), then maintenance tiragolumab or placebo plus atezolizumab. Primary end points were investigator-assessed progression-free survival (PFS) and overall survival (OS) in patients without history or presence of brain metastases at baseline (primary analysis set).\n\nResults: The primary analysis set comprised 54 patients in the experimental arm and 56 in the control arm. Median PFS was 5.6 months (experimental) and 5.4 months (control; unstratified hazard ratio = 0.65, 95% confidence interval: 0.43‒0.97; median follow-up 26.7 months); median OS was 18.7 and 13.5 months, respectively (unstratified hazard ratio 0.89, 95% confidence interval: 0.56‒1.40). The biomarker-evaluable population comprised 69 patients with immunohistochemistry data and 66 with RNA sequencing data. RNA sequencing survival analysis found that patients with non-negative matrix factorization 3 (SCLC-inflamed-neuroendocrine) or non-negative matrix factorization 4 (SCLC-inflamed-non-neuroendocrine) molecular subtypes, and those with high T-effector and tumor-associated macrophage immune signatures, benefited from tiragolumab plus atezolizumab plus CE treatment. Tiragolumab was well tolerated, with no new safety signals.\n\nConclusions: Although results from the global SKYSCRAPER-02 study were not statistically significant, numerical improvements in PFS and OS were observed with tiragolumab plus atezolizumab plus CE versus atezolizumab plus CE in Chinese patients with ES-SCLC. Biomarker analysis identified immune-inflamed signatures that may guide future tyrosine-based inhibitory motif domain-based strategies.\n\nIndexed on Europe PMC as PubMed record 41950998 (DOI 10.1016/j.jtho.2026.103713). Its abstract cites the registry id NCT04665856, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2026, doi: "10.1016/j.jtho.2026.103713", pmid: "41950998", authors: "Lu S, Fang J, Yu Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04665856 with the most citations, so it is the natural first reading for anyone following the SKYSCRAPER-02C trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2026","url":"https://doi.org/10.1016/j.jtho.2026.103713"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41950998/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41950998"},{"label":"ClinicalTrials.gov NCT04665856","url":"https://clinicaltrials.gov/study/NCT04665856"}], tags: ["europepmc-ingest"], cancers: ["sclc","extensive-stage-sclc"], drugs: ["tiragolumab","atezolizumab","carboplatin","etoposide"], targets: [], technologies: [], trials: ["nct04665856"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct04687241-lancet-oncol-2026", name: "Aumolertinib as adjuvant therapy in resected EGFR-mutated non-small-cell lung cancer (ARTS): a double-blind, multicentre, randomised, controlled, phase 3 trial", tldr: "Published report from the trial registered as NCT04687241, in The Lancet Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Patients with resectable non-small-cell lung cancer (NSCLC), particularly those with EGFR mutations, face a high risk of recurrence and mortality post-surgery. Aumolertinib, a third-generation EGFR tyrosine-kinase inhibitor, is approved in China for adjuvant treatment in patients with NSCLC harbouring EGFR with an exon 19 deletion (ex19del) or exon 21 substitution (Leu858Arg) mutation. The ARTS study aimed to evaluate the efficacy and safety of adjuvant therapy with aumolertinib in patients with stage II-IIIB EGFR-mutated NSCLC.\n\nMethods: This double-blind, multicentre, randomised, controlled, phase 3 trial enrolled patients from 48 hospitals in mainland China. Eligible patients were 18 years or older with stage II-IIIB NSCLC, had undergone a complete resection followed by standard adjuvant therapy, and had an EGFR ex19del or Leu858Arg mutation and an Eastern Cooperative Oncology Group performance status score of 0 or 1. Patients were stratified by EGFR mutation status and tumour stage and were randomly assigned (1:1) to receive aumolertinib 110 mg or placebo orally, once daily for 3 years or until disease recurrence or other discontinuation criteria were met. Patients were randomly allocated to groups using an interactive web response system; the double‑dummy technique masked patients, investigators, and assessors. The primary endpoint was disease-free survival in the modified intention-to treat (mITT) population (ie, all patients with stage II-IIIB NSCLC harbouring EGFR mutations who had undergone complete tumour resection and standard adjuvant therapy), assessed by blinded independent central review (BICR). Safety was assessed in all patients who received at least one dose of study treatment. Although the study is ongoing, with some patients remaining in follow-up, this analysis represents the protocol-specified primary analysis. This study is registered with ClinicalTrials.gov (NCT04687241).\n\nFindings: Between April 30, 2021, and May 17, 2022, 399 individuals were screened for study eligibility; of these, 214 patients were randomly assigned to receive aumolertinib or placebo (107 in each group). 120 (56%) patients were female, 94 (44%) were male, median age was 59 years (IQR 54-66), and all patients were Chinese. 204 (95%) of 214 patients had received prior adjuvant chemotherapy. One patient in the aumolertinib group and three patients in the placebo group had stage I disease; therefore, 106 patients in the aumolertinib group and 104 in the placebo group were included in the mITT (primary analysis) population. at the data cutoff date (April 15, 2024), the median duration of follow-up was 27·56 months (IQR 22·18-27·70) in the aumolertinib group and 27·63 months (22·18-27·79) in the placebo group. The BICR-assessed disease-free survival was significantly improved in the aumolertinib group compared with the placebo group, with an HR of 0·17 (95% CI 0·09-0·29, p<0·0001). The median disease-free survival per BICR in the aumolertinib group was not reached (95% CI 29·14 to not applicable), whereas it was 19·42 months (11·24-26·22) in the placebo group. The most common grade 3-4 adverse events in the aumolertinib group versus the placebo group were increased blood creatine phosphokinase (seven [7%] vs none), prolonged electrocardiogram QT interval (three [3%] vs three [3%]), hypertension (one [1%] vs five [5%]), and pneumonia (two [2%] vs three [3%]). Treatment-related serious adverse events occurred in one (1%) patient receiving aumolertinib and three (3%) patients receiving placebo. No treatment-related deaths occurred and no new safety signals were identified for aumolertinib.\n\nInterpretation: Aumolertinib showed substantial clinical benefits as adjuvant therapy in Chinese patients with stage II-IIIB EGFR-mutated NSCLC. The manageable safety profile of aumolertinib supports its suitability in the adjuvant setting.\n\nFunding: Hansoh Pharmaceutical Group.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 41539318 (DOI 10.1016/s1470-2045(25)00643-6). Its abstract cites the registry id NCT04687241, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2026, doi: "10.1016/s1470-2045(25)00643-6", pmid: "41539318", authors: "Zhang L, Zhang X, Wu L, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04687241 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2026","url":"https://doi.org/10.1016/s1470-2045(25)00643-6"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41539318/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41539318"},{"label":"ClinicalTrials.gov NCT04687241","url":"https://clinicaltrials.gov/study/NCT04687241"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc","resectable-nsclc"], drugs: ["aumolertinib"], targets: [], technologies: [], trials: ["nct04687241"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct04765059-esmo-open-2025", name: "COMPEL: osimertinib plus platinum-based chemotherapy in patients with EGFR-mutated advanced NSCLC and progression on first-line osimertinib", tldr: "Published report from the COMPEL trial registered as NCT04765059, in ESMO Open (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: COMPEL (NCT04765059) was a global, randomized, double-blind study that evaluated osimertinib plus chemotherapy versus placebo plus chemotherapy in patients with epidermal growth factor receptor (EGFR)-mutated advanced non-small-cell lung cancer (NSCLC) following non-central nervous system (CNS) progression on first-line osimertinib.\n\nPatients and methods: Patients were randomly assigned to receive osimertinib 80 mg, or placebo, once daily (o.d.) in combination with chemotherapy [cisplatin 75 mg/m 2 or carboplatin area under the curve 5 plus pemetrexed 500 mg/m 2 every 3 weeks (q3w) for four cycles], followed by osimertinib 80 mg, or placebo, o.d. in combination with maintenance pemetrexed (500 mg/m 2 q3w) until progression. The primary endpoint was investigator-assessed progression-free survival (PFS). Secondary endpoints included CNS PFS according to CNS metastases status at baseline and overall survival (OS).\n\nResults: Ninety-eight patients were randomly assigned (49 per arm). Median PFS in all patients was 8.4 months [95% confidence interval (CI) 5.7-11.8 months] with osimertinib plus chemotherapy versus 4.4 months (95% CI 3.5-5.6 months) with placebo plus chemotherapy [hazard ratio (HR) 0.43, 95% CI 0.27-0.70]. CNS PFS was longer with osimertinib plus chemotherapy versus placebo plus chemotherapy (HR 0.56, 95% CI 0.27-1.13) in patients without baseline CNS metastases (n = 75). Median OS in all patients was 15.9 months (95% CI 12.4-20.8 months) with osimertinib plus chemotherapy versus 9.8 months (95% CI 8.4-17.2 months) with placebo plus chemotherapy (HR 0.71, 95% CI 0.42-1.23). Grade ≥3 adverse events occurred more frequently with osimertinib plus chemotherapy (63%) than placebo plus chemotherapy (46%).\n\nConclusions: In patients with non-CNS progression on first-line osimertinib, osimertinib plus chemotherapy was associated with improved PFS and longer OS compared with placebo plus chemotherapy. These findings support osimertinib as a backbone treatment for EGFR-mutated advanced NSCLC through lines of therapy.\n\nIndexed on Europe PMC as PubMed record 41139117 (DOI 10.1016/j.esmoop.2025.105807). Its abstract cites the registry id NCT04765059, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "ESMO Open", year: 2025, doi: "10.1016/j.esmoop.2025.105807", pmid: "41139117", authors: "Peled N, Tufman A, Sequist LV, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04765059 with the most citations, so it is the natural first reading for anyone following the COMPEL trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"ESMO Open 2025","url":"https://doi.org/10.1016/j.esmoop.2025.105807"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41139117/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41139117"},{"label":"ClinicalTrials.gov NCT04765059","url":"https://clinicaltrials.gov/study/NCT04765059"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["osimertinib"], targets: [], technologies: [], trials: ["nct04765059"], journals: ["esmo-open"] }),
  p({ id: "paper-nct04819100-n-engl-j-med-2026", name: "Selpercatinib in Early-Stage RET Fusion-Positive Non-Small-Cell Lung Cancer", tldr: "Published report from the LIBRETTO-432 trial registered as NCT04819100, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Selpercatinib, a highly selective, potent, and central nervous system-penetrant RET inhibitor, is approved for RET fusion-positive advanced or metastatic non-small-cell lung cancer (NSCLC). The efficacy and safety of selpercatinib in early-stage NSCLC are unknown.\n\nMethods: We conducted a phase 3, double-blind trial involving patients with RET fusion-positive NSCLC who had received definitive therapy with curative intent (surgery or radiotherapy with adjuvant systemic anticancer therapy, if applicable). Patients were randomly assigned to receive adjuvant selpercatinib or placebo for up to 3 years. The primary end point was investigator-assessed event-free survival in patients with stage II or IIIA disease. Secondary end points were investigator-assessed event-free survival in patients with stage IB, II, or IIIA disease; event-free survival as assessed by blinded independent central review; overall survival; and safety.\n\nResults: A total of 151 patients were assigned to receive selpercatinib (75 patients) or placebo (76 patients). Median follow-up was 24 months and 27 months in the respective groups. Among 109 patients with stage II or IIIA disease, 2-year investigator-assessed event-free survival was 92% with selpercatinib and 61% with placebo (hazard ratio for disease recurrence, progression, or death, 0.17; 95% confidence interval [CI], 0.06 to 0.51; P<0.001). Event-free survival as assessed by blinded independent central review was consistent with investigator-assessed event-free survival. Among the 151 patients with stage IB, II, or IIIA NSCLC, investigator-assessed event-free survival at 2 years was 94% with selpercatinib and 70% with placebo (hazard ratio for disease recurrence, progression, or death, 0.16; 95% CI, 0.06 to 0.48; P<0.001). The most common adverse events during the treatment period were increased levels of alanine aminotransferase and aspartate aminotransferase (grade ≥3 in 17% and 19% of patients, respectively, in the selpercatinib group). Three deaths occurred, all in the placebo group, owing to disease progression.\n\nConclusions: Among patients with stage II or IIIA RET fusion-positive NSCLC, event-free survival was significantly longer with adjuvant selpercatinib than with placebo. (Funded by Lilly; LIBRETTO-432 ClinicalTrials.gov number, NCT04819100.).\n\nIndexed on Europe PMC as PubMed record 42223087 (DOI 10.1056/nejmoa2602628). Its abstract cites the registry id NCT04819100, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2602628", pmid: "42223087", authors: "Wu YL, Hochmair M, Yang Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04819100 with the most citations, so it is the natural first reading for anyone following the LIBRETTO-432 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2602628"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42223087/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42223087"},{"label":"ClinicalTrials.gov NCT04819100","url":"https://clinicaltrials.gov/study/NCT04819100"}], tags: ["europepmc-ingest"], cancers: ["nsclc","resectable-nsclc","ret-fusion-nsclc"], drugs: ["selpercatinib"], targets: [], technologies: [], trials: ["nct04819100"], journals: ["nejm"] }),
  p({ id: "paper-nct04923906-lancet-oncol-2026", name: "Aumolertinib with or without chemotherapy in EGFR-mutated advanced non-small-cell lung cancer (AENEAS2): an open-label, multicentre, randomised, controlled, phase 3 trial", tldr: "Published report from the trial registered as NCT04923906, in The Lancet Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Although third-generation epidermal growth-factor receptor (EGFR)-tyrosine-kinase inhibitors (TKIs) are standard first-line therapies for patients with advanced EGFR-mutated non-small-cell lung cancer (NSCLC), their effectiveness is often limited by the emergence of drug resistance and subsequent disease progression. Given the previously established clinical efficacy and adverse event profile of aumolertinib, we aimed to evaluate the efficacy and adverse event profile of aumolertinib in combination with platinum-based chemotherapy versus aumolertinib monotherapy as first-line treatment for patients with locally advanced or metastatic NSCLC patients with EGFR-sensitive mutations.\n\nMethods: The open-label, multicentre, randomised, controlled, phase 3 AENEAS2 trial was done across 60 hospitals in China. Patients aged at least 18 years with Eastern Cooperative Oncology Group performance status (ECOG PS) 0-1; treatment-naive; histologically or cytologically confirmed locally advanced or metastatic NSCLC harbouring EGFR-sensitive mutations (ex19del/L858R with or without other EGFR mutations) were eligible. Brain metastases were allowed if neurologically stable. Previous EGFR-TKI therapy was an exclusion criterion. Patients were randomly assigned (1:1) with block randomisation (block size of 6), stratified by EGFR mutation type and baseline brain metastasis, to receive aumolertinib monotherapy (110 mg orally once a day) or combination therapy (aumolertinib 110 mg orally once a day plus pemetrexed 500 mg/m 2 intravenously with cisplatin [75 mg/m 2 ] or carboplatin [area under the plasma concentration-time curve 5] intravenously on day 1 of 21-day cycles for 4-6 cycles), followed by maintenance therapy (aumolertinib 110 mg orally once a day and pemetrexed 500 mg/m 2 intravenously once every 3 weeks). The primary endpoint was progression-free survival assessed by blinded independent central review (BICR; RECIST version 1.1). Efficacy was analysed in the full-analysis set, which included all randomly assigned patients, and safety was analysed in patients who received at least one dose of the actual trial treatment. The trial is registered at ClinicalTrials.gov, NCT04923906, and is ongoing, but closed to enrolment.\n\nFindings: Between Aug 4, 2021, to June 18, 2024, of 1011 patients assessed for eligibility, 624 randomly assigned patients (median age 59·0 years [IQR 52·0-66·0]; 337 [54%] were female, 287 [46%] were male) were randomly assigned. 310 (50%) patients received combination therapy and 314 (50%) received monotherapy. at the data cutoff date (June 18, 2024), the median follow-up was 23·4 months (IQR 20·5-26·5), In the full-analysis set, median BICR-assessed progression-free survival was 28·9 months (95% CI 26.3, NA) in the combination therapy versus 18·9 months (17·8-21·1) in the monotherapy (hazard ratio [HR] 0·47, 95% CI 0·37-0·60; log-rank p<0·0001). The most common grade 3-4 adverse events (occurring in at least 20% in any group) were neutrophil count decreased (168 [55%] of 304 in the combination group versus four [1%] of 316 in monotherapy group), white blood cell count decreased (103 [34%] vs one [<1%]), and platelet count decreased (62 [20%] vs two [1%]). Serious adverse events occurred in 109 (36%) patients in the combination group and 53 (17%) in the monotherapy group, the most common of which were platelet count decreased (22 [7%] vs 0), neutrophil count decreased (17 [6%] vs 0), white blood cell count decreased (13 [4%] vs 0), and anaemia (ten [3%] vs two [1%]). Treatment-related deaths occurred in one (<1%) patient in the combination group (encephalopathy) and two (1%) in the monotherapy group (pulmonary embolism and respiratory failure with circulatory collapse).\n\nInterpretation: Aumolertinib in combination with chemotherapy significantly improved progression-free survival. Although this regimen was associated with increased toxicity, the side-effects were managed with dose adjustment and supportive treatment aligned with clinical practice. Long-term follow-up is required to assess overall survival. The AENEAS2 study provides evidence to guide clinical practice regarding EGFR-TKIs and their combination use in treating patients with advanced EGFR-mutated NSCLC.\n\nFunding: Jiangsu Hansoh Pharmaceutical Group, and the Collaborative Innovation Center for Clinical and Translational Science by Ministry of Education & Shanghai.\n\nTranslations: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 42296979 (DOI 10.1016/s1470-2045(26)00090-2). Its abstract cites the registry id NCT04923906, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2026, doi: "10.1016/s1470-2045(26)00090-2", pmid: "42296979", authors: "Li Z, Hu J, Chen J, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04923906 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2026","url":"https://doi.org/10.1016/s1470-2045(26)00090-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42296979/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42296979"},{"label":"ClinicalTrials.gov NCT04923906","url":"https://clinicaltrials.gov/study/NCT04923906"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc"], drugs: ["aumolertinib"], targets: [], technologies: [], trials: ["nct04923906"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct04956640-nat-commun-2026", name: "Pan-tumor activity of olomorasib, a next-generation KRAS G12C inhibitor in KRAS G12C-mutant advanced solid tumors: a first-in-human study", tldr: "Published report from the trial registered as NCT04956640, in Nature Communications (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "This multicenter, first-in-human Phase 1 study (NCT04956640) evaluated olomorasib (LY3537982), a next-generation KRAS G12C inhibitor designed to enhance target occupancy at low absolute exposures. In total, data from 195 patients are reported: Phase 1a dose escalation (n = 112) assessed olomorasib monotherapy at 50, 100, 150 or 200 mg BID across KRAS G12C-mutant advanced solid tumors; the primary objective was to determine the recommended Phase 2 dose (RP2D) based on dose-limiting toxicities (DLTs). No DLTs occurred, and 150 mg BID was selected as the RP2D. The primary objective for the Phase 1b dose expansion (n = 83) was to evaluate the safety and tolerability of olomorasib in specific KRAS G12C-mutant tumor types. Olomorasib was well tolerated, with predominantly grade 1-2 treatment-related adverse events (TRAEs) and infrequent grade 3 TRAEs; no grade 4/5 TRAEs occurred. Secondary objectives evaluated the antitumor activity of olomorasib. Among 168 efficacy-evaluable patients, the ORR and median PFS were both higher in non-CRC solid tumors compared to CRC, including in patients with NSCLC who previously received a KRAS G12C inhibitor. Intracranial responses were observed in patients with untreated, active brain metastases. This may support the potential of next-generation KRAS G12C inhibitors to overcome limitations of earlier agents and justify further investigation of combination therapy.\n\nIndexed on Europe PMC as PubMed record 41820335 (DOI 10.1038/s41467-026-69943-7). Its abstract cites the registry id NCT04956640, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Communications", year: 2026, doi: "10.1038/s41467-026-69943-7", pmid: "41820335", authors: "Murciano-Goroff YR, Hollebecque A, Heist RS, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04956640 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Commun 2026","url":"https://doi.org/10.1038/s41467-026-69943-7"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41820335/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41820335"},{"label":"ClinicalTrials.gov NCT04956640","url":"https://clinicaltrials.gov/study/NCT04956640"}], tags: ["europepmc-ingest"], cancers: ["nsclc","colorectal","endometrial","ovarian","pancreatic","cholangiocarcinoma","kras-g12c-colorectal","kras-g12c-nsclc","kras-g12c-pdac"], drugs: ["olomorasib","pembrolizumab","cetuximab","pemetrexed","cisplatin","carboplatin"], targets: [], technologies: [], trials: ["nct04956640"], journals: ["nature-communications"] }),
  p({ id: "paper-nct05009329-nat-med-2025", name: "Glecirasib in KRAS G12C -mutated nonsmall-cell lung cancer: a phase 2b trial", tldr: "Published report from the trial registered as NCT05009329, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Glecirasib (JAB-21822) is a new covalent oral KRAS-G12C inhibitor. This multicenter, single-arm phase 2b study assessed the efficacy and safety of glecirasib administered orally at 800 mg daily in patients with locally advanced or metastatic KRAS G12C -mutated nonsmall-cell lung cancer. The primary endpoint was the objective response rate (ORR) assessed by an independent review committee (IRC). Between 15 September 2022 and 28 September 2023, 119 patients with a median age of 62 years were enrolled. at the data cut-off date on 28 March 2024, the ORR assessed by IRC was 47.9% (56/117; 95% confidence interval: 38.5-57.3%). The incidence of treatment-related adverse events (TRAEs) of any grade was 97.5% (116/119). The incidence of grades 3 and 4 TRAEs was 38.7% (46/119). A total of 5.0% (6/119) of patients discontinued the treatment due to TRAEs. No treatment-related deaths occurred. Glecirasib exhibited promising clinical efficacy and manageable safety profiles in these patient populations. ClinicalTrials.gov identifier: NCT05009329.\n\nIndexed on Europe PMC as PubMed record 39762419 (DOI 10.1038/s41591-024-03401-z). Its abstract cites the registry id NCT05009329, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-024-03401-z", pmid: "39762419", authors: "Shi Y, Fang J, Xing L, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05009329 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-024-03401-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39762419/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39762419"},{"label":"ClinicalTrials.gov NCT05009329","url":"https://clinicaltrials.gov/study/NCT05009329"}], tags: ["europepmc-ingest"], cancers: ["nsclc","kras-g12c-nsclc"], drugs: ["glecirasib"], targets: [], technologies: [], trials: ["nct05009329"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05081609-j-immunother-cancer-2022", name: "TransCon IL-2 β/γ: a novel long-acting prodrug with sustained release of an IL-2Rβ/γ-selective IL-2 variant with improved pharmacokinetics and potent activation of cytotoxic immune cells for the treatment of cancer", tldr: "Published report from the trial registered as NCT05081609, in Journal for ImmunoTherapy of Cancer (2022), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Recombinant interleukin-2 (IL-2, aldesleukin) is an approved cancer immunotherapy but causes severe toxicities including cytokine storm and vascular leak syndrome (VLS). IL-2 promotes antitumor function of IL-2Rβ/γ + natural killer (NK) cells and CD8 +, CD4 + and gamma delta (γδ) T cells. However, IL-2 also potently activates immunosuppressive IL-2Rα + regulatory T cells (Tregs) and IL-2Rα + eosinophils and endothelial cells, which may promote VLS. Aldesleukin is rapidly cleared requiring frequent dosing, resulting in high C max likely potentiating toxicity. Thus, IL-2 cancer immunotherapy has two critical drawbacks: potent activation of undesired IL-2Rα + cells and suboptimal pharmacokinetics with high C max and short half-life.\n\nMethods: TransCon IL-2 β/γ was designed to optimally address these drawbacks. To abolish IL-2Rα binding yet retain strong IL-2Rβ/γ activity, IL-2 β/γ was created by permanently attaching a small methoxy polyethylene glycol (mPEG) moiety in the IL-2Rα binding site. To improve pharmacokinetics, IL-2 β/γ was transiently attached to a 40 kDa mPEG carrier via a TransCon (transient conjugation) linker creating a prodrug, TransCon IL-2 β/γ, with sustained release of IL-2 β/γ. IL-2 β/γ was characterized in binding and primary cell assays while TransCon IL-2 β/γ was studied in tumor-bearing mice and cynomolgus monkeys.\n\nResults: IL-2 β/γ demonstrated selective and potent human IL-2Rβ/γ binding and activation without IL-2Rα interactions. TransCon IL-2 β/γ showed slow-release pharmacokinetics with a low C max and a long (>30 hours) effective half-life for IL-2 β/γ in monkeys. In mouse tumor models, TransCon IL-2 β/γ promoted CD8 + T cell and NK cell activation and antitumor activity. In monkeys, TransCon IL-2 β/γ induced robust activation and expansion of CD8 + T cells, NK cells and γδ T cells, relative to CD4 + T cells, Tregs and eosinophils, with no evidence of cytokine storm or VLS. Similarly, IL-2 β/γ enhanced proliferation and cytotoxicity of primary human CD8 + T cells, NK cells and γδ T cells.\n\nSummary: TransCon IL-2 β/γ is a novel long-acting prodrug with sustained release of an IL-2Rβ/γ-selective IL-2. It has remarkable and durable pharmacodynamic effects in monkeys and potential for improved clinical efficacy and tolerability compared with aldesleukin. TransCon IL-2 β/γ is currently being evaluated in a Phase 1/2 clinical trial (NCT05081609).\n\nIndexed on Europe PMC as PubMed record 35817480 (DOI 10.1136/jitc-2022-004991). Its abstract cites the registry id NCT05081609, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal for ImmunoTherapy of Cancer", year: 2022, doi: "10.1136/jitc-2022-004991", pmid: "35817480", authors: "Rosen DB, Kvarnhammar AM, Laufer B, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05081609 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Immunother Cancer 2022","url":"https://doi.org/10.1136/jitc-2022-004991"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/35817480/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/35817480"},{"label":"ClinicalTrials.gov NCT05081609","url":"https://clinicaltrials.gov/study/NCT05081609"}], tags: ["europepmc-ingest"], cancers: ["ovarian","melanoma","cervical","nsclc","sclc"], drugs: ["pembrolizumab","trastuzumab","trastuzumab-emtansine"], targets: [], technologies: [], trials: ["nct05081609"], journals: ["jitc"] }),
  p({ id: "paper-nct05128487-cell-rep-med-2026", name: "HPK1 inhibitor NDI-101150 as monotherapy and in combination with pembrolizumab in patients with advanced solid tumors: Phase 1/2 trial results", tldr: "Published report from the trial registered as NCT05128487, in Cell reports. Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Hematopoietic progenitor kinase 1 (HPK1) induces potent anti-tumor immunity in preclinical models by activating and recruiting T cells, B cells, and dendritic cells into the tumor microenvironment (TME). Here, we evaluate NDI-101150, a potent, selective HPK1 inhibitor, in a phase 1/2 trial as a monotherapy or in combination with pembrolizumab in patients with advanced solid tumors. The monotherapy maximum tolerated dose (MTD) is 150 mg once daily, and doses tested up to 100 mg once daily are combinable with pembrolizumab without reaching an MTD. In clear cell renal cell carcinoma, the investigator-assessed overall response rate with monotherapy treatment is 13.6%, including one complete response and two partial responses, with a clinical benefit rate of 27.3% and a disease control rate of 54.5%. Pharmacodynamic analyses show pharmacodynamic biomarker phospho-SLP76 inhibition and increased activated CD8 + T cells and dendritic cells in the TME, supporting continued development (clinical registration number NCT05128487).\n\nIndexed on Europe PMC as PubMed record 42097144 (DOI 10.1016/j.xcrm.2026.102789). Its abstract cites the registry id NCT05128487, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Cell reports. Medicine", year: 2026, doi: "10.1016/j.xcrm.2026.102789", pmid: "42097144", authors: "Braun DA, Noel MS, Moy RH, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05128487 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Cell Rep Med 2026","url":"https://doi.org/10.1016/j.xcrm.2026.102789"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42097144/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42097144"},{"label":"ClinicalTrials.gov NCT05128487","url":"https://clinicaltrials.gov/study/NCT05128487"}], tags: ["europepmc-ingest"], cancers: ["rcc","nsclc","sclc"], drugs: ["pembrolizumab"], targets: [], technologies: [], trials: ["nct05128487"] }),
  p({ id: "paper-nct05186974-j-thorac-oncol-2026", name: "First-Line Sacituzumab Govitecan Plus Pembrolizumab in Metastatic NSCLC: PD-L1 TPS Less Than 50% and More Than or Equal to 50% Cohorts of the EVOKE-02 Study", tldr: "Published report from the EVOKE-02 trial registered as NCT05186974, in Journal of Thoracic Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Sacituzumab govitecan (SG) is a Trop-2-directed antibody-drug conjugate previously studied in patients with pretreated metastatic NSCLC (mNSCLC). Here, we report the results of EVOKE-02 (NCT05186974), a global, open-label, multicohort phase 2 study of SG plus pembrolizumab as first-line treatment in patients with mNSCLC.\n\nMethods: Adult patients without prior systemic mNSCLC treatment, and no actionable genomic alterations, received SG 10 mg/kg intravenously on days 1 and 8 plus pembrolizumab 200 mg intravenously on day 1 of 21-day cycles. The primary end point was objective response rate (ORR) per independent review committee, and secondary end points included progression-free survival (PFS) and safety.\n\nResults: at data cutoff (June 3, 2024), there were 30 patients with programmed death-ligand 1 (PD-L1) tumor proportion score (TPS) more than or equal to 50% (cohort A) and 62 patients with PD-L1 TPS less than 50% (cohort B). ORR (95% confidence interval) was 66.7% (47.2-82.7) for cohort A and 29.0% (18.2-41.9) for cohort B. Median (95% confidence interval) PFS was 13.1 (6.7-not reached) months for cohort A and 7.0 (4.2-12.9) months for cohort B. Trop-2 expression did not correlate with greater clinical efficacy (PFS, ORR) from treatment with SG plus pembrolizumab. Grade 3 or greater treatment-emergent adverse events (TEAEs) occurred in 70 patients (76.1%); the most common TEAE was neutropenia (17.4%). TEAEs leading to discontinuation of any study drug occurred in 25 patients (27.2%).\n\nConclusions: SG plus pembrolizumab demonstrated activity as treatment for mNSCLC, especially in patients with PD-L1 TPS more than or equal to 50%. AEs were manageable and consistent with the known safety profile of each individual agent.\n\nIndexed on Europe PMC as PubMed record 41173143 (DOI 10.1016/j.jtho.2025.10.016). Its abstract cites the registry id NCT05186974, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2026, doi: "10.1016/j.jtho.2025.10.016", pmid: "41173143", authors: "Reck M, Patel JD, Gray JE, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05186974 with the most citations, so it is the natural first reading for anyone following the EVOKE-02 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2026","url":"https://doi.org/10.1016/j.jtho.2025.10.016"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41173143/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41173143"},{"label":"ClinicalTrials.gov NCT05186974","url":"https://clinicaltrials.gov/study/NCT05186974"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["sacituzumab-govitecan","pembrolizumab","carboplatin","cisplatin"], targets: [], technologies: [], trials: ["nct05186974"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct05195632-lung-cancer-2026", name: "A phase 2 study of encorafenib in combination with binimetinib for Chinese participants with BRAF V600E mutated metastatic non-small cell lung cancer: Results from the OCEAN II study", tldr: "Published report from the OCEANII trial registered as NCT05195632, in Lung cancer (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: The ongoing OCEAN II study (ClinicalTrials.gov identifier: NCT05195632) evaluates encorafenib in combination with binimetinib (E+B) in Chinese participants with BRAF V600E -mutated metastatic non-small cell lung cancer (NSCLC).\n\nMethods: Participants with metastatic unresectable stage IV BRAF V600E -mutated NSCLC (treatment-naïve or with prior systemic therapy excluding BRAF/MEK-inhibitors), were enrolled in a phase 2 study with two parts: safety lead-in (SLI) and pivotal part (PP). Participants received daily oral encorafenib (450mg) and twice daily oral binimetinib (90mg total). Primary endpoints were dose-limiting toxicities (DLT) during SLI and confirmed objective response rate by independent central review (cORR-ICR) during PP. Secondary endpoints were other measures of efficacy, safety, and pharmacokinetics.\n\nResults: In total, 63 participants were enrolled. One DLT (non-serious Grade 3 lipase increased) during SLI considered possibly related to E+B resolved without intervention, supporting initiation of PP. Pre-defined statistical efficacy criteria on the first 50 participants were met. In the main analysis, cORR-ICRwas59% (95%CI 45-72). At a later ad hoc analysis, cORR-ICR was 61% (95%CI 47-74), disease control rate 87% (95%CI 75-95). Medians (95%CI) were, time-to-response 1.8 months, duration of response 17.5 months, progression-free survival 13.8 months (7.5-not estimable), overall survival 27.9 months (14.7-30.0). 98.4% of participants experienced ≥1 treatment-related TEAE, and 55.6% had any Grade ≥3 TEAE. Nine (14.3%) participants discontinued any drug due to adverse events.\n\nConclusion: These data confirm the clinical benefit of E+B in Chinese participants with BRAF V600E -mNSCLC, a population with distinct genomic and disease characteristics. No new safety concerns were identified in Chinese participants.\n\nIndexed on Europe PMC as PubMed record 42612509 (DOI 10.1016/j.lungcan.2026.109580). Its abstract cites the registry id NCT05195632, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Lung cancer", year: 2026, doi: "10.1016/j.lungcan.2026.109580", pmid: "42612509", authors: "Zhou H, Zhou Q, Guo Q, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05195632 with the most citations, so it is the natural first reading for anyone following the OCEANII trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lung Cancer 2026","url":"https://doi.org/10.1016/j.lungcan.2026.109580"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42612509/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42612509"},{"label":"ClinicalTrials.gov NCT05195632","url":"https://clinicaltrials.gov/study/NCT05195632"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","braf-v600e-nsclc"], drugs: ["encorafenib","binimetinib"], targets: [], technologies: [], trials: ["nct05195632"], journals: ["lung-cancer-journal"] }),
  p({ id: "paper-nct05199272-cancer-res-commun-2025", name: "First-in-Human Study of 23ME-00610, an Antagonistic Antibody for Genetically Validated CD200R1 Immune Checkpoint, in Participants with Advanced Solid Malignancies", tldr: "Published report from the trial registered as NCT05199272, in Cancer research communications (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: In this phase 1 portion of a first-in-human phase 1/2a study (NCT05199272), 23ME-00610 was evaluated in participants with advanced solid malignancies to determine its safety, tolerability, pharmacokinetics (PK), and pharmacodynamics (PD). Exploratory biomarkers were evaluated to examine potential correlates of efficacy and safety.\n\nPatients and methods: Eligible participants (≥18 years) were administered 23ME-00610 intravenously every 3 weeks (Q3W) using an accelerated titration design followed by a traditional 3 + 3 design, with an initial dose level of 2 mg.\n\nResults: Twenty-eight participants were enrolled across seven cohorts and received a median of four cycles of 23ME-00610. No treatment-related serious adverse events (AE) were observed, and the maximum tolerated dose was not reached. Overall, the PK of 23ME-00610 was linear and dose proportional for doses ≥60 mg, with a median terminal half-life of 13 days at 1,400 mg. Peripheral saturation of CD200R1 was observed for doses ≥60 mg. Immune-related AEs, including rash, pruritus, and hypothyroidism, were predicted by phenome-wide association studies and observed for doses ≥60 mg. A confirmed partial response was observed in a participant with well-differentiated pancreatic neuroendocrine cancer whose tumor was among those with the highest tumor CD200 expression.\n\nConclusions: 23ME-00610 has mild-to-moderate on-target AEs and PK/PD consistent with tumor target saturation and dosing every 3 weeks. The trend for clinical benefit in participants with tumor CD200 expression suggests that 23ME-00610 inhibits CD200R1 signaling and may reverse CD200-mediated immune evasion. Based on PK/PD, safety, and preliminary antitumor activity, 1,400 mg Q3W was selected as the dose for further study.\n\nSignificance: Genome-wide association studies (GWAS) of the 23andMe genetic database identified CD200R1 as a promising therapeutic target for cancer. This phase 1 study of 23ME-00610, a CD200R1 antagonist IgG1, showed acceptable safety and tolerability, PK supporting Q3W dosing, and PD and preliminary clinical activity supporting an initial recommended phase 2 dose of 1,400 mg.\n\nIndexed on Europe PMC as PubMed record 39651931 (DOI 10.1158/2767-9764.crc-24-0568). Its abstract cites the registry id NCT05199272, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Cancer research communications", year: 2025, doi: "10.1158/2767-9764.crc-24-0568", pmid: "39651931", authors: "Kummar S, Razak AA, Laurie S, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05199272 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Cancer Res Commun 2025","url":"https://doi.org/10.1158/2767-9764.crc-24-0568"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39651931/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39651931"},{"label":"ClinicalTrials.gov NCT05199272","url":"https://clinicaltrials.gov/study/NCT05199272"}], tags: ["europepmc-ingest"], cancers: ["rcc","ovarian","neuroendocrine","sclc"], drugs: [], targets: [], technologies: [], trials: ["nct05199272"], journals: ["cancer-research-communications"] }),
  p({ id: "paper-nct05246514-clin-lung-cancer-2026", name: "Trastuzumab Deruxtecan in Patients From China With Pretreated HER2-Mutant Non-Small Cell Lung Cancer: Final Analysis of the Phase 2, Single-Arm DESTINY-Lung05 Trial", tldr: "Published report from the DESTINY-Lung05 trial registered as NCT05246514, in Clinical lung cancer (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Trastuzumab deruxtecan (T-DXd) was approved in China in October 2024 for previously treated human epidermal growth factor receptor 2 (HER2)-mutant (HER2m) unresectable/metastatic non-small cell lung cancer (NSCLC), based on DESTINY-Lung02 and DESTINY-Lung05 primary results. Here, we report the DESTINY-Lung05 final analysis.\n\nMethods: DESTINY-Lung05 (NCT05246514), an open-label, single-arm, multicenter, phase 2 study, investigated T-DXd (5.4 mg/kg once every 3 weeks) in patients from China with HER2m (locally or centrally confirmed activating HER2 exon 19/20 mutation) metastatic NSCLC with disease progression on/after ≥ 1 prior anticancer therapy. The primary endpoint was confirmed objective response rate (ORR) per Response Evaluation Criteria in Solid Tumors 1.1 by independent central review (ICR). Secondary endpoints included progression-free survival (PFS) by ICR, overall survival (OS), and safety.\n\nResults: at November 4, 2024, 72 patients with HER2m NSCLC had received T-DXd 5.4 mg/kg; the median duration of follow-up was 20.2 months (range, 2-27). Confirmed ORR (ICR) was 56.9% (95% confidence interval [CI] 44.7-68.6). Median PFS (ICR) and OS were 9.9 months (95% CI 7.1-16.5) and 21.0 months (95% CI 17.5-not calculable), respectively. Grade ≥ 3 drug-related adverse events occurred in 40 (55.6%) patients. Adjudicated drug-related interstitial lung disease/pneumonitis events were observed in 9 (12.5%) patients (n = 8 grade 1/2; n = 1 grade 3).\n\nConclusions: With extended follow-up, T-DXd continued to demonstrate clinically meaningful and durable antitumor activity in patients from China with pretreated HER2m metastatic NSCLC, with no new safety signals. Results affirm the use of T-DXd as a treatment option in China for this patient population.\n\nIndexed on Europe PMC as PubMed record 42480250 (DOI 10.1016/j.cllc.2026.06.003). Its abstract cites the registry id NCT05246514, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Clinical lung cancer", year: 2026, doi: "10.1016/j.cllc.2026.06.003", pmid: "42480250", authors: "Liu Y, Li D, Wu L, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05246514 with the most citations, so it is the natural first reading for anyone following the DESTINY-Lung05 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Clin Lung Cancer 2026","url":"https://doi.org/10.1016/j.cllc.2026.06.003"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42480250/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42480250"},{"label":"ClinicalTrials.gov NCT05246514","url":"https://clinicaltrials.gov/study/NCT05246514"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","her2-mutant-nsclc"], drugs: ["trastuzumab-deruxtecan"], targets: [], technologies: [], trials: ["nct05246514"], journals: ["clinical-lung-cancer"] }),
  p({ id: "paper-nct05663866-j-thorac-oncol-2025", name: "Preventing Infusion-Related Reactions With Intravenous Amivantamab-Results From SKIPPirr, a Phase 2 Study: A Brief Report", tldr: "Published report from the trial registered as NCT05663866, in Journal of Thoracic Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Amivantamab, an EGFR-MET bispecific antibody, is approved for multiple indications in EGFR-mutated advanced NSCLC as monotherapy or combined with other agents. Intravenous amivantamab is associated with a 67% infusion-related reaction (IRR) rate.\n\nMethods: The phase 2 SKIPPirr study (NCT05663866) enrolled participants with EGFR-mutated (exon 19 deletion or exon 21 L858R) advanced NSCLC after progression on osimertinib and platinum-based chemotherapy who received intravenous amivantamab plus oral lazertinib (amivantamab-lazertinib), a third-generation tyrosine kinase inhibitor. Aiming to mitigate IRRs, four independent prophylactic approaches were evaluated using Simon's two-stage design with an expansion stage if a cohort passed both stages: oral dexamethasone 4 mg twice daily given on cycle (C) 1 day (D) -1 (two doses); oral dexamethasone 8 mg twice daily given on C1D-2, C1D-1, and the morning of C1D1 (five doses); oral montelukast 10 mg once daily given on C1D-4, C1D-3, C1D-2, C1D-1, and C1D1 (five doses); subcutaneous methotrexate 25 mg (one dose) given anytime between C1D-7 and C1D-3. The primary end point was C1D1 IRR incidence.\n\nResults: at June 24, 2024, 68 participants were treated across all cohorts. The dexamethasone 8 mg cohort passed stages 1 and 2 proceeding to the expansion stage, with 24 additional participants treated. At C1D1, nine of 40 participants (22.5%) experienced IRRs, resulting in an approximately threefold decrease versus historical data (67.4%). By the end of C3, 10 of 41 participants (24.4%) in the dexamethasone 8 mg cohort experienced IRRs (grades 1-2, except one grade 3 on C2D1). Amivantamab-lazertinib's safety and efficacy were consistent with previous reports.\n\nConclusions: Prophylaxis with 8 mg oral dexamethasone meaningfully reduced IRRs and can be readily implemented in clinical practice.\n\nIndexed on Europe PMC as PubMed record 39864547 (DOI 10.1016/j.jtho.2025.01.018). Its abstract cites the registry id NCT05663866, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2025.01.018", pmid: "39864547", authors: "Spira AI, Paz-Ares L, Han JY, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05663866 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2025.01.018"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/39864547/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/39864547"},{"label":"ClinicalTrials.gov NCT05663866","url":"https://clinicaltrials.gov/study/NCT05663866"}], tags: ["europepmc-ingest"], cancers: ["nsclc","egfr-mutant-nsclc"], drugs: ["dexamethasone","methotrexate","amivantamab","lazertinib"], targets: [], technologies: [], trials: ["nct05663866"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct05668988-n-engl-j-med-2026", name: "First-Line Sunvozertinib in NSCLC with EGFR Exon 20 Insertion Mutations", tldr: "Published report from the WU-KONG28 trial registered as NCT05668988, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sunvozertinib received accelerated approval for use in later lines of therapy for patients with advanced non-small-cell lung cancer (NSCLC) with epidermal growth factor receptor ( EGFR) exon 20 insertion mutations. Data are needed on the efficacy and safety of sunvozertinib as a first-line treatment for NSCLC.\n\nMethods: In this phase 3, international trial, we randomly assigned, in a 1:1 ratio, patients with advanced nonsquamous NSCLC with EGFR exon 20 insertions to receive sunvozertinib or chemotherapy (carboplatin-pemetrexed). The primary end point was progression-free survival as assessed by blinded independent central review. Crossover to the sunvozertinib group was allowed after disease progression was confirmed. Secondary end points included overall survival, investigator-assessed progression-free survival, objective response (complete or partial response), change in tumor size, and duration of response.\n\nResults: A total of 324 patients were randomly assigned to receive sunvozertinib (163 patients) or chemotherapy (161 patients). Treatment with sunvozertinib led to significantly longer median progression-free survival than chemotherapy (10.3 vs. 7.5 months; hazard ratio for disease progression or death, 0.65; 95% confidence interval, 0.50 to 0.85; P<0.001). At 12 months, progression-free survival was reported in 46.1% of the patients in the sunvozertinib group and in 26.7% of those in the chemotherapy group; the data for overall survival were immature (38.9% maturity). The percentage of patients with an objective response was 58.9% in the sunvozertinib group and 31.1% in the chemotherapy group; the median best percentage change in tumor size was -42.1% and -24.7% respectively, and the median duration of response was 11.2 and 7.1 months. Grade 3 or higher adverse events were reported in 75.5% of the patients in the sunvozertinib group and in 56.7% of those in the chemotherapy group. In the sunvozertinib group, the most common adverse events of grade 3 or higher included increased serum creatine kinase levels, diarrhea, and anemia. No deaths were attributed to adverse events considered by the investigators to be related to sunvozertinib.\n\nConclusions: The efficacy of sunvozertinib was superior to that of chemotherapy as first-line treatment for advanced NSCLC with EGFR exon 20 insertions. (Funded by Dizal Pharmaceuticals; WU-KONG28 ClinicalTrials.gov number, NCT05668988.).\n\nIndexed on Europe PMC as PubMed record 42212913 (DOI 10.1056/nejmoa2604461). Its abstract cites the registry id NCT05668988, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2604461", pmid: "42212913", authors: "Zhou C, Greillier L, Liu G, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05668988 with the most citations, so it is the natural first reading for anyone following the WU-KONG28 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2604461"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42212913/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42212913"},{"label":"ClinicalTrials.gov NCT05668988","url":"https://clinicaltrials.gov/study/NCT05668988"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["sunvozertinib","pemetrexed","carboplatin"], targets: [], technologies: [], trials: ["nct05668988"], journals: ["nejm"] }),
  p({ id: "paper-nct05671510-nat-med-2026", name: "Gotistobart or docetaxel in metastatic squamous non-small cell lung cancer: stage 1 of the randomized phase 3 PRESERVE-003 trial", tldr: "Published report from the PD-L1 Inhibitors trial registered as NCT05671510, in Nature Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "PRESERVE-003 is a two-stage phase 3 trial evaluating gotistobart (BNT316/ONC-392), a novel pH-sensitive anti-cytotoxic T lymphocyte-associated protein 4 (CTLA-4) antibody that selectively depletes regulatory T cells within the tumor microenvironment, in patients with metastatic squamous non-small cell lung cancer (sqNSCLC) without actionable genomic alterations who progressed on programmed cell death protein/programmed death ligand 1 inhibitor/platinum-based chemotherapy-a population with a poor prognosis. Here we report on stage 1, which aimed to confirm the dose and assess the preliminary efficacy (primary outcome: overall survival; secondary outcomes: progression‑free survival, objective response rate and duration of response) and safety of gotistobart compared to docetaxel. Patients with sqNSCLC were randomized (1:1) to gotistobart (6 mg kg -1 with two 10 mg kg -1 loading doses every 3 weeks (N = 45)) or docetaxel (75 mg m - 2 every 3 weeks (N = 42)). After a median follow-up of 14.5 months, median overall survival was not reached with gotistobart (95% confidence interval (CI) 9.3 to not evaluable) versus 10.0 months (95% CI 6.2 to 11.9 months) with docetaxel (hazard ratio 0.46, 95% CI 0.25 to 0.84, nominal two-sided P = 0.0102). Safety was manageable, with grade ≥3 treatment-related adverse events in 42% and 49% of patients receiving gotistobart and docetaxel, respectively. Stage 1 results suggest that gotistobart monotherapy can provide clinically meaningful benefit for patients with programmed cell death protein/programmed death ligand 1-resistant and chemotherapy-resistant metastatic sqNSCLC. ClinicalTrials.gov identifier: NCT05671510.\n\nIndexed on Europe PMC as PubMed record 41896648 (DOI 10.1038/s41591-026-04323-8). Its abstract cites the registry id NCT05671510, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2026, doi: "10.1038/s41591-026-04323-8", pmid: "41896648", authors: "Cho BC, Balaraman R, Chen HJ, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05671510 with the most citations, so it is the natural first reading for anyone following the PD-L1 Inhibitors trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2026","url":"https://doi.org/10.1038/s41591-026-04323-8"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41896648/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41896648"},{"label":"ClinicalTrials.gov NCT05671510","url":"https://clinicaltrials.gov/study/NCT05671510"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["gotistobart"], targets: [], technologies: [], trials: ["nct05671510"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05712902-lancet-respir-med-2024", name: "Sunvozertinib for patients in China with platinum-pretreated locally advanced or metastatic non-small-cell lung cancer and EGFR exon 20 insertion mutation (WU-KONG6): single-arm, open-label, multicentre, phase 2 trial", tldr: "Published report from the WU-KONG6 trial registered as NCT05712902, in The Lancet. Respiratory medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sunvozertinib is an oral, irreversible, and selective tyrosine kinase inhibitor that has a favourable safety profile and encouraging antitumour activity, as shown in phase 1 studies of patients with heavily pretreated non-small cell lung cancer (NSCLC) with EGFR exon 20 insertion mutation (exon20ins). We aimed to assess the antitumour efficacy of sunvozertinib in patients with platinum-pretreated locally advanced or metastatic NSCLC with EGFR exon20ins.\n\nMethods: WU-KONG6 is a single-group, open-label, multicentre phase 2 trial of sunvozertinib monotherapy, conducted across 37 medical centres in China. We enrolled adult patients with pathologically or cytologically confirmed locally advanced or metastatic NSCLC whose tumour tissue carried an EGFR exon20ins mutation. All patients had received at least one line of previous systemic therapy, with at least one line containing platinum-based chemotherapy. The primary endpoint was objective response rate (ORR), as assessed by the independent review committee. The ORR was defined as the percentage of patients who achieved complete or partial response, confirmed by two separate assessments with at least 4-week time interval, until disease progression or initiation of any new anti-cancer therapy. Enrolled patients received sunvozertinib 300 mg once daily until meeting discontinuation criteria per the protocol. Patients who received at least one dose of treatment and were evaluable for efficacy analysis were included in the primary analysis, and all patients who received at least one dose of treatment were included in the safety analysis. This study is registered with ChinaDrugTrials.org, CTR20211009, and ClinicalTrials.gov, NCT05712902, and efficacy and safety follow-up are ongoing.\n\nFindings: Between July 19, 2021, and May 6, 2022, 104 patients were enrolled. At data cutoff (Oct 17, 2022), the last enrolled patient had been followed up for about 6 months. Among 97 patients evaluable for efficacy analysis, 59 (61%) patients achieved tumour response, with a confirmed ORR of 61% (95% CI 50-71). All tumour responses were partial responses. Tumour responses were observed irrespective of age, sex, smoking history, EGFR exon20ins subtypes, brain metastasis at baseline, previous lines of therapy, and history of onco-immunotherapy. In total, 19 death events occurred over a median follow-up period of 7·6 months (IQR 6·1-9·4). Sunvozertinib was well tolerated at 300 mg once daily. The most common grade 3 or worse treatment-related adverse events were blood creatine phosphokinase increased (18 [17%] of 104), diarrhoea (eight [8%]), and anaemia (six [6%]). The most common serious treatment-related adverse events were interstitial lung disease (five [5%] of 104), anaemia (three [3%]), vomiting (two [2%]), nausea (two [2%]) and pneumonia (two [2%]).\n\nInterpretation: In this phase 2 study, sunvozertinib demonstrated antitumour efficacy in patients with platinum-based chemotherapy pretreated NSCLC with EGFR exon20ins, with a manageable safety profile. A multinational randomised, phase 3 study of sunvozertinib versus platinum-doublet chemotherapy in EGFR exon20ins NSCLC is ongoing (NCT05668988).\n\nFunding: Dizal Pharmaceutical.\n\nIndexed on Europe PMC as PubMed record 38101437 (DOI 10.1016/s2213-2600(23)00379-x). Its abstract cites the registry id NCT05712902, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2024, doi: "10.1016/s2213-2600(23)00379-x", pmid: "38101437", authors: "Wang M, Fan Y, Sun M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05712902 with the most citations, so it is the natural first reading for anyone following the WU-KONG6 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","The abstract cites more than one registry id (NCT05712902, NCT05668988); it was kept because the trial's acronym appears in the title."], links: [{"label":"Lancet Respir Med 2024","url":"https://doi.org/10.1016/s2213-2600(23)00379-x"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38101437/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38101437"},{"label":"ClinicalTrials.gov NCT05712902","url":"https://clinicaltrials.gov/study/NCT05712902"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc"], drugs: ["sunvozertinib"], targets: [], technologies: [], trials: ["nct05712902"] }),
  p({ id: "paper-nct05722015-ann-oncol-2025", name: "Subcutaneous versus intravenous pembrolizumab, in combination with chemotherapy, for treatment of metastatic non-small-cell lung cancer: the phase III 3475A-D77 trial", tldr: "Published report from the trial registered as NCT05722015, in Annals of Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Pembrolizumab with berahyaluronidase alfa is for subcutaneous (s.c.) administration. The phase III open-label 3475A-D77 study (NCT05722015) assessed s.c. pembrolizumab versus intravenous (i.v.) pembrolizumab, plus chemotherapy, for treatment of metastatic non-small-cell lung cancer (mNSCLC).\n\nPatients and methods: Participants with newly diagnosed stage IV squamous or nonsquamous NSCLC without sensitizing EGFR, ALK, or ROS1 alterations were randomized 2: 1 to pembrolizumab s.c. 790 mg every 6 weeks (q6w) or pembrolizumab i.v. 400 mg q6w (18 cycles), each given with platinum-doublet chemotherapy. Dual primary endpoints were pharmacokinetic exposure measures of cycle 1 area under the curve (AUC 0-6 weeks) and steady-state trough concentration (C trough) of pembrolizumab. The noninferiority margin for AUC 0-6 weeks and C trough geometric mean ratios (GMRs) of pembrolizumab s.c. versus i.v. was specified as 0.8. Secondary endpoints included additional pharmacokinetic exposure measures, pembrolizumab immunogenicity, efficacy, and safety.\n\nResults: In total 377 participants were randomized to the pembrolizumab s.c. (n = 251) or i.v. (n = 126) arms. The median time from randomization to data cut-off (12 July 2024) was 9.6 months (range 6.2-16.4 months). The median injection time for pembrolizumab s.c. was 2.0 min (range 1-12 min). The GMR [96% confidence interval (CI)] for cycle 1 AUC 0-6 weeks was 1.14 (1.06-1.22); P < 0.0001. The GMR (94% CI) for steady-state C trough was 1.67 (1.52-1.84); P < 0.0001. Secondary pharmacokinetic endpoints were within established bounds for pembrolizumab. Anti-pembrolizumab antibodies were detected in 1.4% (pembrolizumab s.c. arm) and 0.9% (pembrolizumab i.v. arm) of participants. For the pembrolizumab s.c. versus i.v. arms, objective response rates (ORRs) were 45.4% versus 42.1% (ORR ratio 1.08, 95% CI 0.85-1.37). Other efficacy measures were similar and safety profiles were consistent between treatment arms.\n\nConclusions: Overall exposure and trough concentrations of pembrolizumab s.c. 790 mg q6w were noninferior to those of pembrolizumab i.v. 400 mg q6w given with chemotherapy in participants with treatment-naive mNSCLC. Results support pembrolizumab s.c. as a treatment option in all indications where pembrolizumab i.v. can be used.\n\nIndexed on Europe PMC as PubMed record 40157574 (DOI 10.1016/j.annonc.2025.03.012). Its abstract cites the registry id NCT05722015, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Annals of Oncology", year: 2025, doi: "10.1016/j.annonc.2025.03.012", pmid: "40157574", authors: "Felip E, Rojas CI, Schenker M, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05722015 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Ann Oncol 2025","url":"https://doi.org/10.1016/j.annonc.2025.03.012"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40157574/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40157574"},{"label":"ClinicalTrials.gov NCT05722015","url":"https://clinicaltrials.gov/study/NCT05722015"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["pemetrexed","cisplatin","carboplatin","paclitaxel","pembrolizumab","filgrastim"], targets: [], technologies: [], trials: ["nct05722015"], journals: ["annals-of-oncology"] }),
  p({ id: "paper-nct05840016-lancet-2025", name: "Ivonescimab plus chemotherapy versus tislelizumab plus chemotherapy as first-line treatment for advanced squamous non-small-cell lung cancer (HARMONi-6): a randomised, double-blind, phase 3 trial", tldr: "Published report from the trial registered as NCT05840016, in The Lancet (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Squamous non-small-cell lung cancer (NSCLC) is associated with worse clinical outcomes than non-squamous NSCLC, but treatment options are scarce. We aimed to evaluate the efficacy and safety of ivonescimab plus chemotherapy versus tislelizumab plus chemotherapy as a first-line therapy for patients with advanced squamous NSCLC.\n\nMethods: We conducted a randomised, double-blind, phase 3 trial at 50 sites across China (HARMONi-6). Patients aged 18-75 years with previously untreated, pathologically confirmed, unresectable stage IIIB, IIIC, or stage IV squamous NSCLC and an Eastern Cooperative Oncology Group performance status score of 0 or 1 were eligible for inclusion. Patients were randomly assigned (1:1) to receive intravenous ivonescimab (20 mg/kg) or tislelizumab (200 mg), plus intravenous paclitaxel (175 mg/m 2) and carboplatin (area under the curve 5 mg/mL per min) once every 3 weeks for four cycles, followed by ivonescimab (20 mg/kg) or tislelizumab (200 mg) monotherapy as maintenance treatment for up to 24 months. Randomisation was stratified by disease stage (IIIB or IIIC vs IV) and PD-L1 tumour proportion score (≥1% vs <1%). The primary endpoint was progression-free survival assessed by the independent radiographic review committee as per Response Evaluation Criteria in Solid Tumours guidelines (version 1.1) in all randomly assigned patients. Safety, defined as adverse events and serious adverse events related to treatment, as well as adverse events related to immunity or VEGF blockade, were analysed in all randomly assigned patients who received at least one dose of the assigned study treatment. This study is registered at ClinicalTrial.gov (NCT05840016), has completed enrolment, and is ongoing for treatment and follow-up.\n\nFindings: From Aug 17, 2023, to Jan 21, 2025, 761 patients were screened for eligibility, among whom 532 (70%) patients were enrolled and randomly assigned to receive ivonescimab plus chemotherapy (266 [50%] patients) or tislelizumab plus chemotherapy (266 [50%] patients). at Feb 28, 2025, median follow-up time was 10·3 months (95% CI 9·5-11·0). Median progression-free survival was 11·1 months (95% CI 9·9-not evaluable) in the ivonescimab group and 6·9 months (5·8-8·6) in the tislelizumab group (hazard ratio 0·60 [95% CI 0·46-0·78]; one-sided p<0·0001). The progression-free survival benefit with ivonescimab plus chemotherapy was consistent regardless of PD-L1 status. 170 (64%) patients in the ivonescimab group and 144 (54%) patients in the tislelizumab group had grade 3 or higher treatment-related adverse events, with grade 3 or higher immune-related adverse events occurring in 24 (9%) patients in the ivonescimab group and in 27 (10%) patients in the tislelizumab group. Grade 3 or higher treatment-related haemorrhage occurred in five (2%) patients in the ivonescimab group and in two (1%) patients in the tislelizumab group.\n\nInterpretation: In patients with untreated advanced squamous NSCLC, ivonescimab plus chemotherapy showed significantly improved progression-free survival compared with tislelizumab plus chemotherapy, regardless of PD-L1 status, as well as a manageable safety profile. This regimen could be used as a novel first-line treatment in this patient group.\n\nFunding: Akeso Biopharma.\n\nIndexed on Europe PMC as PubMed record 41125109 (DOI 10.1016/s0140-6736(25)01848-3). Its abstract cites the registry id NCT05840016, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2025, doi: "10.1016/s0140-6736(25)01848-3", pmid: "41125109", authors: "Chen Z, Yang F, Jiang Z, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05840016 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2025","url":"https://doi.org/10.1016/s0140-6736(25)01848-3"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41125109/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41125109"},{"label":"ClinicalTrials.gov NCT05840016","url":"https://clinicaltrials.gov/study/NCT05840016"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["ivonescimab","carboplatin","tislelizumab"], targets: [], technologies: [], trials: ["nct05840016"], journals: ["lancet"] }),
  p({ id: "paper-nct05840016-lancet-2026-update", name: "Ivonescimab plus chemotherapy versus tislelizumab plus chemotherapy in advanced squamous non-small-cell lung cancer (HARMONi-6): interim overall survival analysis of a randomised, double-blind, phase 3 trial in China", tldr: "Later report from the trial registered as NCT05840016, in The Lancet (2026); its title describes an updated or longer-term analysis.", summary: "Background: Bispecific antibodies targeting programmed death 1 (PD-1) and vascular endothelial growth factor (PD1-VEGF) have shown promising efficacy in non-small-cell lung cancer (NSCLC). In our previous report of the HARMONi-6 study, we aimed to evaluate the efficacy and safety of ivonescimab plus chemotherapy versus tislelizumab plus chemotherapy as a first-line therapy for patients with advanced squamous NSCLC. Ivonescimab combined with chemotherapy significantly prolonged progression-free survival compared with tislelizumab plus chemotherapy. Here we report the prespecified interim overall survival analysis.\n\nMethods: HARMONi-6 is a double-blind, randomised, phase 3 trial, which was conducted at 50 hospitals across China. Patients aged 18-75 years with previously untreated, pathologically confirmed, unresectable stage IIIB, IIIC, or stage IV squamous NSCLC and an Eastern Cooperative Oncology Group performance status score of 0 or 1 were eligible for inclusion. Eligible patients were randomly assigned in a 1:1 ratio to receive ivonescimab or tislelizumab, in combination with paclitaxel and carboplatin for four cycles, followed by maintenance ivonescimab or tislelizumab monotherapy. The primary endpoint was progression-free survival assessed by the independent radiographic review committee as per Response Evaluation Criteria in Solid Tumours guidelines (version 1.1) in all randomly assigned patients. Overall survival was a key secondary endpoint; an interim analysis was planned when approximately 225 overall survival events were observed, but it was triggered after 204 overall survival events to meet regulatory deadlines. Safety, defined as adverse events and serious adverse events related to treatment, as well as adverse events related to immunity or VEGF blockade, were analysed in all randomly assigned patients who received at least one dose of the assigned study treatment. This study is registered at ClinicalTrials.gov (NCT05840016), has completed enrolment, and is ongoing for treatment and follow-up.\n\nFindings: From Aug 17, 2023, to Jan 21, 2025, 761 patients were assessed for eligibility, and after 229 exclusions a total of 532 patients were randomly allocated (266 per group). 494 (93%) of patients were male and 38 (7%) of patients were female. The median age was 64 years (IQR 59-69). At data cutoff (Feb 27, 2026), 204 deaths had occurred: 84 (32%) patients in the ivonescimab plus chemotherapy group and 120 (45%) in the tislelizumab plus chemotherapy group. With a median follow-up of 21·4 months (95% CI 20·27-21·91), the median overall survival was 27·9 months (95% CI 27·89-not evaluable [NE]) with ivonescimab versus 23·7 months (20·11-NE) with tislelizumab (hazard ratio for death 0·66 [95% CI 0·50-0·87]; p one-sided =0·0017), meeting the prespecified boundary (p<0·0049). The overall survival benefit with ivonescimab plus chemotherapy was consistent across key subgroups. Treatment-related adverse events of grade 3 or higher occurred in 184 (69%) of 266 patients in the ivonescimab group and 156 (59%) of 265 patients in the tislelizumab group. The incidence of grade 3 or higher haemorrhage was seven (3%) of 266 and two (1%) of 265, respectively.\n\nInterpretation: Ivonescimab plus chemotherapy demonstrated a statistically significant and clinically meaningful improvement in overall survival compared with tislelizumab plus chemotherapy in previously untreated patients with advanced squamous NSCLC. This regimen could provide a novel treatment option as first-line treatment in this patient group.\n\nFunding: Akeso Biopharma.\n\nIndexed on Europe PMC as PubMed record 42218899 (DOI 10.1016/s0140-6736(26)00966-9). Its abstract cites the registry id NCT05840016, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2026, doi: "10.1016/s0140-6736(26)00966-9", pmid: "42218899", authors: "Lu S, Liu B, Luo Y, et al.", paperType: "rct", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Lancet 2026","url":"https://doi.org/10.1016/s0140-6736(26)00966-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42218899/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42218899"},{"label":"ClinicalTrials.gov NCT05840016","url":"https://clinicaltrials.gov/study/NCT05840016"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["ivonescimab","carboplatin","tislelizumab"], targets: [], technologies: [], trials: ["nct05840016"], journals: ["lancet"] }),
  p({ id: "paper-nct05870319-n-engl-j-med-2026", name: "Sacituzumab Tirumotecan in EGFR-TKI-Resistant, EGFR -Mutated Advanced NSCLC", tldr: "Published report from the trial registered as NCT05870319, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sacituzumab tirumotecan (sac-TMT) is an antibody-drug conjugate targeting trophoblast cell-surface antigen 2 that has shown significant survival benefits in patients with EGFR -mutated non-small-cell lung cancer (NSCLC) that has progressed after epidermal growth factor receptor (EGFR) tyrosine kinase inhibitor (TKI) therapy and platinum-based chemotherapy.\n\nMethods: In this phase 3 trial, we enrolled patients with EGFR -mutated locally advanced or metastatic nonsquamous NSCLC that had progressed after EGFR-TKI therapy. The patients were randomly assigned, in a 1:1 ratio, to receive sac-TMT monotherapy or pemetrexed plus platinum-based chemotherapy. The primary end point was progression-free survival as assessed by blinded independent review. Overall survival was a hierarchically tested key secondary end point. In the interim analysis of progression-free survival as assessed by blinded independent review, sac-TMT monotherapy met the prespecified criterion for significance (two-sided P<0.0001); we report here the prespecified final analysis of progression-free survival and the preplanned interim analysis of overall survival.\n\nResults: Overall, 376 patients underwent randomization, with 188 assigned to each group. After a median follow-up of 18.9 months, the median progression-free survival was 8.3 months in the sac-TMT group and 4.3 months in the chemotherapy group (hazard ratio for disease progression or death, 0.49; 95% confidence interval [CI], 0.39 to 0.62). Overall survival was significantly longer with sac-TMT than with chemotherapy (hazard ratio for death, 0.60; 95% CI, 0.44 to 0.82; two-sided P = 0.001); 18-month overall survival was 65.8% and 48.0%, respectively. Treatment-related adverse events of grade 3 or higher occurred in 58.0% of patients receiving sac-TMT and in 53.8% of those receiving chemotherapy, with the most common being a decreased neutrophil count (39.9% vs. 33.0%); treatment-related serious adverse events occurred in 9.0% and 17.6%, respectively.\n\nConclusions: In patients with EGFR -mutated advanced or metastatic NSCLC that had progressed after previous EGFR-TKI therapy, progression-free survival and overall survival outcomes were significantly better with sac-TMT than with platinum-based chemotherapy. (Funded by Sichuan Kelun-Biotech Biopharmaceutical; OptiTROP-Lung04 ClinicalTrials.gov number, NCT05870319.).\n\nIndexed on Europe PMC as PubMed record 41124220 (DOI 10.1056/nejmoa2512071). Its abstract cites the registry id NCT05870319, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2512071", pmid: "41124220", authors: "Fang W, Wu L, Meng X, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05870319 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2512071"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41124220/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41124220"},{"label":"ClinicalTrials.gov NCT05870319","url":"https://clinicaltrials.gov/study/NCT05870319"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc"], drugs: ["sacituzumab-tirumotecan","pemetrexed","carboplatin","cisplatin"], targets: [], technologies: [], trials: ["nct05870319"], journals: ["nejm"] }),
  p({ id: "paper-nct05933265-invest-new-drugs-2026", name: "A first-in-human phase 1a study of LP-184, a tumor-site activated novel alkylating agent, in patients with advanced solid tumors", tldr: "Published report from the trial registered as NCT05933265, in Investigational new drugs (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "LP-184 is a novel acylfulvene pro-drug that alkylates DNA after bioactivation by the intracellular oxidoreductase prostaglandin reductase 1 (PTGR1). In preclinical studies, potent growth inhibition has been observed against a wide variety of solid tumor models, particularly those carrying DNA damage repair deficiency. Here, we report results of the first-in-human dose escalation trial of LP-184 in advanced solid tumors. A dose escalation Bayesian optimal interval design was used with a starting dose of 0.01 mg/kg. Eligible patients with advanced refractory solid tumors were enrolled to receive LP-184 intravenously on days 1 and 8 of each 21-day cycle. Sixty-three patients were enrolled, with a median age of 62 years. Twelve dose levels (DLs) were evaluated with one dose-limiting toxicity (DLT) at DL11 (0.49 mg/kg; grade 4 platelet count decreased) and two DLTs at DL12 (0.61 mg/kg; grade 3 alanine aminotransferase increased and acute liver injury). The most common (≥ 20%) treatment-related adverse events of any grade included nausea, vomiting, fatigue, and platelet count decreased. No treatment-related deaths occurred during the study. Best response to monotherapy LP-184 was stable disease (SD), which was observed in 22 (40%) of the evaluable patients. Three patients experienced SD that lasted more than 12 months. LP-184 was safe and tolerable in the Phase 1a trial in patients with advanced refractory solid tumors. The maximum tolerated dose (MTD) of LP-184 is 0.49 mg/kg. Registry: ClinicalTrials.gov, TRN: NCT05933265, Registration date: June 23, 2023.\n\nIndexed on Europe PMC as PubMed record 42410111 (DOI 10.1007/s10637-026-01626-y). Its abstract cites the registry id NCT05933265, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Investigational new drugs", year: 2026, doi: "10.1007/s10637-026-01626-y", pmid: "42410111", authors: "Mahadevan D, Parekh J, Beck JT, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05933265 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Invest New Drugs 2026","url":"https://doi.org/10.1007/s10637-026-01626-y"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42410111/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42410111"},{"label":"ClinicalTrials.gov NCT05933265","url":"https://clinicaltrials.gov/study/NCT05933265"}], tags: ["europepmc-ingest"], cancers: ["tnbc","nsclc","pancreatic"], drugs: ["olaparib","ipilimumab","nivolumab","lp-184"], targets: [], technologies: [], trials: ["nct05933265"] }),
  p({ id: "paper-nct05955391-j-thorac-oncol-2026", name: "Deulorlatinib (TGRX-326) in ALK Gene Fusion Positive NSCLC After Failure of Second-Generation Inhibitors: A Single-Arm, Multicenter, Phase 2 Trial", tldr: "Published report from the trial registered as NCT05955391, in Journal of Thoracic Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Deulorlatinib (TGRX-326), a potent third-generation anaplastic lymphoma kinase (ALK) inhibitor, has reported promising activity and a favorable safety profile in ALK-positive NSCLC in a phase 1 trial. Here, we report the primary results of the pivotal phase 2 trial (NCT05955391) evaluating deulorlatinib in patients with ALK-positive NSCLC in whom second-generation ALK inhibitors had failed.\n\nMethods: This single-arm, phase 2 trial was conducted at 36 centers in China. Eligible patients received deulorlatinib 60 mg once daily. The primary end point was objective response rate (ORR) assessed by an independent review committee (IRC). Key secondary end points included disease control rate, progression-free survival (PFS), duration of response, overall survival, intracranial efficacy, and safety. Exploratory biomarker analyses were performed using cell-free DNA.\n\nResults: The efficacy and safety analysis sets comprised 158 and 163 patients, respectively. The primary end point was met with an IRC-assessed ORR of 43.7% (95% confidence interval [CI], 35.8-51.8). The IRC-assessed median PFS was 11.1 months (95% CI, 8.3-13.7). Among patients with measurable central nervous system (CNS) metastases (n = 43), the intracranial ORR was 55.8% (95% CI, 39.9-70.9). In patients harboring the G1202R mutation (n = 8), robust activity was observed (ORR: 62.5%; disease control rate: 100%; median PFS: 11.0 months). The investigator-assessed results were consistent with the IRC-assessed findings. Treatment-related adverse events occurred in 96.3% of patients (47.2% grade ≥3). Nevertheless, dose modifications were infrequent (interruption, 13.5%; reduction, 11.0%; permanent discontinuation, 0.6%). The incidence of CNS-related treatment-related adverse events was 12.9%, with no patients interrupting or discontinuing treatment owing to CNS toxicity.\n\nConclusions: Deulorlatinib indicated encouraging antitumor activity in patients with advanced ALK-positive NSCLC after failure of second-generation ALK inhibitors, including those with the G1202R mutation. Given its favorable safety profile, deulorlatinib represents a promising new option for this population.\n\nIndexed on Europe PMC as PubMed record 42031067 (DOI 10.1016/j.jtho.2026.103737). Its abstract cites the registry id NCT05955391, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2026, doi: "10.1016/j.jtho.2026.103737", pmid: "42031067", authors: "Huang J, Chen G, Wang Z, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05955391 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2026","url":"https://doi.org/10.1016/j.jtho.2026.103737"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42031067/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42031067"},{"label":"ClinicalTrials.gov NCT05955391","url":"https://clinicaltrials.gov/study/NCT05955391"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","alk-positive-nsclc"], drugs: ["tgrx-326"], targets: [], technologies: [], trials: ["nct05955391"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct06015503-j-thorac-oncol-2026", name: "Andamertinib in Advanced NSCLC With EGFR Exon 20 Insertions After Platinum-Based Chemotherapy or Immunotherapy: Results From the Phase 2 KANNON Study", tldr: "Published report from the KANNON trial registered as NCT06015503, in Journal of Thoracic Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Objectives: This study aimed to evaluate andamertinib, a selective and irreversible tyrosine kinase inhibitor, in pretreated advanced EGFR exon 20 insertion (ex20ins)-mutant NSCLC.\n\nMethods: In the phase 2, multicenter, single-arm KANNON study (NCT06015503), patients with locally advanced or metastatic NSCLC harboring EGFR ex20ins mutations who had progressed after platinum-based chemotherapy or immunotherapy received oral andamertinib 240 mg once daily in 28-day cycles. The primary end point was the confirmed objective response rate (ORR) assessed by independent review.\n\nResults: A total of 92 patients were enrolled and received daily 240 mg andamertinib, with nearly 30 different exon20ins subtypes included. The confirmed ORR was 42.7% (95% confidence interval [CI], 32.4-53.0), with a disease control rate of 86.5% and a median duration of response of 8.7 months (95% CI, 5.65-11.96). at September 6, 2025, with a median follow-up of 15.4 (range, 0.4-20.5) months, the median progression-free survival was 6.2 months (95% CI, 4.63-7.85) and median overall survival was not reached (95% CI, 13.93 mo to not estimable), with a 12-month survival rate of 70.5%. Among 38 patients with brain metastasis, the systemic confirmed ORR was 47.4% (95% CI, 31.5-63.2). Grade more than or equal to 3 treatment-related adverse events occurred in 40.2% of patients, and the most frequent events were diarrhea (12.0%) and rash (7.6%). No interstitial lung disease or grade more than or equal to 3 QT prolongation was reported.\n\nConclusions: Andamertinib at 240 mg once daily demonstrated efficacy with a manageable safety profile in previously treated patients with EGFR ex20ins-mutant NSCLC.\n\nIndexed on Europe PMC as PubMed record 41248848 (DOI 10.1016/j.jtho.2025.11.008). Its abstract cites the registry id NCT06015503, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2026, doi: "10.1016/j.jtho.2025.11.008", pmid: "41248848", authors: "Yang JJ, Mu Y, Wang ZH, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06015503 with the most citations, so it is the natural first reading for anyone following the KANNON trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2026","url":"https://doi.org/10.1016/j.jtho.2025.11.008"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41248848/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41248848"},{"label":"ClinicalTrials.gov NCT06015503","url":"https://clinicaltrials.gov/study/NCT06015503"}], tags: ["europepmc-ingest"], cancers: ["nsclc","egfr-mutant-nsclc"], drugs: [], targets: [], technologies: [], trials: ["nct06015503"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct06099782-jco-oncol-pract-2026", name: "Participant-Reported Preference for Pembrolizumab Administered Subcutaneously or Intravenously: A Randomized, Open-Label, Phase II Study", tldr: "Published report from the trial registered as NCT06099782, in JCO Oncology Practice (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Pembrolizumab with berahyaluronidase alfa, a human hyaluronidase variant, is for subcutaneous (SC) injection. The phase II, open-label, crossover study 3475A-F11 (ClinicalTrials.gov identifier: NCT06099782) assessed participant preference for SC or intravenous (IV) pembrolizumab.\n\nMethods: Participants with resected melanoma, resected renal cell carcinoma, or metastatic non-small cell lung cancer (PD-L1 tumor proportion score ≥50%) were randomly assigned 1:1 to pembrolizumab SC 395 mg (arm A) or pembrolizumab IV 200 mg (arm B) once every 3 weeks for three cycles before crossover to the other administration route for three cycles. The primary objective was participant preference for SC pembrolizumab as assessed by the Patient Preference Questionnaire. Secondary objectives included reasons for participant preference, participant satisfaction with administration route, participant choice of treatment (SC or IV) to continue after cycle 6, and safety and tolerability.\n\nResults: Overall, 147 participants were randomly assigned (arm A = 71, arm B = 76). The participant preference rate for pembrolizumab SC was 65% (95% CI, 56 to 74). The most common reason for this preference was less time in clinic (64%). Altogether, 64%/25% of participants were very satisfied/satisfied with pembrolizumab SC; 54%/31% were very satisfied/satisfied with pembrolizumab IV. More participants chose to continue treatment after cycle 6 with pembrolizumab SC than pembrolizumab IV (68% v 32%). Grade 3-4 treatment-related adverse events (AEs) in cycles 1-3 occurred in one (1%; arm A) and five (7%; arm B) participants. Injection-site AEs during SC administration cycles of the crossover period occurred in nine (13%; arm A) and 11 (16%; arm B) participants (mostly grade 1).\n\nConclusion: More participants preferred pembrolizumab SC over pembrolizumab IV and chose to continue with pembrolizumab SC. The results of this study suggest that pembrolizumab SC improves convenience compared with pembrolizumab IV in cancer treatment.\n\nIndexed on Europe PMC as PubMed record 42234938 (DOI 10.1200/op-25-01248). Its abstract cites the registry id NCT06099782, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "JCO Oncology Practice", year: 2026, doi: "10.1200/op-25-01248", pmid: "42234938", authors: "Casarini IA, Kowalski DM, Caglevic C, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06099782 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"JCO Oncol Pract 2026","url":"https://doi.org/10.1200/op-25-01248"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42234938/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42234938"},{"label":"ClinicalTrials.gov NCT06099782","url":"https://clinicaltrials.gov/study/NCT06099782"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","rcc","melanoma"], drugs: ["pembrolizumab"], targets: [], technologies: [], trials: ["nct06099782"], journals: ["jco-oncology-practice"] }),
  p({ id: "paper-nct06120140-j-thorac-oncol-2025", name: "Enhanced Versus Standard Dermatologic Management With Amivantamab-Lazertinib in EGFR-Mutated Advanced NSCLC: The COCOON Global Randomized Controlled Trial", tldr: "Published report from the COCOON trial registered as NCT06120140, in Journal of Thoracic Oncology (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Introduction: Amivantamab plus lazertinib significantly improved progression-free and overall survival versus osimertinib in patients with previously untreated, EGFR-mutant advanced NSCLC. EGFR-targeted therapies are associated with dermatologic adverse events (AEs), which can affect quality of life (QoL). COCOON was conducted to assess prophylactic management and improve treatment experience.\n\nMethods: In the phase 2 COCOON study (NCT06120140), participants with previously untreated, EGFR-mutant, locally advanced or metastatic NSCLC received intravenous amivantamab plus oral lazertinib and were randomized 1:1 to enhanced dermatologic management (COCOON DM) or standard of care (SoC DM) per local guidelines. COCOON DM included oral doxycycline or minocycline (100 mg twice daily; weeks 1-12), clindamycin 1% (on scalp daily; weeks 13-52), chlorhexidine 4% (on fingernails and toenails daily), and ceramide-based moisturizer (on body and face at least daily). Primary end point was incidence of grade 2 or higher dermatologic AEs of interest (DAEIs) by week 12.\n\nResults: In total, 201 participants were randomized (99 to COCOON DM and 102 to SoC DM). At a median follow-up of 7.1 months, COCOON DM demonstrated significant reduction in the primary end point versus SoC DM (42% versus 75%; OR, 0.24; 95% confidence interval, 0.13-0.45; p < 0.0001). By week 12, the largest benefit with COCOON DM was observed in DAEIs involving the face and body (excludes paronychia; 26% versus 60%; p < 0.0001) and DAEIs involving the scalp (10% versus 26%; p = 0.0049). This benefit was maintained at 6 months, with significant reductions of DAEIs involving face, body, and scalp (excluding paronychia). Patient-reported outcomes favored COCOON DM, indicating reduced impact of dermatologic symptoms on QoL.\n\nConclusion: An uncomplicated, widely available, prophylactic regimen (COCOON DM) reduced the incidence of DAEIs with amivantamab-lazertinib and the impact of symptoms on QoL.\n\nIndexed on Europe PMC as PubMed record 40923969 (DOI 10.1016/j.jtho.2025.07.117). Its abstract cites the registry id NCT06120140, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2025, doi: "10.1016/j.jtho.2025.07.117", pmid: "40923969", authors: "Cho BC, Li W, Spira AI, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06120140 with the most citations, so it is the natural first reading for anyone following the COCOON trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2025","url":"https://doi.org/10.1016/j.jtho.2025.07.117"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40923969/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40923969"},{"label":"ClinicalTrials.gov NCT06120140","url":"https://clinicaltrials.gov/study/NCT06120140"}], tags: ["europepmc-ingest"], cancers: ["nsclc","egfr-mutant-nsclc"], drugs: ["amivantamab","lazertinib"], targets: [], technologies: [], trials: ["nct06120140"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct06396065-lancet-oncol-2026", name: "Ivonescimab plus chemotherapy versus placebo plus chemotherapy in patients with advanced EGFR-mutated non-small-cell lung cancer after disease progression on EGFR tyrosine kinase inhibitor therapy (HARMONi): a multicentre, randomised, double-blind, phase 3 trial", tldr: "Published report from the trial registered as NCT06396065, in The Lancet Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Ivonescimab has shown clinical efficacy in non-small-cell lung cancer (NSCLC). We aimed to assess the efficacy and safety of ivonescimab plus chemotherapy versus placebo plus chemotherapy in patients with advanced EGFR-mutated NSCLC whose disease progressed after third-generation EGFR tyrosine kinase inhibitor (TKI) therapy.\n\nMethods: HARMONi is a randomised, placebo-controlled, double-blind, phase 3 trial done at 114 cancer centres and hospitals across Asia, Europe, and North America. Eligible patients were aged at least 18 years (upper limit: 75 years in Asia) with stage IIIB/IIIC or IV non-squamous EGFR-mutated NSCLC, disease progression after treatment with a third-generation EGFR-TKI, and an Eastern Cooperative Oncology Group performance status score of 0 or 1. Patients were randomly assigned (1:1) via a centralised interactive voice response system or interactive web response system to receive ivonescimab (20 mg/kg) or placebo plus pemetrexed (500 mg/m 2) and carboplatin (target area under the curve 5 mg/mL per min) intravenously every 3 weeks. Randomisation was stratified by brain metastases status at enrolment and geographical region. The primary endpoints were progression-free survival by blinded independent radiology review committee and overall survival in the intention-to-treat population. Safety was assessed in patients who received at least one dose of trial treatment. This study is registered with ClinicalTrials.gov (NCT06396065), has completed enrolment, and is ongoing for treatment and follow-up.\n\nFindings: From Jan 25, 2022, to Oct 1, 2024, 660 individuals were screened for eligibility; of these, 438 were enrolled and randomly assigned to receive ivonescimab plus chemotherapy or placebo plus chemotherapy (219 per group). Of enrolled patients, 257 (59%) were female and 181 (41%) were male; 306 (70%) reported race as Asian, and 105 (24%) as White. At a median follow-up of 22·3 months (95% CI 21·5-23·0), 275 progression or death events had occurred in 345 patients (129 events among 172 patients in the ivonescimab plus chemotherapy group and 146 events among 173 patients in the placebo plus chemotherapy group). Median progression-free survival was 6·8 months (95% CI 5·7-7·1) in the ivonescimab plus chemotherapy group versus 4·4 months (4·1-5·5) in the placebo plus chemotherapy group (hazard ratio [HR] 0·52; 95% CI 0·41-0·66; p<0·0001). At a median follow-up of 29·7 months (95% CI 27·7-31·0), 262 deaths occurred in 438 patients (122 in the ivonescimab plus chemotherapy group and 140 in the placebo plus chemotherapy group). Median overall survival was 16·8 months (14·3-19·0) in the ivonescimab plus chemotherapy group versus 14·0 months (12·8-15·7) in the placebo plus chemotherapy group (HR 0·79; 0·62-1·01). The most common grade 3-4 treatment-related adverse events in the ivonescimab plus chemotherapy versus the placebo plus chemotherapy group were decreased neutrophil count (42 [19%] of 218 vs 36 [17%] of 218), decreased white blood cell count (28 [13%] vs 24 [11%]), decreased platelet count (27 [12%] vs 14 [6%]), and anaemia (22 [10%] vs 27 [12%]). Serious treatment-related adverse events occurred in 61 (28%) patients in the ivonescimab plus chemotherapy group and 33 (15%) patients in the placebo plus chemotherapy group. Treatment-related adverse events led to death in four patients (disease progression, multiple organ dysfunction syndrome, and hepatic failure, each in one patient; gastrointestinal haemorrhage and pulmonary embolism in one patient) in the ivonescimab plus chemotherapy group and five patients (pneumonitis, myocardial infarction, cerebrovascular accident, cognitive disorder, and embolic stroke, each in one patient) in the placebo plus chemotherapy group.\n\nInterpretation: Ivonescimab plus chemotherapy showed a clinically meaningful and statistically significant progression-free survival benefit in patients with EGFR-mutated NSCLC after progression on EGFR-TKI therapy. The clinical benefit and lack of new safety signals of ivonescimab with chemotherapy support the potential for the combination as a new treatment option in this patient population.\n\nFunding: Summit Therapeutics.\n\nIndexed on Europe PMC as PubMed record 42636833 (DOI 10.1016/s1470-2045(26)00282-2). Its abstract cites the registry id NCT06396065, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet Oncology", year: 2026, doi: "10.1016/s1470-2045(26)00282-2", pmid: "42636833", authors: "Le X, Passaro A, Zhao Y, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06396065 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Oncol 2026","url":"https://doi.org/10.1016/s1470-2045(26)00282-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42636833/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42636833"},{"label":"ClinicalTrials.gov NCT06396065","url":"https://clinicaltrials.gov/study/NCT06396065"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","egfr-mutant-nsclc"], drugs: ["ivonescimab","pemetrexed","carboplatin"], targets: [], technologies: [], trials: ["nct06396065"], journals: ["lancet-oncology"] }),
  p({ id: "paper-nct06448312-lancet-2026", name: "Sacituzumab tirumotecan plus pembrolizumab versus pembrolizumab in PD-L1-positive advanced non-small-cell lung cancer (OptiTROP-Lung05): interim analysis of a randomised, open-label, phase 3 trial", tldr: "Published report from the trial registered as NCT06448312, in The Lancet (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Sacituzumab tirumotecan (sac-TMT), a trophoblast cell-surface antigen 2-targeting antibody-drug conjugate, combined with programmed death 1 (PD-1) or programmed death ligand 1 (PD-L1) inhibitors, has shown promising antitumour activity as first-line therapy for non-small-cell lung cancer (NSCLC) in early-phase studies. Our aim was to evaluate the efficacy and safety of sac-TMT plus pembrolizumab as first-line treatment for patients with PD-L1-positive advanced NSCLC without targetable genomic alterations.\n\nMethods: In this randomised, open-label, phase 3 trial (OptiTROP-Lung05) conducted across 68 hospitals in China, eligible patients had locally advanced or metastatic NSCLC without targetable genomic alterations and a PD-L1 tumour proportion score (TPS) of 1% or greater. Patients were randomly assigned (1:1) to receive sac-TMT (4 mg/kg on days 1, 15, and 29) plus pembrolizumab (400 mg fixed dose on day 1), or pembrolizumab alone, administered intravenously every 6 weeks. The primary endpoint was progression-free survival, as assessed by blinded independent central review in the intention-to-treat population. This trial was registered with ClinicalTrials.gov (NCT06448312). Recruitment is complete, with the trial ongoing and the final analysis to be reported later.\n\nFindings: Between June 7, 2024, and March 27, 2025, 741 patients were screened and 413 eligible patients were randomly assigned to receive sac-TMT plus pembrolizumab (n=208) or pembrolizumab alone (n=205). At the prespecified interim analysis, conducted after a median follow-up of 10·5 months (IQR 8·7-12·5), median progression-free survival was significantly longer with sac-TMT plus pembrolizumab than with pembrolizumab alone (not reached vs 5·7 months; stratified hazard ratio [HR] 0·35 [95% CI 0·26-0·47]; p<0·0001). The progression-free survival benefit was broadly consistent across subgroups, including patients with PD-L1 TPS of 1-49% (HR 0·28 [95% CI 0·19-0·41]) and those with PD-L1 TPS of 50% or greater (HR 0·47 [0·29-0·77]). Grade 3 or higher treatment-emergent adverse events occurred in 115 (55%) of 208 patients in the sac-TMT plus pembrolizumab group and 64 (31%) of 204 patients in the pembrolizumab group.\n\nInterpretation: Among patients with PD-L1-positive advanced NSCLC without targetable genomic alterations, first-line treatment with sac-TMT plus pembrolizumab significantly prolonged progression-free survival compared with pembrolizumab alone. Therefore, sac-TMT plus pembrolizumab has the potential to redefine first-line treatment for patients with PD-L1-positive advanced NSCLC without targetable genomic alterations.\n\nFunding: Sichuan Kelun-Biotech Biopharmaceutical.\n\nIndexed on Europe PMC as PubMed record 42214392 (DOI 10.1016/s0140-6736(26)00968-2). Its abstract cites the registry id NCT06448312, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet", year: 2026, doi: "10.1016/s0140-6736(26)00968-2", pmid: "42214392", authors: "Xiong A, Yao W, Zheng W, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06448312 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet 2026","url":"https://doi.org/10.1016/s0140-6736(26)00968-2"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42214392/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42214392"},{"label":"ClinicalTrials.gov NCT06448312","url":"https://clinicaltrials.gov/study/NCT06448312"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["sacituzumab-tirumotecan","pembrolizumab"], targets: [], technologies: [], trials: ["nct06448312"], journals: ["lancet"] }),
  p({ id: "paper-nct06612151-n-engl-j-med-2026", name: "Tambotatug Pelitecan in Small-Cell Lung Cancer after Platinum-Based Therapy", tldr: "Published report from the TAISHAN-302 trial registered as NCT06612151, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Tambotatug pelitecan (known as Tam-Peli, a new antibody-drug conjugate that targets the immune-checkpoint molecule B7-H3) showed promising clinical efficacy in patients with relapsed extensive-stage small-cell lung cancer in early-phase trials.\n\nMethods: In this phase 3, multicenter, open-label, randomized trial, we assigned eligible patients with small-cell lung cancer that had progressed after first-line platinum-based therapy in a 1:1 ratio to receive tambotatug pelitecan or topotecan. The primary end point was overall survival. The key secondary end points were progression-free survival and objective response as assessed by investigators. Here, we report the results from the prespecified interim analysis.\n\nResults: A total of 451 patients underwent randomization: 225 were assigned to receive tambotatug pelitecan and 226 to receive topotecan. Overall survival was significantly longer with tambotatug pelitecan than with topotecan - a median of 13.3 months (95% confidence interval [CI], 12.1 to could not be estimated), as compared with 9.4 months (95% CI, 7.7 to 10.5); the stratified hazard ratio for death was 0.46 (95% CI, 0.35 to 0.62; P<0.001). Treatment with tambotatug pelitecan also resulted in significantly longer progression-free survival than treatment with topotecan (median, 7.4 months [95% CI, 6.1 to 7.6] vs. 2.8 months [95% CI, 1.8 to 3.0]; stratified hazard ratio, 0.29 [95% CI, 0.23 to 0.37]; P<0.001). A confirmed objective response occurred in 59.1% of the patients in the tambotatug pelitecan group, as compared with 9.7% of those in the topotecan group (P<0.001). The overall incidence of adverse events of grade 3 or higher was lower with tambotatug pelitecan than with topotecan (55.4% vs. 77.9%).\n\nConclusions: Among patients with relapsed small-cell lung cancer after platinum-based therapy, treatment with tambotatug pelitecan resulted in longer overall survival, longer progression-free survival, and a higher percentage of patients with an objective response than treatment with topotecan, with a lower incidence of adverse events of grade 3 or higher. (Funded by the Innovative Drug Research and Development National Science and Technology Major Project and MediLink Therapeutics; TAISHAN-302 ClinicalTrials.gov number, NCT06612151.).\n\nIndexed on Europe PMC as PubMed record 42734213 (DOI 10.1056/nejmoa2610229). Its abstract cites the registry id NCT06612151, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2610229", pmid: "42734213", authors: "Zhao Y, Liu H, Meng X, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT06612151 with the most citations, so it is the natural first reading for anyone following the TAISHAN-302 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2610229"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42734213/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42734213"},{"label":"ClinicalTrials.gov NCT06612151","url":"https://clinicaltrials.gov/study/NCT06612151"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: ["yl201"], targets: [], technologies: [], trials: ["nct06612151"], journals: ["nejm"] }),
  p({ id: "paper-nct04270591-eclinicalmedicine-2023", name: "Gumarontinib in patients with non-small-cell lung cancer harbouring MET exon 14 skipping mutations: a multicentre, single-arm, open-label, phase 1b/2 trial", tldr: "Published report from the trial registered as NCT04270591, in EClinicalMedicine (2023), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Approximately 3-4% of patients with non-small-cell lung cancer (NSCLC) have MET exon 14 ( MET ex14) skipping mutations. We report primary results from the phase 2 stage of a phase 1b/2 study of gumarontinib, a selective, potent, oral MET inhibitor, in patients with MET ex14 skipping mutation-positive ( MET ex14-positive) NSCLC.\n\nMethods: The single-arm, multicentre, open-label, phase 2 stage of the GLORY study was conducted at 42 centres across China and Japan. Adults with locally advanced or metastatic MET ex14-positive NSCLC received oral gumarontinib 300 mg once daily in continuous 21-day cycles until disease progression, intolerable toxicity, or withdrawal of consent. Eligible patients had failed one or two prior lines of therapy (not including a MET inhibitor), were ineligible for/refused chemotherapy, and had no genetic alterations targetable with standard therapies. The primary endpoint was objective response rate in patients with a valid baseline tumour assessment, by blinded independent review. The study was registered at ClinicalTrials.gov (NCT04270591).\n\nFindings: Between Aug 2, 2019 and Apr 28, 2021, 84 patients were enrolled and received gumarontinib (median follow-up 13.5 months [IQR 8.7-17.1]), at data cut-off (Apr 28, 2022) five patients whose MET ex14 status could not be confirmed by a central laboratory were excluded from the efficacy analysis. The objective response rate was 66% (95% CI 54-76) overall (n = 79), 71% (95% CI 55-83) in treatment-naïve patients (n = 44), and 60% (95% CI 42-76) in previously-treated patients (n = 35). The most common treatment-related adverse events (any grade) were oedema (67/84 patients, 80%) and hypoalbuminuria (32/84, 38%). Grade ≥3 treatment-emergent adverse events occurred in 45 (54%) patients. Treatment-related adverse events leading to permanent discontinuation occurred in 8% (7/84) of patients.\n\nInterpretation: Gumarontinib monotherapy had durable antitumour activity with manageable toxicity in patients with locally advanced or metastatic MET ex14-positive NSCLC when used in first line or later.\n\nFunding: Haihe Biopharma Co., Ltd. Supported in part by grants from the National Science and Technology Major Project of China for \"Clinical Research of Gumarontinib, a highly selective MET inhibitor\" (2018ZX09711002-011-003); the National Natural Science Foundation of China (82030045 to S.L. and 82172633 to YF.Y); Shanghai Municipal Science & Technology Commission Research Project (19411950500 to S.L.); Shanghai Shenkang Action Plan (16CR3005A to S.L.) and Shanghai Chest Hospital Project of Collaborative Innovation (YJXT20190105 to S.L.).\n\nIndexed on Europe PMC as PubMed record 37096188 (DOI 10.1016/j.eclinm.2023.101952). Its abstract cites the registry id NCT04270591, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "EClinicalMedicine", year: 2023, doi: "10.1016/j.eclinm.2023.101952", pmid: "37096188", authors: "Yu Y, Zhou J, Li X, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04270591 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"EClinicalMedicine 2023","url":"https://doi.org/10.1016/j.eclinm.2023.101952"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37096188/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/37096188"},{"label":"ClinicalTrials.gov NCT04270591","url":"https://clinicaltrials.gov/study/NCT04270591"}], tags: ["europepmc-ingest"], cancers: ["nsclc","met-altered-nsclc"], drugs: ["glumetinib"], targets: [], technologies: [], trials: ["nct04270591"] }),
  p({ id: "paper-nct04270591-transl-lung-cancer-res-2025-update", name: "Long-term follow-up results from the GLORY study: phase II study of gumarontinib in East Asian patients with MET exon 14 skipping mutated non-small cell lung cancer", tldr: "Later report from the trial registered as NCT04270591, in Translational lung cancer research (2025); its title describes an updated or longer-term analysis.", summary: "Background: Gumarontinib has previously shown activity in patients with non-small cell lung cancer (NSCLC) harboring MET exon 14 skipping mutation ( MET ex14). We hereby report the updated results from the phase II stage of GLORY study after additional 18-month follow-up.\n\nMethods: The single-arm, multicenter, open-label, phase II of the GLORY study was conducted at 42 centers across China and Japan. Patients with locally advanced or metastatic MET ex14-positive NSCLC received gumarontinib 300 mg orally once daily until disease progression or intolerable toxicity. Eligible patients had failed one or two prior lines of therapy (not including a MET inhibitor) and had no genetic alterations targetable with standard therapies. The primary endpoint was the objective response rate (ORR) by the blinded independent review committee (BIRC) per Response Evaluation Criteria in Solid Tumors version 1.1. The study was registered at ClinicalTrials.gov (NCT04270591).\n\nResults: The phase II stage of GLORY study included 84 patients. at the data cutoff date on October 28, 2023, the ORR assessed by BIRC was 65.8% [95% confidence interval (CI): 54.3% to 76.1%], with 70.5% (95% CI: 54.8% to 83.2%) in treatment-naïve and 60.0% (95% CI: 42.1% to 76.1%) in pre-treated populations. The median duration of response (DOR) assessed by BIRC was 8.3 (95% CI: 6.2 to 18.3) months, the median progression-free survival (PFS) was 7.7 (95% CI: 7.6 to 9.7) months, and the median overall survival (OS) was 19.4 (95% CI: 12.1 to 30.1) months, with a median OS of 25.4 [95% CI: 11.7 to not evaluable (NE)] months in treatment-naïve population and 16.3 (95% CI: 8.7 to NE) months in the pre-treated population. The most common treatment-related adverse events (any grade) were oedema (67/84, 79.8%) and hypoalbuminemia (32/84, 38.1%). Grade ≥3 treatment-related adverse events occurred in 53.6% (45/84) patients. Treatment-related adverse events leading to permanent discontinuation occurred in 8.3% (7/84) of patients.\n\nConclusions: Gumarontinib showed promising efficacy and acceptable toxicities in East Asian population, with a rapid onset of action, substantial and durable response, which can be converted into a long-term survival benefit.\n\nIndexed on Europe PMC as PubMed record 41132955 (DOI 10.21037/tlcr-2025-638). Its abstract cites the registry id NCT04270591, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Translational lung cancer research", year: 2025, doi: "10.21037/tlcr-2025-638", pmid: "41132955", authors: "Lu S, Yu Y, Zhou J, et al.", paperType: "observational", findings: [], whatItMeans: "A second publication from the trial, later than the first and described in its title as an update or longer-term analysis. Read it with the primary publication linked from the trial page; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper.","Chosen as a later report by words in its title (updated, long-term, final, overall survival or a year count), not by reading the paper."], links: [{"label":"Transl Lung Cancer Res 2025","url":"https://doi.org/10.21037/tlcr-2025-638"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41132955/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41132955"},{"label":"ClinicalTrials.gov NCT04270591","url":"https://clinicaltrials.gov/study/NCT04270591"}], tags: ["europepmc-ingest"], cancers: ["nsclc","met-altered-nsclc"], drugs: ["glumetinib"], targets: [], technologies: [], trials: ["nct04270591"] }),
  p({ id: "paper-nct04606446-nat-med-2024", name: "Inhibition of lysine acetyltransferase KAT6 in ER + HER2 - metastatic breast cancer: a phase 1 trial", tldr: "Published report from the trial registered as NCT04606446, in Nature Medicine (2024), chosen as the most cited paper whose own text cites the registry id.", summary: "Inhibition of histone lysine acetyltransferases (KATs) KAT6A and KAT6B has shown antitumor activity in estrogen receptor-positive (ER +) breast cancer preclinical models. PF-07248144 is a selective catalytic inhibitor of KAT6A and KAT6B. In the present study, we report the safety, pharmacokinetics (PK), pharmacodynamics, efficacy and biomarker results from the first-in-human, phase 1 dose escalation and dose expansion study (n = 107) of PF-07248144 monotherapy and fulvestrant combination in heavily pretreated ER + human epidermal growth factor receptor-negative (HER2 -) metastatic breast cancer (mBC). The primary objectives of assessing the safety and tolerability and determining the recommended dose for expansion of PF-07248144, as monotherapy and in combination with fulvestrant, were met. Secondary endpoints included characterization of PK and evaluation of antitumor activity, including objective response rate (ORR) and progression-free survival (PFS). Common treatment-related adverse events (any grade; grades 3-4) included dysgeusia (83.2%, 0%), neutropenia (59.8%, 35.5%) and anemia (48.6%, 13.1%). Exposure was approximately dose proportional. Antitumor activity was observed as monotherapy. For the PF-07248144-fulvestrant combination (n = 43), the ORR (95% confidence interval (CI)) was 30.2% (95% CI = 17.2-46.1%) and the median PFS was 10.7 (5.3-not evaluable) months. PF-07248144 demonstrated a tolerable safety profile and durable antitumor activity in heavily pretreated ER + HER2 - mBC. These findings establish KAT6A and KAT6B as druggable cancer targets, provide clinical proof of concept and reveal a potential avenue to treat mBC. clinicaltrial.gov registration: NCT04606446.\n\nIndexed on Europe PMC as PubMed record 38824244 (DOI 10.1038/s41591-024-03060-0). Its abstract cites the registry id NCT04606446, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2024, doi: "10.1038/s41591-024-03060-0", pmid: "38824244", authors: "Mukohara T, Park YH, Sommerhalder D, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT04606446 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2024","url":"https://doi.org/10.1038/s41591-024-03060-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/38824244/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/38824244"},{"label":"ClinicalTrials.gov NCT04606446","url":"https://clinicaltrials.gov/study/NCT04606446"}], tags: ["europepmc-ingest"], cancers: ["prostate","nsclc","sclc"], drugs: ["pf-07248144","fulvestrant","letrozole","palbociclib","atirmociclib","vepdegestrant"], targets: [], technologies: [], trials: ["nct04606446"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05061550-nat-med-2025", name: "Perioperative durvalumab plus chemotherapy plus new agents for resectable non-small-cell lung cancer: the platform phase 2 NeoCOAST-2 trial", tldr: "Published report from the NeoCOAST-2 trial registered as NCT05061550, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "In the phase II NeoCOAST-2 platform study, 202 patients with untreated, resectable stage IIA-IIIB non-small-cell lung cancer (NSCLC) were randomized to receive neoadjuvant durvalumab plus platinum-doublet chemotherapy with oleclumab, a CD73 inhibitor (Arm 1), or with monalizumab, a NKG2A inhibitor (Arm 2), or neoadjuvant durvalumab plus single-agent platinum chemotherapy with the TROP-2 antibody-drug conjugate (ADC) datopotamab deruxtecan (Arm 4), followed by surgical resection and adjuvant durvalumab with oleclumab or monalizumab (Arms 1 and 2) or durvalumab alone (Arm 4). Primary endpoints were pathological complete response (pCR) rate and safety; secondary endpoints included feasibility of surgery and major pathological response (mPR) rate. In the modified intention-to-treat population (n = 198; Arm 1, n = 74; Arm 2, n = 70; Arm 4, n = 54), pCR rates were 20.3% (15/74; 95% CI, 11.8-31.2), 25.7% (18/70; 95% CI, 16.0-37.6) and 35.2% (19/54; 95% CI, 22.7-49.4), and mPR rates were 41.9% (31/74; 95% CI, 30.5-53.9), 50.0% (35/70; 95% CI, 37.8-62.2) and 63.0% (34/54; 95% CI, 48.7-75.7) in arms 1, 2, and 4, respectively. In the safety population, 69/74 (93.2%), 66/71 (93.0%), and 51/54 (94.4%) patients underwent surgery, respectively. Overall, grade ≥3 treatment-related adverse events occurred in 27/74 (36.5%), 29/71 (40.8%) and 11/54 (20.4%) patients, respectively. In NeoCOAST-2, the first neoadjuvant trial examining an ADC plus chemo-immunotherapy in resectable NSCLC, pCR rates were highest in the datopotamab-deruxtecan-containing arm, warranting further investigation in larger trials of ADCs and checkpoint inhibition in the neoadjuvant setting. ClinicalTrials.gov identifier: NCT05061550.\n\nIndexed on Europe PMC as PubMed record 40450142 (DOI 10.1038/s41591-025-03746-z). Its abstract cites the registry id NCT05061550, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-025-03746-z", pmid: "40450142", authors: "Cascone T, Bonanno L, Guisier F, et al.", paperType: "rct", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05061550 with the most citations, so it is the natural first reading for anyone following the NeoCOAST-2 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-025-03746-z"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40450142/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40450142"},{"label":"ClinicalTrials.gov NCT05061550","url":"https://clinicaltrials.gov/study/NCT05061550"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","resectable-nsclc"], drugs: ["durvalumab","oleclumab","monalizumab","datopotamab-deruxtecan","carboplatin","cisplatin"], targets: [], technologies: [], trials: ["nct05061550"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05168566-j-thorac-oncol-2026", name: "Sutetinib for Patients with Non-Small Cell Lung Cancer Harboring Uncommon EGFR Mutations: A Multicenter, Open-Label, Phase IIb Trial", tldr: "Published report from the trial registered as NCT05168566, in Journal of Thoracic Oncology (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Purpose: Uncommon epidermal growth factor receptor (EGFR) mutations account for ∼10% of EGFR-altered non-small cell lung cancer (NSCLC) and show heterogeneous sensitivity to EGFR-tyrosine kinase inhibitors (TKIs), with limited prospective evidence to inform first-line therapy. Sutetinib is an irreversible EGFR-TKI. We assessed the safety and antitumor efficacy of sutetinib in patients with locally advanced or metastatic NSCLC with uncommon EGFR mutations.\n\nMethods: In this multicenter, open-label, single-arm phase IIb trial, adults with locally advanced or metastatic NSCLC harboring EGFR G719X, S768I, L861Q, or predefined compound mutations and no prior EGFR-TKI therapy were enrolled. Patients received sutetinib 80 mg orally once daily in 28-day cycles until radiographic progression or unacceptable toxicity. Patients who received at least one dose of treatment and evaluable for efficacy analysis were included in the primary analysis, and all patients who received at least one dose of treatment were included in the safety analysis. The primary endpoint was objective response rate (ORR), as assessed by the independent review committee (IRC). Secondary endpoints included duration of response (DoR), disease control rate (DCR), time to response (TTR), progression-free survival (PFS), overall survival (OS), and safety.\n\nResults: From December 9, 2021, to May 5, 2024, 99 patients were enrolled (efficacy-evaluable, n=96; safety, n=99). at data cut-off in October, 2024, the median follow-up was 16.6 months. The IRC-confirmed ORR was 70.8% (95% confidence interval [CI], 60.7-79.7) and the DCR was 90.6% (95% CI, 82.9-95.6). Median DoR was 12.0 months (95% CI, 9.3-15.7) and median PFS was 13.7 months (95% CI, 10.9-16.4). Median OS was not reached (95% CI, 22.2-not reached). ORR was numerically higher in patients with compound versus solitary uncommon EGFR mutations (84.4% vs 64.1%), with median PFS of 13.8 versus 11.0 months, respectively. Treatment-related adverse events (TRAEs) of any grade occurred in 97.0% (96/99) of patients, and grade ≥3 TRAEs occurred in 42.4% (42/99). The most common grade ≥3 TRAEs were diarrhea (28.3% [28/99]), hypokalemia (8.1% [8/99]), and increased gamma-glutamyl transferase (5.1% [5/99]). TRAEs led to dose reduction in 34.3% (34/99) and treatment discontinuation in 4.0% (4/99). No treatment-related deaths occurred.\n\nConclusions: Sutetinib met the prespecified primary endpoint and demonstrated clinically meaningful antitumor activity with a manageable safety profile in advanced NSCLC harboring uncommon EGFR mutations (G719X, S768I, and L861Q). These findings support sutetinib as a potential treatment option for this molecularly heterogeneous population.\n\nTrial registration: NCT05168566.\n\nIndexed on Europe PMC as PubMed record 42637134 (DOI 10.1016/j.jtho.2026.104165). Its abstract cites the registry id NCT05168566, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of Thoracic Oncology", year: 2026, doi: "10.1016/j.jtho.2026.104165", pmid: "42637134", authors: "Wu F, Zhang W, Zhao Y, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05168566 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Thorac Oncol 2026","url":"https://doi.org/10.1016/j.jtho.2026.104165"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42637134/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42637134"},{"label":"ClinicalTrials.gov NCT05168566","url":"https://clinicaltrials.gov/study/NCT05168566"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: [], targets: ["egfr"], technologies: [], trials: ["nct05168566"], journals: ["journal-of-thoracic-oncology"] }),
  p({ id: "paper-nct05288205-lancet-respir-med-2026", name: "Glecirasib plus sitneprotafib in patients with KRAS G12C -mutated non-small-cell lung cancer in China: an open-label, multicentre, single-arm, phase 1/2a trial", tldr: "Published report from the Phase 1 trial registered as NCT05288205, in The Lancet. Respiratory medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Monotherapy with KRAS G12C (ie, KRAS Gly12Cys) inhibitors has emerged as a mainstream treatment for patients with KRAS G12C -mutated non-small-cell lung cancer (NSCLC). Synergistic effects have been observed with the combination of a KRAS G12C inhibitor and a SHP2 inhibitor in multiple xenograft models. We aimed to evaluate the safety and efficacy of the KRAS G12C inhibitor glecirasib combined with the SHP2 inhibitor sitneprotafib (JAB-3312; Jacobio Pharmaceuticals, Beijing, China) in patients with KRAS G12C -mutated solid tumours.\n\nMethods: We conducted an open-label, multicentre, single-arm, phase 1/2a trial at 26 hospitals across China. Patients (aged ≥18 years) with locally advanced or metastatic solid tumours harbouring a KRAS G12C mutation, an Eastern Cooperative Oncology Group performance status score of 0-1, and measurable disease according to Response Evaluation Criteria in Solid Tumours (RECIST; version 1.1) were eligible for inclusion in both phases. Patients received oral glecirasib (400 mg or 800 mg once daily) in combination with oral sitneprotafib (2 mg or 3 mg once daily) in seven cohorts evaluating various dose levels and schedules of the two drugs. In phase 1, the primary endpoint was safety assessed by investigators according to the National Cancer Institute Common Terminology Criteria for Adverse Events (version 5.0) from first treatment dose to 30 days after the last dose of both agents. In phase 2a, the primary endpoint was objective response rate (ORR) between baseline and disease progression or initiation of anticancer therapy, whichever occurred first, based on the comprehensive assessment of all tumour evaluations by investigators following RECIST (version 1.1). All patients who received at least one dose of combination therapy were included in the safety and efficacy analyses. This trial is registered with ClinicalTrials.gov (NCT05288205) and is currently recruiting.\n\nFindings: Between May 7, 2022, and Aug 20, 2024, a total of 194 patients with advanced solid tumours were enrolled, of whom 171 (88%) had NSCLC (50 [29%] in phase 1 and 121 [71%] in phase 2a). Median participant age was 65 years (IQR 59-70); 140 (82%) were men and 31 (18%) were women. At data cutoff on Aug 20, 2024, the median follow-up duration was 14·5 months (IQR 11·9-17·1), and 106 (62%) patients had discontinued treatment. Phase 1 concluded with one dose-limiting toxicity (DLT; grade 3 pneumonitis) at the highest dose level (glecirasib 800 mg plus sitneprotafib 3 mg once daily, 1 week on and 1 week off); no DLTs were observed at other dose levels. Across phase 1 and 2a, 167 patients (98%) had at least one treatment-related adverse event, which were grade 3-4 in 78 (46%) patients. The most common treatment-related adverse events (occurring in ≥20% of all 171 patients) were anaemia (105 [61%]), hypertriglyceridaemia (103 [60%]), increased aspartate aminotransferase (95 [56%]), increased alanine aminotransferase (83 [49%]), increased blood bilirubin (78 [46%]), oedema (62 [36%]), increased blood creatine phosphokinase (60 [35%]), neutropenia (54 [32%]), decreased white blood cell count (50 [29%]), and increased bodyweight (44 [26%]). Three (2%) patients discontinued glecirasib and sitneprotafib due to treatment-related adverse events. No grade 5 treatment-related adverse event was reported. The ORR was 71% (72 patients [95% CI 61-79]) in the subgroup of 102 patients with previously untreated NSCLC; 49% (19 patients [32-65]) in the 39 patients previously treated with systemic therapy but naive to KRAS G12C inhibitors; and 10% (three patients [2-27]) in the 30 patients previously treated with KRAS G12C inhibitor therapy.\n\nInterpretation: Glecirasib combined with sitneprotafib showed promising efficacy and manageable safety in patients with advanced KRAS G12C -mutated NSCLC, particularly among those who had not received previous treatment. These findings support the evaluation of this combination in a phase 3 trial comparing this chemotherapy-free regimen to current standard of care in this patient group.\n\nFunding: Jacobio Pharmaceuticals.\n\nTranslation: For the Chinese translation of the abstract see Supplementary Materials section.\n\nIndexed on Europe PMC as PubMed record 41325755 (DOI 10.1016/s2213-2600(25)00258-9). Its abstract cites the registry id NCT05288205, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "The Lancet. Respiratory medicine", year: 2026, doi: "10.1016/s2213-2600(25)00258-9", pmid: "41325755", authors: "Zhong J, Zhao J, Duan J, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05288205 with the most citations, so it is the natural first reading for anyone following the Phase 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Lancet Respir Med 2026","url":"https://doi.org/10.1016/s2213-2600(25)00258-9"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/41325755/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/41325755"},{"label":"ClinicalTrials.gov NCT05288205","url":"https://clinicaltrials.gov/study/NCT05288205"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","colorectal","kras-g12c-colorectal","kras-g12c-nsclc"], drugs: ["glecirasib","sitneprotafib"], targets: [], technologies: [], trials: ["nct05288205"] }),
  p({ id: "paper-nct05351788-nat-med-2025", name: "First-line sacituzumab tirumotecan with tagitanlimab in advanced non-small-cell lung cancer: a phase 2 trial", tldr: "Published report from the trial registered as NCT05351788, in Nature Medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Sacituzumab tirumotecan (sac-TMT, also known as MK-2870 or SKB264) is an antibody-drug conjugate targeting trophoblast cell surface antigen 2. We report the initial findings from the ongoing phase 2 OptiTROP-Lung01 study, evaluating the combination of sac-TMT and tagitanlimab (KL-A167), an anti-PD-L1 antibody, as first-line therapy in patients with advanced or metastatic non-small-cell lung cancer who lack actionable genomic alterations (cohorts 1A and 1B). Cohort 1A received sac-TMT (5 mg kg -1, every 3 weeks) plus tagitanlimab (1,200 mg, every 3 weeks) in each 3-week cycle, whereas cohort 1B was treated with sac-TMT (5 mg kg -1, every 2 weeks) plus tagitanlimab (900 mg, every 2 weeks) in each 4-week cycle, in a nonrandomized manner until disease progression or unacceptable toxicity. The primary endpoints included safety and objective response rate. This study was not powered for formal hypothesis testing. A total of 40 and 63 patients were enrolled in cohorts 1A and 1B, respectively. The median age was 63 years in both cohorts. An Eastern Cooperative Oncology Group performance status of 1 was observed in 97.5% and 85.7% of patients in cohorts 1A and 1B, respectively. In cohorts 1A and 1B, the most common grade ≥3 treatment-related adverse events were decreased neutrophil count (30.0% and 34.9%), decreased white blood cell count (5.0% and 19.0%) and anemia (5.0% and 19.0%). No treatment-related deaths were observed. After median follow-ups of 19.3 months for cohort 1A and 13.0 months for cohort 1B, the confirmed objective response rate in the full analysis set was 40.0% (16 of 40) and 66.7% (42 of 63), the disease control rate was 85.0% and 92.1% and median progression-free survival was 15.4 months (95% confidence interval 6.7-17.9) and not reached for cohorts 1A and 1B, respectively. sac-TMT plus tagitanlimab showed promising efficacy as a first-line treatment for advanced or metastatic non-small-cell lung cancer, with a manageable safety profile. ClinicalTrials.gov registration: NCT05351788.\n\nIndexed on Europe PMC as PubMed record 40830660 (DOI 10.1038/s41591-025-03883-5). Its abstract cites the registry id NCT05351788, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Nature Medicine", year: 2025, doi: "10.1038/s41591-025-03883-5", pmid: "40830660", authors: "Hong S, Wang Q, Cheng Y, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05351788 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Nat Med 2025","url":"https://doi.org/10.1038/s41591-025-03883-5"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40830660/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40830660"},{"label":"ClinicalTrials.gov NCT05351788","url":"https://clinicaltrials.gov/study/NCT05351788"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["sacituzumab-tirumotecan","kl-a167","carboplatin","cisplatin"], targets: [], technologies: [], trials: ["nct05351788"], journals: ["nature-medicine"] }),
  p({ id: "paper-nct05379985-n-engl-j-med-2026", name: "Daraxonrasib in Previously Treated Advanced RAS -Mutated Pancreatic Cancer", tldr: "Published report from the trial registered as NCT05379985, in New England Journal of Medicine (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: Current therapies for patients with pancreatic ductal adenocarcinoma (PDAC) provide modest benefit. Activating RAS mutations occur in more than 90% of PDAC tumors. Daraxonrasib (RMC-6236) is an oral RAS(ON) multiselective inhibitor that targets guanosine triphosphate-bound mutant and wild-type RAS.\n\nMethods: In this phase 1-2 study, we evaluated daraxonrasib in patients with advanced solid tumors with activating RAS mutations. Patients received 10 to 400 mg of daraxonrasib orally once daily; 300 mg was selected as the phase 3 dose. The primary end point was safety. Pharmacokinetics and antitumor activity were secondary end points. This report focuses on the 168 study patients with previously treated RAS -mutated PDAC.\n\nResults: Among the 168 patients with PDAC who received daraxonrasib at a dose of 300 mg or less, treatment-related adverse events of any grade were reported in 96%; such events of grade 3 or higher were reported in 30%. Treatment-related adverse events that occurred in at least 10% of the patients included rash, diarrhea, nausea, stomatitis or mucositis, vomiting, and fatigue. In a subgroup of 26 patients with RAS G12 mutations who were treated with second-line daraxonrasib at a dose of 300 mg, an objective response to therapy was reported in 35% (95% confidence interval [CI], 17 to 56). The median duration of response was 8.2 months (95% CI, 3.8 to not evaluable), with median values of 8.5 months for progression-free survival and 13.1 months for overall survival. Among the 38 patients with RAS G12, G13, or Q61 mutations, 29% (95% CI, 15 to 46) had an objective response. The median duration of response was 8.2 months (95% CI, 3.8 to 8.8), with median values of 8.1 months for progression-free survival and 15.6 months for overall survival.\n\nConclusions: Daraxonrasib was associated with treatment-related adverse events of grade 3 or higher in one third of patients with previously treated RAS -mutated PDAC; antitumor activity was also reported. (Funded by Revolution Medicines; RMC-6236-001 ClinicalTrials.gov number, NCT05379985.).\n\nIndexed on Europe PMC as PubMed record 42090791 (DOI 10.1056/nejmoa2505783). Its abstract cites the registry id NCT05379985, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "New England Journal of Medicine", year: 2026, doi: "10.1056/nejmoa2505783", pmid: "42090791", authors: "Wolpin BM, Park W, Garrido-Laguna I, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05379985 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"N Engl J Med 2026","url":"https://doi.org/10.1056/nejmoa2505783"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42090791/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42090791"},{"label":"ClinicalTrials.gov NCT05379985","url":"https://clinicaltrials.gov/study/NCT05379985"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc","colorectal","pancreatic"], drugs: ["daraxonrasib"], targets: [], technologies: [], trials: ["nct05379985"], journals: ["nejm"] }),
  p({ id: "paper-nct05435248-j-transl-med-2025", name: "HS-10375, a selective EGFR C797S tyrosine kinase inhibitor, in advanced non-small cell lung cancer", tldr: "Published report from the Phase 1 trial registered as NCT05435248, in Journal of translational medicine (2025), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: The C797S mutation is one of the most common mechanisms of acquired resistance to third generation EGFR TKIs, yet no approved therapies have been available to target it. Here we developed a novel selective EGFR C797S inhibitor, HS-10375, and report the results of pre-clinical research and the first-in-human phase 1 trial.\n\nMethods: Ba/F3 cell lines and patient-derived cells expressing mutant EGFR were used to test the selectively inhibitory potency of HS-10375 in vitro, and cell line-derived xenograft animal models were used to evaluate the anticancer efficacy of HS-10375 in vivo. In the phase 1 trial, HS-10375 was administered orally at six dose levels (10-240 mg) daily (QD) in 21-day cycles, following a rule-based, rolling six design. The primary objectives were the safety, tolerability and maximum tolerated dose (MTD). The secondary objectives included PK parameters and anti-tumor activity.\n\nResults: HS-10375 showed more potent activity in inhibiting EGFR phosphorylation compared to 1st to 3rd generation EGFR TKIs in C797S triple-mutant cell lines. HS-10375 also exhibited comparable inhibitory activity to 1st- and 2nd- generation EGFR TKIs and superior activity to 3rd-generation EGFR TKIs in C797S double-mutant cell lines. Furthermore, cells harboring EGFR double or triple C797S mutation underwent remarkable apoptosis upon HS-10375 treatment. HS-10375 effectively inhibited tumor growth in C797S triple-mutant mouse models. In the first-in-human trial, 28 patients with advanced or metastatic non-small cell lung cancers who harbored EGFR mutation and who had experienced treatment failure with EGFR TKI treatment received at least one dose of HS-10375. Dose-limiting toxicities were observed in 2 patients at 240 mg QD, and MTD was reached at HS-10375 150 mg QD. The most common treatment-related adverse events were vomit (37.0%), loss of appetite (33.3%), and elevated AST (33.3%). One patient with EGFR mutations showed tumor shrinkage after progression on five-line treatment including gefitinib, almonertinib, chemotherapy, immunotherapy, and EGFRxHER3 antibody-drug conjugate.\n\nConclusions: HS-10375 demonstrated potent and mutant-selective activity against the EGFR C797S mutation in preclinical results, and showed an acceptable safety profile and objective response in a first-in-human phase 1 trial. Trial registration This trial is registered on China Drug Trials (CTR20220045), and ClinicalTrials.gov (NCT05435248).\n\nIndexed on Europe PMC as PubMed record 40468352 (DOI 10.1186/s12967-025-06613-0). Its abstract cites the registry id NCT05435248, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "Journal of translational medicine", year: 2025, doi: "10.1186/s12967-025-06613-0", pmid: "40468352", authors: "Zhan J, Xue J, Wu L, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05435248 with the most citations, so it is the natural first reading for anyone following the Phase 1 trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"J Transl Med 2025","url":"https://doi.org/10.1186/s12967-025-06613-0"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/40468352/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/40468352"},{"label":"ClinicalTrials.gov NCT05435248","url":"https://clinicaltrials.gov/study/NCT05435248"}], tags: ["europepmc-ingest"], cancers: ["nsclc"], drugs: [], targets: [], technologies: [], trials: ["nct05435248"] }),
  p({ id: "paper-nct05751798-eur-j-cancer-2026", name: "A Phase 1 dose-escalation study to evaluate safety, pharmacokinetics, and pharmacodynamics of OSE-279, an anti-PD-1 monoclonal antibody in patients with advanced solid tumours", tldr: "Published report from the trial registered as NCT05751798, in European Journal of Cancer (2026), chosen as the most cited paper whose own text cites the registry id.", summary: "Background: OSE-279 is a high affinity humanized monoclonal bivalent antibody against PD-1 with potent antitumor activity in vivo in syngeneic non-clinical models.\n\nMethods: This phase I study assessed the safety, pharmacokinetics, pharmacodynamics and antitumor activity of OSE-279 in advanced solid tumours.\n\nResults: Twenty patients received OSE-279 intravenously at 100 mg q3w (n = 2), 300 mg q3w (n = 7) and 600 mg q6w (n = 11). Median age was 61.5 (range 3-81) years, 50% were female, median number of prior metastatic lines was 2 (range 1-6). Most frequent tumour types were soft tissue sarcoma (n = 4) and anal squamous cell carcinoma (n = 3). OSE-279 monotherapy was safe. Two recommended phase 2 doses were established: 300 mg q3w and 600 mg q6w. The most common (≥10%) related TEAEs were diarrhoea, dry mouth, pruritus, chills, fatigue, headache, dysgeusia and hyperthyroidism. OSE-279 PK exhibited linear dose proportionality and mean receptor occupancy was maintained above 80% in all tested doses. There were 1 CR at 300 mg q3w, 4 PRs at 600 mg q6w and 7 SD with response duration ranging from 6.8 to 18.4 months.\n\nConclusion: OSE-279 monotherapy was well tolerated with durable responses in patients with advanced solid tumours. The trial is continuing with OSE-279 combined with OSE2101, a therapeutic cancer vaccine in 1st line HLA-A2 positive PD-L1 ≥ 50% NSCLC. CLINICAL TRIAL REGISTRATION (NCT NUMBER: NCT05751798).\n\nIndexed on Europe PMC as PubMed record 42034003 (DOI 10.1016/j.ejca.2026.116729). Its abstract cites the registry id NCT05751798, which is how it was matched to this trial; no figure has been checked by an editor.", journal: "European Journal of Cancer", year: 2026, doi: "10.1016/j.ejca.2026.116729", pmid: "42034003", authors: "Robert M, Kotecki N, Gomez-Roca C, et al.", paperType: "observational", findings: [], whatItMeans: "This is the paper Europe PMC returns for registry id NCT05751798 with the most citations, so it is the natural first reading for anyone following the trial. Read the abstract above alongside the trial page and the registry entry; the record was linked automatically and its figures have not been checked by hand.", caveats: ["Matched to the trial by the registry id cited in the Europe PMC record; the summary reproduces the record's abstract and no figure has been verified against the full paper."], links: [{"label":"Eur J Cancer 2026","url":"https://doi.org/10.1016/j.ejca.2026.116729"},{"label":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/42034003/"},{"label":"Europe PMC","url":"https://europepmc.org/article/MED/42034003"},{"label":"ClinicalTrials.gov NCT05751798","url":"https://clinicaltrials.gov/study/NCT05751798"}], tags: ["europepmc-ingest"], cancers: ["nsclc","sclc"], drugs: ["ose2101"], targets: [], technologies: [], trials: ["nct05751798"], journals: ["european-journal-of-cancer"] }),
];
